local _, Lore = ...

Lore.stories = {
    {
        id = "q752",
        name = "Rites of the Earthmother",
        zone = "Mulgore",
        minLevel = 1,
        maxLevel = 14,
        importance = 2,
        kind = "world",
        quests = {
            { ids = { 752 }, name = "A Humble Task", level = 2, zone = "Mulgore", giver = "Chief Hawkwind", giverMap = 1412, giverX = 43.9, giverY = 76.7, ender = "Greatmother Hawkwind", enderMap = 1412, enderX = 48.8, enderY = 80.9, objective = "Chief Hawkwind wants you to search for his mother near the water well to the southeast of Camp Narache.", summary = "All members of the tribe share in the harmony of life. We live together and work together.$b$bOur commitment to one another carries with it a high degree of responsibility. I ask of you now a humble task.$b$bMy mother set out this morning to fetch water from the well to the southeast of Narache. It has been quite some time now. Perhaps you could check on her for me while I attend to tribal matters here?" },
            { ids = { 753 }, name = "A Humble Task", level = 3, zone = "Mulgore", giver = "Greatmother Hawkwind", giverMap = 1412, giverX = 48.8, giverY = 80.9, ender = "Chief Hawkwind", enderMap = 1412, enderX = 43.9, enderY = 76.7, objective = "Take a Water Pitcher from the water well.$b$bReturn the pitcher to Chief Hawkwind in Camp Narache which is northwest from the water well.", summary = "I have traveled many paths through life and these old legs lack the vigor they once had. I can still perform my duties to the tribe. Sometimes it just takes an old woman a little longer to do the task.$b$bBut you look like an eager $c. Let's put some of that youthful vitality to the test. Take a water pitcher from the well and bring it to my son, the Chief, in Camp Narache.$b$bRemember that even the most humble task can gain the recognition of elders." },
            { ids = { 755, 763, 776 }, name = "Rites of the Earthmother", level = 3, zone = "Mulgore", giver = "Chief Hawkwind", giverMap = 1412, giverX = 43.9, giverY = 76.7, ender = "Seer Graytongue", enderMap = 1412, enderX = 42.5, enderY = 90.1, objective = "Travel to Seer Graytongue who lives in the hills directly south of Camp Narache.", summary = "Your willingness to perform a humble task for the tauren of Narache and your eagerness to learn are noble traits, $n. I believe one day you will be heralded in Thunder Bluff as a $c of greatness.$b$bBefore that you must embark on the Rites of the Earthmother, of which there are three.$b$bThe first test is the Rite of Strength. Travel to Seer Graytongue and tell him Chief Hawkwind has sent you.$b$bYou will find the seer's abode directly to the south of Camp Narache, tucked away in the hills." },
            { ids = { 757 }, name = "Rite of Strength", level = 4, zone = "Mulgore", giver = "Seer Graytongue", giverMap = 1412, giverX = 42.5, giverY = 90.1, ender = "Chief Hawkwind", enderMap = 1412, enderX = 43.9, enderY = 76.7, objective = "Kill Bristlebacks in Brambleblade Ravine and bring 12 Bristleback Belts to Chief Hawkwind in Camp Narache.", summary = "The Rites of the Earthmother are the steps a young tauren needs to take to gain respect in Thunder Bluff.$b$bFirst you must pass the Rite of Strength. In this test you must prove your bravery by slaying enemies of the tribe.$b$bBristlebacks of Brambleblade Ravine to the east are encroaching on our tribal lands. They ambush our hunting parties and steal from the village by dark.$b$bShow your valor by slaying these villains and return to the Chief in Camp Narache with their belts as proof of your deeds." },
            { ids = { 767 }, name = "Rite of Vision", level = 6, zone = "Mulgore", giver = "Baine Bloodhoof", giverMap = 1412, giverX = 46.7, giverY = 63.4, ender = "Zarlman Two-Moons", enderMap = 1412, enderX = 46.9, enderY = 61.2, objective = "Speak with Zarlman Two-Moons in Bloodhoof Village.", summary = "The Rite of Vision, one of the Rites of the Earthmother, will help guide you toward earning the respect of the elders of Thunder Bluff.$b$bOur people have learned that the land is our most holy provider. In order to take part in the ritualistic vision, you must speak with the spiritual leader of the village, Zarlman Two-Moons." },
            { ids = { 771 }, name = "Rite of Vision", level = 7, zone = "Mulgore", giver = "Zarlman Two-Moons", giverMap = 1412, giverX = 46.9, giverY = 61.2, ender = "Zarlman Two-Moons", enderMap = 1412, enderX = 46.9, enderY = 61.2, objective = "Collect 2 Well Stones and 2 Ambercorn and bring them back to Zarlman Two-Moons in Bloodhoof Village.", summary = "In order to pass through the Rite of Vision, you must gather the reagents needed to make the Water of the Seers.$b$bI will need well stones, which can be found around the water wells in Mulgore. With those I will combine Ambercorn, which fall beneath the mighty trees in our land.$b$bThese reagents contain magical elements, and when brewed and consumed before the tribal fire, will cause you to encounter a vision. Follow it, and it will lead you to the next step of this holy quest." },
            { ids = { 772 }, name = "Rite of Vision", level = 7, zone = "Mulgore", giver = "Zarlman Two-Moons", giverMap = 1412, giverX = 46.9, giverY = 61.2, ender = "Seer Wiserunner", enderMap = 1412, enderX = 34.3, enderY = 43.3, objective = "Consume the Water of the Seers in front of the tribal fire in Bloodhoof Village and follow the vision once it appears.", summary = "I now present you with the Water of the Seers.$b$bWhen you are ready, consume the waters near the tribal fire. Once you have ingested the holy waters, it will take a few moments before the vision materializes before the fire.$b$bAt that point, it is up to you to follow it to your destiny...." },
            { ids = { 773 }, name = "Rite of Wisdom", level = 10, zone = "Mulgore", giver = "Seer Wiserunner", giverMap = 1412, giverX = 34.3, giverY = 43.3, ender = "Ancestral Spirit", enderMap = 1412, enderX = 58.3, enderY = 30.7, objective = "Travel to Red Rocks east of Thunder Bluff and speak with the Ancestral Spirit.", summary = "To gain acceptance amongst the elders of Thunder Bluff you must next complete the Rite of Wisdom.$b$bNow that you have passed the Rite of Vision, the ancestral spirits of Red Rocks will give you the blessing of our ancestors. Only those who have drunk from the Water of Seers can gain the blessing.$b$bTravel east of Thunder Bluff, to Red Rocks and seek out the Ancestral Spirit, $n." },
            { ids = { 775 }, name = "Journey into Thunder Bluff", level = 10, zone = "Mulgore", giver = "Ancestral Spirit", giverMap = 1412, giverX = 58.3, giverY = 30.7, ender = "Cairne Bloodhoof", enderMap = 1456, enderX = 60.3, enderY = 51.7, objective = "Speak with Cairne Bloodhoof in Thunder Bluff.", summary = "You will now be revered within our great city. Any $r worthy of completing the Rites of the Earthmother earns that honor.$b$bFor your final quest, seek out our noble leader, Cairne Bloodhoof, who dwells atop the highest mesa in Thunder Bluff." },
        },
    },
    {
        id = "q381",
        name = "The Scarlet Crusade",
        zone = "Tirisfal Glades",
        minLevel = 2,
        maxLevel = 5,
        importance = 1,
        kind = "world",
        quests = {
            { ids = { 376 }, name = "The Damned", level = 2, zone = "Tirisfal Glades", giver = "Novice Elreth", giverMap = 1420, giverX = 30.9, giverY = 66.0, ender = "Novice Elreth", enderMap = 1420, enderX = 30.9, enderY = 66.0, objective = "Novice Elreth requires 6 Scavenger Paws and 6 Duskbat Wings.", summary = "My duties include tending to our wounded warriors, tailoring armor and clothes, and assisting Shadow Priest Sarvis with whatever else he might need.$b$bFrom the look of it, you'll be enlisted in his service also... hunting the Mindless Ones, if I know his mind. Well, if you'd like to stay in one piece--and I've no doubt you do--perhaps I can help. I'm running out of paws and wings, and if you bring me some, I'll find some armor for you. You'll find a good number of wolves and bats to the south." },
            { ids = { 380 }, name = "Night Web's Hollow", level = 4, zone = "Tirisfal Glades", giver = "Executor Arren", giverMap = 1420, giverX = 32.1, giverY = 66.0, ender = "Executor Arren", enderMap = 1420, enderX = 32.1, enderY = 66.0, objective = "Executor Arren wants you to kill 10 Young Night Web Spiders and 8 Night Web Spiders.", summary = "One of our greatest struggles is obtaining the natural resources we need to survive. Gold was scarce even in the height of the Alliance's power.$b$bThere is a gold mine to the northwest that has been overrun with spiders. We need gold from the mine, but we can't very well get it while the spiders are crawling around in there. I've not much manpower to commit to the task, so we'll just have to do it little by little.$B$BGet up there and see what you can do for us, $n." },
            { ids = { 381 }, name = "The Scarlet Crusade", level = 4, zone = "Tirisfal Glades", giver = "Executor Arren", giverMap = 1420, giverX = 32.1, giverY = 66.0, ender = "Executor Arren", enderMap = 1420, enderX = 32.1, enderY = 66.0, objective = "Bring Executor Arren 12 Scarlet Armbands from Scarlet Converts and Scarlet Initiates.", summary = "You'll be happy to know we appear to be making progress in the mine, thanks in no small part to your efforts.  We can now turn our eyes to other concerns.$b$bMy scouts have reported that a detachment of the Scarlet Crusade is setting up a camp southeast of here. The Scarlet Crusade is a despicable organization that hunts us, and they will not rest until every undead--Lich King's Scourge or no--is destroyed. We must strike first!$b$bBe careful, their unholy zeal makes them dangerous adversaries." },
            { ids = { 382 }, name = "The Red Messenger", level = 5, zone = "Tirisfal Glades", giver = "Executor Arren", giverMap = 1420, giverX = 32.1, giverY = 66.0, ender = "Executor Arren", enderMap = 1420, enderX = 32.1, enderY = 66.0, objective = "Kill Meven Korgal, the messenger, at the Crusader camp, then return any information you find to Executor Arren.", summary = "Reports from my superiors in Brill indicate that an agent of the Scarlet Crusade was dispatched from the Scarlet Monastery and sent here to Deathknell. According to the reports, the messenger possesses important information on his person. I do not have further details, but whatever it is, we must have it!$b$bYou're the most qualified person I have to send, $n. Find that messenger and bring me whatever information you can find." },
            { ids = { 383 }, name = "Vital Intelligence", level = 5, zone = "Tirisfal Glades", giver = "Executor Arren", giverMap = 1420, giverX = 32.1, giverY = 66.0, ender = "Executor Zygand", enderMap = 1420, enderX = 60.6, enderY = 51.8, objective = "Deliver the Scarlet Crusade Documents to Executor Zygand in Brill.", summary = "These will need to be taken to my superior, Executor Zygand, in Brill. With this information, we'll be able to deal a decisive blow to the Scarlet Crusade. Your services have been useful here in Deathknell, but I need someone to deliver this to Zygand, and I believe he'll be able to find you more appropriate work.$b$bTake the road north out of Deathknell. Soon after entering Tirisfal proper, you'll hit a crossroads. Take the eastern fork, and keep going east. You'll pass Cold Hearth Manor along the way." },
        },
    },
    {
        id = "q405",
        name = "The Prodigal Lich",
        zone = "Tirisfal Glades",
        minLevel = 4,
        maxLevel = 12,
        importance = 3,
        kind = "world",
        quests = {
            { ids = { 358 }, name = "Graverobbers", level = 8, zone = "Tirisfal Glades", giver = "Magistrate Sevren", giverMap = 1420, giverX = 61.3, giverY = 50.8, ender = "Magistrate Sevren", enderMap = 1420, enderX = 61.3, enderY = 50.8, objective = "Kill Rot Hide Graverobbers and Rot Hide Mongrels.  $B$BBring 8 Embalming Ichors to Magistrate Sevren in Brill.", summary = "The Mass Graves, southwest of Garren's Haunt to the north, were made to accommodate the...impressive...number of deaths Tirisfal suffered when the Plague first came.  $B$BThe bodies in these graves have so far been spared an undeath, but the Scourge now send Rot Hide Gnolls to gather the corpses and use them to bolster their armies.  This cannot be allowed!$B$BYour task is twofold: slay the Rot Hides at the Mass Grave and Garren's Haunt, and gather from them the Embalming Ichor that gives them life." },
            { ids = { 405 }, name = "The Prodigal Lich", level = 8, zone = "Tirisfal Glades", giver = "Magistrate Sevren", giverMap = 1420, giverX = 61.3, giverY = 50.8, ender = "Bethor Iceshard", enderMap = 1458, enderX = 84.1, enderY = 17.4, objective = "Present Sevren's Orders to Bethor Iceshard in the Undercity.", summary = "Bethor Iceshard, a high-ranking and powerful mage in the Undercity to the south, commands me to send him an agent with proven worth against the Scourge.  You, $N, will be that agent.$B$BPresent these orders to Bethor.  He will then instruct you on your mission.  I don't know its details, but it deals with recruiting a wayward Lich.  And it will be dangerous.$B$BSo ready yourself, $C.  You must not fail.$B$BYou may find Bethor in the Magic Quarter of the Undercity." },
            { ids = { 357 }, name = "The Lich's Identity", level = 8, zone = "Undercity", giver = "Bethor Iceshard", giverMap = 1458, giverX = 84.1, giverY = 17.4, ender = "Bethor Iceshard", enderMap = 1458, enderX = 84.1, enderY = 17.4, objective = "Bring the Lich's Spellbook to Bethor Iceshard in the Undercity.", summary = "There is a lich who dwells on the island in Brightwater Lake to the north.  Although he is a free-willed Forsaken, he believes all other Undead are Scourge slaves and has his minions attack anyone who approaches him.$B$BBut because he is Forsaken, the Queen will want him.  And if he is skilled in Necromancy, then his knowledge would be...quite useful to us.$B$BTo discover his identity and his talents, I must see his spellbook.  Steal into his camp and acquire it, then return to me." },
            { ids = { 366 }, name = "Return the Book", level = 8, zone = "Undercity", giver = "Bethor Iceshard", giverMap = 1458, giverX = 84.1, giverY = 17.4, ender = "Gunther Arcanus", enderMap = 1420, enderX = 68.2, enderY = 41.9, objective = "Return Gunther's Spellbook to him, on the island of Gunther's Retreat.", summary = "Long ago Gunther and I, along with the now Scourge Necromancer Thule Ravenclaw, were friends and students within the Kirin Tor - a society of mages in Dalaran.$B$BGunther and I both fell to the Plague, but I thought he either remained dead, or was raised into the ranks of the Lich King.  It is good to know he is free.$B$BWe must have him.  I have placed a spell on his book that, when he sees it, will show him that I too am free of the Lich King.  After knowing this, it is my hope that he will join us." },
            { ids = { 409 }, name = "Proving Allegiance", level = 12, zone = "Tirisfal Glades", giver = "Gunther Arcanus", giverMap = 1420, giverX = 68.2, giverY = 41.9, ender = "Gunther Arcanus", enderMap = 1420, enderX = 68.2, enderY = 41.9, objective = "Obtain a Candle of Beckoning.$B$BSummon Lillith Nefara and kill her.$B$BReturn to Gunther on his island.", summary = "You say you are not bound by the will of the Lich King, and the enchantment Bethor placed upon my book corroborates this.  But before I believe you I must have proof that you are enemy to the Scourge.$B$BThere is an old, bloody altar just off the southern coast of this island.  it is used by a powerful Scourge agent, Lillith Nefara.$B$BTake a Candle of Beckoning from this crate here.  Light it on the altar and Lillith will awake.  Destroy Lillith, and I will believe you are the Lich King's foe." },
            { ids = { 411 }, name = "The Prodigal Lich Returns", level = 12, zone = "Tirisfal Glades", giver = "Gunther Arcanus", giverMap = 1420, giverX = 68.2, giverY = 41.9, ender = "Bethor Iceshard", enderMap = 1458, enderX = 84.1, enderY = 17.4, objective = "Bring the Nether Gem to Bethor Iceshard in the Undercity.", summary = "Take this Nether Gem to my old comrade Bethor.  It will let us communicate ... and I have much to tell him." },
        },
    },
    {
        id = "q823",
        name = "Ak'Zeloth",
        zone = "Durotar",
        minLevel = 4,
        maxLevel = 14,
        importance = 3,
        kind = "world",
        quests = {
            { ids = { 823 }, name = "Report to Orgnil", level = 7, zone = "Durotar", giver = "Master Gadrin", giverMap = 1411, giverX = 56.0, giverY = 74.7, ender = "Orgnil Soulscar", enderMap = 1411, enderX = 52.2, enderY = 43.1, objective = "Speak with Orgnil Soulscar in Razor Hill.", summary = "We at Sen'jin Village are not without our own troubles, and we thank you for your aid.  But the news you bring regarding the Burning Blade could be trouble for everyone.$B$BThere is an orc stationed at Razor Hill, Orgnil Soulscar, who polices Durotar from evils such as the Burning Blade!  Go to Orgnil and tell him of our plight, as well as your news from the Valley of Trials.  He will want to know these things.$B$BRazor Hill lies to the north." },
            { ids = { 806 }, name = "Dark Storms", level = 12, zone = "Durotar", giver = "Orgnil Soulscar", giverMap = 1411, giverX = 52.2, giverY = 43.1, ender = "Orgnil Soulscar", enderMap = 1411, enderX = 52.2, enderY = 43.1, objective = "Bring Fizzle's Claw to Orgnil Soulscar in Razor Hill.", summary = "We cannot allow the Burning Blade a foothold in Durotar!  We must destroy them before their evil festers!$B$BI have undergone my own investigations and found that a Burning Blade warlock, the goblin Fizzle Darkstorm, has camped within Thunder Ridge to the northwest.  There he and his cultist minions spread chaos.$B$BFind and defeat Fizzle, and bring me his dead claw!" },
            { ids = { 828 }, name = "Margoz", level = 12, zone = "Durotar", giver = "Orgnil Soulscar", giverMap = 1411, giverX = 52.2, giverY = 43.1, ender = "Margoz", enderMap = 1411, enderX = 56.4, enderY = 20.0, objective = "Speak with Margoz.", summary = "One of our Shamans, Margoz, knows more of the Burning Blade's corruption.  He speaks of a cave called Skull Rock in the mountains - just outside Orgrimmar! - that shelters a large band of Burning Blade cultists.$B$BBefore you go to Skull Rock speak with Margoz.  He is wise and his council is valued.$B$BHe is camped to the northeast, between the coast and Drygulch Ravine.$B$BFollow his advice, but whatever Margoz says, $N, I still want you to crush those cultists!" },
            { ids = { 827 }, name = "Skull Rock", level = 12, zone = "Durotar", giver = "Margoz", giverMap = 1411, giverX = 56.4, giverY = 20.0, ender = "Margoz", enderMap = 1411, enderX = 56.4, enderY = 20.0, objective = "Gather Searing Collars from the cultists in Skull Rock.$B$BBring them to Margoz at his camp.", summary = "$N.  The Burning Blade has infested the cave east of Orgrimmar known as Skull Rock.  Inside that cave they perform vile rituals, and burn their own flesh with Searing Collars.$B$BBy wearing these collars, I believe the cultists attune themselves to demonic power.  But to confirm this, I must have a collection of the collars to study.$B$BGo to Skull Rock and gather Searing Collars from the cultists you find there.  Bring them to me, and I will uncover their secrets." },
            { ids = { 829 }, name = "Neeru Fireblade", level = 12, zone = "Durotar", giver = "Margoz", giverMap = 1411, giverX = 56.4, giverY = 20.0, ender = "Neeru Fireblade", enderMap = 1454, enderX = 49.5, enderY = 50.6, objective = "Bring an Example Collar to Neeru Fireblade in Orgrimmar.", summary = "The Searing Collars you brought me are powerful, demonic implements.  Divining their origin is, I'm afraid, beyond my skills as a shaman.  We will need a warlock to study them.$B$BTake a searing collar to Neeru Fireblade.  Although he is a skilled warlock, he professes to use his powers to thwart demons, and claims his research in the occult is benign.  Be that true or false, we may need his aid against the demonic cult in Durotar.$B$BYou may find Neeru in Orgrimmar in the Cleft of Shadow." },
            { ids = { 809 }, name = "Ak'Zeloth", level = 13, zone = "Orgrimmar", giver = "Neeru Fireblade", giverMap = 1454, giverX = 49.5, giverY = 50.6, ender = "Ak'Zeloth", enderMap = 1413, enderX = 62.3, enderY = 20.1, objective = "Speak with Ak'Zeloth in the Barrens.", summary = "Since the last great war when the Burning Legion was defeated, I have searched for sources of demonic corruption in orc society.  The collar you brought me confirms my fears.$B$BIt belongs to the Burning Blade, a cult that rallies around an item of demonic power.  It is called the Demon Seed, and it resides in the Barrens atop Dreadmist Peak.  It must be destroyed!$B$BGo to Far Watch Post, on the border of the Barrens to the west, and speak with my assistant, Ak'Zeloth.  He will direct you further." },
            { ids = { 924 }, name = "The Demon Seed", level = 14, zone = "The Barrens", giver = "Ak'Zeloth", giverMap = 1413, giverX = 62.3, giverY = 20.1, ender = "Ak'Zeloth", enderMap = 1413, enderX = 62.3, enderY = 20.1, objective = "Grab a Flawed Power Stone.  Bring it to the Altar of Fire before the stone expires, then return to Ak'Zeloth.", summary = "The Demon Seed is a powerful tool for the Burning Legion. It rests in a cave on Dreadmist Peak, above a demonic altar of fire.$B$BI have prepared power stones that when placed near the Seed will disrupt its connection to the Legion.$B$BTake a stone from the table and bring it to the altar of fire atop Dreadmist Peak. Travel west, then north when the road forks. The Peak will be to your left. The safest climb to the top is on its northern face.$B$BAnd hurry--the stone's power will consume itself in time." },
        },
    },
    {
        id = "q370",
        name = "At War With The Scarlet Crusade",
        zone = "Tirisfal Glades",
        minLevel = 5,
        maxLevel = 12,
        importance = 1,
        kind = "world",
        quests = {
            { ids = { 427 }, name = "At War With The Scarlet Crusade", level = 8, zone = "Tirisfal Glades", giver = "Executor Zygand", giverMap = 1420, giverX = 60.6, giverY = 51.8, ender = "Executor Zygand", enderMap = 1420, enderX = 60.6, enderY = 51.8, objective = "Executor Zygand of Brill wants you to kill 10 Scarlet Warriors.", summary = "The documents Executor Arren provided are just the break we needed in our battle with the wretched Scarlet Crusade.  We now know their exact locations throughout Tirisfal Glades.$b$bBut the Deathguard has larger concerns.  The Lich King's army grows in number each night.  We need someone with \"initiative\" like yourself to drive the Scarlet Crusade to the grave.$b$bProve to me you are capable of serving The Dark Lady by travelling west to the tower past the Solliden Farmstead and slay 10 Scarlet Warriors." },
            { ids = { 370 }, name = "At War With The Scarlet Crusade", level = 9, zone = "Tirisfal Glades", giver = "Executor Zygand", giverMap = 1420, giverX = 60.6, giverY = 51.8, ender = "Executor Zygand", enderMap = 1420, enderX = 60.6, enderY = 51.8, objective = "Executor Zygand in Brill wants you to kill Captain Perrine, 3 Scarlet Zealots and 3 Scarlet Missionaries.", summary = "The strategic documents from Executor Arren contain all the details we need to wipe the human infestation from the lands.  According to the information, The Scarlet Crusade has assigned Captain Perrine and a brigade to the ruined tower southwest of Brill.$b$bKill Perrine along with 3 Zealots and 3 Missionaries and report back to me." },
            { ids = { 371 }, name = "At War With The Scarlet Crusade", level = 10, zone = "Tirisfal Glades", giver = "Executor Zygand", giverMap = 1420, giverX = 60.6, giverY = 51.8, ender = "Executor Zygand", enderMap = 1420, enderX = 60.6, enderY = 51.8, objective = "Executor Zygand in Brill has commissioned you to slay Captain Vachon and 5 Scarlet Friars.", summary = "We are still at war and the Scarlet Crusade grows in strength.  The report Executor Arren sent me indicates Scarlet Crusaders have been raiding from the ruined tower in southeastern Tirisfal near the Balnir Farmstead under the command of Captain Vachon.$b$bKill Vachon along with 5 Scarlet Friars. It should prove to be a devastating blow to the Crusade!" },
            { ids = { 372 }, name = "At War With The Scarlet Crusade", level = 12, zone = "Tirisfal Glades", giver = "Executor Zygand", giverMap = 1420, giverX = 60.6, giverY = 51.8, ender = "Executor Zygand", enderMap = 1420, enderX = 60.6, enderY = 51.8, objective = "Executor Zygand in the town of Brill wants you to assassinate Captain Melrache and his two bodyguards.", summary = "Scarlet Crusaders have been raiding from the ruined tower in northern Tirisfal, past Faol's Rest.  According to the information we have, a ruthless commander named Captain Melrache is in charge of this evil crew.$b$bI am entrusting you now with a special and dangerous mission.  Slay Melrache and his two bodyguards, in the name of The Dark Lady." },
        },
    },
    {
        id = "q367",
        name = "A New Plague",
        zone = "Tirisfal Glades",
        minLevel = 6,
        maxLevel = 11,
        importance = 1,
        kind = "world",
        quests = {
            { ids = { 367 }, name = "A New Plague", level = 6, zone = "Tirisfal Glades", giver = "Apothecary Johaan", giverMap = 1420, giverX = 59.5, giverY = 52.4, ender = "Apothecary Johaan", enderMap = 1420, enderX = 59.5, enderY = 52.4, objective = "Apothecary Johaan in the town of Brill wants you to collect 5 Vials of Darkhound Blood.", summary = "Lady Sylvanas has called upon the Royal Apothecary Society. The Dark Lady believes our knowledge coupled with the newfound magic will provide the key to Arthas's demise.  She has challenged us to concoct a new plague, a plague deadlier than any ailment on Azeroth. This new disease will bring Arthas's Scourge Army to ruin.$b$bMy studies show that the blood of beasts might prove to be the key. Bring to me 5 vials of darkhound blood so I can test my theory. " },
            { ids = { 368 }, name = "A New Plague", level = 9, zone = "Tirisfal Glades", giver = "Apothecary Johaan", giverMap = 1420, giverX = 59.5, giverY = 52.4, ender = "Apothecary Johaan", enderMap = 1420, enderX = 59.5, enderY = 52.4, objective = "Apothecary Johaan of the town of Brill needs 5 Vile Fin Scales from Murlocs in Tirisfal Glades.", summary = "While you were collecting samples for me, my experiments led me to realize that more reagents will be required for this new disease to spread properly. Poisoning some hapless victim is child's play. Plaguing an entire world proves to be a bit more complicated.$b$bI will need 5 Vile Fin Scales from Murlocs in the vicinity.  You will find the creatures along the coast to the north or to the west." },
            { ids = { 369 }, name = "A New Plague", level = 11, zone = "Tirisfal Glades", giver = "Apothecary Johaan", giverMap = 1420, giverX = 59.5, giverY = 52.4, ender = "Apothecary Johaan", enderMap = 1420, enderX = 59.5, enderY = 52.4, objective = "Apothecary Johaan in the town of Brill wants you to bring him 4 samples of venom from a Vicious Night Web Spider.", summary = "While you were out gathering, I uncovered some old text in one of my tomes that indicates that an ancient plague wiped out thousands of innocent victims.  Later it was discovered that the deadly agent in the plague was preserved through the venom of Night Web Spiders.$b$bBring me some venom from a Vicious Night Web Spider to complete this experiment.  I want to see if the contagious element from the venom will work with my new concoction.  Rumor has it the spiders can be found in Eastern Tirisfal Glades." },
            { ids = { 492 }, name = "A New Plague", level = 11, zone = "Tirisfal Glades", giver = "Apothecary Johaan", giverMap = 1420, giverX = 59.5, giverY = 52.4, ender = "Captured Mountaineer", enderMap = 1420, enderX = 61.9, enderY = 51.4, objective = "Bring Johaan's Special Drink to the Captured Mountaineer.", summary = "According to the Deathguard, another one of those foolish Dwarven Mountaineers has just been captured.  The Deathguard likes to use the cellar of the Gallows End Tavern as a holding cell until prisoners can be \"properly\" dealt with.$b$bWhy don't you go see how the Captured Mountaineer enjoys this special drink I made for him?  It contains a subtle hint of what The Dark Lady has planned for the rest of Azeroth." },
        },
    },
    {
        id = "q5726",
        name = "Hidden Enemies",
        zone = "Orgrimmar",
        minLevel = 9,
        maxLevel = 16,
        importance = 3,
        kind = "dungeon",
        quests = {
            { ids = { 5726 }, name = "Hidden Enemies", level = 12, zone = "Orgrimmar", giver = "Thrall", giverMap = 1454, giverX = 31.7, giverY = 37.8, ender = "Thrall", enderMap = 1454, enderX = 31.7, enderY = 37.8, objective = "Bring a Lieutenant's Insignia to Thrall in Orgrimmar.", summary = "One thing I will not tolerate are traitors in our midst, $N. But I would be a fool to play my hand so early--it would not sufficiently cut the corruption out of our lands and only cause the infection to grow worse.$B$BBut you, a young adventurer, could go places my agents could not... could learn the truth... could find the true head of the beast.$B$BIf you are brave enough, then enter Skull Rock to the east of Orgrimmar, find a lieutenant's insignia off one of the Burning Blade there, and return to me." },
            { ids = { 5727 }, name = "Hidden Enemies", level = 12, zone = "Orgrimmar", giver = "Thrall", giverMap = 1454, giverX = 31.7, giverY = 37.8, ender = "Thrall", enderMap = 1454, enderX = 31.7, enderY = 37.8, objective = "Take the Lieutenant's Insignia to Neeru Fireblade and speak to him. Gauge if he believes you are a member of the Burning Blade and then return to Thrall in Orgrimmar.", summary = "Now let us see if this insignia you found is worth the effort.$B$BThere is a warlock within the city who believes he has my trust. He does not know that I realize where his true loyalties lie. He is in fact the leader of the Burning Blade. But do not rush off to do battle with him; he has a purpose, and we shall use him against our enemies.$B$BTake this insignia to him in the Cleft of Shadow here in Orgrimmar, speak to him and see if he believes you are one of his own, then return to me here." },
            { ids = { 5728 }, name = "Hidden Enemies", level = 16, zone = "Orgrimmar", giver = "Thrall", giverMap = 1454, giverX = 31.7, giverY = 37.8, ender = "Thrall", enderMap = 1454, enderX = 31.7, enderY = 37.8, objective = "Kill Bazzalan and Jergosh the Invoker before returning to Thrall in Orgrimmar.", summary = "Hmm, leaders of the Searing Blade... this concerns me most. If they are the ones of value to Neeru, then those are who we must target first. This satyr... Bazzalan, and the other Neeru mentioned--what was he, a warlock?--must be slain.$B$BReturn to the Cleft of Shadow and enter Ragefire Chasm, $N. Find these two leaders of the Searing Blade, and kill them. But be careful not to let Neeru know it was you who did this. You must retain your identity as one of his $gbrothers:sisters; in arms." },
            { ids = { 5729 }, name = "Hidden Enemies", level = 15, zone = "Orgrimmar", giver = "Thrall", giverMap = 1454, giverX = 31.7, giverY = 37.8, ender = "Neeru Fireblade", enderMap = 1454, enderX = 49.5, enderY = 50.6, objective = "Speak to Neeru Fireblade in Orgrimmar.", summary = "I think our next step should be to have you placed close to Neeru. If he is as agitated as reports suggest, then we may accomplish two things. One, you may be able to gain some greater knowledge about the Council or at least the Burning Blade, and two, he may just begin to trust you enough that he asks you to start to aid him. He may very well look at you as someone who can fill the void now that some of the leadership is in turmoil.$B$BReturn to the Cleft and speak to him again, but do not be too overt." },
            { ids = { 5730 }, name = "Hidden Enemies", level = 16, zone = "Orgrimmar", giver = "Neeru Fireblade", giverMap = 1454, giverX = 49.5, giverY = 50.6, ender = "Thrall", enderMap = 1454, enderX = 31.7, enderY = 37.8, objective = "Speak to Thrall in Orgrimmar and tell him what you've learned.", summary = "You are one of my lieutenants! Prepare yourself, $c. I will call upon you soon.$B$BMy time spent on the Searing Blade may be all but wasted now, but that does not mean that the Shadow Council's schemes elsewhere must suffer. I will do what I can to minimize the damage here in Ragefire Chasm. In the meantime, I will have my agents in the Barrens and Ashenvale begin work on our newest agenda. Return to me soon." },
        },
    },
    {
        id = "q447",
        name = "A Recipe For Death",
        zone = "Silverpine Forest",
        minLevel = 9,
        maxLevel = 18,
        importance = 2,
        kind = "world",
        quests = {
            { ids = { 447 }, name = "A Recipe For Death", level = 12, zone = "Silverpine Forest", giver = "Apothecary Renferrel", giverMap = 1421, giverX = 42.8, giverY = 40.9, ender = "Master Apothecary Faranell", enderMap = 1458, enderX = 48.8, enderY = 69.3, objective = "Collect 6 Grizzled Bear Hearts and 6 samples of Skittering Blood and deliver them to Master Apothecary Faranell in the Undercity.", summary = "Arthas's numbers are overwhelming. But with a New Plague we could eradicate both the Scourge Army and the Human infestation once and for all.$b$bMy studies have proven that spider blood combined with a toxin derived from a grizzled bear heart results in a deadly elixir. Collect samples from the spiders in the Skittering Dark to the northwest and from the bears wandering throughout Silverpine Forest. Deliver the reagents to Master Apothecary Faranell of the Royal Apothecary Society in the Undercity." },
            { ids = { 450 }, name = "A Recipe For Death", level = 15, zone = "Undercity", giver = "Master Apothecary Faranell", giverMap = 1458, giverX = 48.8, giverY = 69.3, ender = "Apothecary Renferrel", enderMap = 1421, enderX = 42.8, enderY = 40.9, objective = "Retrieve Apothecary Berard's journal from Pyrewood Village and take it to Apothecary Renferrel at the Sepulcher.", summary = "You can be of further service to the Royal Apothecary Society, $N.$b$bWhen Arugal cast his wretched magic on the forest, he cursed one of our most promising members, Apothecary Berard.  Now a mindless servant of Arugal, Berard is useless to us.  But his findings might prove to be of worth.  He was studying an ancient plague that killed off all the aquatic life in Lake Lordamere ages ago.$b$bRetrieve Berard's Journal from his study in the Pyrewood Village Inn and take it to Apothecary Renferrel." },
            { ids = { 451 }, name = "A Recipe For Death", level = 18, zone = "Silverpine Forest", giver = "Apothecary Renferrel", giverMap = 1421, giverX = 42.8, giverY = 40.9, ender = "Master Apothecary Faranell", enderMap = 1458, enderX = 48.8, enderY = 69.3, objective = "Bring 6 samples of Lake Creeper Moss, 6 samples of Lake Skulker Moss and a Hardened Tumor to Master Apothecary Faranell in the Undercity.", summary = "According to Berard's Journal the moss from Lake Skulkers and Creepers might prove useful for our quest to brew a new plague.  Those beasts dwell on the islands in Lake Lordamere to the east.$b$bHe also mentions a very rare Hardened Tumor that he discovered on a Vile Fin murloc.  Apparently the tumor is so rare Berard was only able to obtain one.$b$bCollect samples of the moss as well as the rare hardened tumor and take them to Master Apothecary Faranell in the Undercity." },
        },
    },
    {
        id = "q861",
        name = "The Hunter's Way",
        zone = "Mulgore",
        minLevel = 9,
        maxLevel = 27,
        importance = 2,
        kind = "world",
        quests = {
            { ids = { 861 }, name = "The Hunter's Way", level = 10, zone = "Mulgore", giver = "Skorn Whitecloud", giverMap = 1412, giverX = 46.0, giverY = 63.4, ender = "Melor Stonehoof", enderMap = 1456, enderX = 61.5, enderY = 80.9, objective = "Bring 4 Flatland Prowler Claws to Melor Stonehoof in Thunder Bluff.", summary = "You are eager to explore, I can tell.  I too had the lust to wander, once...$B$BWander, and hunt.  For hunting is a Tauren's greatest honor.$B$BIf you truly wish to follow the ways of the hunter, then Melor Stonehoof can show you the path.  He is in Thunder Bluff, on the Hunter's Rise.$B$BAnd to show him your skill and resolve, bring him the claws of the flatland prowlers of Mulgore.  They are tough and cunning -- fitting prey for a young $c on the hunter's path." },
            { ids = { 860 }, name = "Sergra Darkthorn", level = 10, zone = "Thunder Bluff", giver = "Melor Stonehoof", giverMap = 1456, giverX = 61.5, giverY = 80.9, ender = "Sergra Darkthorn", enderMap = 1413, enderX = 52.2, enderY = 31.0, objective = "Speak with Sergra Darkthorn at the Crossroads.", summary = "If you wish to walk the hunter's path, then your journey leads to the Barrens.  Its beasts are strong-willed and fierce.  You will learn much by hunting there, and your spirit will grow.$B$BSpeak with Sergra Darkthorn.  She will be your first guide in the Barrens.$B$BSergra is at the Crossroads.  To reach her, travel east from Bloodhoof Village into the Barrens, then north as the road forks.  And have care as you travel--the Barrens holds great danger for the unprepared and unwary." },
            { ids = { 844 }, name = "Plainstrider Menace", level = 12, zone = "The Barrens", giver = "Sergra Darkthorn", giverMap = 1413, giverX = 52.2, giverY = 31.0, ender = "Sergra Darkthorn", enderMap = 1413, enderX = 52.2, enderY = 31.0, objective = "Collect 7 Plainstrider Beaks and return them to Sergra Darkthorn in the Crossroads.", summary = "Your first prey will be easy.$B$BThe plainstriders to the east have been harassing our food supplies and have become a nuisance.$B$BPut down the plainstriders and return to me with their beaks." },
            { ids = { 845 }, name = "The Zhevra", level = 13, zone = "The Barrens", giver = "Sergra Darkthorn", giverMap = 1413, giverX = 52.2, giverY = 31.0, ender = "Sergra Darkthorn", enderMap = 1413, enderX = 52.2, enderY = 31.0, objective = "Slay Zhevra Runners to collect 4 Zhevra Hooves for Sergra Darkthorn in the Crossroads.", summary = "The zhevra, although not the fiercest beast in the Barrens, are a shade tougher than the plainstriders.  Don't worry -- we'll send you against bigger prey in good time, but for now your teeth could use a little more cutting.$B$BHunt the zhevra to the north and south, and collect their hooves.  Bring them to me and perhaps we'll next send you against something tougher." },
            { ids = { 903 }, name = "Prowlers of the Barrens", level = 15, zone = "The Barrens", giver = "Sergra Darkthorn", giverMap = 1413, giverX = 52.2, giverY = 31.0, ender = "Sergra Darkthorn", enderMap = 1413, enderX = 52.2, enderY = 31.0, objective = "Collect 7 Prowler Claws from Savannah Prowlers for Sergra Darkthorn in the Crossroads.", summary = "Now it's time to go after something that really bites.  The prowlers of the Barrens are a tough breed.  Tough, resourceful, sly... and deadly.  You'll find them among the tall grasses.  You'll find many to the southwest of the Crossroads.$B$BBe wary as you hunt them, $n, or you may find yourself no longer the predator, but instead the prey." },
            { ids = { 881 }, name = "Echeyakee", level = 16, zone = "The Barrens", giver = "Sergra Darkthorn", giverMap = 1413, giverX = 52.2, giverY = 31.0, ender = "Sergra Darkthorn", enderMap = 1413, enderX = 52.2, enderY = 31.0, objective = "Bring Echeyakee's Hide to Sergra Darkthorn at the Crossroads.", summary = "Whitemist, Echeyakee in the Tauren tongue, is the king of the savannah cats.  He hunts with such stealth, they say he's like a thin, white mist on the earth.  And he kills so fast his prey have no time for fear, or pain.$B$BThe Tauren say he is both mercy and death.$B$BYou will learn if that's true, for I now set you on the path to hunt Echeyakee.  His lair is northeast of the Crossroads, among the bones of giant Kodo$B$BGo.  Blow this horn when you reach his lair.  Blow the horn, and he will come." },
            { ids = { 905 }, name = "The Angry Scytheclaws", level = 17, zone = "The Barrens", giver = "Sergra Darkthorn", giverMap = 1413, giverX = 52.2, giverY = 31.0, ender = "Sergra Darkthorn", enderMap = 1413, enderX = 52.2, enderY = 31.0, objective = "Kill Sunscale raptors and collect their feathers. Use the feathers on the 3 Scytheclaw nests. Return to Sergra Darkthorn in the Crossroads.", summary = "Now, $N, the hunt deepens.  Now you must defeat your prey, and then find your way to its lair.$B$BHunt the sunscale raptors to the south.  Slay them and remove the feathers they wear.  Place the feathers on the scytheclaw nests southwest of the Stagnant Oasis. Show their brethren you do not fear them!" },
            { ids = { 3261 }, name = "Jorn Skyseer", level = 18, zone = "The Barrens", giver = "Sergra Darkthorn", giverMap = 1413, giverX = 52.2, giverY = 31.0, ender = "Jorn Skyseer", enderMap = 1413, enderX = 44.9, enderY = 59.1, objective = "Speak with Jorn Skyseer at Camp Taurajo.", summary = "Your time with me is over, $N.  To learn more, you must go to Camp Taurajo to the south and speak with Jorn Skyseer.  He will continue your guidance." },
            { ids = { 882 }, name = "Ishamuhale", level = 19, zone = "The Barrens", giver = "Jorn Skyseer", giverMap = 1413, giverX = 44.9, giverY = 59.1, ender = "Jorn Skyseer", enderMap = 1413, enderX = 44.9, enderY = 59.1, objective = "Bring Ishamuhale's Fang to Jorn at Camp Taurajo.", summary = "Ishamuhale, Speartooth, is the fiercest sunscale raptor of the Barrens.  He does not hunt for sport, nor for food.  He hunts because hunting is his passion.  He kills because it is his nature to kill.$B$BAnd you will learn of his nature, $N, for your path now follows the taloned tracks of Ishamuhale.$B$BBegin the hunt.  Slay his favorite prey, a zhevra, then bring its carcass to the dead tree northwest of Ratchet.  Ishamuhale will smell the carcass and be drawn to it.$B$BBe ready when he comes." },
            { ids = { 907 }, name = "Enraged Thunder Lizards", level = 18, zone = "The Barrens", giver = "Jorn Skyseer", giverMap = 1413, giverX = 44.9, giverY = 59.1, ender = "Jorn Skyseer", enderMap = 1413, enderX = 44.9, enderY = 59.1, objective = "Bring 3 Thunder Lizard Blood to Jorn Skyseer at Camp Taurajo.", summary = "Now, $N, you must face the great thunder lizards.  So large are the beasts, the ground rumbles as they stomp across the plains.  Take care as you fight them, for one false step and you may find yourself beneath their feet.$B$BYou will find the thunder lizards in the southern Barrens.  They are known as Stormsnouts, Stormhides and Thunderheads.  Return to me after you have bested them." },
            { ids = { 913 }, name = "Cry of the Thunderhawk", level = 20, zone = "The Barrens", giver = "Jorn Skyseer", giverMap = 1413, giverX = 44.9, giverY = 59.1, ender = "Jorn Skyseer", enderMap = 1413, enderX = 44.9, enderY = 59.1, objective = "Find and slay a Thunderhawk, return its wings to Jorn Skyseer at Camp Taurajo.", summary = "The thunderhawk, $N, is a fierce beast.  It is time for you to face them.  You must find where it roams, and bring me its wings as proof of your successful hunt.$B$BDo this, and your time with me will near its end." },
            { ids = { 874 }, name = "Mahren Skyseer", level = 27, zone = "The Barrens", giver = "Jorn Skyseer", giverMap = 1413, giverX = 44.9, giverY = 59.1, ender = "Mahren Skyseer", enderMap = 1413, enderX = 65.8, enderY = 43.9, objective = "Speak with Mahren Skyseer.", summary = "You have hunted the beasts of the Barrens.  Your spirit is strong.  But a hunter must always be prepared.  A true hunter can stalk prey down any path.  Mountains and swamps will not sway $ghim:her;.$B$BNot even the sea.$B$BFind my sister, Mahren.  She hunts the great water beasts along the coast.  She will be your teacher in their ways.$B$BBut be wary in your search for her, for the Barrens' coast is held by humans." },
            { ids = { 873 }, name = "Isha Awak", level = 27, zone = "The Barrens", giver = "Mahren Skyseer", giverMap = 1413, giverX = 65.8, giverY = 43.9, ender = "Mahren Skyseer", enderMap = 1413, enderX = 65.8, enderY = 43.9, objective = "Bring the Heart of Isha Awak to Mahren Skyseer.", summary = "The grand Isha Awak is lord of these waters.  Great is his strength, and solemn his pride.  The humans on the coast fear him, for he has consumed many of their number.$B$BBut I do not fear him.  I am grateful he is here.  He is a worthy challenge, and honorable prey.$B$BIf you are ready, then swim out and search for Isha Awak, the Deep Doom.$B$BHis spirit dwells in his heart, and to hear its beat is to know your fate." },
        },
    },
    {
        id = "q5761",
        name = "Slaying the Beast",
        zone = "Orgrimmar",
        minLevel = 9,
        maxLevel = 16,
        importance = 1,
        kind = "dungeon",
        quests = {
            { ids = { 5761 }, name = "Slaying the Beast", level = 16, zone = "Orgrimmar", giver = "Neeru Fireblade", giverMap = 1454, giverX = 49.5, giverY = 50.6, ender = "Neeru Fireblade", enderMap = 1454, enderX = 49.5, enderY = 50.6, objective = "Enter Ragefire Chasm and slay Taragaman the Hungerer, then bring his heart back to Neeru Fireblade in Orgrimmar.", summary = "The primary task set upon me by our great Warchief is to root out the creatures responsible for infesting our lord's great city with demonic influence. The Burning Blade is one threat, but there are others; the Searing Blade for instance, who make their home in Ragefire Chasm, secretly attempting to subvert innocent members of the Horde.$B$BIf they are to be stopped, then their leader must be slain--a Felguard named Taragaman the Hungerer.$B$BKill him, and his heart will appease Thrall, of this I'm sure." },
        },
    },
    {
        id = "q886",
        name = "Leaders of the Fang",
        zone = "Thunder Bluff",
        minLevel = 10,
        maxLevel = 22,
        importance = 3,
        kind = "dungeon",
        quests = {
            { ids = { 886 }, name = "The Barrens Oases", level = 10, zone = "Thunder Bluff", giver = "Arch Druid Hamuul Runetotem", giverMap = 1456, giverX = 78.6, giverY = 28.6, ender = "Tonga Runetotem", enderMap = 1413, enderX = 52.3, enderY = 31.9, objective = "Speak with Tonga Runetotem at the Crossroads.", summary = "The druids of Thunder Bluff sense a strange power leaking into the Barrens, east of Mulgore.$B$BTonga Runetotem was sent to discover the source of this power, but we fear he will need aid.$B$BTravel to the Barrens and speak with Tonga.  He will be at the Crossroads.  To reach there, take the road east out of Bloodhoof village.  Enter the Barrens, then turn north when the road forks.  Continue north and  you will find the Crossroads.$B$BAnd do not leave the road, $N, for the Barrens is a harsh land." },
            { ids = { 870 }, name = "The Forgotten Pools", level = 13, zone = "The Barrens", giver = "Tonga Runetotem", giverMap = 1413, giverX = 52.3, giverY = 31.9, ender = "Tonga Runetotem", enderMap = 1413, enderX = 52.3, enderY = 31.9, objective = "Report back to Tonga Runetotem with your findings.", summary = "Long ago, the Barrens was a lush place, teeming with life.  But war and cataclysm raged across the land, scorching it and leaving a dry husk.  Such is the way of things, and it saddens my heart.$B$BBut within the past few years, new oases have formed in the Barrens, and life stirs.  And deep down, we druids sense a power leaking its way to the surface.$B$BWe must find its source.  Travel to the Forgotten Pools, northwest of the Crossroads.  Search its waters for a source of power, then return here." },
            { ids = { 877 }, name = "The Stagnant Oasis", level = 16, zone = "The Barrens", giver = "Tonga Runetotem", giverMap = 1413, giverX = 52.3, giverY = 31.9, ender = "Tonga Runetotem", enderMap = 1413, enderX = 52.3, enderY = 31.9, objective = "Return to Tonga at The Crossroads, after investigating the Stagnant Oasis.", summary = "Like the one you found at the Forgotten Pools, there may be fissures at the other oases in the Barrens.  If so, then perhaps the fissures are the oases' source of life.$B$BWe must test this.$B$BHere, take these seeds.  They are dead and infertile, but take them to the Stagnant Oasis to the southeast.  If there is a fissure there, then place the seeds within it...and observe." },
            { ids = { 880 }, name = "Altered Beings", level = 16, zone = "The Barrens", giver = "Tonga Runetotem", giverMap = 1413, giverX = 52.3, giverY = 31.9, ender = "Tonga Runetotem", enderMap = 1413, enderX = 52.3, enderY = 31.9, objective = "Bring 8 Altered Snapjaw Shells to Tonga Runetotem at the Crossroads.", summary = "Your findings are incredible, $N.  These oases hold properties that must come from an outside source.  Or perhaps an inside one.$B$BI want to know how these fissures are affecting the beasts who drink from the oases' water.$B$BHunt oasis snapjaws at the Lushwater and Stagnant Oases.  Bring me their shells so I may examine them." },
            { ids = { 1489 }, name = "Hamuul Runetotem", level = 16, zone = "The Barrens", giver = "Tonga Runetotem", giverMap = 1413, giverX = 52.3, giverY = 31.9, ender = "Arch Druid Hamuul Runetotem", enderMap = 1456, enderX = 78.6, enderY = 28.6, objective = "Speak with Hamuul Runetotem", summary = "The shells you brought me have a taint, one I have never before seen.  I am certain the water of the Oases is the cause, and I can sense the confusion they cause this land.  It is as if the land dreams and cannot awake.$B$BThe Wailing Caverns must be the source of the taint.  But before you go there, speak with Hamuul Runetotem, the elder druid.  I sent word to him of the happenings in the Barrens.  He is wise, and can offer you counsel.$B$BYou will find him in Thunder Bluff, on the Elder Rise." },
            { ids = { 1490 }, name = "Nara Wildmane", level = 16, zone = "Thunder Bluff", giver = "Arch Druid Hamuul Runetotem", giverMap = 1456, giverX = 78.6, giverY = 28.6, ender = "Nara Wildmane", enderMap = 1456, enderX = 75.7, enderY = 31.6, objective = "Speak with Nara Wildmane.", summary = "I entered the land of dreams, and dreamed of a cult of druids who dwell in the Wailing Caverns.  I saw that their goals were once noble, but they have lost their way.  They are now servants of the taint seeping through the Barrens.$B$BI am old and my strength fails.  I could not long dwell in that dreaming place and know little more of the tainted druids.  But Nara is young and her spirit is fierce.  She remained in the dreaming when I fled.$B$BSpeak with Nara.  She is in the tent, over yonder." },
            { ids = { 914 }, name = "Leaders of the Fang", level = 22, zone = "Thunder Bluff", giver = "Nara Wildmane", giverMap = 1456, giverX = 75.7, giverY = 31.6, ender = "Nara Wildmane", enderMap = 1456, enderX = 75.7, enderY = 31.6, objective = "Bring the Gems of Cobrahn, Anacondra, Pythas and Serpentis to Nara Wildmane in Thunder Bluff.", summary = "The druids in the Wailing Caverns, the Druids of the Fang, are an aberration.  They were part of an order of noble druids whose plan was to heal the Barrens, but now seek to remake that land to match their own, twisted dreams.$B$BThe Druids of the Fang have four leaders, and each possesses a dream gem.  Even now their faces haunt me!  Defeat the leaders and bring me their gems, and the Barrens may again know peace.$B$BGo, $N.  You will find them lurking deep within the Wailing Caverns." },
        },
    },
    {
        id = "q437",
        name = "Rot Hide Origins",
        zone = "Silverpine Forest",
        minLevel = 10,
        maxLevel = 24,
        importance = 2,
        kind = "world",
        quests = {
            { ids = { 437 }, name = "The Dead Fields", level = 14, zone = "Silverpine Forest", giver = "High Executor Hadrec", giverMap = 1421, giverX = 43.4, giverY = 40.9, ender = "High Executor Hadrec", enderMap = 1421, enderX = 43.4, enderY = 40.9, objective = "Kill rot hide gnolls at the Dead Fields.$B$BWhen Nightlash appears, kill her.$B$BBring the Essence of Nightlash to High Executor Hadrec at the Sepulcher.", summary = "Our initial scouting reports of Silverpine show the rot hides have a base at an old farm to the north, the Dead Fields.  We have sent small assaults against them, but each time they are reinforced by the banshee Nightlash, who uses her magic to rout our forces.$B$BWe want Nightlash destroyed.$B$BGo to the Dead Fields and assault the rot hides.  If you don't see Nightlash then kill the rot hides until she appears, then defeat her.$B$BHer essence will turn to dust.  Bring me that dust as proof." },
            { ids = { 438 }, name = "The Decrepit Ferry", level = 16, zone = "Silverpine Forest", giver = "High Executor Hadrec", giverMap = 1421, giverX = 43.4, giverY = 40.9, ender = "Corpse Laden Boat", enderMap = 1421, enderX = 58.4, enderY = 34.9, objective = "Go to the Decrepit Ferry.$B$BSearch for the reason the Scourge are there.", summary = "$N, we've discovered a new hive for the Scourge: the Decrepit Ferry.  The ferry lies east of the Sepulcher, and is heavily patrolled by rot hides and other undead.$B$BThere must be a reason for the Scourge's occupation of the area.  Go to the Decrepit Ferry and find out why the Scourge are there." },
            { ids = { 439 }, name = "Rot Hide Clues", level = 16, zone = "Silverpine Forest", giver = "Corpse Laden Boat", giverMap = 1421, giverX = 58.4, giverY = 34.9, ender = "High Executor Hadrec", enderMap = 1421, enderX = 43.4, enderY = 40.9, objective = "Bring Deliah's Ring to High Executor Hadrec at the Sepulcher.", summary = "Among the corpses a hand protrudes, unwrapped.  It is the hand of a woman, pockmarked from the plague but relatively fresh.  $B$BOn the hand is a ring.  Removing the ring and inspecting it reveals an engraving:$B$B\"For Deliah\"" },
            { ids = { 443 }, name = "Rot Hide Ichor", level = 17, zone = "Silverpine Forest", giver = "High Executor Hadrec", giverMap = 1421, giverX = 43.4, giverY = 40.9, ender = "Apothecary Renferrel", enderMap = 1421, enderX = 42.8, enderY = 40.9, objective = "Bring 8 bottles of rot hide ichor to Apothecary Renferrel at the Sepulcher.", summary = "Before we launch an assault on Fenris Isle, we must determine who is behind the rot hide gnolls.  Our apothecaries believe their origin lies within the strange fluid that flows through their bodies.$B$BGo to Fenris Isle, east of the Decrepit Ferry, and collect rot hide ichor from the gnolls you find there.  Bring it to Apothecary Renferrel, stationed outside the Sepulcher." },
            { ids = { 444 }, name = "Rot Hide Origins", level = 17, zone = "Silverpine Forest", giver = "Apothecary Renferrel", giverMap = 1421, giverX = 42.8, giverY = 40.9, ender = "Bethor Iceshard", enderMap = 1458, enderX = 84.1, enderY = 17.4, objective = "Bring the Sample Ichor to Bethor Iceshard in the Undercity.", summary = "I have reduced the ichor you brought me and separated it into its base components.  My findings are not conclusive, but I have determined that warlock and necromantic magics were used in the ichor's creation.$B$BWhile I continue to study the ichor, I want you to take a sample to Bethor Iceshard in the Undercity.  Bethor is not an apothecary, but his knowledge of magic may help to unravel the mystery of the rot hides.$B$BGo.  You will find Bethor in the Magic Quarter of the Undercity." },
            { ids = { 446 }, name = "Thule Ravenclaw", level = 16, zone = "Undercity", giver = "Bethor Iceshard", giverMap = 1458, giverX = 84.1, giverY = 17.4, ender = "Apothecary Renferrel", enderMap = 1421, enderX = 42.8, enderY = 40.9, objective = "Bring Bethor's Scroll to Apothecary Renferrel at the Silverpine Sepulcher.", summary = "This Ichor was crafted by an old colleague of mine: Thule Ravenclaw.  He was a young, promising mage before the great war, but when the Lich King rose to power, he betrayed his brethren and allied with the Scourge.$B$BI did not realize he still lives, nor that he leads the Rot Hides in their forays against us!$B$BI know many of his spells, and can help concoct a potion to counter them.  Take this scroll back to Apothecary Renferrel.  It has the incantations needed for the potion." },
            { ids = { 448 }, name = "Report to Hadrec", level = 16, zone = "Silverpine Forest", giver = "Apothecary Renferrel", giverMap = 1421, giverX = 42.8, giverY = 40.9, ender = "High Executor Hadrec", enderMap = 1421, enderX = 43.4, enderY = 40.9, objective = "Report to High Executor Hadrec at the Sepulcher.", summary = "Before you launch an assault on Fenris Isle, report to High Executor Hadrec.  He may have additional information or equipment you'll need." },
            { ids = { 442 }, name = "Assault on Fenris Isle", level = 24, zone = "Silverpine Forest", giver = "High Executor Hadrec", giverMap = 1421, giverX = 43.4, giverY = 40.9, ender = "High Executor Hadrec", enderMap = 1421, enderX = 43.4, enderY = 40.9, objective = "Bring Thule's Head to High Executor Hadrec at the Sepulcher.", summary = "Now is the time to assault the Scourge's place of strength in Silverpine: Fenris Isle.$B$BYou must again go to the Isle and destroy Thule Ravenclaw.  I want his head!$B$BThis mission is as dangerous as it is vital, $N.  You must not fail." },
        },
    },
    {
        id = "q5926",
        name = "Body and Heart",
        zone = "Thunder Bluff",
        minLevel = 10,
        maxLevel = 10,
        importance = 2,
        kind = "class",
        races = { 6 },
        classes = { 11 },
        quests = {
            { ids = { 5926 }, name = "Heeding the Call", level = 10, zone = "Thunder Bluff", giver = "Innkeeper Pala", giverMap = 1456, giverX = 45.8, giverY = 64.7, ender = "Turak Runetotem", enderMap = 1456, enderX = 76.5, enderY = 27.2, objective = "Speak with Turak Runetotem on the Elder Rise of Thunder Bluff.", summary = "Excuse me, friend...$B$BIt has come to my attention that Turak Runetotem has put out word that he wishes to speak with you.  It seems that your training as a druid is about to take on a new life, and he will be training you personally.  Turak is one of the Arch Druid's assistants; he is known as a wise and patient druid, and he should teach you well.$B$BHe is located in Thunder Bluff, inside the Cenarion Circle's main tent on the Elder Rise." },
            { ids = { 5922 }, name = "Moonglade", level = 10, zone = "Thunder Bluff", giver = "Turak Runetotem", giverMap = 1456, giverX = 76.5, giverY = 27.2, ender = "Dendrite Starblaze", enderMap = 1450, enderX = 56.2, enderY = 30.6, objective = "Use the spell \"Teleport: Moonglade\" to travel to Moonglade.  When you arrive, speak with Dendrite Starblaze in the village of Nighthaven.", summary = "All druids are welcomed to the sacred lands of Moonglade, tauren and night elf alike.  Keeper Remulos - Moonglade's guardian - keeps watch over all druids who hibernate there.  Now that you're learning the ways of the Claw, I'll teach you the spell that lets you transport yourself there.  Cast it whenever you seek Moonglade's knowledge or solace.$B$BAs for your first lesson, travel to Moonglade and speak with Dendrite Starblaze in Nighthaven about the path you're now on.  Good luck, young druid." },
            { ids = { 5930 }, name = "Great Bear Spirit", level = 10, zone = "Moonglade", giver = "Dendrite Starblaze", giverMap = 1450, giverX = 56.2, giverY = 30.6, ender = "Dendrite Starblaze", enderMap = 1450, enderX = 56.2, enderY = 30.6, objective = "Seek out the Great Bear Spirit in northwestern Moonglade and learn what it has to share with you about the nature of the bear.  When finished, return to Dendrite Starblaze in Nighthaven, Moonglade.", summary = "In the northwest part of Moonglade resides the home of a wise and noble being we call the Great Bear Spirit.  For all druids, it has served as a tutor and mentor into the first true natural understanding of the bear.  All druids at one point seek the spirit's wisdom, and you shall be no exception.$B$BGo to the Great Bear Spirit now and learn what it will teach.  When it is satisfied with you, return to me here in Nighthaven.  We will then see if you have truly taken account of the lessons it teaches." },
            { ids = { 5932 }, name = "Back to Thunder Bluff", level = 10, zone = "Moonglade", giver = "Dendrite Starblaze", giverMap = 1450, giverX = 56.2, giverY = 30.6, ender = "Turak Runetotem", enderMap = 1456, enderX = 76.5, enderY = 27.2, objective = "Return to Thunder Bluff and speak with Turak Runetotem on the Elder Rise.", summary = "The time has come for us to part ways, young one, as the application of your lessons takes you back to whom that sent you to me.  Though the tauren are thought to be young in the ways of Cenarius, Turak Runetotem walks with much balance in the presence of nature.  Listen to his instructions, and you will soon complete your first lessons into your role as a protector of balance.$B$BGo now, young one.  We shall meet again." },
            { ids = { 6002 }, name = "Body and Heart", level = 10, zone = "Thunder Bluff", giver = "Turak Runetotem", giverMap = 1456, giverX = 76.5, giverY = 27.2, ender = "Turak Runetotem", enderMap = 1456, enderX = 76.5, enderY = 27.2, objective = "Use the Cenarion Lunardust on the Moonkin Stone between Mulgore and the Barrens to bring forth Lunaclaw.  From there, you must face Lunaclaw and earn the strength of body and heart it possesses.$B$BSpeak with Turak Runetotem in Thunder Bluff when you are done.", summary = "On land west of Taurajo in the Barrens - just before it turns into Mulgore - lies a Moonkin Stone.  The moonkin are special beasts, not native to these parts.  Lunaclaw, the stone's defender, will face you when Cenarion Lunardust is applied to it.  Lunaclaw possesses within it a strength that you must use as one of the Claw.$B$BYou've earned the right to use this Cenarion Lunardust, $N... now show me that you've earned the right to possess the strength of body and the strength of heart needed as a druid!" },
        },
    },
    {
        id = "q1885",
        name = "The Deathstalkers",
        zone = "Tirisfal Glades",
        minLevel = 10,
        maxLevel = 13,
        importance = 2,
        kind = "class",
        races = { 5 },
        classes = { 4 },
        quests = {
            { ids = { 1885 }, name = "Mennet Carkad", level = 10, zone = "Tirisfal Glades", giver = "Marion Call", giverMap = 1420, giverX = 61.8, giverY = 52, ender = "Mennet Carkad", enderMap = 1458, enderX = 83.5, enderY = 69.1, objective = "Speak with Mennet Carkad in the Rogues' Quarter of the Undercity.", summary = "$n? Not quite what I was expecting, considering Carkad himself has taken an interest to you. Looks can be deceiving though, right?$b$bEither way, you should go see him as soon as possible. You wouldn't want to know what happened to the last few that chose to ignore his summons." },
            { ids = { 1886 }, name = "The Deathstalkers", level = 13, zone = "Undercity", giver = "Mennet Carkad", giverMap = 1458, giverX = 83.5, giverY = 69.1, ender = "Mennet Carkad", enderMap = 1458, enderX = 83.5, enderY = 69.1, objective = "Get Astor's Letter of Introduction and return it to Mennet Carkad in the Rogues' Quarter.", summary = "If you wish to join the Deathstalkers, Lord Varimathras' elite guard, you will have to prove your worth.$b$bI will not lie to you, $n, this task could mean your death.$b$bI have some things that need attending to. I require the personal effects of Astor Hadren, a messenger who travels between Silverpine and the Undercity. I will leave the method of procurement to your discretion.$b$bIt will be better for you if you know less of the nature of this business. Succeed and I shall tell you more." },
            { ids = { 1898 }, name = "The Deathstalkers", level = 13, zone = "Undercity", giver = "Mennet Carkad", giverMap = 1458, giverX = 83.5, giverY = 69.1, ender = "Andron Gant", enderMap = 1458, enderX = 54.8, enderY = 76.3, objective = "Speak with Andron Gant in the Undercity.", summary = "The letter of introduction should be enough to convince Andron that you are the messenger he's been waiting for. I've met Andron before, he doesn't quite have the mental capacity to be that suspicious.$b$bLord Varimathras suspects that Andron has been providing aid to some other group. He wishes to know what organization this is and requires proof of it.$b$bI want you to speak with Andron, and obtain this information. You'll find him at his shop near the Apothecarium." },
            { ids = { 1899 }, name = "The Deathstalkers", level = 13, zone = "Undercity", giver = "Andron Gant", giverMap = 1458, giverX = 54.8, giverY = 76.3, ender = "Mennet Carkad", enderMap = 1458, enderX = 83.5, enderY = 69.1, objective = "Bring Astor's Ledger to Mennet Carkad in the Rogues' Quarter of Undercity.", summary = "You'll find the ledger with the information your employers seek on the bookshelf behind me. Deliver it with my regards, and tell them that I would prefer it if they sent you, if they find enough value that they should wish to continue our arrangement." },
            { ids = { 1978 }, name = "The Deathstalkers", level = 13, zone = "Undercity", giver = "Mennet Carkad", giverMap = 1458, giverX = 83.5, giverY = 69.1, ender = "Varimathras", enderMap = 1458, enderX = 56.2, enderY = 92.2, objective = "Deliver Andron's Ledger to Varimathras in the Hall of the Dark Lady in the Undercity.", summary = "The Syndicate? I would never have suspected. It seems the lords of Alterac have fallen far in the years since their betrayal.$b$bLord Varimathras will be pleased to learn of this, and as you were so instrumental in this discovery, it would be fitting if you were the one to deliver it to him.$b$bAh, and how could I forget?$b$bWelcome to the Deathstalkers." },
        },
    },
    {
        id = "q1523",
        name = "Call of Fire",
        zone = "Thunder Bluff",
        minLevel = 10,
        maxLevel = 13,
        importance = 2,
        kind = "class",
        classes = { 7 },
        quests = {
            { ids = { 1523 }, name = "Call of Fire", level = 10, zone = "Thunder Bluff", giver = "Xanis Flameweaver", giverMap = 1456, giverX = 25.2, giverY = 20.5, ender = "Kranal Fiss", enderMap = 1413, enderX = 56.0, enderY = 19.9, objective = "Find Kranal Fiss in the Barrens.", summary = "Long has it been since you were last tested, $N. You have shown patience thus far in your studies, but the time has come for you to learn more. The time has come for you to learn about destruction... and chaos. The element of fire is yours for the understanding, if you're prepared to pay for it.$B$BSeek out Kranal Fiss in the Barrens. He lives in a small dwelling north of the Crossroads, but be mindful, if you've reached the night elf lands, you've gone too far." },
            { ids = { 1524 }, name = "Call of Fire", level = 11, zone = "The Barrens", giver = "Kranal Fiss", giverMap = 1413, giverX = 56.0, giverY = 19.9, ender = "Telf Joolam", enderMap = 1411, enderX = 38.5, enderY = 59.0, objective = "Bring the Torch of the Dormant Flame to Telf Joolam in Durotar.", summary = "You are powerful enough to wield the totem of fire, but that does not mean you are ready.$B$BAlong the Southfury River in Durotar, before the Great Sea, lies a hidden trail to one of the highest peaks in the land. Find your way to the top and you shall find one of our holy shrines watched over by Telf Joolam--the Shrine of the Dormant Flame.$B$BTake this torch to him--it marks that you attempt to tame fire. Return it to me aflame by the brazier at the shrine and I will see you are given the totem of fire." },
            { ids = { 1525 }, name = "Call of Fire", level = 12, zone = "Durotar", giver = "Telf Joolam", giverMap = 1411, giverX = 38.5, giverY = 59.0, ender = "Telf Joolam", enderMap = 1411, enderX = 38.5, enderY = 59.0, objective = "Bring 1 Fire Tar and 1 Reagent Pouch to Telf Joolam in Durotar.", summary = "But you did not come here for a history lesson, did you? You came for the Eternal Flame and fire totem.$B$BThe first step is to create a sapta and bind you to the flame.$B$BI can create the fire sapta for you if you bring me two items. The first is fire tar, a simple item usually carried by Razormane spellcasters in eastern Barrens.$B$BThe second item will be more dangerous: a reagent pouch from one of the cultists of the Burning Blade. You can find them in a cave above the ravines northeast of Razor Hill." },
            { ids = { 1526 }, name = "Call of Fire", level = 13, zone = "Durotar", giver = "Telf Joolam", giverMap = 1411, giverX = 38.5, giverY = 59.0, ender = "Brazier of the Dormant Flame", enderMap = 1411, enderX = 39.0, enderY = 58.2, objective = "Defeat the Minor Manifestation of Fire, and place the Glowing Ember in the brazier atop the Shrine of Eternal Flame.", summary = "The fire sapta is finished. The time has come for you to face the flame. Use the sapta at the shrine and head to the top of the mountain to face the manifestation there. He will not attack until you are ready, but he will realize you are able to see him.$B$BStrike him down swiftly, $N, for he shall only grow in power the longer you take to slay him. Once he is defeated, place his glowing embers within the brazier and light the torch." },
            { ids = { 1527 }, name = "Call of Fire", level = 13, zone = "Durotar", giver = "Brazier of the Dormant Flame", giverMap = 1411, giverX = 39.0, giverY = 58.2, ender = "Kranal Fiss", enderMap = 1413, enderX = 56.0, enderY = 19.9, objective = "Bring the Torch of Eternal Flame to Kranal Fiss in the Barrens.", summary = "Torch firmly in hand, you turn away from the brazier and look out over Durotar. You feel an excitement tugging at your spirit as the wind picks up and forces the flame to dance violently.$B$BYou start off down the path back to the Barrens in search of Kranal Fiss." },
        },
    },
    {
        id = "q6065",
        name = "Training the Beast",
        zone = "Thunder Bluff",
        minLevel = 10,
        maxLevel = 10,
        importance = 2,
        kind = "class",
        races = { 6 },
        classes = { 3 },
        quests = {
            { ids = { 6065 }, name = "The Hunter's Path", level = 10, zone = "Thunder Bluff", giver = "Kary Thunderhorn", giverMap = 1456, giverX = 58.5, giverY = 88.3, ender = "Yaw Sharpmane", enderMap = 1412, enderX = 46.9, enderY = 59.7, objective = "Speak with Yaw Sharpmane in Bloodhoof Village.", summary = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.$B$BYou must see Yaw Sharpmane in Bloodhoof Village. He can put you on the path to earning a pet of your own." },
            { ids = { 6061 }, name = "Taming the Beast", level = 10, zone = "Mulgore", giver = "Yaw Sharpmane", giverMap = 1412, giverX = 46.9, giverY = 59.7, ender = "Yaw Sharpmane", enderMap = 1412, enderX = 46.9, enderY = 59.7, objective = "Use the Taming Rod to tame an Adult Plainstrider. Practice your skills, then return the Taming Rod to Yaw Sharpmane in Bloodhoof Village.", summary = "As a tauren, it is important to follow the traditions of our ancestors by fighting mighty creatures. By besting these creatures, we are able to intake their spirits, allowing us to become closer to the Earthmother.$B$BIn the same way, taming a beast to fight alongside us helps us become one with nature around us. Eventually, you will learn to tame a beast of your choosing. But all things take practice, and you have much to learn. Begin by taking this taming rod; you must tame an adult plainstrider." },
            { ids = { 6087 }, name = "Taming the Beast", level = 10, zone = "Mulgore", giver = "Yaw Sharpmane", giverMap = 1412, giverX = 46.9, giverY = 59.7, ender = "Yaw Sharpmane", enderMap = 1412, enderX = 46.9, enderY = 59.7, objective = "Use the Taming Rod to tame a Prairie Stalker. Practice your skills, then return the Taming Rod to Yaw Sharpmane in Bloodhoof Village.", summary = "You have a fiery spirit, hunter, readily awaiting your next challenge.$B$BYour next task is to gain the companionship of a wolf known as the prairie stalker. This creature is swift and fearless; in taking this beast as your pet, you must also take on these qualities.$B$BDuring a battle, you will learn how you and your pet will become a team. In the end you must work as one, muscle to muscle.$B$BHere is the taming rod, $N. Tame a prairie stalker and practice your skills." },
            { ids = { 6088 }, name = "Taming the Beast", level = 10, zone = "Mulgore", giver = "Yaw Sharpmane", giverMap = 1412, giverX = 46.9, giverY = 59.7, ender = "Yaw Sharpmane", enderMap = 1412, enderX = 46.9, enderY = 59.7, objective = "Use the Taming Rod to tame a Swoop. Practice your skills, then return the Taming Rod to Yaw Sharpmane in Bloodhoof Village.", summary = "The final task that I have for you requires that you tame a creature that inhabits the sky. The swoop is a difficult opponent, but as your ally, you will acquire its sharp attacks and threatening presence.$B$BBy the will of the Earthmother, when you return I will bestow you with the skills you will need to tame an animal of your choosing to be your companion; this creature will face the challenges you face, and gain experience alongside you. I will also show you how to call it and dismiss it as you wish." },
            { ids = { 6089 }, name = "Training the Beast", level = 10, zone = "Mulgore", giver = "Yaw Sharpmane", giverMap = 1412, giverX = 46.9, giverY = 59.7, ender = "Holt Thunderhorn", enderMap = 1456, enderX = 57.3, enderY = 89.8, objective = "Speak with Holt Thunderhorn on Hunter Rise in Thunder Bluff.", summary = "You now have the power to tame a pet, but you must also gain the skills to train it.$B$BTravel to Thunder Bluff. There you must speak to one of our most revered hunters, Holt Thunderhorn. If he deems you worthy, he will give you the ability to train your new pet.$B$BHolt has bested the most powerful and feared beasts of Azeroth, and commands many strong creatures of his own. His ties to the Earthmother are strong, and you can learn much from him. Good luck, $N." },
        },
    },
    {
        id = "q894",
        name = "Samophlange",
        zone = "The Barrens",
        minLevel = 10,
        maxLevel = 19,
        importance = 2,
        kind = "world",
        quests = {
            { ids = { 894 }, name = "Samophlange", level = 14, zone = "The Barrens", giver = "Sputtervalve", giverMap = 1413, giverX = 63.0, giverY = 37.2, ender = "Control Console", enderMap = 1413, enderX = 52.4, enderY = 11.7, objective = "Access the control console at the Venture Company research site.", summary = "The Venture Company set up a small research facility far to the north of here, southwest of the Sludge Fen. I don't know very much about what they're doing, but did manage to discover that they're experimenting with something called a \"samophlange\".$b$bNow what the heck is a samophlange? Well, whatever it is, I want to examine it, so I need someone to go get it.$b$bI obtained a copy of their control system operating manual, you should be able to figure out how to disengage the samophlange from it." },
            { ids = { 900 }, name = "Samophlange", level = 14, zone = "The Barrens", giver = "Control Console", giverMap = 1413, giverX = 52.4, giverY = 11.7, ender = "Control Console", enderMap = 1413, enderX = 52.4, enderY = 11.7, objective = "Close off the Fuel Control Valve, the Regulator Valve and the Main Control Valve then use the control console again.", summary = "The three control valves are currently opened. The various readings on the control panel lead you to presume that they must be shut off before the apparatus can be shut off." },
            { ids = { 901 }, name = "Samophlange", level = 14, zone = "The Barrens", giver = "Control Console", giverMap = 1413, giverX = 52.4, giverY = 11.7, ender = "Control Console", enderMap = 1413, enderX = 52.4, enderY = 11.7, objective = "Get the Console Key from Tinkerer Sniggles to use on the control console.", summary = "With the apparatus deactivated, the control panel can be opened up and the samophlange removed from the console. With everything else in place, all that is left is to acquire the key to unlock the console." },
            { ids = { 902 }, name = "Samophlange", level = 16, zone = "The Barrens", giver = "Control Console", giverMap = 1413, giverX = 52.4, giverY = 11.7, ender = "Sputtervalve", enderMap = 1413, enderX = 63.0, enderY = 37.2, objective = "Return the Samophlange to Sputtervalve in Ratchet.", summary = "Pulling open the face of the control console reveals a dense jumble of wires, tubing and other strange mechanical objects--most of which seem to serve no practical purpose. Pushing them aside and digging deeper into the console, you find the samophlange. A tug removes it from its housing." },
            { ids = { 3921 }, name = "Wenikee Boltbucket", level = 14, zone = "The Barrens", giver = "Sputtervalve", giverMap = 1413, giverX = 63.0, giverY = 37.2, ender = "Wenikee Boltbucket", enderMap = 1413, enderX = 49.0, enderY = 11.2, objective = "Bring the Broken Samophlange to Wenikee Boltbucket.", summary = "I think I might have broken that Samophlange.  That's not good, because I already told some colleagues in Undermine about it and they were very intrigued.  We must find a way to fix it!$B$BTake the broken samophlange to Wenikee Boltbucket, just south of Mor'shan Rampart, the horde outpost between the Barrens and Ashenvale.  She is very clever and inquisitive.  If you show her the samophlange I bet she'd jump at the chance to fix it." },
            { ids = { 3922 }, name = "Nugget Slugs", level = 15, zone = "The Barrens", giver = "Wenikee Boltbucket", giverMap = 1413, giverX = 49.0, giverY = 11.2, ender = "Wenikee Boltbucket", enderMap = 1413, enderX = 49.0, enderY = 11.2, objective = "Bring 15 Nugget Slugs to Wenikee Boltbucket in the Barrens.", summary = "I want to fix this samophlange, but to do that I'm going to need some supplies.  I ran out of seventeen-point-five gauge nugget slugs and I'm going to need a bunch of those for the work ahead.$B$BThe closest place to get them is the Sludge Fen to the east.  The Venture Company usually keeps them in their tool buckets.  Go to the Sludge Fen and look in the tool buckets you find there, then return to me when you've gathered enough nugget slugs." },
            { ids = { 3923 }, name = "Rilli Greasygob", level = 18, zone = "The Barrens", giver = "Wenikee Boltbucket", giverMap = 1413, giverX = 49.0, giverY = 11.2, ender = "Rilli Greasygob", enderMap = 1454, enderX = 76.5, enderY = 24.4, objective = "Bring the Broken and Battered Samophlange to Rilli Greasygob in Orgrimmar.", summary = "Well, that didn't work.  I put some extra gauges on the samophlange to measure its structural integrity, and they read the integrity at an all-time low.  I could add some more dials and maybe a lever or two to try and fix it, but... I think that might make things even worse.$B$BYou should take the samophlange to Rilli Greasygob.  He used to work for the Venture Company -- if anyone knows how to fix it, it's Rilli.$B$BYou can find him at Nogg's Machine Shop in Orgrimmar, in the Valley of Honor." },
            { ids = { 3924 }, name = "Samophlange Manual", level = 19, zone = "Orgrimmar", giver = "Rilli Greasygob", giverMap = 1454, giverX = 76.5, giverY = 24.4, ender = "Rilli Greasygob", enderMap = 1454, enderX = 76.5, enderY = 24.4, objective = "Bring the Samophlange Manual to Rilli Greasygob in Orgrimmar.", summary = "I think I can fix the samophlange, but I'm going to need the user's manual first.  When I was in the Venture Company I had a rival, Boss Copperplug, who hoarded the secrets of the samophlange, giving out small bits of knowledge on the device to those he trusted.  I wasn't one of the trusted few...$B$BBoss Copperplug used to stay at the Boulder Lode Mine in northeastern Barrens.  Get the manual from him, and if he's given pages from it to anyone, you'll have to collect them too." },
        },
    },
    {
        id = "q1818",
        name = "Ulag the Cleaver",
        zone = "Tirisfal Glades",
        minLevel = 10,
        maxLevel = 11,
        importance = 2,
        kind = "class",
        classes = { 1 },
        quests = {
            { ids = { 1818 }, name = "Speak with Dillinger", level = 10, zone = "Tirisfal Glades", giver = "Austil de Mon", giverMap = 1420, giverX = 61.9, giverY = 52.5, ender = "Deathguard Dillinger", enderMap = 1420, enderX = 58.2, enderY = 51.5, objective = "Speak with Deathguard Dillinger in Brill.", summary = "I was told Deathguard Dillinger has a job for someone like you.  If you're willing to show your value to the Dark Lady's forces, then report to Dillinger immediately.$B$BDeathguard Dillinger's post is on the west end of Brill, near the graveyard." },
            { ids = { 1819 }, name = "Ulag the Cleaver", level = 10, zone = "Tirisfal Glades", giver = "Deathguard Dillinger", giverMap = 1420, giverX = 58.2, giverY = 51.5, ender = "Deathguard Dillinger", enderMap = 1420, enderX = 58.2, enderY = 51.5, objective = "Kill Ulag the Cleaver, then speak with Deathguard Dillinger.", summary = "When the Scourge swept through Tirisfal Glades, we captured one to study.  He had a free mind, and called himself Ulag the Cleaver.  But, although his will was free, he was still enthralled by the Lich King.$B$BWe hoped to find a way to break the king's control over Ulag, but we failed.  Now, finally, it is time to free him.  $B$BFree him, and kill him.$B$BActivate the skull stone trigger near the mausoleum to the north.  This will lift the magical seal that binds him.$B$BThen... be ready, $N." },
            { ids = { 1820 }, name = "Speak with Coleman", level = 10, zone = "Tirisfal Glades", giver = "Deathguard Dillinger", giverMap = 1420, giverX = 58.2, giverY = 51.5, ender = "Coleman Farthing", enderMap = 1420, enderX = 61.7, enderY = 52.3, objective = "Speak with Coleman Farthing.", summary = "You have proven your value to the Dark Lady, now perhaps you can prove yourself to one of her subjects.$B$BColeman Farthing awaits a warrior who is willing to be his instrument of revenge against the Forsaken's enemies.$B$BYou will find him in the Gallow's End Tavern in eastern Brill." },
            { ids = { 1821 }, name = "Agamand Heirlooms", level = 11, zone = "Tirisfal Glades", giver = "Coleman Farthing", giverMap = 1420, giverX = 61.7, giverY = 52.3, ender = "Coleman Farthing", enderMap = 1420, enderX = 61.7, enderY = 52.3, objective = "Bring Coleman Farthing the Agamand Family Axe, the Agamand Family Sword, the Agamand Family Mace and the Agamand Family dagger.", summary = "The Agamand family were my employers in life, and they were the cause of my death!  It is fitting that the Agamands are now mindless minions of the Lich King.$B$BNow I would have their last vestiges of honor.  Go into their family crypt and rob them of their family heirlooms: a sword, an axe, a dagger and a mace.  Bring them to me!$B$BThe Agamand family crypt is at the north end of the Agamand mills, protected by lurking scourge and dead Agamands." },
            { ids = { 1822 }, name = "Heirloom Weapon", level = 11, zone = "Tirisfal Glades", giver = "Coleman Farthing", giverMap = 1420, giverX = 61.7, giverY = 52.3, ender = "Coleman Farthing", enderMap = 1420, enderX = 61.7, enderY = 52.3 },
        },
    },
    {
        id = "q1506",
        name = "Creature of the Void",
        zone = "Durotar",
        minLevel = 10,
        maxLevel = 11,
        importance = 2,
        kind = "class",
        races = { 2 },
        classes = { 9 },
        quests = {
            { ids = { 1506 }, name = "Gan'rul's Summons", level = 10, zone = "Durotar", giver = "Ophek", giverMap = 1411, giverX = 54.4, giverY = 41.3, ender = "Gan'rul Bloodeye", enderMap = 1454, enderX = 48.2, enderY = 45.3, objective = "Speak with Gan'rul Bloodeye in Orgrimmar.", summary = "You there. $n, right?$b$bI hope your schedule isn't busy, because Gan'rul wants to see you right away. You'll find him with the senior warlocks in the Cleft of Shadow.$b$bBased on my past dealings with Gan'rul, your summons is either a very good thing or a very bad thing." },
            { ids = { 1501 }, name = "Creature of the Void", level = 11, zone = "Orgrimmar", giver = "Gan'rul Bloodeye", giverMap = 1454, giverX = 48.2, giverY = 45.3, ender = "Gan'rul Bloodeye", enderMap = 1454, enderX = 48.2, enderY = 45.3, objective = "Retrieve the Tablet of Verga for Gan'rul Bloodeye in Orgrimmar.", summary = "So few warlocks remain... We risk much, but the risks are warranted. You must quickly reach maturity in your ability if you are to be of use to the Horde and to the Warchief.$b$bIt is time that you learned a new summoning spell.$b$bFirst, you must recover the Tablet of Verga, which was stolen by warlocks of the Burning Blade and is now kept at their lair in Skull Rock to the east of the city. With the tablet, I will show you the runes necessary to summoning a voidwalker." },
            { ids = { 1504 }, name = "The Binding", level = 11, zone = "Orgrimmar", giver = "Gan'rul Bloodeye", giverMap = 1454, giverX = 48.2, giverY = 45.3, ender = "Gan'rul Bloodeye", enderMap = 1454, enderX = 48.2, enderY = 45.3, objective = "Using the Glyphs of Summoning, summon and subdue a voidwalker, then return the Glyphs of Summoning to Gan'rul Bloodeye in Orgrimmar.", summary = "Now, observe the Tablet of Verga, for it contains the glyphs you will need for the summoning. Take them to the circle in Neeru Fireblade's tent on the other side of the cavern. There you will be able to call for the voidwalker.$b$bYou must defeat it using whatever physical and magical means you have at your disposal. When this is completed, return to me with the glyphs of summoning and I will demonstrate how you may bind the creature to your will." },
        },
    },
    {
        id = "q6068",
        name = "Training the Beast",
        zone = "Orgrimmar",
        minLevel = 10,
        maxLevel = 10,
        importance = 2,
        kind = "class",
        races = { 2, 8 },
        classes = { 3 },
        quests = {
            { ids = { 6068 }, name = "The Hunter's Path", level = 10, zone = "Orgrimmar", giver = "Sian'dur", giverMap = 1454, giverX = 68.0, giverY = 17.8, ender = "Thotar", enderMap = 1411, enderX = 51.9, enderY = 43.5, objective = "Speak with Thotar at Razor Hill.", summary = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.$B$BYou must see Thotar at Razor Hill. He can put you on the path to earning a pet of your own." },
            { ids = { 6062 }, name = "Taming the Beast", level = 10, zone = "Durotar", giver = "Thotar", giverMap = 1411, giverX = 51.9, giverY = 43.5, ender = "Thotar", enderMap = 1411, enderX = 51.9, enderY = 43.5, objective = "Use the Taming Rod to tame a Dire Mottled Boar. Practice your skills, then return the Taming Rod to Thotar in Razor Hill.", summary = "It is an admirable skill to command one's authority over nature. As a hunter, you must strive to learn to use the force and power inherent to any creature of your choosing.$B$BGaining control of an animal is not an easy feat; it is a task that you must undertake with much determination.$B$BFor your first assignment, take this taming rod and use it to tame a dire mottled boar. You can find them quite close to Razor Hill. Practice your skills in battle with the boar at your side, then return to me." },
            { ids = { 6083 }, name = "Taming the Beast", level = 10, zone = "Durotar", giver = "Thotar", giverMap = 1411, giverX = 51.9, giverY = 43.5, ender = "Thotar", enderMap = 1411, enderX = 51.9, enderY = 43.5, objective = "Use the Taming Rod to tame a Surf Crawler. Practice your skills, then return the Taming Rod to Thotar at Razor Hill.", summary = "The advantage a pet affords you against your rivals is duly noted, $N. When you gain control over another creature, you are adding to your own strength. Your pet must become an extension of yourself.$B$BThe next task requires you to turn from the land; you will find the next creature in the waters off the coast. Across from Sen'jin Village, near the Echo Isles. look for a spirited crab called the surf crawler. Use the taming rod to tame it, then practice your skills." },
            { ids = { 6082 }, name = "Taming the Beast", level = 10, zone = "Durotar", giver = "Thotar", giverMap = 1411, giverX = 51.9, giverY = 43.5, ender = "Thotar", enderMap = 1411, enderX = 51.9, enderY = 43.5, objective = "Use the Taming Rod to tame an Armored Scorpid. Practice your skills, then return to Thotar at Razor Hill.", summary = "The final creature you need to tame is one you should strive to emulate; the armored scorpid. It strikes quickly and confidently; to control a force such as this is your fate as a hunter.$B$BWhen you return, I will bestow you with the skills you will need to tame an animal of your choosing; this creature will be yours to command. Under your control, your pet will gain experience alongside you. I will also show you how to call it and dismiss it as you wish." },
            { ids = { 6081 }, name = "Training the Beast", level = 10, zone = "Durotar", giver = "Thotar", giverMap = 1411, giverX = 51.9, giverY = 43.5, ender = "Ormak Grimshot", enderMap = 1454, enderX = 66.0, enderY = 18.5, objective = "Speak with Ormak Grimshot in Orgrimmar.", summary = "You now have the power to tame a pet, but you must also gain the skills to train it.$B$BTravel to Orgrimmar. There you must speak to one of our most revered hunters, Ormak Grimshot. He will give you the ability to train your new pet. You will find him near the Hall of the Brave.$B$BGood luck, $N." },
        },
    },
    {
        id = "q428",
        name = "Wild Hearts",
        zone = "Silverpine Forest",
        minLevel = 10,
        maxLevel = 12,
        importance = 1,
        kind = "world",
        quests = {
            { ids = { 428 }, name = "Lost Deathstalkers", level = 12, zone = "Silverpine Forest", giver = "High Executor Hadrec", giverMap = 1421, giverX = 43.4, giverY = 40.9, ender = "Rane Yorick", enderMap = 1421, enderX = 53.5, enderY = 13.4, objective = "Find the Deathstalkers Quinn and Rane Yorick.", summary = "A couple weeks ago two of our Deathstalkers, Rane and Quinn Yorick, were sent on a reconnaissance mission through northern Silverpine.  We have not heard from them.$B$BThey may have become victim to the Scourge, though if that is true then I want it confirmed.  Find these Deathstalkers.$B$BTheir first objective was to scout the farms in northern Silverpine.  You should begin your search there." },
            { ids = { 429 }, name = "Wild Hearts", level = 11, zone = "Silverpine Forest", giver = "Rane Yorick", giverMap = 1421, giverX = 53.5, giverY = 13.4, ender = "Apothecary Renferrel", enderMap = 1421, enderX = 42.8, enderY = 40.9, objective = "Gather 6 discolored worg hearts and bring them to Apothecary Renferrel at the Sepulcher.", summary = "My brother Quinn was badly hurt by the ghoul, Ivar the Foul, and I don't know if he will heal properly without magical aid.  Although I am not an apothecary, I do know that our apothecaries can make healing potions from the discolored hearts of worgs.$B$BGather such hearts and take them to Apothecary Renferrel at the Sepulcher to the south.  Then return here with the potion.$B$BYou can find plenty of worgs between here and Malden's Orchard to the east." },
            { ids = { 430 }, name = "Return to Quinn", level = 11, zone = "Silverpine Forest", giver = "Apothecary Renferrel", giverMap = 1421, giverX = 42.8, giverY = 40.9, ender = "Quinn Yorick", enderMap = 1421, enderX = 53.4, enderY = 12.6, objective = "Bring Quinn's potion to Quinn Yorick at the Ivar Patch, north of the Sepulcher.", summary = "Here is the potion to aid in Quinn Yorick's recovery.$B$BNow if you will excuse me, I have very important work to continue..." },
            { ids = { 425 }, name = "Ivar the Foul", level = 12, zone = "Silverpine Forest", giver = "Rane Yorick", giverMap = 1421, giverX = 53.5, giverY = 13.4, ender = "Rane Yorick", enderMap = 1421, enderX = 53.5, enderY = 13.4, objective = "Kill Ivar the Foul, and bring Ivar's Head to Rane Yorick at the Ivar Patch.", summary = "My brother Quinn and I were tasked to recon Silverpine Forest and report to High Executor Hadrec.  But we didn't get far -- when moving through this farm we were attacked by the ghoul Ivar the Foul.$B$BWe escaped from Ivar, but he seriously mauled Quinn.  He's healing from the potion you gave him, but Ivar may return before Quinn recovers.$B$BKill Ivar so Quinn will have time to heal.  Ivar is usually in the barn yonder, waiting for my guard to drop." },
        },
    },
    {
        id = "q850",
        name = "Kolkar Leaders",
        zone = "The Barrens",
        minLevel = 11,
        maxLevel = 20,
        importance = 1,
        kind = "world",
        quests = {
            { ids = { 850 }, name = "Kolkar Leaders", level = 16, zone = "The Barrens", giver = "Regthar Deathgate", giverMap = 1413, giverX = 45.3, giverY = 28.4, ender = "Regthar Deathgate", enderMap = 1413, enderX = 45.3, enderY = 28.4, objective = "Bring Barak's Head to Regthar Deathgate, west of the Crossroads.", summary = "The centaurs have plagued the Tauren for years.  And recently, the Kolkar centaurs of the Barrens have grown into a real threat.  Normally they were disorganized in these lands, but new leaders have risen among them.  Rallying them.$B$BTo preserve our holdings here, these centaur leaders must be destroyed.$B$BBring me the head of Barak Kodobane.  He camps near the Forgotten Pools to the north.$B$BDefeat him, then return to me." },
            { ids = { 851 }, name = "Verog the Dervish", level = 18, zone = "The Barrens", giver = "Regthar Deathgate", giverMap = 1413, giverX = 45.3, giverY = 28.4, ender = "Regthar Deathgate", enderMap = 1413, enderX = 45.3, enderY = 28.4, objective = "Bring Verog's Head to Regthar Deathgate, west of the Crossroads.", summary = "The centaur Verog the Dervish wanders the Barrens, and will be difficult to find.  But he is based at the centaur command tent at the Stagnant Oasis to the southeast.  It may be possible to draw him to you.$B$BTravel to the Stagnant Oasis to the southeast and attack centaur near the command tent.  It will be dangerous, but if you can kill enough centaur then they should raise an alarm.  And Verog will come.$B$BBring me his head and I will place it with Barak Kodobane's." },
            { ids = { 852 }, name = "Hezrul Bloodmark", level = 19, zone = "The Barrens", giver = "Regthar Deathgate", giverMap = 1413, giverX = 45.3, giverY = 28.4, ender = "Regthar Deathgate", enderMap = 1413, enderX = 45.3, enderY = 28.4, objective = "Bring Hezrul's Head to Regthar Deathgate, west of the Crossroads.", summary = "Hezrul Bloodmark is the leader of the Kolkar centaurs in the Barrens.  He is fierce, brutal and cunning.  Defeating him would disrupt and fracture the Kolkars, greatly reducing their threat to us.$B$BSo kill him.  As with Barak and Verog, bring me Hezrul's Head.$B$BHe leads his people from the Lushwater Oasis, to the south." },
            { ids = { 4021 }, name = "Counterattack!", level = 20, zone = "The Barrens", giver = "Regthar Deathgate", giverMap = 1413, giverX = 45.3, giverY = 28.4, ender = "Regthar Deathgate", enderMap = 1413, enderX = 45.3, enderY = 28.4, objective = "Bring a Piece of Krom'zar's Banner to Regthar Deathgate, west of the Crossroads.", summary = "The Horde commends your successes against the Kolkar, but the Kolkar themselves are maddened.  I have reports that a contingent of Kolkar has traveled to the Barrens from their home in Desolace, to seek vengeance.  My latest report was that, even now, they move against these bunkers, from the west!$B$BFace the Kolkar invaders, and end their threat in the Barrens.  Kill them until their leader, Warlord Krom'zar, appears.  Defeat him and bring me a piece of his banner as proof.$B$BWe're counting on you, $N." },
        },
    },
    {
        id = "q460",
        name = "Resting in Pieces",
        zone = "Silverpine Forest",
        minLevel = 12,
        maxLevel = 18,
        importance = 1,
        kind = "world",
        quests = {
            { ids = { 460 }, name = "Resting in Pieces", level = 17, zone = "Silverpine Forest", ender = "Shallow Grave", enderMap = 1421, enderX = 67.9, enderY = 24.9, objective = "Bring Alaric's Head to his grave.", summary = "You don't look like a rot hide.  Good.  I had lost hope...$B$BMy name is Alaric, and I was once Thule's head servant and bodyguard.  He used his magic to \"protect\" me from the Plague of Undeath, but instead his spell gave me an unlife from which I cannot escape.  And after creating the cursed rot hide gnolls, Thule beheaded me... and gave my head to the gnolls as a plaything!$B$BPlease, take me to my body.  I believe the gnolls buried it here in Fenris Keep, near the stable, in an unmarked grave." },
            { ids = { 461 }, name = "The Hidden Niche", level = 18, zone = "Silverpine Forest", giver = "Shallow Grave", giverMap = 1421, giverX = 67.9, giverY = 24.9, ender = "Dusty Shelf", enderMap = 1421, enderX = 65.4, enderY = 24.8, objective = "Take Alaric to the hidden alcove.", summary = "I know of a hidden niche within the keep that holds an item dear to Thule, and his old colleagues.  It also holds something you might find useful.  Take me there!$B$BThe alcove is in the southwestern tower of the keep, behind a dusty shelf.$B$BTake my body, but leave my boots.  They never fit me anyway..." },
            { ids = { 491 }, name = "Wand to Bethor", level = 18, zone = "Silverpine Forest", giver = "Dusty Shelf", giverMap = 1421, giverX = 65.4, giverY = 24.8, ender = "Bethor Iceshard", enderMap = 1458, enderX = 84.1, enderY = 17.4, objective = "Take the Woven Wand to Bethor Iceshard in the Magic Quarter of the Undercity.", summary = "Thule once told me that, long ago, he and two colleagues created a magic wand, woven together from the apprentice wands each mage possessed.  This wand was a symbol of their friendship, and although Thule came to despise it he could not part with it, nor could he let the others have it.  So he stole the wand, and hid it in Fenris Keep.$B$BHere.  Take the wand to Bethor Iceshard, one of Thule's friends from years past.  I'm sure he will want it." },
        },
    },
    {
        id = "q1061",
        name = "Forsaken Aid",
        zone = "Orgrimmar",
        minLevel = 13,
        maxLevel = 23,
        importance = 3,
        kind = "world",
        quests = {
            { ids = { 1061 }, name = "The Spirits of Stonetalon", level = 17, zone = "Orgrimmar", giver = "Zor Lonetree", giverMap = 1454, giverX = 38.9, giverY = 38.4, ender = "Seereth Stonebreak", enderMap = 1413, enderX = 35.3, enderY = 27.9, objective = "Speak with Seereth Stonebreak in the Stonetalon Mountains.", summary = "The spirits of the Stonetalon Mountains are angered, for goblins and their servants are plundering and burning the land.  So the land has cried out, and those who listen for such things... have heard.$B$BSeereth Stonebreak, a promising shaman of the Horde, was sent to Stonetalon.  She reports massive deforestation at the hands of the goblins, and requests aid.$B$BMeet Seereth in Stonetalon.  To reach her, follow the road west of the Barrens' Crossroads.  She is camped near the Greatwood Vale." },
            { ids = { 1062 }, name = "Goblin Invaders", level = 19, zone = "The Barrens", giver = "Seereth Stonebreak", giverMap = 1413, giverX = 35.3, giverY = 27.9, ender = "Seereth Stonebreak", enderMap = 1413, enderX = 35.3, enderY = 27.9, objective = "Kill 15 Venture Co. Loggers, then return to Seereth Stonebreak on the border of Stonetalon and the Barrens.", summary = "The goblin-run Venture Company moved into the Stonetalon Mountains, chopping down trees and burning huge stretches of forest.  The spirits of this place are nearly blind with pain and rage.  We must stop the Venture Company!$B$BHead northwest, beyond the Greatwood Vale and into the Windshear Crag.  You will find the goblins and their servants at work -- show them the Horde will not allow the exploitation of Stonetalon.  Show them in the language they best understand...$B$BViolence." },
            { ids = { 1063 }, name = "The Elder Crone", level = 18, zone = "The Barrens", giver = "Seereth Stonebreak", giverMap = 1413, giverX = 35.3, giverY = 27.9, ender = "Magatha Grimtotem", enderMap = 1456, enderX = 69.8, enderY = 30.9, objective = "Speak with Magatha in Thunder Bluff.", summary = "To truly tend the spirits of Stonetalon we must consult the tauren elders.$B$BI do not know many of their leaders' names, but I do know of one: Magatha.  I have heard that she is very old, and she knows much.  If anyone can marshal spiritual aid from the tauren, it is she.$B$BMagatha resides in the tauren capital of Thunder Bluff, on Elder Rise -- the city's northeastern bluff.  Speak with Magatha, and tell her of the peril of Stonetalon Mountains." },
            { ids = { 1064 }, name = "Forsaken Aid", level = 18, zone = "Thunder Bluff", giver = "Magatha Grimtotem", giverMap = 1456, giverX = 69.8, giverY = 30.9, ender = "Apothecary Zamah", enderMap = 1456, enderX = 22.8, enderY = 20.9, objective = "Speak with Apothecary Zamah in the Pools of Vision in Thunder Bluff.", summary = "The tauren have a bond with the land, and it pains me to hear of Stonetalon's plight.  But I fear that to heal the land, we must first remove the disease upon it.$B$BIs it not fortunate, then, that the Forsaken are allied with us?  They know much of disease.  I believe they can aid us, and by doing so they will strengthen the trust between our people.$B$BSpeak with Apothecary Zamah.  She is a scholar and an emissary of the Forsaken.  You will find her in the Pools of Vision below the Spirit Rise." },
            { ids = { 1065 }, name = "Journey to Tarren Mill", level = 18, zone = "Thunder Bluff", giver = "Apothecary Zamah", giverMap = 1456, giverX = 22.8, giverY = 20.9, ender = "Apothecary Lydon", enderMap = 1424, enderX = 61.4, enderY = 19.1, objective = "Bring Zamah's Note to Apothecary Lydon in Tarren Mill.", summary = "To rid Stonetalon of the Venture Company, we must take extreme measures.  Extreme, but without bloodshed.$B$BA colleague of mine may have just the tool we need.  His name is Lydon; he dwells in the town of Tarren Mill in the Hillsbrad Foothills, in the distant land of Lordaeron.$B$BTo reach Hillsbrad, travel by zeppelin to our capital, the Undercity.  Then go north to Tirisfal Glades, southwest to Silverpine, and south to Hillsbrad.$B$BSeek Lydon and bring him this note.  It details our needs to him." },
            { ids = { 1066 }, name = "Blood of Innocents", level = 23, zone = "Hillsbrad Foothills", giver = "Apothecary Lydon", giverMap = 1424, giverX = 61.4, giverY = 19.1, ender = "Apothecary Lydon", enderMap = 1424, enderX = 61.4, enderY = 19.1, objective = "Bring 5 Vials of Innocent Blood to Apothecary Lydon in Tarren Mill.", summary = "I will create a toxin to bleed the violence from the Venture Company, rendering them weak and docile.  That should fix the Horde's problem in Stonetalon, yes?$B$BBut to create the toxin, I will need the blood of innocents, a difficult ingredient to obtain.$B$BFortunately the Syndicate, a group of human brigands in this area, employ shadow mages... and those mages collect innocent blood for their own, unsavory purposes.$B$BYou can find the Syndicate shadow mages in Durnholde Keep to the southeast." },
            { ids = { 1067 }, name = "Return to Thunder Bluff", level = 23, zone = "Hillsbrad Foothills", giver = "Apothecary Lydon", giverMap = 1424, giverX = 61.4, giverY = 19.1, ender = "Apothecary Zamah", enderMap = 1456, enderX = 22.8, enderY = 20.9, objective = "Bring Lydon's Toxin to Apothecary Zamah in Thunder Bluff.", summary = "Here is the toxin.  If you use it against the Venture Company it should produce favorable, perhaps even contagious, results.  I must say, it is quite exciting to see my work applied in the field!$B$BBut before using it, take it to Apothecary Zamah.  She must create a delivery method for the toxin to maximize its effect." },
            { ids = { 1086 }, name = "The Flying Machine Airport", level = 23, zone = "Thunder Bluff", giver = "Apothecary Zamah", giverMap = 1456, giverX = 22.8, giverY = 20.9, ender = "Apothecary Zamah", enderMap = 1456, enderX = 22.8, enderY = 20.9, objective = "Bring the Toxic Fogger to the Venture Co. sky port, then return to Apothecary Zamah.", summary = "The toxin is ready.  All that remains is its delivery.  You, $N, must make that delivery.$B$BThe Venture Company must have a means of sending messages and light cargo between its headquarters and its operations in Stonetalon.  It is likely a small sky port -- not big enough for a zeppelin, but perhaps for a flying machine.  You must search the areas in Stonetalon under control of the Venture Company and find this sky port, if it exists.  If you find it, then place the toxin there.$B$BPlace it, and run." },
        },
    },
    {
        id = "q1483",
        name = "Super Reaper 6000",
        zone = "The Barrens",
        minLevel = 16,
        maxLevel = 27,
        importance = 2,
        kind = "world",
        quests = {
            { ids = { 1483 }, name = "Ziz Fizziks", level = 21, zone = "The Barrens", giver = "Sputtervalve", giverMap = 1413, giverX = 63.0, giverY = 37.2, ender = "Ziz Fizziks", enderMap = 1442, enderX = 59.0, enderY = 62.6, objective = "Speak with Ziz Fizziks in Windshear Crag.", summary = "The Venture Company stole many of the best goblin minds, but from time to time, we get the opportunity to steal some back.$b$bA while ago, the Venture Company outfit in the Stonetalon Mountains hired Gerenzo Wrenchwhistle--a gnome! Their other engineer, Ziz Fizziks, was so taken aback by this, he pleaded with me to find him new employment with the Tinkers' Union. I set him on a few tasks, but he might need help.$b$bMaybe you could look in on him for me? He's stationed at the western edge of Windshear Crag." },
            { ids = { 1093 }, name = "Super Reaper 6000", level = 21, zone = "Stonetalon Mountains", giver = "Ziz Fizziks", giverMap = 1442, giverX = 59.0, giverY = 62.6, ender = "Ziz Fizziks", enderMap = 1442, enderX = 59.0, enderY = 62.6, objective = "Get the Super Reaper 6000 Blueprints for Ziz Fizziks in the Stonetalon Mountains.", summary = "Terrible what the Venture Company has done here, eh? What were they thinking? Goblin company hiring a gnome!$b$bLucky for me, Sputtervalve knows a genius when he sees one. Hired me just after I'd been kicked out!$b$bTells me they built some enormous woodcutting machine, and Sput' wants me to steal the plans for him. Unfortunately, Gerenzo--bloody gnome--wants me dead on sight... maybe you could steal the plans for me? You should be able to find them on one of their operators." },
            { ids = { 1094 }, name = "Further Instructions", level = 21, zone = "Stonetalon Mountains", giver = "Ziz Fizziks", giverMap = 1442, giverX = 59.0, giverY = 62.6, ender = "Sputtervalve", enderMap = 1413, enderX = 63.0, enderY = 37.2, objective = "Deliver the Sealed Envelope to Sputtervalve in the Barrens.", summary = "This envelope has all the information I was able to snatch as they booted me out the door... Venture Company internal documents, some manuals, technical things... Oh, and of course the Super Reaper 6000 blueprints.$b$bSputtervalve has taken up residence at Ratchet in the Barrens. Shouldn't have much trouble finding him, he's a little green fellow." },
            { ids = { 1095 }, name = "Further Instructions", level = 27, zone = "The Barrens", giver = "Sputtervalve", giverMap = 1413, giverX = 63.0, giverY = 37.2, ender = "Ziz Fizziks", enderMap = 1442, enderX = 59.0, enderY = 62.6, objective = "Bring the new orders to Ziz Fizziks in the Stonetalon Mountains.", summary = "The matter of this gnome that has been hired by the Venture Company has caused a bit of a stir in Undermine. The trade princes do not approve of Razdunk's consorting with this Gerenzo.$b$bRiddlevox has asked me to take care of the problem, and I'm sure he was instructed to do so by one or more of the trade princes. Of course, the Director didn't tell me that. Let's just say I have a hunch.$b$bWhatever the case, Gerenzo must be removed, and it would be a fitting test to have Fizziks take care of him." },
            { ids = { 1096 }, name = "Gerenzo Wrenchwhistle", level = 27, zone = "Stonetalon Mountains", giver = "Ziz Fizziks", giverMap = 1442, giverX = 59.0, giverY = 62.6, ender = "Ziz Fizziks", enderMap = 1442, enderX = 59.0, enderY = 62.6, objective = "Bring Gerenzo Wrenchwhistle's Mechanical Arm to Ziz Fizziks in the Stonetalon Mountains.", summary = "I met Gerenzo once, but let me tell you, he's not easy on the eyes. His flesh looks like it's rotting away, and he's grafted metal and gears onto his body, replaced some of his limbs with mechanical ones.$b$bNortheast of here, far above Cragpool Lake, up near the water wheel is where Gerenzo watches over the entire site. There's no way I could fight my way up there, not to mention take on Gerenzo... But you look like you might be able to make it.$b$bIf you kill him for me, I'll make it worth your while!" },
        },
    },
    {
        id = "q498",
        name = "Blackmoore's Legacy",
        zone = "Hillsbrad Foothills",
        minLevel = 17,
        maxLevel = 42,
        importance = 3,
        kind = "world",
        quests = {
            { ids = { 498 }, name = "The Rescue", level = 22, zone = "Hillsbrad Foothills", giver = "Krusk", giverMap = 1424, giverX = 63.2, giverY = 20.7, ender = "Krusk", enderMap = 1424, enderX = 63.2, enderY = 20.7, objective = "Krusk in Tarren Mill needs you to free Drull and Tog'thar from Durnholde Keep.", summary = "Me and some other warriors were sent by the Warchief to retrieve an object from Durnholde and to investigate this so-called Syndicate.$b$bWe went to Durnholde to take a look around, but we were taken by surprise by a large number of the humans. We fought bravely, but their sheer numbers were enough to defeat us. They took a few of us captive, but I was able to escape.$b$bDurnholde is just southeast of here, across the river. Drull and Tog'thar are being held there, you must go and rescue them." },
            { ids = { 533 }, name = "Infiltration", level = 34, zone = "Hillsbrad Foothills", giver = "Krusk", giverMap = 1424, giverX = 63.2, giverY = 20.7, ender = "Krusk", enderMap = 1424, enderX = 63.2, enderY = 20.7, objective = "Retrieve information about Gol'dir's whereabouts for Krusk in Tarren Mill.", summary = "At last we begin to hear word and rumor, find evidence of Gol'dir's whereabouts. The humans have been moving him around, but we are narrowing down our search and focusing on the large Syndicate camp just north of here.$b$bGo there, $n, and bring back whatever information you can get your hands on." },
            { ids = { 503 }, name = "Gol'dir", level = 36, zone = "Hillsbrad Foothills", giver = "Krusk", giverMap = 1424, giverX = 63.2, giverY = 20.7, ender = "Gol'dir", enderMap = 1416, enderX = 60.0, enderY = 43.7, objective = "Free Gol'dir then return to Krusk in Tarren Mill.", summary = "From what I can tell of the documents you procured, Gol'dir is being held in a large Syndicate base to the north, most likely in the Alterac Mountains. He has been held captive far too long and must be freed." },
            { ids = { 506 }, name = "Blackmoore's Legacy", level = 36, zone = "Alterac Mountains", giver = "Gol'dir", giverMap = 1416, giverX = 60.0, giverY = 43.7, ender = "Krusk", enderMap = 1424, enderX = 63.2, enderY = 20.7, objective = "Return the information gathered by Gol'dir to Krusk in Tarren Mill.", summary = "A day or two ago, I was visited by the leader of this Syndicate. His name was Aliden Perenolde, and styled himself lord of this land. He confided in me his plans to take the orcs that stood against him as slaves, just as his father and his mentor, the despised Blackmoore, had planned.$b$bMore important was that he brought his mistress, a wisp of a girl named Elysa. Around her neck was the pendant the Warchief desires.$b$bNow go, I will make my own way, after I have settled my business here." },
            { ids = { 507 }, name = "Lord Aliden Perenolde", level = 42, zone = "Hillsbrad Foothills", giver = "Krusk", giverMap = 1424, giverX = 63.2, giverY = 20.7, ender = "Elysa", enderMap = 1416, enderX = 39.3, enderY = 14.3, objective = "Kill Lord Aliden Perenolde and ask his mistress, Elysa, about Taretha's pendant.", summary = "It is clear that Perenolde must be killed, his foulness removed from the world. His manor lies a ways to the north of here, on the shores of Lordamere Lake. Do your duty, $n, then retrieve the pendant that the Warchief desires, and return here." },
            { ids = { 508 }, name = "Taretha's Gift", level = 40, zone = "Alterac Mountains", giver = "Elysa", giverMap = 1416, giverX = 39.3, giverY = 14.3, ender = "Krusk", enderMap = 1424, enderX = 63.2, enderY = 20.7, objective = "Return Taretha's pendant to Krusk in Tarren Mill.", summary = "The pendant? Of course you can have it... Take it! I want no memory of him... just please, please leave in peace..." },
        },
    },
    {
        id = "q6562",
        name = "Allegiance to the Old Gods",
        zone = "Stonetalon Mountains",
        minLevel = 17,
        maxLevel = 26,
        importance = 2,
        kind = "dungeon",
        quests = {
            { ids = { 6562 }, name = "Trouble in the Deeps", level = 22, zone = "Stonetalon Mountains", giver = "Tsunaman", giverMap = 1442, giverX = 47.4, giverY = 64.2, ender = "Je'neu Sancrea", enderMap = 1440, enderX = 11.6, enderY = 34.3, objective = "Speak to Je'neu Sancrea in Ashenvale.", summary = "Je'neu Sancrea is in need of aid. He is at the Zoram'gar Outpost in Ashenvale. The Night elf forest is to the north of the Stonetalon mountains. You can reach it by traveling through Windshear Crag or by heading north through Barrens. Zoram Strand is far to the west of the forest. Be careful, $N. There are forces there that will not take to your presence kindly." },
            { ids = { 6564 }, name = "Allegiance to the Old Gods", level = 22, zone = "Blackfathom Deeps", ender = "Je'neu Sancrea", enderMap = 1440, enderX = 11.6, enderY = 34.3, objective = "Bring the Damp Note to Je'neu Sancrea in Ashenvale.", summary = "Some poor handwriting is scrawled on the crumpled up note:$B$B\"Yes, tell all the priestesses to bring the crystals to me. The water elemental spirits are strong within them and they will aid our aquamancers greatly in their own summonings.$B$BBy controlling the power within the crystals, we will appease Aku'Mai. One day we will have enough power to bring Aku'Mai back to us and the world will return to its greatest era! An era of rule by the Old Gods!\"" },
            { ids = { 6565 }, name = "Allegiance to the Old Gods", level = 26, zone = "Ashenvale", giver = "Je'neu Sancrea", giverMap = 1440, giverX = 11.6, giverY = 34.3, ender = "Je'neu Sancrea", enderMap = 1440, enderX = 11.6, enderY = 34.3, objective = "Kill Lorgus Jett in Blackfathom Deeps and then return to Je'neu Sancrea in Ashenvale.", summary = "This Twilight's Hammer follower cannot be allowed to complete his plan. The Twilight's Hammer do not understand the spirits of nature. They believe in the Old Gods--creatures of chaos and destruction that were long ago defeated. This Lorgus cannot be allowed to succeed. You must stop him, $N. I cannot do it myself--I am too weak.$B$BGo into Blackfathom Deeps, find him, and kill him. Return to me here at Zoram'gar when it's done." },
        },
    },
    {
        id = "q527",
        name = "Battle of Hillsbrad",
        zone = "Hillsbrad Foothills",
        minLevel = 19,
        maxLevel = 32,
        importance = 2,
        kind = "world",
        quests = {
            { ids = { 527 }, name = "Battle of Hillsbrad", level = 24, zone = "Hillsbrad Foothills", giver = "High Executor Darthalia", giverMap = 1424, giverX = 62.3, giverY = 20.4, ender = "High Executor Darthalia", enderMap = 1424, enderX = 62.3, enderY = 20.4, objective = "Kill 6 Hillsbrad Farmhands, 6 Hillsbrad Farmers, Farmer Ray and Farmer Getz and report back to Darthalia in Tarren Mill.", summary = "Stand at attention while addressing me, $c.$b$bI am under direct command of Varimathras.  We are to quell the human infestation until our apothecaries can develop the new plague.$b$bOur information leads us to believe that the town of Hillsbrad is vulnerable to attack.  Your first assignment is aimed at disrupting their food supply and infrastructure.$b$bTravel west.  Raid the northernmost farms of Hillsbrad Fields.  Make sure that the landowners, Farmer Ray and Farmer Getz, are executed as well." },
            { ids = { 528 }, name = "Battle of Hillsbrad", level = 25, zone = "Hillsbrad Foothills", giver = "High Executor Darthalia", giverMap = 1424, giverX = 62.3, giverY = 20.4, ender = "High Executor Darthalia", enderMap = 1424, enderX = 62.3, enderY = 20.4, objective = "Kill 15 Hillsbrad Peasants and report back to Darthalia in Tarren Mill.", summary = "Word of the attack on the northern farms has the townsfolk panicked.  Most excellent.$b$bOur Deathstalkers report peasants fleeing to the fields in southern Hillsbrad.  The fools think they can hide in the orchards and escape their doom.$b$bProve them wrong, $N.  Return to Hillsbrad Fields and seek out the cowering peasants.  Lay waste to them in the name of our Dark Lady.$b$bDismissed!" },
            { ids = { 529 }, name = "Battle of Hillsbrad", level = 26, zone = "Hillsbrad Foothills", giver = "High Executor Darthalia", giverMap = 1424, giverX = 62.3, giverY = 20.4, ender = "High Executor Darthalia", enderMap = 1424, enderX = 62.3, enderY = 20.4, objective = "Kill Blacksmith Verringtan and 4 Hillsbrad Apprentice Blacksmiths.$b$bRetrieve a shipment of iron and report back to Darthalia in Tarren Mill.", summary = "The humans of Hillsbrad have been putting up unexpected resistance.  The problem appears to be that the townsfolk are being armed by the local blacksmith.  We need to shut down all supply lines.$b$bYour mission will be to execute Blacksmith Verringtan.  Slay his apprentices as well.  While there, bring back a shipment of iron from their stockpile.  The supplies will come in handy when we are done with the conquering of Hillsbrad and begin razing Southshore." },
            { ids = { 532 }, name = "Battle of Hillsbrad", level = 26, zone = "Hillsbrad Foothills", giver = "High Executor Darthalia", giverMap = 1424, giverX = 62.3, giverY = 20.4, ender = "High Executor Darthalia", enderMap = 1424, enderX = 62.3, enderY = 20.4, objective = "Kill Magistrate Burnside and 5 Hillsbrad Councilmen.  Destroy the Hillsbrad Proclamation.  Steal the Hillsbrad Town Registry.  Report back to Darthalia in Tarren Mill afterwards.", summary = "The town of Hillsbrad is in disarray and we believe it will soon fall.  We must, however, persist in our ruthlessness until the human scum are wiped from the foothills for eternity.$b$bDespite their overwhelming losses, the humans rally around their leadership and keep fighting.  We must eliminate their leader, Magistrate Burnside, as well as the town council.  Destroy their revered political document as well, the Hillsbrad Proclamation.  And while you're at it, steal the town registry." },
            { ids = { 539 }, name = "Battle of Hillsbrad", level = 28, zone = "Hillsbrad Foothills", giver = "High Executor Darthalia", giverMap = 1424, giverX = 62.3, giverY = 20.4, ender = "High Executor Darthalia", enderMap = 1424, enderX = 62.3, enderY = 20.4, objective = "Kill Foreman Bonds and 10 Hillsbrad Miners and report back to Darthalia in Tarren Mill.", summary = "The Hillsbrad Town Registry indicates that the Azureload Mine is under Alliance control.  Furthermore, the mine is a prime source of iron ore for the Alliance armories.$b$bEven though we've struck a decisive blow to the town of Hillsbrad, the Alliance still supports and protects the Azureload Mine fervently.$b$bThe mine lies due south of Hillsbrad.  Go there and slay the foreman, a human by the name of Bonds.  Kill his miners as well.  That should send a clear message to the Alliance." },
            { ids = { 541 }, name = "Battle of Hillsbrad", level = 30, zone = "Hillsbrad Foothills", giver = "High Executor Darthalia", giverMap = 1424, giverX = 62.3, giverY = 20.4, ender = "High Executor Darthalia", enderMap = 1424, enderX = 62.3, enderY = 20.4, objective = "Travel to Dun Garok and kill 10 Mountaineers, 8 Riflemen, 4 Priests and Captain Ironhill and report back to Darthalia in Tarren Mill.", summary = "Dwarves aiding the humans?  Damn those filthy little beasts.$b$bWe shall test the strength of the so-called Alliance.  We'll see how anxious those little ankle-bashers are to help the humans once they feel our wrath.  We know exactly where their stronghold is in this territory.$b$bThey have established a barracks in southeastern Hillsbrad along Thoradin's Wall called Dun Garok.  The final mission of this battle is to lay siege on Dun Garok, $c.  Captain Ironhill, their leader, must die." },
            { ids = { 550 }, name = "Battle of Hillsbrad", level = 32, zone = "Hillsbrad Foothills", giver = "High Executor Darthalia", giverMap = 1424, giverX = 62.3, giverY = 20.4, ender = "Varimathras", enderMap = 1458, enderX = 56.2, enderY = 92.2, objective = "Take Darthalia's Sealed Commendation to Varimathras in the Undercity.", summary = "Because you fought with such valor and perseverance in the Battle of Hillsbrad, I have written this commendation, extolling your heroics in combat for the high command to recognize.$b$bTake this sealed commendation to Varimathras in the Undercity.  Go with pride, $c." },
        },
    },
    {
        id = "q1528",
        name = "Call of Water",
        zone = "Orgrimmar",
        minLevel = 20,
        maxLevel = 23,
        importance = 2,
        kind = "class",
        classes = { 7 },
        quests = {
            { ids = { 1528 }, name = "Call of Water", level = 20, zone = "Orgrimmar", giver = "Searn Firewarder", giverMap = 1454, giverX = 38.0, giverY = 37.7, ender = "Islen Waterseer", enderMap = 1413, enderX = 65.8, enderY = 43.8, objective = "Find Islen Waterseer in the Barrens.", summary = "Water be in ya future, mon. I see you be strong in da ways of fire already, an' me tinkin' you be ready to talk to Islen.$B$BIslen live along the coast of da Barrens. If ya head south along the Southfury River, ya canna miss her--look fer da big shark! She be strong in da ways of da elements and can teach ya da ways of water... if you tink you be ready.$B$BShe be easy ta find, just don' go too far south--she be jus' beyond Ratchet." },
            { ids = { 1530 }, name = "Call of Water", level = 22, zone = "The Barrens", giver = "Islen Waterseer", giverMap = 1413, giverX = 65.8, giverY = 43.8, ender = "Brine", enderMap = 1413, enderX = 43.4, enderY = 77.4, objective = "Find Brine in Southern Barrens.", summary = "If there is one lesson you must learn of water, it is this: water means rebirth.$B$BIts power flows, erodes, and makes clean all manner of things. You will find its ability to heal and replenish incomparable, but only when it is pure.$B$BWhen you understand that water, when polluted, can devastate all that it touches, you will appreciate how vital a resource it is.$B$BIf you wish the water sapta, find Brine deep in Southern Barrens. Her home is continually molested by the quilboar there." },
            { ids = { 1535 }, name = "Call of Water", level = 22, zone = "The Barrens", giver = "Brine", giverMap = 1413, giverX = 43.4, giverY = 77.4, ender = "Brine", enderMap = 1413, enderX = 43.4, enderY = 77.4, objective = "Fill the Empty Brown Waterskin at the watering hole below Brine's hut and return it to her in the Barrens.", summary = "To find understanding and gain the sapta from me, you must seek out only the purest forms of water. As you fetch the samples for me, take note of your surroundings. Be aware of the creatures that rely on the water, that protect it. See how it affects forests and deserts. Witness how the very substance that sustains life will force creatures to take lives.$B$BWe shall start with a simple task: down below my hut there is a pond of the precious liquid. Fill this skin with it and return to me." },
            { ids = { 1536 }, name = "Call of Water", level = 22, zone = "The Barrens", giver = "Brine", giverMap = 1413, giverX = 43.4, giverY = 77.4, ender = "Brine", enderMap = 1413, enderX = 43.4, enderY = 77.4, objective = "Fill the Empty Red Waterskin at the well in Tarren Mill and return to Brine in the Barrens.", summary = "Long ago I followed some companions into the Hillsbrad Foothills. We defended ourselves from some tenacious humans who make their home there and we found ourselves in a small town the Forsaken had taken over: Tarren Mill.$B$BIt was there I found a most peculiar thing: in the center of town was a small well of fresh spring water. I'm not sure the plagued citizens of the town even realize its value--it's a small holy vestige in an unhallowed sea.$B$BBring me a sample of that water in this waterskin." },
            { ids = { 1534 }, name = "Call of Water", level = 23, zone = "The Barrens", giver = "Brine", giverMap = 1413, giverX = 43.4, giverY = 77.4, ender = "Brine", enderMap = 1413, enderX = 43.4, enderY = 77.4, objective = "Fill the Empty Blue Waterskin at the Ruins of Stardust in Ashenvale and return to Brine in the Barrens.", summary = "Take this waterskin and head deep into the lush forest the night elves call Ashenvale. It is to the far north of the Barrens.$B$BOnce you've entered the forest, travel west. Along the mountains that separate Stonetalon and Ashenvale, and beyond Lake Mystral, you will find a holy place: the Ruins of Stardust. At the center of the lake you will find a small fountain.$B$BBring me a sample of the fountain's water. It will be the final component you'll need before I send you back to Islen." },
            { ids = { 220 }, name = "Call of Water", level = 23, zone = "The Barrens", giver = "Brine", giverMap = 1413, giverX = 43.4, giverY = 77.4, ender = "Islen Waterseer", enderMap = 1413, enderX = 65.8, enderY = 43.8, objective = "Bring the Vial of Purest Water to Islen Waterseer in the Barrens.", summary = "Islen will have one more task for you before rewarding you with your next totem. The vial of water I've given you is necessary for whatever that task is.$B$BGo now and find her. We shall meet again some day." },
            { ids = { 63 }, name = "Call of Water", level = 23, zone = "The Barrens", giver = "Islen Waterseer", giverMap = 1413, giverX = 65.8, giverY = 43.8, ender = "Brazier of Everfount", enderMap = 1421, enderX = 38.3, enderY = 44.6, objective = "Defeat the Corrupt Manifestation of Water and place the Corrupted Manifestation's Bracers along with the Remaining Drops of Purest Water on the Brazier of Everfount in Silverpine Forest.", summary = "Along the coast of Silverpine, west of the Sepulcher, you will find a shrine that has become tainted by the plague. The spirits there no longer speak to our people and it will be up to you to defeat the manifestation and cleanse the pool.$B$BTake the elemental's bracers, along with the remaining drops of Brine's potion, and place them on the brazier. The ritual should be enough to summon a pure spirit for you to communicate with.$B$BBring me proof the task is done, and I will reward you with your totem." },
            { ids = { 100 }, name = "Call of Water", level = 23, zone = "Silverpine Forest", giver = "Brazier of Everfount", giverMap = 1421, giverX = 38.3, giverY = 44.6, ender = "Minor Manifestation of Water", enderMap = 1421, enderX = 38.6, enderY = 44.6, objective = "Speak to the Minor Manifestation of Water in Silverpine Forest.", summary = "Light explodes as you finish the incantation. The sounds of the water drops hitting the flame have died down and your senses are overcome as the corrupt spirits around you are destroyed." },
            { ids = { 96 }, name = "Call of Water", level = 23, zone = "Silverpine Forest", giver = "Minor Manifestation of Water", giverMap = 1421, giverX = 38.6, giverY = 44.6, ender = "Islen Waterseer", enderMap = 1413, enderX = 65.8, enderY = 43.8, objective = "Bring the Shard of Water to Islen Waterseer in the Barrens.", summary = "Take shard. Take shard and give life.$B$BGive life and understand. Understand water is life... corruption stops life.$B$BYou protect and give life with water's power." },
        },
    },
    {
        id = "q1507",
        name = "Love's Gift",
        zone = "Orgrimmar",
        minLevel = 20,
        maxLevel = 20,
        importance = 2,
        kind = "class",
        classes = { 9 },
        quests = {
            { ids = { 1507 }, name = "Devourer of Souls", level = -1, zone = "Orgrimmar", giver = "Gan'rul Bloodeye", giverMap = 1454, giverX = 48.2, giverY = 45.3, ender = "Cazul", enderMap = 1454, enderX = 47.1, enderY = 46.4, objective = "Speak with Cazul in the Cleft of Shadow.", summary = "The time has come for you to learn more of the summoning magics. You will learn to summon a succubus, a creature of incredible mental powers. It can lull those of weak minds into its servitude--but have no fear! I feel certain that you will be equal to the challenge.$b$bA succubus can only be summoned when baited with an item that represents great devotion and love. I leave it to you to find such an object.$b$bA suggestion? Speak with Cazul... There seems to be little the ancient warlock does not know." },
            { ids = { 1508 }, name = "Blind Cazul", level = -1, zone = "Orgrimmar", giver = "Cazul", giverMap = 1454, giverX = 47.1, giverY = 46.4, ender = "Zankaja", enderMap = 1454, enderX = 37.0, enderY = 59.5, objective = "Speak with Zankaja in Orgrimmar.", summary = "Hmm... But, of course, that is not why you have come to speak with me.$b$bIf Gan'rul has sent you to me, it must be that you are to summon a succubus, and need an object to use for enticement.$b$bHmm... If you trust a blind man to lead you, $n, then listen. In the bluffs of Orgrimmar, west of the wind rider tower, lives Zankaja. She waits for the return of her mate.$b$bGo to her." },
            { ids = { 1509 }, name = "News of Dogran", level = 20, zone = "Orgrimmar", giver = "Zankaja", giverMap = 1454, giverX = 37.0, giverY = 59.5, ender = "Gazrog", enderMap = 1413, enderX = 51.9, enderY = 30.3, objective = "Speak with Gazrog at the Crossroads.", summary = "My mate, Dogran, was recently sent to the Crossroads for duty. It was a promotion, and he was very proud.$b$bI was sad, of course, but I didn't let him know that. And worried, too. The Barrens is a more dangerous place than Orgrimmar, and I feared the worst.$b$bNow it's been a week after he should have returned, and I have received no word from him...$b$bPerhaps you could go to the Crossroads and see if they have any news? He worked with Gazrog, who should still be stationed there." },
            { ids = { 1510 }, name = "News of Dogran", level = 20, zone = "The Barrens", giver = "Gazrog", giverMap = 1413, giverX = 51.9, giverY = 30.3, ender = "Ken'zigla", enderMap = 1442, enderX = 73.2, enderY = 95.1, objective = "Speak with Ken'zigla at the Malaka'jin.", summary = "He was stationed at Camp Taurajo, where we've been trying to weed out the quilboar. He led a few grunts to one of their camps, where he was hurt bad. The others made it back and tried to rescue him. He was in bad shape, his wounds festered, so they were afraid to move him without patching him up first.$b$bThey sent a message here, requesting a healing draught from the trolls at the Malaka'jin at the base of the Stonetalon Mountains. We sent someone to get it, but they haven't returned yet." },
            { ids = { 1511 }, name = "Ken'zigla's Draught", level = 20, zone = "Stonetalon Mountains", giver = "Ken'zigla", giverMap = 1442, giverX = 73.2, giverY = 95.1, ender = "Grunt Logmar", enderMap = 1413, enderX = 44.6, enderY = 59.3, objective = "Bring Ken'zigla's Draught to Grunt Logmar at Camp Taurajo.", summary = "I figured there might be another coming to get the draught, so I prepared it anyways.$b$bHere you go, $n. Mind you, you should only give half of it to him! That will give him enough strength to move without bleeding himself dry. Wait a night, then give him the other half.$b$bAnyways, you'll want to bring this to Logmar at Camp Taurajo. From what the first one told me, he should have an idea where this Dogran is." },
            { ids = { 1515 }, name = "Dogran's Captivity", level = 20, zone = "The Barrens", giver = "Grunt Logmar", giverMap = 1413, giverX = 44.6, giverY = 59.3, ender = "Grunt Dogran", enderMap = 1413, enderX = 43.3, enderY = 47.9, objective = "Bring Ken'zigla's Draught to Dogran in the Barrens.", summary = "You've made it this far, so if you want to see this through to the end, I won't stop you. I can't spare you any additional manpower though, you'll be on your own.$b$bDogran is being held in a quilboar camp to the north of here. Look for a group of two huts. He'll be heavily guarded--that is, if they haven't killed him yet, or he hasn't succumbed to his wounds.$b$bGood luck." },
            { ids = { 1512 }, name = "Love's Gift", level = 20, zone = "The Barrens", giver = "Grunt Dogran", giverMap = 1413, giverX = 43.3, giverY = 47.9, ender = "Gan'rul Bloodeye", enderMap = 1454, enderX = 48.2, enderY = 45.3, objective = "Bring the Dirt-caked Pendant to Gan'rul Bloodeye in Orgrimmar.", summary = "Zankaja is young and beautiful. To be chained to an invalid... I will not allow her to suffer that injustice.$b$bLeave me, $n. And thank you. I may end my life in glorious battle, instead of a lifeless husk.$b$bAnd please, I would ask you not to tell my mate of this... I do not want guilt on her conscience." },
            { ids = { 1513 }, name = "The Binding", level = 20, zone = "Orgrimmar", giver = "Gan'rul Bloodeye", giverMap = 1454, giverX = 48.2, giverY = 45.3, ender = "Gan'rul Bloodeye", enderMap = 1454, enderX = 48.2, enderY = 45.3, objective = "Using Dogran's Pendant, summon and subdue a succubus, then return Dogran's Pendant to Gan'rul Bloodeye in Orgrimmar.", summary = "Take this to the summoning circle in Neeru's tent, $n. Summon forth a foul succubus, then show it your mastery. I believe in the strength of your magic. As always, though, be wary, for pride and overconfidence has overcome many a promising warlock.$b$bWhen you have defeated it, return the pendant to me so that I might deliver the news to Zankaja." },
        },
    },
    {
        id = "q1823",
        name = "Chimaeric Horn",
        zone = "Thunder Bluff",
        minLevel = 20,
        maxLevel = 30,
        importance = 2,
        kind = "class",
        classes = { 1 },
        quests = {
            { ids = { 1823 }, name = "Speak with Ruga", level = 20, zone = "Thunder Bluff", giver = "Torm Ragetotem", giverMap = 1456, giverX = 57.2, giverY = 87.4, ender = "Ruga Ragetotem", enderMap = 1413, enderX = 44.7, enderY = 59.4, objective = "Speak with Ruga Ragetotem.", summary = "You are a warrior of skill and growing renown.  Perhaps you are ready for Ruga Ragetotem's trial?  If so, then find Ruga in Camp Taurajo in the Barrens.$B$BHe awaits those warriors who answer his call." },
            { ids = { 1824 }, name = "Trial at the Field of Giants", level = 20, zone = "The Barrens", giver = "Ruga Ragetotem", giverMap = 1413, giverX = 44.7, giverY = 59.4, ender = "Ruga Ragetotem", enderMap = 1413, enderX = 44.7, enderY = 59.4, objective = "Bring 5 twitching antennae to Ruga Ragetotem at Camp Taurajo", summary = "To pass this trial, you must travel south to the Field of Giants.  There you will find a host of crawling, insect creatures.  They are new to the Barrens and I do not like what they herald.$B$BBring me their still-twitching antennae, and waste no time, $N, for harvested antennae will not twitch for long.  Bring me the antennae in the time allowed, and you will pass the trial." },
            { ids = { 1825 }, name = "Speak with Thun'grim", level = 20, zone = "The Barrens", giver = "Ruga Ragetotem", giverMap = 1413, giverX = 44.7, giverY = 59.4, ender = "Thun'grim Firegaze", enderMap = 1413, enderX = 57.2, enderY = 30.3, objective = "Speak with Thun'grim Firegaze in the Barrens.", summary = "Thun'grim Firegaze, an orc blacksmith of renown, has heard of your continued deeds of valor in service of the Horde.  He would like to fashion for you a suit of armor, and bids you speak with him immediately.$B$BThun'grim is camped east of the Crossroads in the Barrens." },
            { ids = { 1838 }, name = "Brutal Armor", level = 30, zone = "The Barrens", giver = "Thun'grim Firegaze", giverMap = 1413, giverX = 57.2, giverY = 30.3, ender = "Thun'grim Firegaze", enderMap = 1413, enderX = 57.2, enderY = 30.3, objective = "Bring to Thun'grim Firegaze 15 Smoky Iron Ingots, 10 Powdered Azurite, 10 Iron Bars and a Vial of Phlogiston.", summary = "I have heard tales of your strength and valor, and wish to make for you a suit of armor, a companion to aid you as tales of your great deeds grow.$B$BBut the fashioning of this armor will be a quest unto itself, $N.  I will need your help, and the help of other smiths of the Horde.$B$BHere, take this scroll.  I spent many nights, struggling with near-blind eyes, writing that which I need for the armor.  Bring me the items on this scroll and I will create for you the first piece of the suit." },
            { ids = { 1848 }, name = "Brutal Hauberk", level = 30, zone = "The Barrens", giver = "Thun'grim Firegaze", giverMap = 1413, giverX = 57.2, giverY = 30.3, ender = "Thun'grim Firegaze", enderMap = 1413, enderX = 57.2, enderY = 30.3 },
            { ids = { 1840 }, name = "Orm Stonehoof and the Brutal Helm", level = 30, zone = "The Barrens", giver = "Thun'grim Firegaze", giverMap = 1413, giverX = 57.2, giverY = 30.3, ender = "Orm Stonehoof", enderMap = 1456, enderX = 39.0, enderY = 56.0, objective = "Speak with Orm Stonehoof in Thunder Bluff.", summary = "Orm Stonehoof is respected greatly for his skill.  He will make for you the brutal helm.$B$BSeek him out in Thunder Bluff, near the pool by the city's great, central totem." },
            { ids = { 1844 }, name = "Chimaeric Horn", level = 30, zone = "Thunder Bluff", giver = "Orm Stonehoof", giverMap = 1456, giverX = 39.0, giverY = 56.0, ender = "Orm Stonehoof", enderMap = 1456, enderX = 39.0, enderY = 56.0, objective = "Bring a Galvanized Horn to Orm Stonehoof in Thunder Bluff.", summary = "I will make you the helm, but you must show me you are worthy of it.$B$BNestled in the northwestern reaches of the Stonetalon Mountains there lies the Charred Vale.  It was once a verdant place, but is now defiled and ashen, and what creatures remain there are mad with pain and despair.$B$BThat place is where I send you, $N.$B$BYou must go to the Charred Vale and find a chimaera matriarch.  Slay her, free her of her misery.  Bring me her galvanized horn as proof, and I shall make for you the helm. " },
            { ids = { 1845 }, name = "Brutal Helm", level = 30, zone = "Thunder Bluff", giver = "Orm Stonehoof", giverMap = 1456, giverX = 39.0, giverY = 56.0, ender = "Orm Stonehoof", enderMap = 1456, enderX = 39.0, enderY = 56.0 },
        },
    },
    {
        id = "q2460",
        name = "The Shattered Salute",
        zone = "Orgrimmar",
        minLevel = 20,
        maxLevel = 26,
        importance = 2,
        kind = "class",
        classes = { 4 },
        quests = {
            { ids = { 2460 }, name = "The Shattered Salute", level = 20, zone = "Orgrimmar", giver = "Shenthul", giverMap = 1454, giverX = 43.0, giverY = 53.7, ender = "Shenthul", enderMap = 1454, enderX = 43.0, enderY = 53.7, objective = "Perform the Shattered Salute on Shenthul.", summary = "As a rogue of the Shattered Hand, it is imperative that you learn the Shattered Salute. It is the only way to truly identify another member of the Hand.$B$BWatch, learn, repeat." },
            { ids = { 2458 }, name = "Deep Cover", level = 20, zone = "Orgrimmar", giver = "Shenthul", giverMap = 1454, giverX = 43.0, giverY = 53.7, ender = "Taskmaster Fizzule", enderMap = 1413, enderX = 55.4, enderY = 5.6, objective = "Travel to the Venture Co. Tower, north of the Sludge Fen and contact the Shattered Hand's covert operative, Taskmaster Fizzule.$B$BWhen the tower is in sight, use the Flare Gun to signal your arrival to Taskmaster Fizzule. Fire off TWO flares, then approach Taskmaster Fizzule and perform the Shattered /Salute.$B$BThese actions must be performed in the correct order, as Fizzule will attack and terminate any person he does not recognize.", summary = "The Venture Company... Perhaps you have heard of them?$B$BFor one year we have worked on planting an agent deep within their ranks. Through much hard work and careful planning, we succeeded.$B$BRecently we received word that the Venture Co. are planning something on a grand scale. Go north of the Sludge Fen to the Venture Co. tower and contact our undercover agent, Taskmaster Fizzule.$B$BWhen you find the tower, use this flare gun, then approach Fizzule and show him the salute of the Shattered Hand." },
            { ids = { 2478 }, name = "Mission: Possible But Not Probable", level = 24, zone = "The Barrens", giver = "Taskmaster Fizzule", giverMap = 1413, giverX = 55.4, giverY = 5.6, ender = "Shenthul", enderMap = 1454, enderX = 43.0, enderY = 53.7, objective = "Steal Silixiz's Tower Key from Foreman Silixiz, then kill two Mutated Venture Co. Drones, two Venture Co. Patrollers, and two Venture Co. Lookouts.$B$BAssassinate Grand Foreman Gallywix and take his head, then pick the lock on Gallywix's lockbox and steal the Cache of Zanzil's Altered Mixture. Take the Cache and Gallywix's Head back to Shenthul in Orgrimmar for further instruction.", summary = "You will need to steal the tower key from Foreman Silixiz, $N. Once you've got the key in your possession, hold on to it - I may need it later.$B$BRemember, the poison has weakened everything in this tower. Use your abilities to bring chaos and destruction to its inhabitants. Slay them all -- show no mercy!$B$BOnce everything inside lays in a bloodied heap, pick Gallywix's lockbox and steal the cache of Zanzil's mixture held inside. Take both the head of Gallywix and the mixture to Shenthul in Orgrimmar." },
            { ids = { 2479 }, name = "Hinott's Assistance", level = 26, zone = "Orgrimmar", giver = "Shenthul", giverMap = 1454, giverX = 43.0, giverY = 53.7, ender = "Serge Hinott", enderMap = 1424, enderX = 61.6, enderY = 19.2, objective = "Travel to Tarren Mill in Hillsbrad Foothills and deliver the Sample of Zanzil's Mixture to Serge Hinott.$B$BTo get to Tarren Mill, take the Zeppelin to the Undercity and follow the road south through Silverpine and towards Hillsbrad. Follow the signs!", summary = "Take a sample of the mixture to Serge Hinott in Tarren Mill.$B$BIf anyone can cure you, it's Serge. Live long enough and Serge will show you the ways of poison creation and use." },
            { ids = { 2480 }, name = "Hinott's Assistance", level = 20, zone = "Hillsbrad Foothills", giver = "Serge Hinott", giverMap = 1424, giverX = 61.6, giverY = 19.2, ender = "Serge Hinott", enderMap = 1424, enderX = 61.6, enderY = 19.2, objective = "Wait for Serge Hinott to complete the cure.", summary = "I have never seen such wondrous results from a poison! Zanzil you say? Never heard of him, however, I must commend him on the creation of this concoction.$B$BSo, I am to cure you of this and then teach you how to make use of the poison?$B$BGive me a few moments to examine the toxin, $N." },
        },
    },
    {
        id = "q1472",
        name = "Hearts of the Pure",
        zone = "Undercity",
        minLevel = 20,
        maxLevel = 20,
        importance = 2,
        kind = "class",
        classes = { 9 },
        quests = {
            { ids = { 1472 }, name = "Devourer of Souls", level = -1, zone = "Undercity", giver = "Carendin Halgar", giverMap = 1458, giverX = 85.1, giverY = 26.0, ender = "Godrick Farsan", enderMap = 1458, enderX = 84.8, enderY = 14.8, objective = "Speak with Godrick Farsan in the Temple of the Damned.", summary = "A succubus is a devourer of souls, destroyer of hearts, tempter of men. A creature of profound evil and of singular mind.$b$bIt cannot be brought into our world without a stimulus.$b$bThus we use its own strength against it. With the hearts of good men, pure men, loving men, the succubus will be unable to resist, and will cross into our world. Then you can dominate it, and make it your own.$b$bSpeak with my assistant, Godrick Farsan, within the Temple. He will help you find your bait." },
            { ids = { 1476 }, name = "Hearts of the Pure", level = -1, zone = "Undercity", giver = "Godrick Farsan", giverMap = 1458, giverX = 84.8, giverY = 14.8, ender = "Carendin Halgar", enderMap = 1458, enderX = 85.1, enderY = 26.0, objective = "Bring the hearts of Dalin Forgewright and Comar Villard to Carendin Halgar in the Temple of the Damned.", summary = "Men of honor and goodness? Does such a man exist?$b$bIt took much research, but through bits of overheard stories, I managed to find two men that should do.$b$bThe first is Dalin Forgewright, who has dedicated himself to the care of the Lordaeron refugees, whom are refused by their kin at the Greymane Wall.$b$bThe other is Comar Villard, a man who remains faithful to his lost love, wandering the Wetlands for a sign of his wife.$b$bDeliver their hearts to Carendin. But first, let me show you your quarry." },
            { ids = { 1474 }, name = "The Binding", level = 20, zone = "Undercity", giver = "Carendin Halgar", giverMap = 1458, giverX = 85.1, giverY = 26.0, ender = "Carendin Halgar", enderMap = 1458, enderX = 85.1, enderY = 26.0, objective = "Using the Pure Hearts, summon and subdue a succubus, then return the Pure Hearts to Carendin Halgar in the Magic Quarter of the Undercity.", summary = "Using these hearts, cast a spell at the summoning circle to open a doorway for the succubus to come through. Your powers are greater now, and you will need all of them to defeat the succubus. $b$bBeware its charms, $n, many a strong mind has been bound to its will. When overcome, the succubus will be returned to the void, and I will teach you the spell to summon it forth at your command." },
        },
    },
    {
        id = "q2842",
        name = "Gnomer-gooooone!",
        zone = "Orgrimmar",
        minLevel = 20,
        maxLevel = 35,
        importance = 1,
        kind = "dungeon",
        quests = {
            { ids = { 2842 }, name = "Chief Engineer Scooty", level = 35, zone = "Orgrimmar", giver = "Sovik", giverMap = 1454, giverX = 75.5, giverY = 25.4, ender = "Scooty", enderMap = 1434, enderX = 27.6, enderY = 77.5, objective = "Speak with Scooty in Booty Bay.", summary = "As soon as we got word from Kernobee about the new gnomish rig, Scooty and I began work on the Transpolyporter 6000: The fastest and most reliable way to Gnomeregan.$B$BIt's finally ready for passengers to board, $N. If you want to give it a try, go to Booty Bay and talk with Scooty at the wind rider roost. To get to Booty Bay, take the boat from Ratchet.$B$BOf course, you could always try and make the run to Gnomeregan through the dwarf infested mountains of Dun Morogh!" },
            { ids = { 2843 }, name = "Gnomer-gooooone!", level = 35, zone = "Stranglethorn Vale", giver = "Scooty", giverMap = 1434, giverX = 27.6, giverY = 77.5, ender = "Scooty", enderMap = 1434, enderX = 27.6, enderY = 77.5, objective = "Wait for Scooty to calibrate the Goblin Transponder.", summary = "As long as you have the transponder in your possession, all you need to do is step on the pad and you'll be teleported to Gnomeregan.$B$BYou may experience some unusual side effects, but none of those should be permanent... anymore.$B$BI almost forgot the most important part - getting back. When you're ready to come back, just step on the transpolyporter pad in Gnomeregan!$B$BNow to calibrate the transponder to your size and weight." },
        },
    },
    {
        id = "q513",
        name = "Elixir of Agony",
        zone = "Hillsbrad Foothills",
        minLevel = 24,
        maxLevel = 30,
        importance = 2,
        kind = "world",
        quests = {
            { ids = { 509 }, name = "Elixir of Agony", level = 28, zone = "Hillsbrad Foothills", giver = "Apothecary Lydon", giverMap = 1424, giverX = 61.4, giverY = 19.1, ender = "Apothecary Lydon", enderMap = 1424, enderX = 61.4, enderY = 19.1, objective = "Bring 6 Mudsnout Blossoms to Apothecary Lydon in Tarren Mill.", summary = "Another day, another elixir to be made. If it were up to me, I'd just let the pathetic humans and Scourge fight it out.  They seem bent on killing each other as is.$b$bAlas, our Dark Lady wants to help speed up the process a tad so why not pass these morbid days by spreading a little death and disease across the land?$b$bHere's the plan, $N: you go out to Nethander Stead, south of Tarren Mill and east of the river and Southshore. Collect for me 6 Mudsnout Blossoms from the field for my next elixir." },
            { ids = { 513 }, name = "Elixir of Agony", level = 28, zone = "Hillsbrad Foothills", giver = "Apothecary Lydon", giverMap = 1424, giverX = 61.4, giverY = 19.1, ender = "Master Apothecary Faranell", enderMap = 1458, enderX = 48.8, enderY = 69.3, objective = "Take the Mudsnout Composite to Master Apothecary Faranell in the Undercity.", summary = "Just when I thought another day was going to pass devoid of any joy, you brought me those marvelous Mudsnout Blossoms.$b$bFirst I will mix them down into a fine composite.  We'll then need Master Apothecary Faranell in the Undercity to apply his colloid of decay to it and then we'll be ready for some good fun indeed!$b$bHere, take this Mudsnout Composite and run it off to Master Faranell at once, $N." },
            { ids = { 515 }, name = "Elixir of Agony", level = 30, zone = "Undercity", giver = "Master Apothecary Faranell", giverMap = 1458, giverX = 48.8, giverY = 69.3, ender = "Apothecary Lydon", enderMap = 1424, enderX = 61.4, enderY = 19.1, objective = "Bring the Mudsnout Mixture, a Strong Troll's Blood Potion, 5 Daggerspine Scales and 5 Torn Fin Eyes to Apothecary Lydon in Tarren Mill.", summary = "A mudsnout composite?  Absolutely brilliant!  Why didn't I think of that?$b$bLet me contribute my colloid of decay to this devilish brew.$b$bIn order to activate the contaminating agents in this mudsnout mixture, Lydon is going to need a strong troll's blood potion, as well as some daggerspine scales and torn fin eyes from the southern coast of Hillsbrad.  He'll know what to do once you've gathered him all the reagents.  And my, how anxious I am to hear how his experiment goes!" },
            { ids = { 517 }, name = "Elixir of Agony", level = 30, zone = "Hillsbrad Foothills", giver = "Apothecary Lydon", giverMap = 1424, giverX = 61.4, giverY = 19.1, ender = "Apothecary Lydon", enderMap = 1424, enderX = 61.4, enderY = 19.1, objective = "Bring a keg of Shindigger Stout to Apothecary Lydon in Tarren Mill.", summary = "This new elixir is finally ready to be tested.  But why let a perfectly good, highly contagious plague go to waste on a mere frog or dog?  Let's have us some true fun in the name of Lady Sylvanas.$b$bHead down to Dun Garok.  You know the barracks where those filthy little dwarves skitter about.  Steal me a keg of their Shindigger Stout.  Once I have that keg, you and I will have quite the party, $N." },
            { ids = { 524 }, name = "Elixir of Agony", level = 30, zone = "Hillsbrad Foothills", giver = "Apothecary Lydon", giverMap = 1424, giverX = 61.4, giverY = 19.1, ender = "Dusty Rug", enderMap = 1424, enderX = 62.8, enderY = 18.7, objective = "Place the Tainted Keg on the rug for the captured farmers.", summary = "Next door the Deathguards are holding a few captured farmers hostage.  High Executor Darthalia suspected one of the military strategists from Stormwind to be hiding out amongst them.  Apparently the military chap was found dead in the Plaguelands last night.  Darthalia, always looking out for me, decided the prisoners would be left to my disposal.$b$bI think it's time we threw those farmers a party.  Sounds like a grand ol' time!$b$bPlace this tainted keg on the rug in their room.  Plagued brew for all!" },
        },
    },
    {
        id = "q4821",
        name = "Arikara",
        zone = "Thousand Needles",
        minLevel = 24,
        maxLevel = 28,
        importance = 1,
        kind = "world",
        quests = {
            { ids = { 4821 }, name = "Alien Egg", level = 26, zone = "Thousand Needles", giver = "Hagar Lightninghoof", giverMap = 1441, giverX = 44.6, giverY = 50.3, ender = "Hagar Lightninghoof", enderMap = 1441, enderX = 44.6, enderY = 50.3, objective = "Return the Alien Egg to Hagar Lightninghoof in Freewind Post.", summary = "A rumor has surfaced about an alien egg here in Thousand Needles. Those that report seeing this egg have failed to even get close enough to examine it in detail. Serpents guard the egg as if it's one of their own.$B$BI want you to seek out this alien egg and bring it to me so that I may examine it. Reports say the egg is located within a serpent den, but there are several serpent dens along the base of the cliff walls south and northeast of Freewind Post." },
            { ids = { 4865 }, name = "Serpent Wild", level = 26, zone = "Thousand Needles", giver = "Hagar Lightninghoof", giverMap = 1441, giverX = 44.6, giverY = 50.3, ender = "Motega Firemane", enderMap = 1441, enderX = 21.5, enderY = 32.4, objective = "Report your findings to Motega Firemane.", summary = "If I did not see that with my own eyes I would never have believed it to be true. Vengeance has come to Thousand Needles!$B$B<Hagar wipes his brow.>$B$B$N, you must act quickly! Go now and seek out Motega Firemane; he is located at Whitereach Post just northwest of Freewind Post along the road. He will know what to do!" },
            { ids = { 5062 }, name = "Sacred Fire", level = 27, zone = "Thousand Needles", giver = "Motega Firemane", giverMap = 1441, giverX = 21.5, giverY = 32.4, ender = "Magatha Grimtotem", enderMap = 1456, enderX = 69.8, enderY = 30.9, objective = "Gather 10 bushels of Incendia Agave, and then consult Magatha Grimtotem on Elder Rise in Thunderbluff.", summary = "Arikara is a deadly creature that must be dealt with swiftly. In order to hunt her down you will need to light the sacred fire of life - this will summon Arikara.$B$BGo now and harvest the rare Incendia agave plant. Once you have harvested enough agave, seek council with Magatha Grimtotem on Elder Rise in Thunder Bluff. She is a powerful shaman that can enchant the agave plant to create a powder that will light the fire.$B$BTravel northeast to the Boiling Pool and gather Incendia Agave." },
            { ids = { 5088 }, name = "Arikara", level = 28, zone = "Thunder Bluff", giver = "Magatha Grimtotem", giverMap = 1456, giverX = 69.8, giverY = 30.9, ender = "Motega Firemane", enderMap = 1441, enderX = 21.5, enderY = 32.4, objective = "Slay Arikara. Bring her remains and the Incendia powder to Motega Firemane in Whitereach Post as proof of your deed.", summary = "Take this refined and purified Incendia powder to Thousand Needles and toss it on the sacred fire of life. It is located in the Darkcloud Pinnacle on an isolated needle where they bury their dead.$B$BThe enchantment that I have weaved into the Incendia powder will summon Arikara to you, $N.$B$BI fear she may be stalking Cairne Bloodhoof; too much Tauren lore has changed, and I fear this has angered Arikara. Move quickly before all is lost, $c!" },
        },
    },
    {
        id = "q1149",
        name = "Test of Lore",
        zone = "Thousand Needles",
        minLevel = 25,
        maxLevel = 36,
        importance = 3,
        kind = "dungeon",
        quests = {
            { ids = { 1149 }, name = "Test of Faith", level = 26, zone = "Thousand Needles", giver = "Dorn Plainstalker", giverMap = 1441, giverX = 54.0, giverY = 41.5, ender = "Dorn Plainstalker", enderMap = 1441, enderX = 54.0, enderY = 41.5, objective = "If you have faith, leap from the planks overlooking Thousand Needles.", summary = "So, you have sought me out, or perhaps destiny brings you to me? No matter. You are here now, and so your journey will begin anew.$B$BMany facets make up a being: the spirit, the body, the mind. Some of these can be measured by a culture's traditions. Others we can only hope exist within ourselves. If you agree, I shall test some of the facets within you.$B$BIf you pass, then you shall become stronger. If you fail, then you will realize the vastness of the Nether.$B$BThe first is a Test of Faith." },
            { ids = { 1150 }, name = "Test of Endurance", level = 30, zone = "Thousand Needles", giver = "Dorn Plainstalker", giverMap = 1441, giverX = 54.0, giverY = 41.5, ender = "Dorn Plainstalker", enderMap = 1441, enderX = 54.0, enderY = 41.5, objective = "Bring Grenka's Claw to Dorn Plainstalker in Thousand Needles.", summary = "I'm pleased to see your courage remains steadfast in light of what you've already done. Since your faith is intact, the time has come to test your body.$B$BFirst is  a test of endurance. Go with friends to the Roguefeather Den west of Freewind Post. Make your way to the depths of their lair and destroy their foodstuffs. By then you should have provoked their fury, and if you are able to survive long enough, Grenka Bloodscreech herself will come for you--kill her and bring me her claw to complete your test." },
            { ids = { 1151 }, name = "Test of Strength", level = 30, zone = "Thousand Needles", giver = "Dorn Plainstalker", giverMap = 1441, giverX = 54.0, giverY = 41.5, ender = "Dorn Plainstalker", enderMap = 1441, enderX = 54.0, enderY = 41.5, objective = "Bring Fragments of Rok'Alim to Dorn Plainstalker in Thousand Needles.", summary = "During the time of the Old Gods, elementals inhabited much of this world. They worshipped the Old Gods, and the Gods, through their power, kept the elementals bound to this world. When the Old Gods were banished, the elementals faded from our world and now only return at the bidding of powerful mages.$B$BThere are exceptions though. Some elementals were powerful enough to remain here on their own. One such elemental is Rok'Alim.$B$BTo test your strength, find Rok'Alim in Thousand Needles and slay him." },
            { ids = { 1152 }, name = "Test of Lore", level = 30, zone = "Thousand Needles", giver = "Dorn Plainstalker", giverMap = 1441, giverX = 54.0, giverY = 41.5, ender = "Braug Dimspirit", enderMap = 1442, enderX = 78.8, enderY = 45.7, objective = "Find Braug Dimspirit near the entrance to Talondeep Path in Stonetalon Mountains.", summary = "Your time with me is just about finished. I am knowledgeable, but the Test of Lore is not mine to give. There are lessons to be learned and places to visit that others claim domain over.$B$BIf you are prepared, then seek out Braug Dimspirit--he is a shaman of great wisdom. He will test you further, so heed his words, $N.$B$BWhen you are ready, find the tunnel that connects the Stonetalon Mountains with Ashenvale: Braug dwells near there. And be careful, $N, the night elves may wish to impede your test." },
            { ids = { 1154 }, name = "Test of Lore", level = 30, zone = "Stonetalon Mountains", giver = "Braug Dimspirit", giverMap = 1442, giverX = 78.8, giverY = 45.7, ender = "Braug Dimspirit", enderMap = 1442, enderX = 78.8, enderY = 45.7, objective = "Find the Legacy of the Aspects and return it to Braug Dimspirit near the entrance to Talondeep Path in Stonetalon Mountains.", summary = "You have passed Dorn's tests, and now you seek to pass your next trial. Very good. But up until now, your challenges have been childish. It is easy to test your body--your mind is another matter completely.$B$BI shall explain it simply: find the book I name, study it, and answer my question about its contents.$B$BWhat book, you must be asking? The Legacy of the Aspects. It can be found at the bottom of Dor'danil in southern Ashenvale, protected by the dead druids and their slayers." },
            { ids = { 6627 }, name = "Test of Lore", level = 30, zone = "Stonetalon Mountains", giver = "Braug Dimspirit", giverMap = 1442, giverX = 78.8, giverY = 45.7, ender = "Braug Dimspirit", enderMap = 1442, enderX = 78.8, enderY = 45.7, objective = "Answer Braug Dimspirit's question successfully and then speak to him again. He will remain in Stonetalon Mountains when you are ready.", summary = "You have brought me the book, and now it is time for your question. Are you ready?$B$BTime is not an issue, $c, so do not feel pressured. You may take as long as you like to answer." },
            { ids = { 1159 }, name = "Test of Lore", level = 30, zone = "Stonetalon Mountains", giver = "Braug Dimspirit", giverMap = 1442, giverX = 78.8, giverY = 45.7, ender = "Parqual Fintallas", enderMap = 1458, enderX = 57.8, enderY = 65.4, objective = "Find Parqual Fintallas in Undercity.", summary = "Well done, $N. You have passed the first portion of the Test of Lore, but there is still another question to be answered. But that question is not mine to ask.$B$BSeek out Parqual Fintallas in Lordaeron City. He was a great historian for the humans before the Plague overtook him. Now he continues to seek enlightenment, but of a different nature.$B$BHe will have another requirement of you before he asks you anything, but you have done masterfully thus far--I'm sure you will overcome his obstacle." },
            { ids = { 1160 }, name = "Test of Lore", level = 36, zone = "Undercity", giver = "Parqual Fintallas", giverMap = 1458, giverX = 57.8, giverY = 65.4, ender = "Parqual Fintallas", enderMap = 1458, enderX = 57.8, enderY = 65.4, objective = "Find The Beginnings of the Undead Threat, and return it to Parqual Fintallas in Undercity.", summary = "I will tell you what you must seek, and I will even ask you my question, but not because you wish to prove yourself. Knowledge is far more important than strength. Even as others seem to pass you by in ability, your knowledge of the world will be more valuable.$B$BGo to the Monastery in the north of Tirisfal Glades. In the library there, a book called Beginnings of the Undead Threat resides. It was used by the now-corrupt paladins there to train them to fight my kind.$B$BBring it to me." },
            { ids = { 6628 }, name = "Test of Lore", level = 30, zone = "Undercity", giver = "Parqual Fintallas", giverMap = 1458, giverX = 57.8, giverY = 65.4, ender = "Parqual Fintallas", enderMap = 1458, enderX = 57.8, enderY = 65.4, objective = "Answer Parqual Fintallas' question successfully and then speak to him again. He will remain in the Undercity until you are ready.", summary = "So the time is once again upon us. As a student of lore, you have shown great tenacity by undertaking my task.$B$BAnd so now I offer you your question. If you are ready, speak to me again, and take all the time you need, $N--there is no pressure to answer quickly." },
            { ids = { 1394 }, name = "Final Passage", level = 36, zone = "Undercity", giver = "Parqual Fintallas", giverMap = 1458, giverX = 57.8, giverY = 65.4, ender = "Dorn Plainstalker", enderMap = 1441, enderX = 54.0, enderY = 41.5, objective = "Speak to Dorn Plainstalker in Thousand Needles.", summary = "You have done well, $N. You have passed my test, and the tests before mine. Return to Dorn in Thousand Needles. He will sense the change within you, and see that your mind, body and spirit are strong enough that you should be rewarded for your efforts.$B$BStay true to the balance you've shown throughout these trials, $N. Dorn will test you again in the future if you do." },
        },
    },
    {
        id = "q1480",
        name = "The Corrupter",
        zone = "Desolace",
        minLevel = 25,
        maxLevel = 40,
        importance = 2,
        kind = "world",
        quests = {
            { ids = { 1480 }, name = "The Corrupter", level = 33, zone = "Desolace", ender = "Maurin Bonesplitter", enderMap = 1443, enderX = 52.2, enderY = 53.4, objective = "Bring the Flayed Demon Skin to Maurin Bonesplitter in Desolace.", summary = "The torn skin smells rotten, and is remarkably pliable for something that appears to be dry and fragile.$B$BAs you unroll it, you can clearly see the red markings of some kind of language on one side. At the bottom of the skin is a very clear symbol that you guess is a signature of some kind.$B$BPerhaps it is something Maurin could tell you more about?" },
            { ids = { 1481 }, name = "The Corrupter", level = 33, zone = "Desolace", giver = "Maurin Bonesplitter", giverMap = 1443, giverX = 52.2, giverY = 53.4, ender = "Maurin Bonesplitter", enderMap = 1443, enderX = 52.2, enderY = 53.4, objective = "Bring a Shadowstalker Scalp to Maurin Bonesplitter in Desolace.", summary = "I believe I can find this demon lord given the proper reagents.$B$BIf he is indeed as powerful as I suspect, I will need items gathered from deadly creatures. But you act in the Warchief's name, so I am sure you will accept my task.$B$BFirst, I will have to break any wards he has against scrying. For this, I will need the scalp from a satyr--but not any satyr. The scalp must come from a Hatefury shadowstalker.$B$BSearch for them among the ancient ruins in the northeast of Desolace." },
            { ids = { 1482 }, name = "The Corrupter", level = 35, zone = "Desolace", giver = "Maurin Bonesplitter", giverMap = 1443, giverX = 52.2, giverY = 53.4, ender = "Maurin Bonesplitter", enderMap = 1443, enderX = 52.2, enderY = 53.4, objective = "Bring an Oracle Crystal to Maurin Bonesplitter in Desolace.", summary = "An oracle crystal would do nicely. They are crafted by the naga for their oracles to use.$B$BNorthwest of here, along the coast, is a vast coral reef that the naga have taken as their home when this close to the shore. You can find their oracles there. The Slitherblade are deadly and will not react kindly to your intrusions, so be careful and make haste.$B$BWhen you return, we shall see about finding this demon lord Azrethoc." },
            { ids = { 1484 }, name = "The Corrupter", level = 35, zone = "Desolace", giver = "Maurin Bonesplitter", giverMap = 1443, giverX = 52.2, giverY = 53.4, ender = "Takata Steelblade", enderMap = 1443, enderX = 52.6, enderY = 54.4, objective = "Speak to Takata Steelblade in Desolace.", summary = "This creature is far more dangerous than I had anticipated.  No doubt Takata questions my abilities to take on such a creature, and it would insult his honor if he were not informed about what just happened.$B$BSpeak to the swordsman, tell him you are willing to slay the demon if he would allow it, but do not press too hard. It is better if he thinks it his own idea." },
            { ids = { 1488 }, name = "The Corrupter", level = 40, zone = "Desolace", giver = "Takata Steelblade", giverMap = 1443, giverX = 52.6, giverY = 54.4, ender = "Takata Steelblade", enderMap = 1443, enderX = 52.6, enderY = 54.4, objective = "Slay Lord Azrethoc and Jugkar Grim'rod and return to Takata Steelblade in Desolace.", summary = "Although I have no knowledge of this Lord Azrethoc, I agree with Maurin, he must be stopped; especially if he is attempting to gain influence over the Burning Blade to further his goals.$B$BYou have already shown you wish to aid the Warchief, and I would trust you to gather a party to slay the demon lord and his warlock servant.$B$BWhen you are ready, head directly south,  and return to me when the threat has been ended." },
        },
    },
    {
        id = "q1431",
        name = "Alliance Relations",
        zone = "Orgrimmar",
        minLevel = 25,
        maxLevel = 33,
        importance = 2,
        kind = "world",
        quests = {
            { ids = { 1431 }, name = "Alliance Relations", level = 30, zone = "Orgrimmar", giver = "Craven Drok", giverMap = 1454, giverX = 51.3, giverY = 45.9, ender = "Keldran", enderMap = 1454, enderX = 22.6, enderY = 52.6, objective = "Speak to Keldran in Orgrimmar.", summary = "Be still, $c, and allow me to share with you something important to our people, but far from obvious.$B$BWe are a proud race, and the war with the humans tried even Thrall's great patience. You see, our Warchief is wise and prudent, and he continues to put his people first. Ultimately, he is a diplomat, and in his time with the humans he learned much of their ways.$B$BIf the tale I've started piques your interest, then find Keldran near the western exit of the city. His hovel is there." },
            { ids = { 1432 }, name = "Alliance Relations", level = 30, zone = "Orgrimmar", giver = "Keldran", giverMap = 1454, giverX = 22.6, giverY = 52.6, ender = "Takata Steelblade", enderMap = 1443, enderX = 52.6, enderY = 54.4, objective = "Speak to Takata Steelblade in Desolace.", summary = "As the Alliance progresses deeper and deeper into Kalimdor, incorrect conclusions may be drawn about the Horde making pacts with the Burning Legion. The Warchief cannot allow that to happen. And with his blessing, I am taking control of overseeing them removed.$B$BI have agents in the area of Desolace at the Ghost Walker Post north of the great Kodo Graveyard. Head south of the Charred Vale in the Stonetalon Mountains and you shall come across it. When you arrive, seek out Takata Steelblade." },
            { ids = { 1433, 1436 }, name = "Alliance Relations", level = 33, zone = "Desolace", giver = "Takata Steelblade", giverMap = 1443, giverX = 52.6, giverY = 54.4, ender = "Maurin Bonesplitter", enderMap = 1443, enderX = 52.2, enderY = 53.4, objective = "Speak to Maurin Bonesplitter in Desolace.", summary = "The Burning Blade have many agendas, but know that they are evil to their core, their spirits corrupted, and their destruction is the only way to thwart their objectives.$B$BKeldran sent Maurin with me because of his knowledge of the Blade and their warlock ways.$B$BHe has control of our plots against the Blade while I deal with the other demonic threats here in Desolace.$B$BSpeak to him, and he will guide you in his designs." },
            { ids = { 1434 }, name = "Befouled by Satyr", level = 33, zone = "Desolace", giver = "Takata Steelblade", giverMap = 1443, giverX = 52.6, giverY = 54.4, ender = "Takata Steelblade", enderMap = 1443, enderX = 52.6, enderY = 54.4, objective = "Slay 7 Hatefury Rogues, 7 Hatefury Felsworn, 7 Hatefury Betrayers, and 7 Hatefury Hellcallers, and return to Takata Steelblade in Desolace.", summary = "A demon infestation does not occur without other influences--something else allows evil to gain a foothold.$B$BIt may start with a weakened spirit, a needless desire for power; perhaps it's a thirst for revenge, or the appeal for final justice. When we are beset by pain, evil takes advantage of us--evil such as the satyr.$B$BTies have been made between them and the Burning Blade, and Thrall would have them slain. Seek them out to the northeast of here, and return to me when you've driven them back." },
            { ids = { 1435 }, name = "The Burning of Spirits", level = 33, zone = "Desolace", giver = "Maurin Bonesplitter", giverMap = 1443, giverX = 52.2, giverY = 53.4, ender = "Maurin Bonesplitter", enderMap = 1443, enderX = 52.2, enderY = 53.4, objective = "Return the Burning Gem and 15 Infused Burning Gems to Maurin Bonesplitter in Desolace.", summary = "Death is most desirable for those despicable creatures that turn their back on their liege for such selfish reasons. But death is not enough when dealing with those that have given themselves over to the darkness.$B$BTake this gem. When one of the Burning Blade's near death, activate its magic. The spell shall pull the corrupted spirit out of its victim, leaving an infused gem behind.$B$BBring me these infused gems so I may dispose of them properly.$B$BGo now, and may you elude death." },
        },
    },
    {
        id = "q1104",
        name = "Martek the Exiled",
        zone = "Thousand Needles",
        minLevel = 26,
        maxLevel = 41,
        importance = 1,
        kind = "world",
        quests = {
            { ids = { 1104 }, name = "Salt Flat Venom", level = 30, zone = "Thousand Needles", giver = "Fizzle Brassbolts", giverMap = 1441, giverX = 78.1, giverY = 77.1, ender = "Fizzle Brassbolts", enderMap = 1441, enderX = 78.1, enderY = 77.1, objective = "Bring 6 Salty Scorpid Venoms to Fizzle Brassbolts in the Shimmering Flats.", summary = "I have so many designs for our rocket car!  So many!  And I must try them all!!$B$BI'm working on a new type of fuel.  One that burns really really really hot!!  I haven't gotten the mixture perfect, but I think I know what I need...$B$BThe scorpids who wander the Shimmering Flats have a venom with lots and lots of salt in it.  It's very unique!  And it's just what I need!$B$BBring me venom and trust me -- our car will fly!!" },
            { ids = { 1105 }, name = "Hardened Shells", level = 30, zone = "Thousand Needles", giver = "Wizzle Brassbolts", giverMap = 1441, giverX = 78.1, giverY = 77.1, ender = "Wizzle Brassbolts", enderMap = 1441, enderX = 78.1, enderY = 77.1, objective = "Bring 9 Hardened Tortoise Shells to Wizzle Brassbolts in the Shimmering Flats.", summary = "My brother is working on a new fuel for his rocket car.  He's brilliant, he really is.  So brilliant that... I think that new fuel he's designing is strong enough to eat right through the car's chassis!$B$BI want to reinforce its fuel tanks before that happens.$B$BThe tortoises out on the flats have very hard shells.  I want to use them to create new tanks for our rocket car.  Tanks that can hold my brother's new fuel.$B$BYou look responsible enough.  Will you get me those shells?" },
            { ids = { 1106 }, name = "Martek the Exiled", level = 35, zone = "Thousand Needles", giver = "Fizzle Brassbolts", giverMap = 1441, giverX = 78.1, giverY = 77.1, ender = "Martek the Exiled", enderMap = 1418, enderX = 42.2, enderY = 52.7, objective = "Bring Fizzle's Letter to Martek the Exiled in the Badlands.", summary = "I'm developing a new engine that'll make the car go so fast!  Fast enough to fly, I know it!  I just need to make pistons that can handle very very heavy stress.  All my trials have failed because I can't make pistons hard enough!$B$BBut there is someone who might know how.$B$BHis name is Martek the Exiled.  He is a great smith and knows more about metal than anyone.  Take him this letter, I know he can help!$B$BBut he's far far away -- in Azeroth, in the Badlands, in a camp, with a goblin!$B$BFind him!" },
            { ids = { 1108 }, name = "Indurium", level = 39, zone = "Badlands", giver = "Martek the Exiled", giverMap = 1418, giverX = 42.2, giverY = 52.7, ender = "Martek the Exiled", enderMap = 1418, enderX = 42.2, enderY = 52.7, objective = "Bring 10 Indurium Flakes to Martek the Exiled in the Badlands.", summary = "I'm not out here just to stay away from people.  There is a wealth of metal in the Badlands, $N, if you have the guts to get it.$B$BThe metal's called indurium and as luck would have it, it is rumored to possess high resistance to heat and stress.  It might work for Fizzle's car.$B$BBut let's make sure.  Get me samples of indurium and I'll test its properties.$B$BTrue indurium ore lies deep in Uldaman, but the Stonevault troggs of the Badlands sometimes have flakes of it on them.  Bring me those flakes." },
            { ids = { 1137 }, name = "News for Fizzle", level = 38, zone = "Badlands", giver = "Martek the Exiled", giverMap = 1418, giverX = 42.2, giverY = 52.7, ender = "Fizzle Brassbolts", enderMap = 1441, enderX = 78.1, enderY = 77.1, objective = "Speak with Fizzle Brassbolts in the Shimmering Flats.", summary = "Indurium has an amazing resistance to heat!  I'm sure it will work for Fizzle's pistons.  But he'll need true indurium ore, not just the flakes.$B$BTo get the ore, it must be mined from deep within Uldaman, on the northern borders of the Badlands.  That is the true source of indurium.$B$BSend Fizzle Brassbolts my regards, and tell him what I told you.$B$BSafe travels, $N.  And it won't surprise me if we meet again -- once Fizzle learns of indurium he'll probably send you to Uldaman to acquire it!" },
            { ids = { 1190 }, name = "Keeping Pace", level = 41, zone = "Thousand Needles", giver = "Pozzik", giverMap = 1441, giverX = 80.2, giverY = 75.9, ender = "Rizzle's Unguarded Plans", enderMap = 1441, enderX = 77.2, enderY = 77.4, objective = "Have Zamek create a diversion, then steal Rizzle's plans for Pozzik on the Shimmering Flats.", summary = "The Brassbolts brothers have discovered a new building material, that's the only explanation that makes sense. Their cars have been operating faster than before, but their designs, and all the other data we've gathered from their runs is identical.$b$bWhat we do know, is that Rizzle Brassbolts has been focused on the plans for this new discovery almost constantly.$b$bZamek can create a diversion for you, so that you can steal those plans from them." },
            { ids = { 1194 }, name = "Rizzle's Schematics", level = 41, zone = "Thousand Needles", giver = "Rizzle's Unguarded Plans", giverMap = 1441, giverX = 77.2, giverY = 77.4, ender = "Pozzik", enderMap = 1441, enderX = 80.2, enderY = 75.9, objective = "Bring the Sample of Indurium Ore to Pozzik on the Shimmering Flats.", summary = "Rizzle's schematics describe the process of the refinement of indurium ore. From his scrawls, it is apparent that indurium ore is being obtained from the dwarven excavation site of Uldaman in the Badlands.$b$bMuch of the other notes relate to the heat resistant properties.$b$bUsed as a paperweight for the plans is a hunk of what appears to be unrefined indurium ore." },
        },
    },
    {
        id = "q6522",
        name = "An Unholy Alliance",
        zone = "Razorfen Downs",
        minLevel = 28,
        maxLevel = 36,
        importance = 2,
        kind = "dungeon",
        quests = {
            { ids = { 6522 }, name = "An Unholy Alliance", level = 36, zone = "Razorfen Downs", ender = "Varimathras", enderMap = 1458, enderX = 56.2, enderY = 92.2, objective = "Take the Small Scroll to Varimathras in the Undercity.", summary = "My Lady,$B$BYou know very well what it is we are offering. The opportunity for you to take the Barrens and the lands beyond is a great one. We simply want your aid in return. By aid we mean nothing more than your giving us the freedom to take action in the area.$B$BPlease, allow us to discuss this further. We have great power and are willing to share with those wise enough to join us. I will remain outside Razorfen Downs for the time being.$B$BBest Regards,$BAmbassador Malcin" },
            { ids = { 6521 }, name = "An Unholy Alliance", level = 36, zone = "Undercity", giver = "Varimathras", giverMap = 1458, giverX = 56.2, giverY = 92.2, ender = "Varimathras", enderMap = 1458, enderX = 56.2, enderY = 92.2, objective = "Bring Ambassador Malcin's Head to Varimathras in the Undercity.", summary = "Malcin claims he is outside Razorfen Downs. This ambassador must be slain--his mission a failure in the eyes of the Lich King.$B$BHis presence there does explain much of what we've discovered about the area--some of the quilboar have grown frightfully powerful while showing signs of the Plague in their own way. Truly that must be a sign of some sort of deal they've struck.$B$BFind Malcin and slay him, $N. Return to me after the deed is done." },
        },
    },
    {
        id = "q1145",
        name = "Parts of the Swarm",
        zone = "The Barrens",
        minLevel = 28,
        maxLevel = 35,
        importance = 1,
        kind = "world",
        quests = {
            { ids = { 1145 }, name = "The Swarm Grows", level = 33, zone = "The Barrens", giver = "Korran", giverMap = 1413, giverX = 51.1, giverY = 29.6, ender = "Belgrom Rockmaul", enderMap = 1454, enderX = 75.2, enderY = 34.2, objective = "Deliver Korran's Sealed Note to Belgrom Rockmaul in Orgrimmar.", summary = "Many travelers who've come through the Crossroads helped me gather eggs from the Field of Giants, and many of them have tales of how deadly the creatures are. I've heard enough to consider them insects a much larger threat than my masters first thought.$B$BI need a courier to travel to Orgrimmar to meet Belgrom Rockmaul. It be no simple matter, and someone who would take the task seriously should go.$B$BBelgrom usually be found outside the warriors' guild house." },
            { ids = { 1146 }, name = "The Swarm Grows", level = 33, zone = "Orgrimmar", giver = "Belgrom Rockmaul", giverMap = 1454, giverX = 75.2, giverY = 34.2, ender = "Moktar Krin", enderMap = 1441, enderX = 67.6, enderY = 63.9, objective = "Deliver Belgrom's Sealed Note to Moktar Krin in Thousand Needles.", summary = "So, Korran has come to a similar conclusion about these insects--they seem to be a larger threat than we assumed.$B$BA few days ago a hunter returned to me from Thousand Needles nearly dead. He was with a raiding party sent to drive a dwarven excavation team out of the Shimmering Flats. During the attack, more of these insects erupted from a cave in the dig site and nearly killed the party.$B$BThey were led by Moktar Krin, and they've taken refuge on the border of the Shimmering Flats. Bring him this note." },
            { ids = { 1148 }, name = "Parts of the Swarm", level = 35, zone = "Thousand Needles", ender = "Korran", enderMap = 1413, enderX = 51.1, enderY = 29.6, objective = "Bring 1 Silithid Heart, 5 Silithid Talons, and 3 Intact Silithid Carapaces, to Korran at the Crossroads.", summary = "You inspect the carapace carefully. As you turn it over in your hands you realize that the chitinous plating is interlaced in such a way that makes it incredibly strong. It's unlike anything you've ever seen. You inspect the rest of the corpse further and realize that these creatures are very powerful and highly evolved.$B$BLooking down at the carapace again, you think that Korran would enjoy studying more of these creatures. It could help him figure out what these creatures are, and where they come from." },
            { ids = { 1184 }, name = "Parts of the Swarm", level = 35, zone = "The Barrens", giver = "Korran", giverMap = 1413, giverX = 51.1, giverY = 29.6, ender = "Belgrom Rockmaul", enderMap = 1454, enderX = 75.2, enderY = 34.2, objective = "Return to Belgrom Rockmaul in Orgrimmar.", summary = "Head back to Belgrom in Orgrimmar and tell him Moktar be doing his bidding well out in the Thousand Needles. Tell him also, that me studies progress, and I hope to be havin' learned more soon. That should please him greatly." },
        },
    },
    {
        id = "q1178",
        name = "Goblin Sponsorship",
        zone = "Thousand Needles",
        minLevel = 29,
        maxLevel = 41,
        importance = 2,
        kind = "world",
        quests = {
            { ids = { 1176 }, name = "Load Lightening", level = 30, zone = "Thousand Needles", giver = "Pozzik", giverMap = 1441, giverX = 80.2, giverY = 75.9, ender = "Pozzik", enderMap = 1441, enderX = 80.2, enderY = 75.9, objective = "Get 10 Hollow Vulture Bones for Pozzik in the Shimmering Flats.", summary = "When it comes to racing, every bit counts! Whether it's a minor tweaking on the power output, a slight slackening on the tension coils, or lightening the weight of the frame, you have to take everything into account.$b$bWe use vulture bones for a lot of the minor structural tweaks we make to our racers, which offer the perfect balance of strength and weight. Even better, it's easy for us to get more, as the salt flats are littered with vultures.$b$bBring me some and I'll give you a good price on them." },
            { ids = { 1178 }, name = "Goblin Sponsorship", level = 37, zone = "Thousand Needles", giver = "Pozzik", giverMap = 1441, giverX = 80.2, giverY = 75.9, ender = "Gazlowe", enderMap = 1413, enderX = 62.7, enderY = 36.2, objective = "Speak to Gazlowe in Ratchet.", summary = "Our racing team is the pride of goblins everywhere. You'd be surprised at some of the people who contribute in one way or another to our team.$b$bYou know Gazlowe? He tracks down parts from around the world for us. He even came down to work on one of our rigs once!$b$bA few weeks ago, he said he'd send us a new prototype fuel regulator but it hasn't come yet. He's usually very prompt... Maybe you wouldn't mind going to Ratchet to ask him about it? I wouldn't be so pushy, but the gnomes are gaining on us!" },
            { ids = { 1180 }, name = "Goblin Sponsorship", level = 37, zone = "The Barrens", giver = "Gazlowe", giverMap = 1413, giverX = 62.7, giverY = 36.2, ender = "Wharfmaster Lozgil", enderMap = 1434, enderX = 26.4, enderY = 73.6, objective = "Speak with Wharfmaster Lozgil in Booty Bay.", summary = "Back to what you came here about. I know I promised Pozzik that I'd deliver a new fuel regulator for him, but I still haven't received it yet. Revilgaz over in Booty Bay said he'd have it shipped over, but it might be it slipped through the cracks somehow.$b$bIf that's true, there's not much we can do about it. We can at least find out if it was dispatched from Booty Bay.$b$bCheck in with Wharfmaster Lozgil over there, he should be able to check the cargo records." },
            { ids = { 1181 }, name = "Goblin Sponsorship", level = 37, zone = "Stranglethorn Vale", giver = "Wharfmaster Lozgil", giverMap = 1434, giverX = 26.4, giverY = 73.6, ender = "Baron Revilgaz", enderMap = 1434, enderX = 27.2, enderY = 76.9, objective = "Speak with Baron Revilgaz in Booty Bay.", summary = "I'm afraid I can't be of much more help to you, $n. If you'd like to follow up on it more, I'd suggest you go hit up the Baron himself. If there's anyone who knows Revilgaz's business, it's Revilgaz.$b$bYou'll find him at the tavern across the harbor, top floor." },
            { ids = { 1182 }, name = "Goblin Sponsorship", level = 37, zone = "Stranglethorn Vale", giver = "Baron Revilgaz", giverMap = 1434, giverX = 27.2, giverY = 76.9, ender = "Baron Revilgaz", enderMap = 1434, enderX = 27.2, enderY = 76.9, objective = "Bring the Fuel Regulator Blueprints to Baron Revilgaz in Booty Bay.", summary = "See, the Venture Company shredders out in Lake Nazferiti (in northern Stranglethorn) have been equipped with a new model fuel regulator. I was thinking that Pozzik would be able to take advantage of it, if he could get some details. Unfortunately, Cozzle, the foreman out there, appears to be a little more clever than I gave him credit for.$b$bYou seem like you might have more luck finding the blueprints though. I know he keeps them in his house, but they're almost certainly under lock and key." },
            { ids = { 1183 }, name = "Goblin Sponsorship", level = 37, zone = "Stranglethorn Vale", giver = "Baron Revilgaz", giverMap = 1434, giverX = 27.2, giverY = 76.9, ender = "Pozzik", enderMap = 1441, enderX = 80.2, enderY = 75.9, objective = "Deliver the Fuel Regulator Blueprints to Pozzik on the Shimmering Flats.", summary = "You should be all set to go. Give Pozzik my regards and tell him that if he ever needs anything, not to hesitate to ask. I'll be waiting for the news that he breaks the track record soon!" },
            { ids = { 1186 }, name = "The Eighteenth Pilot", level = 37, zone = "Thousand Needles", giver = "Pozzik", giverMap = 1441, giverX = 80.2, giverY = 75.9, ender = "Razzeric", enderMap = 1441, enderX = 80.3, enderY = 76.1, objective = "Speak with Razzeric on the Shimmering Flats.", summary = "I'm going to be busy with working on integrating this new fuel regulator to our racer designs, but if you'd like to help out the team some more, talk to Razzeric. He's our pilot--well, our eighteenth pilot, to be exact--and he likes to add his own little modifications to the racers.$b$bHe's a little off his rocker, though, so try not to act too surprised." },
            { ids = { 1187 }, name = "Razzeric's Tweaking", level = 41, zone = "Thousand Needles", giver = "Razzeric", giverMap = 1441, giverX = 80.3, giverY = 76.1, ender = "Razzeric", enderMap = 1441, enderX = 80.3, enderY = 76.1, objective = "Retrieve the Seaforium Booster for Razzeric in the Shimmering Flats.", summary = "Pozzik's a great mechanic, I know that, but he's afraid to just load on the firepower and grab on for the ride. Not me, though.$b$bAfter Pozzik finishes with a racer, I take a little time to put my own modifications on--you know, loosening up the controls, removing parts of the frame, and adding more juice!$b$bI ordered a seaforium booster from Shreev at the Gizmorium in Gadgetzan, but apparently the zeppelin it was being sent on crashed in Dustwallow Marsh! I gotta have it, $n!" },
            { ids = { 1188 }, name = "Safety First", level = 41, zone = "Thousand Needles", giver = "Razzeric", giverMap = 1441, giverX = 80.3, giverY = 76.1, ender = "Shreev", enderMap = 1446, enderX = 51.0, enderY = 27.2, objective = "Bring the Seaforium Booster to Shreev in Gadgetzan.", summary = "But wait, what's this? Shreev left the safety on. That will limit the amount of power I can draw from the booster at any time. I told him I wanted it off! This is no good.$b$bYou have to take this to the Gadgetzan Gizmorium in the Tanaris Desert and have Shreev remove this." },
            { ids = { 1189 }, name = "Safety First", level = 41, zone = "Tanaris", giver = "Shreev", giverMap = 1446, giverX = 51.0, giverY = 27.2, ender = "Razzeric", enderMap = 1441, enderX = 80.3, enderY = 76.1, objective = "Return the Modified Seaforium Booster to Razzeric on the Shimmering Flats.", summary = "There, I did what Razzeric wanted. Just tell him to be careful when he sets this off. If he makes the slightest mistake, he won't be moving forward, he'll just be a burnt spot on the track.$b$bWould be a shame, too, if that happened. Who knows if our nineteenth driver would be any good?" },
        },
    },
    {
        id = "q1238",
        name = "Service to the Horde",
        zone = "Dustwallow Marsh",
        minLevel = 30,
        maxLevel = 40,
        importance = 3,
        kind = "world",
        quests = {
            { ids = { 1238 }, name = "The Lost Report", level = 35, zone = "Dustwallow Marsh", giver = "Loose Dirt", giverMap = 1445, giverX = 55.4, giverY = 25.9, ender = "Nazeer Bloodpike", enderMap = 1445, enderX = 35.2, enderY = 30.7, objective = "Bring the Spy's Report to Nazeer Bloodpike in Brackenwall Village.", summary = "Sifting through the loose dirt, the severed hand of an orc is found.  And clutched in the hand is a bone-carved tube.  And in the tube is a dirt-stained parchment.$B$BThe parchment is a report made by an orc who spent weeks spying on the city of Theramore.$B$BAfter scanning the parchment, it is clear that it must be brought to the orc spymaster in Brackenwall Village." },
            { ids = { 1239 }, name = "The Severed Head", level = 35, zone = "Dustwallow Marsh", giver = "Loose Dirt", giverMap = 1445, giverX = 55.4, giverY = 25.9, ender = "Nazeer Bloodpike", enderMap = 1445, enderX = 35.2, enderY = 30.7, objective = "Bring the Defiant Orc Head to Nazeer Bloodpike in Brackenwall Village.", summary = "Vigorous digging reveals the head of a male orc, raggedly severed at the neck.  His lips are frozen in a snarl, and its dark eyes stare defiantly." },
            { ids = { 1240 }, name = "The Troll Witchdoctor", level = 35, zone = "Dustwallow Marsh", giver = "Nazeer Bloodpike", giverMap = 1445, giverX = 35.2, giverY = 30.7, ender = "Kin'weelay", enderMap = 1434, enderX = 32.3, enderY = 27.7, objective = "Take the Defiant Orc Head to Kin'weelay in the Grom'gol Base Camp in Stranglethorn Vale.", summary = "We must know the events surrounding Marg's death!  And the only way to do that, $N, is through the witch-magic of trolls.$B$BBring Marg's head to Kin'weelay in Stranglethorn Vale, at the Grom'gol Base Camp.$B$BKin'weelay is the most powerful witchdoctor of the Darkspear trolls.  If anyone can speak to Marg Nighteye's spirit, it is he." },
            { ids = { 1261 }, name = "Marg Speaks", level = 40, zone = "Stranglethorn Vale", giver = "Bubbling Cauldron", giverMap = 1434, giverX = 32.2, giverY = 27.6, ender = "Nazeer Bloodpike", enderMap = 1445, enderX = 35.2, enderY = 30.7, objective = "Bring the Jeweled Pendant to Nazeer in Brackenwall Village.", summary = "Cursed muckshell!  You can't kill Marg!  Ah, but I am dead.  So it must have slain me...$B$BBut my mission!  My mission!  You, $N, must complete it.$B$BWhile near Theramore, I spied a group of Alliance soldiers camped on the beach.  And one soldier wore a pendant... a pendant laden with more gems than any soldier could afford!$B$BThat night I snuck into their camp and stole the pendant, but on my return to base a muckshell crab-man killed me!$B$B$N, you must find that muckshell and recover the pendant!" },
            { ids = { 1262 }, name = "Report to Zor", level = 40, zone = "Dustwallow Marsh", giver = "Nazeer Bloodpike", giverMap = 1445, giverX = 35.2, giverY = 30.7, ender = "Zor Lonetree", enderMap = 1454, enderX = 38.9, enderY = 38.4, objective = "Bring the Jeweled Pendant to Zor Lonetree in Orgrimmar.", summary = "It is strange that the pendant Marg stole was in the hands of common soldiers.  Perhaps its owner was in disguise, or perhaps the soldiers themselves stole it!$B$BRegardless of which is true, this is a noble's pendant and we must discover its true owner if we are to unravel its mystery.$B$BTake the pendant to Zor Lonetree in Orgrimmar.  He is well schooled in Alliance politics, and will know if this pendant has a history among the nobles of Stormwind." },
            { ids = { 7541 }, name = "Service to the Horde", level = 40, zone = "Orgrimmar", giver = "Zor Lonetree", giverMap = 1454, giverX = 38.9, giverY = 38.4, ender = "Zor Lonetree", enderMap = 1454, enderX = 38.9, enderY = 38.4 },
        },
    },
    {
        id = "q1111",
        name = "The Rumormonger",
        zone = "Stranglethorn Vale",
        minLevel = 30,
        maxLevel = 44,
        importance = 3,
        kind = "world",
        quests = {
            { ids = { 621 }, name = "Zanzil's Secret", level = 44, zone = "Stranglethorn Vale", giver = "Crank Fizzlebub", giverMap = 1434, giverX = 27.1, giverY = 77.2, ender = "Crank Fizzlebub", enderMap = 1434, enderX = 27.1, enderY = 77.2, objective = "Bring 12 samples of Zanzil's Mixture to Crank Fizzlebub in Booty Bay.", summary = "Zanzil the Outcast dwells with his followers in the Jubuwai and Aboraz Ruins, northeast of Booty Bay.  He is exiled from his tribe.  Why? Well...$B$BZanzil has methods of bending the minds of others, and his leaders fear him.  He uses a mixture of jungle plants on his followers to suppress their will and strengthen their bodies.$B$BHis mixture would be worth much to those who wish to control others.$B$BBring me samples of his mixture, and I will find a use for them." },
            { ids = { 1111 }, name = "Wharfmaster Dizzywig", level = 36, zone = "Thousand Needles", giver = "Kravel Koalbeard", giverMap = 1441, giverX = 77.8, giverY = 77.3, ender = "Wharfmaster Dizzywig", enderMap = 1413, enderX = 63.4, enderY = 38.5, objective = "Bring Kravel's Parts Order to Wharfmaster Dizzywig in Ratchet.", summary = "I make it my job to get people what they need, and the gnomes over there need a parts order filled.  Their parts were shipped to Ratchet a week ago, but I haven't been able to make the trip.$B$BSo, are you ready for some legwork?  Go to Ratchet and give this parts order to Wharfmaster Dizzywig -- he'll probably be at the docks.$B$BDo this for me, and I'll have more jobs for you.$B$BJobs, my friend, with serious profit potential..." },
            { ids = { 1112 }, name = "Parts for Kravel", level = 36, zone = "The Barrens", giver = "Wharfmaster Dizzywig", giverMap = 1413, giverX = 63.4, giverY = 38.5, ender = "Kravel Koalbeard", enderMap = 1441, enderX = 77.8, enderY = 77.3, objective = "Bring Kravel's Parts to Kravel Koalbeard in the Shimmering Flats.", summary = "Here's Kravel's package, $N.  And when you deliver it, tell him... if he wants more special orders, then he'll have to pay his tab!" },
            { ids = { 1114 }, name = "Delivery to the Gnomes", level = 36, zone = "Thousand Needles", giver = "Kravel Koalbeard", giverMap = 1441, giverX = 77.8, giverY = 77.3, ender = "Fizzle Brassbolts", enderMap = 1441, enderX = 78.1, enderY = 77.1, objective = "Bring the Delicate Car Parts to Fizzle Brassbolts in Shimmering Flats.", summary = "Now that I have what I need, give these parts to Fizzle Brassbolts.  He's been waiting a long time for them -- I'm sure he won't miss the little piece I removed from his order...$B$BAnd I wouldn't bother mentioning it to him.  It was small and worthless.$B$BTrust me." },
            { ids = { 1115 }, name = "The Rumormonger", level = 36, zone = "Thousand Needles", giver = "Kravel Koalbeard", giverMap = 1441, giverX = 77.8, giverY = 77.3, ender = "Krazek", enderMap = 1434, enderX = 26.9, enderY = 77.2, objective = "Talk to Krazek in Booty Bay.", summary = "Now that we've done a service for the gnomes, it's time to do the goblins a favor!  $B$BI hear that the goblin racer pilot, Nazz Steamboil, didn't always use that name.  I wonder why he changed it.  I wonder if it's a secret, and... I wonder if he values that secret.$B$BIf anyone knows the truth, then it's Krazek of Booty Bay, on the southern tip of Stranglethorn.  Speak with Krazek and ask him about our goblin pilot.$B$BIf you can get useful information from him, then we might just turn a profit from it." },
            { ids = { 1116 }, name = "Dream Dust in the Swamp", level = 36, zone = "Stranglethorn Vale", giver = "Krazek", giverMap = 1434, giverX = 26.9, giverY = 77.2, ender = "Krazek", enderMap = 1434, enderX = 26.9, enderY = 77.2, objective = "Bring 10 Specks of Dream Dust to Krazek in Booty Bay.  Dream Dust is gathered from the dragon whelps of the Swamp of Sorrows.", summary = "Getting the information on Nazz is quite a favor, $N.  Yes, quite a favor.  But you've come all the way from the Shimmering Flats to get it... are you willing to travel some more?$B$BWhile I contact my sources, why don't you gather something for me, eh?$B$BHm... what will it be?  How about dream dust, from the dragon whelps of the Swamp of Sorrows.  Yes, I'd love some dream dust for my snuff pouch!$B$BGet it for me, $N, and I'll give you the information you seek." },
            { ids = { 1117 }, name = "Rumors for Kravel", level = 36, zone = "Stranglethorn Vale", giver = "Krazek", giverMap = 1434, giverX = 26.9, giverY = 77.2, ender = "Kravel Koalbeard", enderMap = 1441, enderX = 77.8, enderY = 77.3, objective = "Bring the Goblin Rumors to Kravel Koalbeard in the Shimmering Flats.", summary = "I had to use some of my favors, and gave away a rare bottle of elven wine, and did some heavy deducing myself!  But I found the information you seek.$B$BHere, I wrote a letter with some very interesting bits on our friend, Nazz Steamboil.  Do with it what you will -- it's too dangerous for me to use.$B$BJust don't tell anyone where you got it!" },
            { ids = { 1118 }, name = "Back to Booty Bay", level = 43, zone = "Thousand Needles", giver = "Kravel Koalbeard", giverMap = 1441, giverX = 77.8, giverY = 77.3, ender = "Crank Fizzlebub", enderMap = 1434, enderX = 27.1, enderY = 77.2, objective = "Bring Kravel's Scheme to Crank Fizzlebub in Booty Bay.", summary = "$N, you're a $c I can trust, both to get the job done and to keep your mouth shut while doing it.$B$BI've been brewing up a new scheme.  It's risky, but if it works then we could both make a bundle!  And I think you're just the person to see it through.$B$BTo start, you must go back to Booty Bay.  I apologize, good $N.  I know my last task took you there.  But this time, speak with Crank Fizzlebub.$B$BGive him this letter.  And if he requires aid, do your best to help him.  It will be worth the effort." },
            { ids = { 1119 }, name = "Zanzil's Mixture and a Fool's Stout", level = 44, zone = "Stranglethorn Vale", giver = "Crank Fizzlebub", giverMap = 1434, giverX = 27.1, giverY = 77.2, ender = "Kravel Koalbeard", enderMap = 1441, enderX = 77.8, enderY = 77.3, objective = "Bring the Fool's Stout back to Kravel in the Shimmering Flats.", summary = "I figured out how to use Zanzil's mixture with stout to make a powerful libation.  A Fool's Stout.  I think it'll be just what Kravel needs, but try it out and let me know how it works.$B$BAnd $N, don't keep this stuff too long without using it.  Zanzil's mixture has a weird effect on the stout's yeast, kicking it into high gear.  So it won't stay fresh forever." },
            { ids = { 1120 }, name = "Get the Gnomes Drunk", level = 44, zone = "Thousand Needles", giver = "Kravel Koalbeard", giverMap = 1441, giverX = 77.8, giverY = 77.3, ender = "Gnome Pit Boss", enderMap = 1441, enderX = 77.6, enderY = 76.9, objective = "Bring the Fool's Stout to the Gnome Pit Boss.", summary = "We need to try the Fool's Stout on one of the pit crews.  If you want to try it on the gnomes, then here -- take the stout and give it to the gnome pit boss.$B$BAnd don't wait too long.  This stout will go bad eventually." },
            { ids = { 1122 }, name = "Report Back to Fizzlebub", level = 44, zone = "Thousand Needles", giver = "Kravel Koalbeard", giverMap = 1441, giverX = 77.8, giverY = 77.3, ender = "Crank Fizzlebub", enderMap = 1434, enderX = 27.1, enderY = 77.2, objective = "Bring the Fool's Stout report to Crank Fizzlebub in Booty Bay.", summary = "That Fool's Stout worked great!  I placed a bet on the next race, and... let's hope the crew you got drunk did a number on their car!$B$BThere's only one more task for you -- take this note back to Crank Fizzlebub in Booty Bay.  He'll want to know of the successful test.$B$BAnd hopefully we can get more of that Fool's Stout for future races!" },
        },
    },
    {
        id = "q1109",
        name = "Hearts of Zeal",
        zone = "Undercity",
        minLevel = 30,
        maxLevel = 33,
        importance = 3,
        kind = "dungeon",
        quests = {
            { ids = { 1109 }, name = "Going, Going, Guano!", level = 33, zone = "Undercity", giver = "Master Apothecary Faranell", giverMap = 1458, giverX = 48.8, giverY = 69.3, ender = "Master Apothecary Faranell", enderMap = 1458, enderX = 48.8, enderY = 69.3, objective = "Bring 1 pile of Kraul Guano to Master Apothecary Faranell in the Undercity.", summary = "As you can see, $n, we're up to some very.... interesting experiments at the Royal Apothecary Society.$b$bAs the Master here, it is my job to oversee the most ambitious of our alchemical attempts. So much work and so little time!$b$bYou look well traveled for a $c. Perhaps you can aid me.$b$bI'm in need of a rare substance. It's foul material; it comes from a rare species of bats only found in the muck-hole known as Razorfen Kraul. Bring to me the guano from the Kraul Bats so we can begin our work..." },
            { ids = { 1113 }, name = "Hearts of Zeal", level = 33, zone = "Undercity", giver = "Master Apothecary Faranell", giverMap = 1458, giverX = 48.8, giverY = 69.3, ender = "Master Apothecary Faranell", enderMap = 1458, enderX = 48.8, enderY = 69.3, objective = "Master Apothecary Faranell in the Undercity wants 20 Hearts of Zeal.", summary = "Why do I need a rare type of guano, you might ask. Well, for this experiment I want to see what effect two diametrically opposed chemical substances can have on each other, especially when both are combined with an ever-toxic agent to ensure the most... ghastly results.$b$bIn the northeastern peaks of Tirisfal Glades lies the Scarlet Monastery. There the crazed disciples of the Scarlet Crusade congregate. Slay them and bring me their zealous hearts.$b$bOur concoction will be most wicked!" },
        },
    },
    {
        id = "q1718",
        name = "Cyclonian",
        zone = "Thunder Bluff",
        minLevel = 30,
        maxLevel = 40,
        importance = 2,
        kind = "class",
        classes = { 1 },
        quests = {
            { ids = { 1718 }, name = "The Islander", level = 30, zone = "Thunder Bluff", giver = "Torm Ragetotem", giverMap = 1456, giverX = 57.2, giverY = 87.4, ender = "Klannoc Macleod", enderMap = 1413, enderX = 68.6, enderY = 49.2, objective = "Speak with Klannoc Macleod.", summary = "Your renown as a warrior grows, $N.  Now it is time to pit yourself against your peers and see where you stand.$B$BThere is an island off the coast of the Barrens, south of Ratchet.  It is called Fray Island and it is a place where warriors meet.$B$BMeet, and fight.$B$BSpeak with the chief warrior of Fray Island, Klannoc Macleod.  If he finds you worthy, then Klannoc will lead you further down the warrior's path.$B$BTo reach Fray Island, search for the sand bar shallows along the Merchant Coast." },
            { ids = { 1719 }, name = "The Affray", level = 30, zone = "The Barrens", giver = "Klannoc Macleod", giverMap = 1413, giverX = 68.6, giverY = 49.2, ender = "Klannoc Macleod", enderMap = 1413, enderX = 68.6, enderY = 49.2, objective = "Kill Big Will, then speak to Klannoc Macleod on Fray Island.", summary = "If you want to learn from me, then you must first pass The Affray.  It is a challenge we on Fray Island like to offer rising warriors who think they're tough, and if you can pass this test then I'll know you are.$B$BTo begin, walk into the middle of that crowd yonder and step on the grate.  That'll tell Twiggy Flathead you're ready, and he'll send challengers against you.$B$BBeat all the challengers and he'll call out Big Will.  Kill Big Will, and return to me in the time we allow." },
            { ids = { 1791 }, name = "The Windwatcher", level = 30, zone = "The Barrens", giver = "Klannoc Macleod", giverMap = 1413, giverX = 68.6, giverY = 49.2, ender = "Bath'rah the Windwatcher", enderMap = 1416, enderX = 80.5, enderY = 66.9, objective = "Speak with Bath'rah the Windwatcher.", summary = "Now that you've learned your berserker's stance, you'll want a nice weapon to use it with.$B$BTalk to Bath'rah the Windwatcher, a troll hermit who lives between the Alterac Mountains and the Western Plaguelands.  He is a skilled weapon maker and a powerful shaman.$B$BTo find Bath'rah, go to the river that flows along Tarren Mill's eastern flank.  Follow it north--Bath'rah is camped near ruins that rest along the river's eastern bank." },
            { ids = { 1712 }, name = "Cyclonian", level = 40, zone = "Alterac Mountains", giver = "Bath'rah the Windwatcher", giverMap = 1416, giverX = 80.5, giverY = 66.9, ender = "Bath'rah the Windwatcher", enderMap = 1416, enderX = 80.5, enderY = 66.9, objective = "Bring the items on Bath'rah's Parchment to Bath'rah the Windwatcher in Alterac.", summary = "I have spent ages watching this site.  I watch, so that one day I might see the great Cyclonian fall.  But I have not yet found a champion to defeat the wind lord.$B$BPerhaps you are that champion.$B$BProve it to me.  Gather the items I need to summon Cyclonian, and I will know you are a great warrior.  Perhaps then you can defeat him and gain his whirlwind heart.$B$BIf so, then I will infuse the heart's power in a weapon, and I will give that weapon to you.$B$BHere is a parchment with the items I need." },
            { ids = { 1713 }, name = "The Summoning", level = 40, zone = "Alterac Mountains", giver = "Bath'rah the Windwatcher", giverMap = 1416, giverX = 80.5, giverY = 66.9, ender = "Bath'rah the Windwatcher", enderMap = 1416, enderX = 80.5, enderY = 66.9, objective = "Bring the Whirlwind Heart to Bath'rah Windwatcher.", summary = "I am ready to perform the ritual to summon Cyclonian.  When he is summoned, you must defeat him and take his whirlwind heart.  This I will use to instill a weapon with Cyclonian's power.$B$B$N, are you ready to face the wind lord?" },
            { ids = { 1792 }, name = "Whirlwind Weapon", level = 40, zone = "Alterac Mountains", giver = "Bath'rah the Windwatcher", giverMap = 1416, giverX = 80.5, giverY = 66.9, ender = "Bath'rah the Windwatcher", enderMap = 1416, enderX = 80.5, enderY = 66.9 },
        },
    },
    {
        id = "q3001",
        name = "Tome of the Cabal",
        zone = "Undercity",
        minLevel = 30,
        maxLevel = 30,
        importance = 2,
        kind = "class",
        classes = { 9 },
        quests = {
            { ids = { 3001 }, name = "Seeking Strahad", level = 30, zone = "Undercity", giver = "Carendin Halgar", giverMap = 1458, giverX = 85.1, giverY = 26.0, ender = "Strahad Farsan", enderMap = 1413, enderX = 62.6, enderY = 35.5, objective = "Find Strahad Farsan in Ratchet.", summary = "I have taught you skills in the past, but the time has come for another to teach you. He is in Ratchet, and his name is Strahad. He is human, but do not let that fool you into thinking he is weak, nor is he your enemy... at least for now. He is powerful and should be respected. He can teach you about greater summonings, summonings I feel you are prepared for. Go to him now.$B$BYou can find him in Ratchet... above the port town next to the tower there." },
            { ids = { 1801 }, name = "Tome of the Cabal", level = 30, zone = "The Barrens", giver = "Strahad Farsan", giverMap = 1413, giverX = 62.6, giverY = 35.5, ender = "Jorah Annison", enderMap = 1458, enderX = 75.9, enderY = 37.9, objective = "Speak with Jorah Annison in the Undercity.", summary = "It will take more than a simple summoning circle to bring forth a felhunter for you to challenge.$b$bMy three acolytes and I will assist in creating the magic circles. You require a copy of the Tome of the Cabal, which has been lost to us for some time. It was written by the first group of warlocks to summon a felhunter unaided.$b$bPerhaps Jorah Annison can help you with this. He's employed as a cartographer in the Undercity these days, but still knows more of ancient texts than any I know." },
            { ids = { 1803 }, name = "Tome of the Cabal", level = 30, zone = "Undercity", giver = "Jorah Annison", giverMap = 1458, giverX = 75.9, giverY = 37.9, ender = "Jorah Annison", enderMap = 1458, enderX = 75.9, enderY = 37.9, objective = "Retrieve the Moldy Tome and Tattered Manuscript for Jorah Annison in the Undercity.", summary = "Ah! I see that you are a warlock of similar tastes to mine. Indeed, acquiring the Tome of the Cabal is a worthy aspiration. Did you know that it was once held within the walls of Lordaeron? It was vandalized though, almost half its pages removed. Who would commit such a heinous act?$b$bThat half is lost, though rumor says that it fell into the hands of the centaur of the Thousand Needles.$b$bThe rest of the text was to be transferred to Ironforge, but was lost in transit on the coast west of Southshore." },
            { ids = { 1805 }, name = "Tome of the Cabal", level = 30, zone = "Undercity", giver = "Jorah Annison", giverMap = 1458, giverX = 75.9, giverY = 37.9, ender = "Strahad Farsan", enderMap = 1413, enderX = 62.6, enderY = 35.5, objective = "Bring the Reconstructed Tome and 3 Rods of Channeling to Strahad Farsan in Ratchet.", summary = "This is one of the most interesting texts I have perused in the last few years. The selection here is sparse--mostly books on geography--and I have already read them all. I should hope that Strahad would send me a copy of this tome when he has the chance.$b$bSpeaking of him, he sent word to me while you were away. For your task, you must obtain three rods of channeling.$b$bFor allowing me to look at this text, I will share a secret: You can find the rods on orcs of the Dragonmaw Clan in the Wetlands." },
            { ids = { 1795 }, name = "The Binding", level = 30, zone = "The Barrens", giver = "Strahad Farsan", giverMap = 1413, giverX = 62.6, giverY = 35.5, ender = "Strahad Farsan", enderMap = 1413, enderX = 62.6, enderY = 35.5, objective = "Using the Tome of the Cabal, summon and subdue a felhunter, then return the Tome of the Cabal to Strahad Farsan in Ratchet.", summary = "If you're are sufficiently prepared, then we should begin. Let me explain the process to you.$b$bI will begin by creating the basic summoning circle. When that is finished, my acolytes will use the rods of channeling to create the greater circle.$b$bOnce that is done, read the incantation from the Tome of the Cabal, and the felhunter will be pulled forth. Be careful, $n. A felhunter is a powerful foe, and I'd like to see you keep your head on your shoulders." },
        },
    },
    {
        id = "q1947",
        name = "Rituals of Power",
        zone = "Thunder Bluff",
        minLevel = 30,
        maxLevel = 40,
        importance = 2,
        kind = "class",
        classes = { 8 },
        quests = {
            { ids = { 1947 }, name = "Journey to the Marsh", level = 38, zone = "Thunder Bluff", giver = "Ursyn Ghull", giverMap = 1456, giverX = 25.7, giverY = 14.2, ender = "Tabetha", enderMap = 1445, enderX = 46.1, enderY = 57.1, objective = "Speak with Tabetha.", summary = "Now it is time for you to earn your mage's wand.  To begin this quest, speak with the human hermit Tabetha in Dustwallow Marsh.  You will find her shack deep in the marsh, west of Theramore.$B$BSpeak with her, for her knowledge is vast.  You will find Tabetha's cottage west of Theramore, and just north of the Stonemaul Ruins." },
            { ids = { 1948 }, name = "Items of Power", level = 40, zone = "Dustwallow Marsh", giver = "Tabetha", giverMap = 1445, giverX = 46.1, giverY = 57.1, ender = "Tabetha", enderMap = 1445, enderX = 46.1, enderY = 57.1, objective = "Bring 1 Jade and the Bolt Charged Bramble to Tabetha in Dustwallow Marsh.", summary = "The building of a mage's wand is not easy.  Rare substances are required, and a vessel must be made that can store great quantities of magical energy.  You must gather these things and bring them to me.$B$BI have written onto this parchment that which you need, and instructions on how to get it.  Bring me exactly what is on this list, and follow my written directions to the letter, for if you do not then when we make your wand things might go... badly." },
            { ids = { 1949 }, name = "Hidden Secrets", level = 38, zone = "Dustwallow Marsh", giver = "Tabetha", giverMap = 1445, giverX = 46.1, giverY = 57.1, ender = "Magus Tirth", enderMap = 1441, enderX = 78.3, enderY = 75.7, objective = "Speak with Magus Tirth in the Shimmering Flats.", summary = "To make your wand, there are key passages in a certain book that I must read.  The book is called Rituals of Power, written by the Magus Tirth.$B$BI do not have a copy of his book, and none of the world's great libraries possess it.  So you must speak with Tirth and gain it from him.$B$BGood luck.  Tirth used to be a great mage and scholar, but now he spends his time at the gnome and goblin races in the Shimmering Flats, drinking and gambling." },
            { ids = { 1950 }, name = "Get the Scoop", level = 30, zone = "Thousand Needles", giver = "Magus Tirth", giverMap = 1441, giverX = 78.3, giverY = 75.7, ender = "Magus Tirth", enderMap = 1441, enderX = 78.3, enderY = 75.7, objective = "Find the phrase to Tirth's strongbox, then return to Tirth.", summary = "I can help you with the book, but first you have to help me!$B$BThe tome you seek is in my magically locked strongbox.  To open it a special phrase must be uttered, and I can't remember the phrase!  Normally my assistant helps me remember these things but he's nowhere to be found.$B$BIf you want my book, then find my apprentice!  Ask around the race track--if you're lucky then someone has seen him.  Either drag him back here, or at least get my magic phrase from him so we can open my box!" },
            { ids = { 1951 }, name = "Rituals of Power", level = 40, zone = "Thousand Needles", giver = "Magus Tirth", giverMap = 1441, giverX = 78.3, giverY = 75.7, ender = "Tabetha", enderMap = 1445, enderX = 46.1, enderY = 57.1, objective = "Bring the book Rituals of Power to Tabetha in Dustwallow Marsh.", summary = "Hm... now that I think about it, I don't have my book!  You see, I had some gambling debts and to pay them off I sold the last copy of Rituals of Power to a member of the clergy....$B$BA member of the Scarlet Brotherhood.  He must have taken it to their library in the Scarlet Monastery in Tirisfal Glades!$B$BIf you want that book, then you'll have to go to the monastery to find it.  And sorry about all the trouble.  I'm not myself these days..." },
            { ids = { 1952 }, name = "Mage's Wand", level = 40, zone = "Dustwallow Marsh", giver = "Tabetha", giverMap = 1445, giverX = 46.1, giverY = 57.1, ender = "Tabetha", enderMap = 1445, enderX = 46.1, enderY = 57.1, objective = "Speak with Tabetha after her ritual.", summary = "I'll go make the wands now." },
        },
    },
    {
        id = "q584",
        name = "The Fate of Yenniku",
        zone = "Stranglethorn Vale",
        minLevel = 30,
        maxLevel = 46,
        importance = 2,
        kind = "world",
        quests = {
            { ids = { 581 }, name = "Hunt for Yenniku", level = 34, zone = "Stranglethorn Vale", giver = "Nimboya", giverMap = 1434, giverX = 32.2, giverY = 27.7, ender = "Nimboya", enderMap = 1434, enderX = 32.2, enderY = 27.7, objective = "Bring 9 Bloodscalp Tusks to Nimboya at the Grom'gol Base Camp.", summary = "A doom, there is.  A doom on my chief's youngest son, Yenniku.  As is a custom with our people, he was given to the Gurubashi Trolls of Zul'Gurub, but after my tribe, the Darkspear tribe, left with the orc Thrall, poor Yenniku was lost to us.  I was sent from distant Orgrimmar, back to Stranglethorn, to search for my chief's son.$B$BAnd I believe the Bloodscalp tribe has him.$B$BIf you would help me, then hunt the Bloodscalps.  You may find them to the north.  Gather their tusks and return to me." },
            { ids = { 582 }, name = "Headhunting", level = 37, zone = "Stranglethorn Vale", giver = "Nimboya", giverMap = 1434, giverX = 32.2, giverY = 27.7, ender = "Nimboya", enderMap = 1434, enderX = 32.2, enderY = 27.7, objective = "Bring 20 Shrunken Heads to Nimboya at the Grom'gol Base Camp.", summary = "We must find if Yenniku is dead.$B$BSlay the Bloodscalp Headhunters and take from them their Shrunken Heads.  You must gather many, many heads, and I will inspect them to make sure Yenniku's head is not among them.$B$BAnd if Yenniku was killed by the Bloodscalps, then may a 600-year curse fall on the spirit of their chief, Gan'zulah!$B$BGo, $N.  You may find many Headhunters at the ruins of Zuuldaia and Zul'Kunda, along the coast to the north." },
            { ids = { 584 }, name = "Bloodscalp Clan Heads", level = 41, zone = "Stranglethorn Vale", giver = "Nimboya", giverMap = 1434, giverX = 32.2, giverY = 27.7, ender = "Bubbling Cauldron", enderMap = 1434, enderX = 32.2, enderY = 27.6, objective = "Bring Gan'zulah's Head and Nezzliok's Head to the bubbling cauldron at the Grom'gol Base Camp.", summary = "Yenniku was not among the heads, and I thank the Great Serpent for it.  But we are no closer to finding him.$B$BWe must know the truth, and I fear that only the Bloodscalp chief and his witchdoctor know it.  They are the enemies of the Darkspear tribe and will not speak freely, so we must force the truth from their dead lips!$B$BBring me the heads of Gan'zulah and Nezzliok the Dire and place them within this cauldron.$B$BThey are deep within Zul'Kunda.  Bring their heads...we will then make them talk." },
            { ids = { 585 }, name = "Speaking with Nezzliok", level = 40, zone = "Stranglethorn Vale", giver = "Bubbling Cauldron", giverMap = 1434, giverX = 32.2, giverY = 27.6, ender = "Bubbling Cauldron", enderMap = 1434, enderX = 32.2, enderY = 27.6, objective = "Bring a Balia'mah Trophy, a Ziata'jai Trophy and a Zul'Mamwe Trophy to the Bubbling Cauldron at the Grom'gol Base Camp.", summary = "<The head of Nezzliok speaks.>$B$BIt is true.  I know where the child of the Darkspears was taken.  You have bested me and bound my spirit, but I will say nothing without appeasement!$B$BThe Bloodscalps war with the Skullsplitters.  To gain my favor, steal from the Skullsplitters 3 of their trophy skulls and place them here with us, so that my spirit will have slaves in the Nether.  One skull must be from their trophy pile in Balia'mah, another from Ziata'jai, and the last from Zul'Mamwe." },
            { ids = { 586 }, name = "Speaking with Gan'zulah", level = 46, zone = "Stranglethorn Vale", giver = "Bubbling Cauldron", giverMap = 1434, giverX = 32.2, giverY = 27.6, ender = "Bubbling Cauldron", enderMap = 1434, enderX = 32.2, enderY = 27.6, objective = "Kill 8 Skullsplitter Hunters, 6 Skullsplitter Headhunters, and 4 Skullsplitter Berserkers.$B$BBring the Broken Armor of Ana'thek to the Bubbling Cauldron at the Grom'gol Base Camp.", summary = "<The head of Gan'zulah speaks.>$B$BCurse you!  And curse your ancestors!!$B$BOnly blood and revenge can cool my rage, so if that is your wish, then... do this:$B$BThrow yourself into the heart of the Skullsplitters to the east.  Slay the fiercest among them, and if you survive...then break yourself against their chief, Ana'thek the Cruel.  Hah!  Bring me his shattered armor if you can!$B$BMay he tear off your limbs and leave you to rot and be eaten by carrion." },
            { ids = { 588 }, name = "The Fate of Yenniku", level = 45, zone = "Stranglethorn Vale", giver = "Bubbling Cauldron", giverMap = 1434, giverX = 32.2, giverY = 27.6, ender = "Kin'weelay", enderMap = 1434, enderX = 32.3, enderY = 27.7, objective = "Speak with Kin'weelay.", summary = "<Nezzliok speaks.>$B$BYou have appeased myself and my chief, so I will tell you that which you seek to discover...$B$BYoung Yenniku is lost to his clan.$B$BHe was taken by the witchdoctor Zanzil the Outcast.  Now Zanzil controls him, body and soul, and only the most potent magic could set him free.$B$BA magic that you do not have, $c.$B$BPerhaps your Darkspear allies can offer a hope of Yenniku's salvation.  But that, I doubt." },
            { ids = { 589 }, name = "The Singing Crystals", level = 45, zone = "Stranglethorn Vale", giver = "Kin'weelay", giverMap = 1434, giverX = 32.3, giverY = 27.7, ender = "Kin'weelay", enderMap = 1434, enderX = 32.3, enderY = 27.7, objective = "Bring 3 Pulsing Blue Shards to Kin'weelay at the Grom'gol Base Camp.", summary = "Legends tell of a jewel, hidden deep in the heart of Stranglethorn.  We call it the Mind's Eye, and it has great powers.  If you gain this Eye then, perhaps, we can use it to bring lost Yenniku back from the darkness.$B$BI will consult with the spirits of the jungle to find the Mind's Eye.  While I do this, you enter the Crystalvein Mine, southeast of here, and gather Pulsing Blue Shards from Ironjaw Basilisks.  The shards are rare, but we will need their magic to bend the Mind's Eye to our will." },
            { ids = { 591 }, name = "The Mind's Eye", level = 46, zone = "Stranglethorn Vale", giver = "Kin'weelay", giverMap = 1434, giverX = 32.3, giverY = 27.7, ender = "Kin'weelay", enderMap = 1434, enderX = 32.3, enderY = 27.7, objective = "Bring the Mind's Eye to Kin'weelay at the Grom'gol Base Camp.", summary = "The Mind's Eye is held by an ogre mage, east of here and deep within the Mosh'Ogg ogre mound.  His name is Mai'Zoth.  I know him from when the Darkspears dwelt in Stranglethorn - he is vicious, and his magic is strong.$B$BAnd if he has the Mind's Eye, then his magic will be stronger still.$B$BYou must face Mai'Zoth and wrest from him the Mind's Eye.  It is a perilous task, but it is the only hope we have of saving Yenniku." },
            { ids = { 592 }, name = "Saving Yenniku", level = 46, zone = "Stranglethorn Vale", giver = "Kin'weelay", giverMap = 1434, giverX = 32.3, giverY = 27.7, ender = "Nimboya", enderMap = 1434, enderX = 32.2, enderY = 27.7, objective = "Bring the Filled Soul Gem to Nimboya.", summary = "I have reshaped the Mind's Eye into a Soul Gem.  Its purpose is twofold: you must use it to stun Yenniku, and once stunned place it upon his head to entrap his soul.$B$BThen, bring the gem to Nimboya.$B$BYenniku dwells with Zanzil the Outcast, at the Ruins of Aboraz, along the Crystal Shore on the distant Cape of Stranglethorn." },
        },
    },
    {
        id = "q1361",
        name = "Regthar Deathgate",
        zone = "Hillsbrad Foothills",
        minLevel = 30,
        maxLevel = 35,
        importance = 1,
        kind = "world",
        quests = {
            { ids = { 1361 }, name = "Regthar Deathgate", level = 32, zone = "Hillsbrad Foothills", giver = "Krusk", giverMap = 1424, giverX = 63.2, giverY = 20.7, ender = "Regthar Deathgate", enderMap = 1413, enderX = 45.3, enderY = 28.4, objective = "Speak with Regthar Deathgate.", summary = "A warrior of the Horde, Regthar Deathgate, is recruiting agents for a mission into the land of Desolace.  Speak with him if you wish to volunteer.  He is stationed in the Barrens, in a series of bunkers west of the Crossroads.$B$BAnd sharpen your weapons.  Desolace is a place torn by war." },
            { ids = { 1362 }, name = "The Kolkar of Desolace", level = 32, zone = "The Barrens", giver = "Regthar Deathgate", giverMap = 1413, giverX = 45.3, giverY = 28.4, ender = "Felgur Twocuts", enderMap = 1443, enderX = 56.2, enderY = 59.6, objective = "Speak with Felgur Twocuts at Ghost Walker Post in Desolace.", summary = "The Kolkar centaur live in Desolace, and their forces have spread into the Barrens.  This is a known fact and we have Horde agents dealing with them here.$B$BBut as long as the centaur are strong in Desolace, they will always pose a threat.  It is time we rid ourselves of that threat.$B$BSpeak with Felgur Twocuts at Ghost Walker Post in Desolace.  He was sent to gather intelligence on the centaur.  He will know how to best deal with the Kolkar of Desolace." },
            { ids = { 1365 }, name = "Khan Dez'hepah", level = 35, zone = "Desolace", giver = "Felgur Twocuts", giverMap = 1443, giverX = 56.2, giverY = 59.6, ender = "Felgur Twocuts", enderMap = 1443, enderX = 56.2, enderY = 59.6, objective = "Bring Khan Dez'hepah's Head to Felgur Twocuts in Desolace.", summary = "The Kolkar are not the only centaur of Desolace.  Many clans wander these dry plains, fighting and dying against each other.  And it is good that they fight among themselves, for they are strong and brutal.  If the centaur united against us, they would be a fierce foe.$B$BWe must deal with them before they unite.$B$BYour first task is to disrupt the Kolkar clan.  Do this by killing its leader, Khan Dez'hepah.$B$BThe Kolkar Village is northeast of here.  Go, and may fortune go with you." },
            { ids = { 1366 }, name = "Centaur Bounty", level = 31, zone = "Desolace", giver = "Felgur Twocuts", giverMap = 1443, giverX = 56.2, giverY = 59.6, ender = "Felgur Twocuts", enderMap = 1443, enderX = 56.2, enderY = 59.6, objective = "Bring 15 Centaur Ears to Felgur Twocuts in Desolace.", summary = "Now that you scared the centaur clans, it's time to bleed them.  When traveling Desolace, hunt centaur.  I don't care which clan you hunt.  Just gather ears.  A hoard of ears.$B$BBy weakening their numbers you will weaken their resolve, and stamp out any thoughts of expansion.$B$BGood hunting, $N." },
        },
    },
    {
        id = "q709",
        name = "Solution to Doom",
        zone = "Badlands",
        minLevel = 30,
        maxLevel = 44,
        importance = 1,
        kind = "dungeon",
        quests = {
            { ids = { 709 }, name = "Solution to Doom", level = 40, zone = "Badlands", giver = "Theldurin the Lost", giverMap = 1418, giverX = 51.4, giverY = 76.9, ender = "Theldurin the Lost", enderMap = 1418, enderX = 51.4, enderY = 76.9, objective = "Bring the Tablet of Ryun'eh to Theldurin the Lost.", summary = "Oh my!  Oh my!  There is a doom approaching.  Mark me!  A doom!$B$BNo, I cannot speak of it...cannot utter their names or they may hear me!  But if we learn, yes, if we learn more of them...then maybe we can learn how to foil them!$B$BMaybe.$B$BGo into Uldaman.  No!  I said it!  You must find...find the tablet of...Ryun'eh.  Yes, find it!  And don't make me speak that name again!$B$BIt is deep in that place, in an ancient chest.  That's where it hides...in a chest crafted before the works of any dwarf." },
            { ids = { 728 }, name = "To the Undercity for Yagyin's Digest", level = 40, zone = "Badlands", giver = "Theldurin the Lost", giverMap = 1418, giverX = 51.4, giverY = 76.9, ender = "Keeper Bel'dugur", enderMap = 1458, enderX = 53.7, enderY = 54.5, objective = "Bring the Sigil of the Hammer to Keeper Bel'dugur in the Undercity.", summary = "The tablet tells much.  But not enough!  Not nearly enough!$B$BThere is a book, a digest that Yagyin wrote in ages past.  The... people I fled from... they keep this book in many places.  And their most learned study it.  It holds vast knowledge.  Knowledge to protect us!$B$BGo to Keeper Bel'dugur in the Undercity of Lordaeron.  Show him this sigil and he'll think you one of them.  Ask him for Yagin's Digest...and bring it to me!" },
            { ids = { 736 }, name = "The Star, the Hand and the Heart", level = 44, zone = "Undercity", giver = "Keeper Bel'dugur", giverMap = 1458, giverX = 53.7, giverY = 54.5, ender = "Keeper Bel'dugur", enderMap = 1458, enderX = 53.7, enderY = 54.5, objective = "Bring the items on Bel'dugur's Note to Keeper Bel'dugur in the Undercity.", summary = "You need Yagyin's Digest?  Your plan, then, is to gather another flock?  Of course it is...and of course I will help you, $gbrother:sister;.$B$BBut you must help me too.$B$BI require three items of power.  Bring me these and the digest will be yours.$B$BI cannot utter the names of these items, but I will write them down.$B$BGet me the items on this list.  If you can do that, then you are truly worthy of opening your own chapter of our order." },
            { ids = { 737 }, name = "Forbidden Knowledge", level = 40, zone = "Ironforge", giver = "Gerrig Bonegrip", giverMap = 1455, giverX = 50.8, giverY = 5.6, ender = "Theldurin the Lost", enderMap = 1418, enderX = 51.4, enderY = 76.9, objective = "Bring Yagyin's Digest to Theldurin.", summary = "I have the digest for you, $N.  I need not tell you to take great care with it.  And to keep it far from unfriendly hands.  $B$BThis book holds many truths...$B$B...And the truth can burn." },
        },
    },
    {
        id = "q652",
        name = "Summoning the Princess",
        zone = "Arathi Highlands",
        minLevel = 30,
        maxLevel = 50,
        importance = 1,
        kind = "world",
        quests = {
            { ids = { 642 }, name = "The Princess Trapped", level = 37, zone = "Arathi Highlands", giver = "Shards of Myzrael", giverMap = 1417, giverX = 62.5, giverY = 33.7, ender = "Iridescent Shards", enderMap = 1417, enderX = 84.3, enderY = 30.9, objective = "Gather 12 Motes of Myzrael, then bring them to the Iridescent Shards in Drywhisker Gorge.", summary = "My name is Myzrael.  I am a princess of the earth, and my captors, the giants, have trapped me deep beneath the Arathi Highlands.  These crystal shards are the only way I can speak with the surface world.$B$BPlease help me.  Allies of the giants, the Drywhisker Kobolds, have a shard like this one in their Drywhisker Gorge, to the east.  To power the cluster, you must gather Motes of Myzrael from the kobolds and apply them to it.$B$BI beg you, $N, aid me!" },
            { ids = { 651 }, name = "Stones of Binding", level = 38, zone = "Arathi Highlands", giver = "Iridescent Shards", giverMap = 1417, giverX = 84.3, giverY = 30.9, ender = "Stone of Inner Binding", enderMap = 1417, enderX = 36.2, enderY = 57.4, objective = "Gather the Burning Key, the Cresting Key and the Thundering Key from the Stone of West Binding, the Stone of East Binding and the Stone of Outer Binding.$B$BBring them to the Stone of Inner Binding.", summary = "Four Stones of Binding are scattered throughout Arathi.  These stones keep me pinned beneath the earth.$B$BTo unlock them you must unlock the strongest: the Stone of Inner Binding.  And to do that, you must gather keys from the other three.$B$BThese stones are watched by guardians, but if you are clever, or lucky, you may find ways to banish them." },
            { ids = { 652 }, name = "Breaking the Keystone", level = 42, zone = "Arathi Highlands", giver = "Stone of Inner Binding", giverMap = 1417, giverX = 36.2, giverY = 57.4, ender = "Keystone", enderMap = 1417, enderX = 36.1, enderY = 58.1, objective = "Find and kill Fozruk.  Bring the Rod of Order to the Keystone in the Arathi Highlands.", summary = "Opening the Stones of Binding loosened much of my confinement, but a lock still holds me chained.  It is the Keystone you see among this circle of stones.  And the key is held by one of my captors, the stone watcher Fozruk.$B$BYou must obtain that key, which the stone watchers call the Rod of Order, from Fozruk and use it to open the Keystone.$B$B$N, you have done so much to aid me.  Just a little more...and my gratitude will shake the very foundations of the earth!" },
            { ids = { 688 }, name = "Myzrael's Allies", level = 40, zone = "Arathi Highlands", giver = "Keystone", giverMap = 1417, giverX = 36.1, giverY = 58.1, ender = "Zaruk", enderMap = 1417, enderX = 74.5, enderY = 35.6, objective = "Speak with Zaruk in Hammerfall.", summary = "<Myzrael speaks.>$B$BFree!  I AM FREE!  I am free to gather strength, hidden from my captors.  For if they faced me now they would surely overpower and again imprison me.$B$BBut in time I will confront the giants, and they will regret their wardship of me!$B$BYou are a noble ally, $N.  I will need your help again in time.  When I am ready, I will need you to summon me to the surface$B$BSpeak with Zaruk in Hammerfall.  He knows how I can be summoned." },
            { ids = { 687 }, name = "Theldurin the Lost", level = 40, zone = "Ironforge", giver = "Gerrig Bonegrip", giverMap = 1455, giverX = 50.8, giverY = 5.6, ender = "Theldurin the Lost", enderMap = 1418, enderX = 51.4, enderY = 76.9, objective = "Find Theldurin the Lost.", summary = "Theldurin the Lost was once a member of our order, the Twilight's Hammer.  But he lost his mind and scorned our teachings.  And before he fled from us, he stole the scroll of Myzrael!  We could not catch him, but rumors say he hides in the Badlands, gibbering and mad.$B$BTo bring the Lady back to us, you must find the scroll.  And to do that, you must find Theldurin." },
            { ids = { 692 }, name = "The Lost Fragments", level = 41, zone = "Badlands", giver = "Theldurin the Lost", giverMap = 1418, giverX = 51.4, giverY = 76.9, ender = "Theldurin the Lost", enderMap = 1418, enderX = 51.4, enderY = 76.9, objective = "Bring the Torn Scroll Fragment, the Crumpled Scroll Fragment and the Singed Scroll Fragment to Theldurin the Lost.", summary = "The Scroll of Myzrael...the Scroll of Myzrael?!  You don't want that!  Its magic can pull Myzrael to the surface world and if you do that, we are in trouble!$B$BOr...maybe it's too late.  Maybe she already is free.  Maybe she's just gathering strength before unleashing herself upon us.  If so, then you'll NEED the scroll!$B$B...too bad it's destroyed.  Enraged elementals stole it and tore it up and now fight over the fragments.$B$BBut if you can gather those fragments, maybe we can fix it..." },
            { ids = { 656 }, name = "Summoning the Princess", level = 50, zone = "Badlands", giver = "Theldurin the Lost", giverMap = 1418, giverX = 51.4, giverY = 76.9, ender = "Shards of Myzrael", enderMap = 1417, enderX = 62.5, enderY = 33.7, objective = "Go to the Shards of Myzrael, summon her and defeat her.$B$BGather her Eldritch Shackles and bind them to the Shards of Myzrael.", summary = "You must defeat Myzrael before she grows in strength.  If you do not, then once she has gathered enough power she will challenge her captors!  There are some who think they can control her, but if she can be controlled then why did the giants chain her in the first place??$B$BCrazy logic, eh?$B$BTo defeat her, summon her at the Shards of Myzrael where you first spoke with her.  Defeat her and gather her Eldritch Shackles, then bind them to the Shards of Myzrael.$B$BDo that, and she will again be trapped." },
        },
    },
    {
        id = "q4737",
        name = "The Completed Robe",
        zone = "Orgrimmar",
        minLevel = 31,
        maxLevel = 38,
        importance = 2,
        kind = "class",
        classes = { 9 },
        quests = {
            { ids = { 4737 }, name = "In Search of Menara Voidrender", level = 31, zone = "Orgrimmar", giver = "Zevrost", giverMap = 1454, giverX = 48.5, giverY = 45.4, ender = "Menara Voidrender", enderMap = 1413, enderX = 62.5, enderY = 35.5, objective = "Speak to Menara Voidrender in the Barrens.", summary = "Hmph, still you strive to become more powerful. I say it's only time before the corruption and addiction takes hold of you and you become a slave to that which you seek to gain power over.$B$BPfah! A fool you are! Time will prove me right--nothing else... just time.$B$BBut it seems that not all agree with Zevrost. It seems Menara would create tools for you to become more powerful and to harness your strength. If you're interested, then go to Ratchet in the Barrens. She is there overlooking the town." },
            { ids = { 1796 }, name = "Components for the Enchanted Gold Bloodrobe", level = 31, zone = "The Barrens", giver = "Menara Voidrender", giverMap = 1413, giverX = 62.5, giverY = 35.5, ender = "Menara Voidrender", enderMap = 1413, enderX = 62.5, enderY = 35.5, objective = "Bring Robes of the Arcana to Menara Voidrender in the Barrens.", summary = "The first item I will aid you in creating is a robe. You will gather the items for me, and we will put them together. Afterwards, assuming you succeed, you will have the first of many items that will make you more powerful and aid you in your struggles.$B$BTo start, you must have crafted Robes of Arcana. A tailor can make this for you, or perhaps you can purchase one from someone else--I'd be most impressed if you could make it yourself--but regardless, bring me the robes, and we shall go from there." },
            { ids = { 4781 }, name = "Components for the Enchanted Gold Bloodrobe", level = 34, zone = "The Barrens", giver = "Menara Voidrender", giverMap = 1413, giverX = 62.5, giverY = 35.5, ender = "Xizk Goodstitch", enderMap = 1434, enderX = 28.7, enderY = 76.9, objective = "Bring a Gold Bar to Xizk Goodstitch in Stranglethorn Vale.", summary = "Your next task is as simple as your first, but will require you to seek out aid.$B$BI require gold thread for the embroidery of the cloak, but gold thread is not easy to come by, and very few know how to make it. Fortunately, one who is loyal to our cause knows its secrets and is willing to help those rising in our ranks.$B$BBring a gold bar to Xizk Goodstitch in Booty Bay. He is a master tailor and will be happy to spin the thread for you. Gold bars are smelted by skilled miners. Ask a miner for help." },
            { ids = { 4782 }, name = "Components for the Enchanted Gold Bloodrobe", level = 34, zone = "Stranglethorn Vale", giver = "Xizk Goodstitch", giverMap = 1434, giverX = 28.7, giverY = 76.9, ender = "Menara Voidrender", enderMap = 1413, enderX = 62.5, enderY = 35.5, objective = "Return to Menara Voidrender in the Barrens.", summary = "Return to Menara, tell her it'll take some time, but I'll make sure to come through for her... and you. Tell her to have you finish gathering the rest of your components--I should have the thread done by then. You can return and pick it up then.$B$BGood luck, $N. Oh, and say hello to Strahad for me while you're there. That old coot... putting a tower right there next to Ratchet... crazy." },
            { ids = { 4783 }, name = "Components for the Enchanted Gold Bloodrobe", level = 37, zone = "The Barrens", giver = "Menara Voidrender", giverMap = 1413, giverX = 62.5, giverY = 35.5, ender = "Menara Voidrender", enderMap = 1413, enderX = 62.5, enderY = 35.5, objective = "Bring 10 Vials of Hatefury Blood and 1 Lesser Infernal Stone to Menara Voidrender in the Barrens.", summary = "The next components are found in Desolace, far to the west of the Barrens and even the Stonetalon Mountains.$B$BThere, chaos still reigns after the Sundering. Both your strength and cunning will be tested there--you will face creatures of hatred and also of the Burning Legion.$B$BFrom the Hatefury satyr in the northeast, bring me their blood. From the lesser infernals in Mannoroc Coven, bring me a lesser infernal stone.$B$BWe will use both in the construction of your robe." },
            { ids = { 4784 }, name = "Components for the Enchanted Gold Bloodrobe", level = 37, zone = "The Barrens", giver = "Menara Voidrender", giverMap = 1413, giverX = 62.5, giverY = 35.5, ender = "Menara Voidrender", enderMap = 1413, enderX = 62.5, enderY = 35.5, objective = "Bring some Fine Gold Thread, 2 Smoldering Coals, and a Soul Shard to Menara Voidrender in the Barrens.", summary = "I need only three things now, $N, then we can finish your robe.$B$BFirst, the fine gold thread Xizk is making for you. Return to him in Booty Bay and get it.$B$BSecond, bring me two smoldering coals from the fire elementals in the Arathi Highlands. If I recall correctly, they are to the west, near Thoradin's Wall.$B$BFinally, a soul shard created by you.$B$BAfter you have all the components, return here to the tower and I will complete the robe for you." },
            { ids = { 4786 }, name = "The Completed Robe", level = 38, zone = "The Barrens", giver = "Menara Voidrender", giverMap = 1413, giverX = 62.5, giverY = 35.5, ender = "Menara Voidrender", enderMap = 1413, enderX = 62.5, enderY = 35.5, objective = "Wait for Menara Voidrender to complete your robe and then speak to her again.", summary = "I will put the robe together for you now. It will take but a few moments. Do not go far." },
        },
    },
    {
        id = "q638",
        name = "Trol'kalar",
        zone = "Stranglethorn Vale",
        minLevel = 32,
        maxLevel = 42,
        importance = 2,
        kind = "world",
        quests = {
            { ids = { 638 }, name = "Trollbane", level = 37, zone = "Stranglethorn Vale", giver = "Nimboya", giverMap = 1434, giverX = 32.2, giverY = 27.7, ender = "Zengu", enderMap = 1417, enderX = 73.8, enderY = 34.0, objective = "Travel to Hammerfall in the Arathi Highlands and speak with Zengu.", summary = "With Thoras Trollbane dead and Stromgarde in ruins, Vol'jin has instructed that we make every effort to spirit the legendary sword Trol'kalar from the humans' hands, so that we might use it in our coming battles against the trolls of Zul'Gurub.$b$bZengu, one of our seasoned hunters, was dispatched to Hammerfall in northeastern Arathi Highlands to oversee its procurement." },
            { ids = { 639 }, name = "Sigil of Strom", level = 37, zone = "Arathi Highlands", giver = "Zengu", giverMap = 1417, giverX = 73.8, giverY = 34.0, ender = "Zengu", enderMap = 1417, enderX = 73.8, enderY = 34.0, objective = "Get the Sigil of Strom for Zengu in Hammerfall.", summary = "In ancient times, trolls fought against the Arathorian Empire and our most capable adversary, Lord Ignaeus of Strom, named Trollbane. He rode into battle wielding Trol'kalar--troll slayer, in their ancient tongue.$b$bBut now the sons of Trollbane are weakened, their stronghold brought to ruin.$b$bThe sword is protected by several sigils that were divided among the survivors of Stromgarde, and we must retrieve them.$b$bThe first was taken by the Syndicate, one of their men in Stromgarde should have it." },
            { ids = { 640 }, name = "The Broken Sigil", level = 40, zone = "Arathi Highlands", giver = "Zengu", giverMap = 1417, giverX = 73.8, giverY = 34.0, ender = "Tor'gan", enderMap = 1417, enderX = 74.7, enderY = 36.3, objective = "Retrieve the 11 Sigil Fragments from the defenders in Stromgarde, and bring them to Tor'gan in Hammerfall.", summary = "Thoras Trollbane's tomb is protected by three sigils--the first of which you retrieved from the Syndicate. The other two will be harder to get, as they're held by the firmly entrenched Stromgarde militia.$b$bThe sigil of Thoradin was divided into eleven pieces by Thoras' son, Galen, and dispersed among the Stromgarde defenders. Retrieve the pieces and bring them to Tor'gan, the troll shaman, he will be able to bind them into the complete sigil." },
            { ids = { 641 }, name = "Sigil of Thoradin", level = 40, zone = "Arathi Highlands", giver = "Tor'gan", giverMap = 1417, giverX = 74.7, giverY = 36.3, ender = "Zengu", enderMap = 1417, enderX = 73.8, enderY = 34.0, objective = "Bring the restored Sigil of Thoradin to Zengu in Hammerfall.", summary = "The reconstruction worked flawlessly. The sigil can now be used to unlock the seal on Trollbane's tomb. Return it to Zengu, no doubt he has additional tasks for you to complete." },
            { ids = { 643 }, name = "Sigil of Arathor", level = 41, zone = "Arathi Highlands", giver = "Zengu", giverMap = 1417, giverX = 73.8, giverY = 34.0, ender = "Zengu", enderMap = 1417, enderX = 73.8, enderY = 34.0, objective = "Retrieve the Sigil of Arathor and return it to Zengu in Hammerfall.", summary = "Though they can barely be said to control Stromgarde, let alone the whole of Arathi Highlands, the human prince trots the remnants of his cavalry over the countryside. I can't understand why he does it, but who understands the way the humans think, hm?$b$bWhatever his reasoning, more importantly, he has given one of the sigils to Lieutenant Valorcall, their cavalry leader. Locate him and bring his sigil back to me." },
            { ids = { 644 }, name = "Sigil of Trollbane", level = 42, zone = "Arathi Highlands", giver = "Zengu", giverMap = 1417, giverX = 73.8, giverY = 34.0, ender = "Zengu", enderMap = 1417, enderX = 73.8, enderY = 34.0, objective = "Kill Prince Galen Trollbane and bring the Sigil of Trollbane to Zengu in Hammerfall.", summary = "The final of the sigils needed to unlock the tomb of Thoras Trollbane is held by his son personally. He resides deep within Stromgarde, in a chapel in the militia-held districts. Prince Galen is well protected and no slouch of a warrior himself, so this task could prove most difficult." },
            { ids = { 645 }, name = "Trol'kalar", level = 42, zone = "Arathi Highlands", giver = "Zengu", giverMap = 1417, giverX = 73.8, giverY = 34.0, ender = "Trollbane's Tomb", enderMap = 1417, enderX = 28.9, enderY = 59.6, objective = "Retrieve Trol'kalar from Trollbane's tomb in Stromgarde.", summary = "What's this? With the four sigils brought together, they have formed together to create one sigil. There can be no doubt that this will be able to break the wardings placed upon Trollbane's tomb.$b$bTrollbane's remains are entombed in the Sanctum behind the chapel in Stromgarde. Retrieve Trol'kalar." },
            { ids = { 646 }, name = "Trol'kalar", level = 42, zone = "Arathi Highlands", giver = "Trollbane's Tomb", giverMap = 1417, giverX = 28.9, giverY = 59.6, ender = "Zengu", enderMap = 1417, enderX = 73.8, enderY = 34.0, objective = "Deliver Trol'kalar to Zengu in Hammerfall.", summary = "The light slowly fades, the sword Trol'kalar, held within a stone sheath has been released." },
        },
    },
    {
        id = "q3523",
        name = "Scourge of the Downs",
        zone = "Razorfen Downs",
        minLevel = 32,
        maxLevel = 37,
        importance = 1,
        kind = "dungeon",
        quests = {
            { ids = { 3523 }, name = "Scourge of the Downs", level = 37, zone = "Razorfen Downs", giver = "Belnistrasz", giverMap = 1413, giverX = 49.0, giverY = 93.9, giverInside = "Razorfen Downs", ender = "Belnistrasz", enderMap = 1413, enderX = 49.0, enderY = 93.9, enderInside = "Razorfen Downs", objective = "If you agree to aid Belnistrasz, speak with him again and hand the Oathstone he gave you back to him.", summary = "Outstanding!  My name is Belnistrasz, and I thank you for rescuing me.  I had given myself up for dead... or worse, as a meal for these Scourge-infested vermin.  Yes - I said Scourge all right; they've brokered some sort of deal with the Quilboar here, and this nightmare is a result.$B$BListen... rather than just flee, I want to make a difference for all of our sakes.  Would you be up to helping me out to that end?  It's probably dangerous, but you seem to be the type not to worry about that too much." },
            { ids = { 3525 }, name = "Extinguishing the Idol", level = 37, zone = "Razorfen Downs", giver = "Belnistrasz", giverMap = 1413, giverX = 49.0, giverY = 93.9, giverInside = "Razorfen Downs", ender = "Belnistrasz's Brazier", enderMap = 1413, enderX = 49.0, enderY = 93.9, enderInside = "Razorfen Downs", objective = "Escort Belnistrasz to the Quilboar's idol in Razorfen Downs.$B$BProtect Belnistrasz while he performs the ritual to shut down the idol.", summary = "Near the entrance is an idol that functions as a macabre oven for the Quilboar; the beasts... they literally consume their abductees from the Barrens.  I can shut down the idol and bind them from using it again, but I need your aid in doing so.  My plan: escort me to the idol.  Once we arrive, I'll commence the ritual.  I'll barely be able to communicate with you, let alone defend myself.  Protect me while I shut down the idol.  If they take me down, then it's all over for us.$B$BAre you with me?!" },
        },
    },
    {
        id = "q495",
        name = "The Crown of Will",
        zone = "Undercity",
        minLevel = 34,
        maxLevel = 43,
        importance = 1,
        kind = "world",
        quests = {
            { ids = { 495 }, name = "The Crown of Will", level = 39, zone = "Undercity", giver = "Sharlindra", giverMap = 1458, giverX = 57.6, giverY = 93.8, ender = "Melisara", enderMap = 1424, enderX = 62.6, enderY = 20.6, objective = "Report to Melisara at Tarren Mill in the Hillsbrad Foothills.", summary = "Mug'Thol and his ogre warband was sent to Alterac to retrieve the Crown of Will for Lady Sylvanas. Unfortunately, instead of returning it, the idiot decided to try it on... I suppose ogres can't resist anything bright and shiny.$b$bHis bumbling actions have become something of a problem, however. The Crown of Will enabled him to resist the possession placed upon him to serve Lady Sylvanas.$b$bThe Dark Lady wants an example made, travel to Tarren Mill in Hillsbrad and report to Melisara, my lieutenant." },
            { ids = { 518 }, name = "The Crown of Will", level = 39, zone = "Hillsbrad Foothills", giver = "Melisara", giverMap = 1424, giverX = 62.6, giverY = 20.6, ender = "Melisara", enderMap = 1424, enderX = 62.6, enderY = 20.6, objective = "Kill 14 Crushridge Maulers for Melisara in Tarren Mill.", summary = "Mug'Thol and his Crushridge ogres have overrun the ruins of Alterac. It will be hard to inflict any serious punishment upon him without thinning out the ogres' numbers.$b$bAfter softening them up, we'll proceed.$b$bUnderstood? Good. Now go." },
            { ids = { 519 }, name = "The Crown of Will", level = 41, zone = "Hillsbrad Foothills", giver = "Melisara", giverMap = 1424, giverX = 62.6, giverY = 20.6, ender = "Melisara", enderMap = 1424, enderX = 62.6, enderY = 20.6, objective = "Kill Targ, Muckrake, and Glommus and bring their heads to Melisara in Tarren Mill.", summary = "Targ, Muckrake, and Glommus are Mug'Thol's lieutenants. They are loyal to him, though who can say what drives an ogre to loyalty.$b$bBring me their heads, $n, and then all that will remain is to remove Mug'Thol's head, crown and all." },
            { ids = { 520 }, name = "The Crown of Will", level = 43, zone = "Hillsbrad Foothills", giver = "Melisara", giverMap = 1424, giverX = 62.6, giverY = 20.6, ender = "Melisara", enderMap = 1424, enderX = 62.6, enderY = 20.6, objective = "Kill Mug'Thol, and return his head with the Crown of Will to Melisara in Tarren Mill.", summary = "With Mug'Thol's lieutenants dead, all that remains is to kill Mug'Thol and retrieve the Crown of Will. I have no doubt he'll be reluctant to part with it. Most likely expecting you, too, given the... departure... of his fellows.$b$bFind Mug'Thol, and deliver his head and the Crown to me. The Crushridge resistance will be at an end." },
            { ids = { 521 }, name = "The Crown of Will", level = 43, zone = "Hillsbrad Foothills", giver = "Melisara", giverMap = 1424, giverX = 62.6, giverY = 20.6, ender = "Sharlindra", enderMap = 1458, enderX = 57.6, enderY = 93.8, objective = "Deliver the Crown of Will to Sharlindra in the Undercity.", summary = "All that remains is to deliver the Crown of Will to Sharlindra in the Undercity. She will see that it is delivered to Lady Sylvanas. I would warn you against thinking to use it for your own purposes, $n, Mug'Thol's fate should be illustration enough." },
        },
    },
    {
        id = "q1953",
        name = "Power in Uldaman",
        zone = "Thunder Bluff",
        minLevel = 35,
        maxLevel = 40,
        importance = 2,
        kind = "class",
        classes = { 8 },
        quests = {
            { ids = { 1953 }, name = "Return to the Marsh", level = 40, zone = "Thunder Bluff", giver = "Ursyn Ghull", giverMap = 1456, giverX = 25.7, giverY = 14.2, ender = "Tabetha", enderMap = 1445, enderX = 46.1, enderY = 57.1, objective = "Speak with Tabetha.", summary = "It is time, $N, for you to speak with Tabetha... the hermit of Dustwallow Marsh.  She will instruct you on the creation of a powerful mage's implement.$B$BTabetha's shack lies deep in Dustwallow Marsh, west of Theramore." },
            { ids = { 1954 }, name = "The Infernal Orb", level = 40, zone = "Dustwallow Marsh", giver = "Tabetha", giverMap = 1445, giverX = 46.1, giverY = 57.1, ender = "Tabetha", enderMap = 1445, enderX = 46.1, enderY = 57.1, objective = "Bring an Infernal Orb to Tabetha in Dustwallow Marsh.", summary = "The first step is to acquire an orb with power.  The warlocks of the Burning Blade have nice, high quality orbs... it's too bad they've bound demons into them!  But we can fix that, yes we can.$B$BGo to Desolace and snatch an infernal orb from a Burning Blade summoner.  You'll find summoners at the Mannoroc Coven.$B$BWhen you have the orb, return to me." },
            { ids = { 1955 }, name = "The Exorcism", level = 40, zone = "Dustwallow Marsh", giver = "Tabetha", giverMap = 1445, giverX = 46.1, giverY = 57.1, ender = "Tabetha", enderMap = 1445, enderX = 46.1, enderY = 57.1, objective = "Kill the Demon of the Orb, then speak with Tabetha.", summary = "Now that we have a summoner's orb, we must exorcise the demon within it.  I can do that.  That's the easy part.$B$BYou're the one who has the hard job.  You're the one who has to kill the demon once it's out.$B$BAnd you'll have to be quick.  If you take too long then he'll jump back in the orb and we'll have to start over!$B$BSo get yourself ready.  Prepare your strongest spells and keep your potions handy, and go get a friend if you have one.  Because this isn't going to be pretty." },
            { ids = { 1956 }, name = "Power in Uldaman", level = 40, zone = "Dustwallow Marsh", giver = "Tabetha", giverMap = 1445, giverX = 46.1, giverY = 57.1, ender = "Tabetha", enderMap = 1445, enderX = 46.1, enderY = 57.1, objective = "Retrieve an Obsidian Power Source and bring it to Tabetha in Dustwallow Marsh.", summary = "Now that the demon has been removed, we must gain a power source.  Unfortunately, the best power sources are usually the oldest and the hardest to get.  It's neat how fate likes to take a bite out of you sometimes, isn't it?$B$BSo you're going to need to go to Uldaman and defeat the obsidian sentinel there.  He's big, he's tough, and his power source packs a punch!$B$BI wish you the best of luck, $N.  And if you don't get lucky then, well... it was nice knowing you." },
            { ids = { 1957 }, name = "Mana Surges", level = 40, zone = "Dustwallow Marsh", giver = "Tabetha", giverMap = 1445, giverX = 46.1, giverY = 57.1, ender = "Tabetha", enderMap = 1445, enderX = 46.1, enderY = 57.1, objective = "Kill 12 Mana Surges in the allowed time limit.", summary = "We are almost finished, but this last step is the most perilous, $N.$B$BI have the empty summoner's orb and am ready to empower it.  We will do this by harnessing the energy of a mana rift.  I'll cast a spell that will temporarily open a rift, from which creatures, mana surges, will pour out.  You must defeat the mana surges and their power will be released, which I will then collect.$B$BKill enough mana surges before the rift closes and I will place all their collected energy in your orb." },
            { ids = { 1958 }, name = "Celestial Power", level = 40, zone = "Dustwallow Marsh", giver = "Tabetha", giverMap = 1445, giverX = 46.1, giverY = 57.1, ender = "Tabetha", enderMap = 1445, enderX = 46.1, enderY = 57.1 },
        },
    },
    {
        id = "q4967",
        name = "Cleansing of the Orb of Orahil",
        zone = "The Barrens",
        minLevel = 35,
        maxLevel = 40,
        importance = 2,
        kind = "class",
        classes = { 9 },
        quests = {
            { ids = { 4962 }, name = "Shard of a Felhound", level = 40, zone = "The Barrens", giver = "Acolyte Wytula", giverMap = 1413, giverX = 62.6, giverY = 35.3, ender = "Menara Voidrender", enderMap = 1413, enderX = 62.5, enderY = 35.5, objective = "Take the Felhas Ruby and use it on one of the Felhounds found in Desolace. After successful, bring the Felhas Ruby and the Imprisoned Felhound Spirit back to Menara Voidrender in the Barrens.", summary = "So, you have chosen to capture the soul of a felhound, good.$B$BTake this ruby--with it, you will be able to capture the creature's soul. It works very similar to spells you already know: when the creature is close to dying, use the gem and it should do the rest of the work for you.$B$BI would suggest going to Desolace and trying your hand at any of the felhounds there. Those should do nicely.$B$BAfter you're successful, take both the captured spirit and your ruby to Menara." },
            { ids = { 4967 }, name = "Knowledge of the Orb of Orahil", level = 35, zone = "Orgrimmar", giver = "Zevrost", giverMap = 1454, giverX = 48.5, giverY = 45.4, ender = "Menara Voidrender", enderMap = 1413, enderX = 62.5, enderY = 35.5, objective = "Speak to Menara Voidrender in the Barrens.", summary = "Still a fool, and still seeking the trappings of mortals. Yes, I speak to you with arrogance. I see you before me and I laugh. You're pathetic!$B$BBut it matters not what I think. It only matters what those willing to deal with you thinks!  And in this case, against my better judgment, those with some portion of power feel you deserve more.$B$BIf this is something you strive for then you should speak with Menara Voidrender in the tower above Ratchet. I believe you have met her before some time ago." },
            { ids = { 1799 }, name = "Fragments of the Orb of Orahil", level = 40, zone = "The Barrens", giver = "Menara Voidrender", giverMap = 1413, giverX = 62.5, giverY = 35.5, ender = "Tabetha", enderMap = 1445, enderX = 46.1, enderY = 57.1, objective = "Speak to Menara's acolytes inside the tower above Ratchet and choose one of their paths to follow.$B$BAfterwards, bring an Infernal Orb to Tabetha in Dustwallow Marsh.", summary = "Good, then we shall begin.$B$BThe first thing you must do is speak to my acolytes inside. Choose one of their paths to follow--they will explain more.$B$BSecond, you must travel to Desolace and find an Infernal Orb from one of the warlocks of Mannoroc Coven. It is that orb that you will cleanse with the help of a mage named Tabetha deep in southern Dustwallow Marsh. She will aid you because of our history together.$B$BAgain, do not come back until you have done both things I've asked." },
            { ids = { 4961 }, name = "Cleansing of the Orb of Orahil", level = 40, zone = "Dustwallow Marsh", giver = "Tabetha", giverMap = 1445, giverX = 46.1, giverY = 57.1, ender = "Tabetha", enderMap = 1445, enderX = 46.1, enderY = 57.1, objective = "Kill the Demon of the Orb, then speak with Tabetha.", summary = "Ah, a summoner's orb--this is where the taint must be coming from. We must exorcise the demon within it if you're to use it. That I can do easily.$B$BYou're the one who has the hard job.  You must kill the demon once I release it.$B$BAnd you'll have to be quick.  If you take too long then he'll return to the orb and we'll have to start over!$B$BSo get yourself ready, $N.  Prepare your strongest spells and keep your potions handy, and go get a friend if you have one.  Because this isn't going to be pretty." },
            { ids = { 4976 }, name = "Returning the Cleansed Orb", level = 40, zone = "Dustwallow Marsh", giver = "Tabetha", giverMap = 1445, giverX = 46.1, giverY = 57.1, ender = "Menara Voidrender", enderMap = 1413, enderX = 62.5, enderY = 35.5, objective = "Return the Cleansed Infernal Orb to Menara Voidrender in the Barrens.", summary = "Take the cleansed orb back to Menara in Ratchet, $N. Give her my regards and be safe. I truly hope you are able to withstand the temptation and corruption that is sure to come as you follow your path.$B$BGood luck." },
            { ids = { 4964 }, name = "The Completed Orb of Dar'Orahil", level = 40, zone = "The Barrens", giver = "Menara Voidrender", giverMap = 1413, giverX = 62.5, giverY = 35.5, ender = "Menara Voidrender", enderMap = 1413, enderX = 62.5, enderY = 35.5, objective = "Wait for Menara Voidrender to complete the Orb of Dar'Orahil and then speak to her again.", summary = "I will get started immediately on crafting your orb and infusing your new demon into it. When done, you will have the choice of having it in the form of a staff or orb. I always felt it was important to cater to a warlock's chosen weapon... I see no reason not to continue that practice." },
        },
    },
    {
        id = "q663",
        name = "Land Ho!",
        zone = "Arathi Highlands",
        minLevel = 35,
        maxLevel = 44,
        importance = 1,
        kind = "world",
        quests = {
            { ids = { 663 }, name = "Land Ho!", level = 35, zone = "Arathi Highlands", giver = "Lolo the Lookout", giverMap = 1417, giverX = 31.8, giverY = 82.7, ender = "Shakes O'Breen", enderMap = 1417, enderX = 32.3, enderY = 81.4, objective = "Talk to Captain O'Breen in Faldir's Cove.", summary = "Lolo sees a tiny $r! Always on the lookout, Lolo is!$b$bWelcome to Faldir's Cove.  Captain O'Breen said we'd only be here for a few hours.  Just long enough to gather the treasure and get back to Booty Bay.$b$bBut Lolo thinks we're going to be here a lot longer than that.  We lost the other two ships from our formation.  Poor Spirit of Silverpine and Maiden's Folly.  On the bottom of the sea they rest now!$b$bLolo suggests you talk to Captain O'Breen if you plan on sticking around here." },
            { ids = { 665 }, name = "Sunken Treasure", level = 40, zone = "Arathi Highlands", giver = "Professor Phizzlethorpe", giverMap = 1417, giverX = 33.9, giverY = 80.5, ender = "Doctor Draxlegauge", enderMap = 1417, enderX = 33.9, enderY = 80.5, objective = "Escort Professor Phizzlethorpe to the cave and back.", summary = "Now that we are full-fledged Blackwater Raiders it is our job to help Mr. O'Breen locate the lost elven treasure.$b$bIt is next to impossible to find the gems in the dark sea without aid. The doctor has constructed some goggles that will help. He needs the goggles charged with the energy derived from the enchanted stone in the cave just up the hill.$b$bBut the cave is cursed! When we get close, we get ambushed. Defend me and I can harness the energy from the stone into the goggles." },
            { ids = { 666 }, name = "Sunken Treasure", level = 40, zone = "Arathi Highlands", giver = "Doctor Draxlegauge", giverMap = 1417, giverX = 33.9, giverY = 80.5, ender = "Doctor Draxlegauge", enderMap = 1417, enderX = 33.9, enderY = 80.5, objective = "Doctor Draxlegauge in Faldir's Cove wants you to collect 10 Elven Gems and return the Goggles of Gem Hunting once you are done.", summary = "The treasure has been on the sea floor so long that the gems have calcified into thick stone. But the power harnessed in these goggles will allow you to locate them easily.$b$bA little gnomish ingenuity goes a long way!$b$bSo borrow the Goggles of Gem Hunting, $n, and see if you can collect some of the lost treasure for Captain O'Breen.$b$bI'd swim down there myself but...um...well, I have important scientific business to tend to up on the safe, dry land....er, yeah." },
            { ids = { 668 }, name = "Sunken Treasure", level = 40, zone = "Arathi Highlands", giver = "Doctor Draxlegauge", giverMap = 1417, giverX = 33.9, giverY = 80.5, ender = "Shakes O'Breen", enderMap = 1417, enderX = 32.3, enderY = 81.4, objective = "Take the Elven Gems to Captain O'Breen.", summary = "Let's not leave Captain O'Breen waiting. He'll want to see these gems first hand. After all, that's why we're here!$b$bAnd after a few weeks of consorting with these pirates, the professor and I have realized the last thing that's good for our health is to be caught hanging on to their treasure.$b$bHere, $n, take these to O'Breen." },
            { ids = { 669 }, name = "Sunken Treasure", level = 40, zone = "Arathi Highlands", giver = "Shakes O'Breen", giverMap = 1417, giverX = 32.3, giverY = 81.4, ender = "Fleet Master Seahorn", enderMap = 1434, enderX = 27.2, enderY = 77.0, objective = "Take the Sample Elven Gem to Fleet Master Seahorn in Booty Bay.", summary = "Fleet Master Seahorn will want to hear about our find at once.$b$bBut as you can see, we're not in much of a position to get out of here. Not only is the tide too low, but those damned creatures we disrupted are keeping a close eye on our movements.$b$bYou can be of great service to the Blackwater Raiders if you can get word to Fleet Master Seahorn in Booty Bay that we discovered the treasure and are working on extracting more.  Take him this sample as proof." },
            { ids = { 670 }, name = "Sunken Treasure", level = 40, zone = "Stranglethorn Vale", giver = "Fleet Master Seahorn", giverMap = 1434, giverX = 27.2, giverY = 77.0, ender = "Shakes O'Breen", enderMap = 1417, enderX = 32.3, enderY = 81.4, objective = "Deliver Seahorn's Letter to Shakes O'Breen in Arathi Highlands.", summary = "Say, $n, you seem to be an adventurous type. My fleet is stuck in Booty Bay until we can restock.$b$bThere are some heavy things brewing here and abroad and I need to get some top secret correspondence to Shakes O'Breen who is tied up off the Arathi coast.$b$bCan I trust you to deliver this message safely and in confidence?" },
            { ids = { 667 }, name = "Death From Below", level = 44, zone = "Arathi Highlands", giver = "Shakes O'Breen", giverMap = 1417, giverX = 32.3, giverY = 81.4, ender = "Shakes O'Breen", enderMap = 1417, enderX = 32.3, enderY = 81.4, objective = "Protect Shakes O'Breen during the attack.", summary = "This is bad. It seems the Daggerspines are amassing for an attack.$b$bNaga are known for their ruthlessness in battle. They will keep attacking until I am dead.$b$bI don't value my own life above that of my crew members, but you must help to defend me. The crew will not be able to make it back to Booty Bay without my knowledge of the seas.$b$bThe naga will be coming from the sea. I need you to remain up here with me to fend off the attack. Man the cannon and drive them back.$b$bAre you ready, $n?" },
        },
    },
    {
        id = "q713",
        name = "This Is Going to Be Hard",
        zone = "Badlands",
        minLevel = 35,
        maxLevel = 45,
        importance = 1,
        kind = "world",
        quests = {
            { ids = { 710 }, name = "Study of the Elements: Rock", level = 37, zone = "Badlands", giver = "Lotwil Veriatus", giverMap = 1418, giverX = 25.9, giverY = 44.9, ender = "Lotwil Veriatus", enderMap = 1418, enderX = 25.9, enderY = 44.9, objective = "Find 10 Small Stone Shards and bring them to Lotwil Veriatus in the Badlands.", summary = "Here in the Badlands I've stopped to work on my latest project: my shackles of elemental binding.$B$BWhen complete, they will allow mages to summon even more powerful elementals for use in even greater capacities. To start things off, I need small stone shards to test some of my newest offensive spells along with a few gizmos I've pieced together.$B$BThe shards are easily collected from the lesser rock elementals to the west of here. Could you bring me some?" },
            { ids = { 713 }, name = "Coolant Heads Prevail", level = 37, zone = "Badlands", giver = "Lotwil Veriatus", giverMap = 1418, giverX = 25.9, giverY = 44.9, ender = "Lotwil Veriatus", enderMap = 1418, enderX = 25.9, enderY = 44.9, objective = "Find Frost Oil and bring it to Lotwil Veriatus in Badlands.", summary = "Let me tell you something about Frost Oil: nothing can keep an engine or gears from overheating quite like it.$B$BIts cooling properties are extraordinary, and its longevity as a lubricant without equal. That's not all: it also aids in retaining enchantments on magical items.$B$BI need a vial of it to increase the magical capacity of my shackles and make them powerful enough to stop our summoned friend from killing us all.$B$BBro'kin, a goblin friend of mine, can teach you to make it. He's in Alterac." },
            { ids = { 711 }, name = "Study of the Elements: Rock", level = 39, zone = "Badlands", giver = "Lotwil Veriatus", giverMap = 1418, giverX = 25.9, giverY = 44.9, ender = "Lotwil Veriatus", enderMap = 1418, enderX = 25.9, enderY = 44.9, objective = "Bring 3 Large Stone Slabs to Lotwil Veriatus in the Badlands.", summary = "$N, you've already proven more able than all my apprentices combined.$B$BThe next parts I need require a little more strength. Large stone slabs can be found on rock elementals if you're careful enough. Their bodies are stronger and larger, and therefore more prone to having pieces large enough for my tests. You can find them further west of here or southeast along the mountains' edges.$B$BTake your time; I'll need a while to test these smaller pieces you brought me." },
            { ids = { 714 }, name = "Gyro... What?", level = 37, zone = "Badlands", giver = "Lotwil Veriatus", giverMap = 1418, giverX = 25.9, giverY = 44.9, ender = "Lotwil Veriatus", enderMap = 1418, enderX = 25.9, enderY = 44.9, objective = "Bring a Gyrochronatom to Lotwil Veriatus in the Badlands.", summary = "$N, you've done your job well beyond all standards.$B$B<Lotwil's obviously distracted by his work.>$B$BIf we ever meet in Kharanos, feel free to come apply for work.$B$BWhoops! Quick, grab the... yes, that. Thanks.$B$BNow I just need one more thing. It's a small part, but rather crucial, I'm afraid: a gyrochronatom.$B$BIf you could just go grab one and bring it to me, I should be ready to complete this." },
            { ids = { 712 }, name = "Study of the Elements: Rock", level = 42, zone = "Badlands", giver = "Lotwil Veriatus", giverMap = 1418, giverX = 25.9, giverY = 44.9, ender = "Lotwil Veriatus", enderMap = 1418, enderX = 25.9, enderY = 44.9, objective = "Bring 5 Bracers of Rock Binding to Lotwil Veriatus in the Badlands.", summary = "$N, there's one more part I need from the elementals here in the Badlands: the bracers of rock binding from the greater rock elementals. By my calculations, those bracers should be enough to gauge the strength of my own shackles.$B$BMy attempts at scrying the greater rock elementals showed a group of them southwest of here, near some ogres if I recall.$B$BBring me 5 of their bracers just so I have extras. Servo's notorious for misplacing my reagents and research." },
            { ids = { 734 }, name = "This Is Going to Be Hard", level = 42, zone = "Badlands", giver = "Lotwil Veriatus", giverMap = 1418, giverX = 25.9, giverY = 44.9, ender = "Lucien Tosselwrench", enderMap = 1418, enderX = 25.8, enderY = 44.2, objective = "Speak to Lucien Tosselwrench in the Badlands.", summary = "Wonderful, wonderful.$B$B<Lotwil looks up at you for a moment before going back to his shackles.>$B$BGo speak to Lucien, $N. I need a cog #5. Bring it to me, will you?" },
            { ids = { 777 }, name = "This Is Going to Be Hard", level = 42, zone = "Badlands", giver = "Lucien Tosselwrench", giverMap = 1418, giverX = 25.8, giverY = 44.2, ender = "Lotwil Veriatus", enderMap = 1418, enderX = 25.9, enderY = 44.9, objective = "Bring Cog #5 to Lotwil Veriatus.", summary = "Okay, here you go.$B$BI'm going to be over here... behind cover.$B$BFeel free to join me." },
            { ids = { 778 }, name = "This Is Going to Be Hard", level = 45, zone = "Badlands", giver = "Lotwil Veriatus", giverMap = 1418, giverX = 25.9, giverY = 44.9, ender = "Lotwil Veriatus", enderMap = 1418, enderX = 25.9, enderY = 44.9, objective = "Defeat the Fam'retor Guardian and bring Lotwil's Shackles of Elemental Binding back to Lotwil Veriatus.", summary = "Haha! Done! The shackles are done!$B$BIt's time, Lucien. It's time, Servo!$B$BAre you ready to bear witness to the perfect blend of alchemy, engineering, and the arcane, $N?$B$BI shall summon forth a powerful elemental now. This is a groundbreaking day for all of us." },
        },
    },
    {
        id = "q2283",
        name = "Necklace Recovery",
        zone = "Orgrimmar",
        minLevel = 37,
        maxLevel = 44,
        importance = 3,
        kind = "dungeon",
        quests = {
            { ids = { 2283 }, name = "Necklace Recovery", level = 41, zone = "Orgrimmar", giver = "Dran Droffers", giverMap = 1454, giverX = 59.5, giverY = 36.6, ender = "Dran Droffers", enderMap = 1454, enderX = 59.5, enderY = 36.6, objective = "Look for a valuable necklace within the Uldaman dig site and bring it back to Dran Droffers in Orgrimmar.  The necklace may be damaged.", summary = "We've got work for you, that is if you've got the guts to do it!$B$BDeep in the Badlands is the Uldaman dig site.  We've heard a tale about some idiot paladin who died there recently.  Why we even care is that he had a very valuable necklace on him.  It's supposedly got three large gems: a ruby, a sapphire, and a topaz.$B$BThe shot: we want it, and we're payin' TOP SILVER to get it.  It may be damaged, but that's neither here nor there; we'll fix whatever scratches are on it." },
            { ids = { 2284 }, name = "Necklace Recovery, Take 2", level = 41, zone = "Orgrimmar", giver = "Dran Droffers", giverMap = 1454, giverX = 59.5, giverY = 36.6, ender = "Remains of a Paladin", enderMap = 1418, enderX = 44.6, enderY = 12.1, enderInside = "Uldaman", objective = "Find a clue as to the gems' whereabouts in the depths of Uldaman.", summary = "As sure as Malton is a dummy, those gems are still in Uldaman somewhere.  You're going to have to go back there and look for them.$B$BLike I said before, if the information we have is correct then there's a ruby, a sapphire, and a topaz that go with the necklace.  Find them and put them in the necklace.$B$BAs to where the gems are, who knows?  Maybe you'll get lucky and find the corpse of the Paladin.  If he's not been stripped clean already, then maybe he's got them on him still." },
            { ids = { 2318 }, name = "Translating the Journal", level = 42, zone = "Uldaman", giver = "Remains of a Paladin", giverMap = 1418, giverX = 44.6, giverY = 12.1, giverInside = "Uldaman", ender = "Jarkal Mossmeld", enderMap = 1418, enderX = 2.4, enderY = 46.1, objective = "Find someone who can translate the paladin's journal.  The closest location that might have someone is Kargath, in the Badlands.", summary = "At an impasse of sorts, you know that you will need the book translated into a language you can understand.  There certainly are a number of people in the world who could do it; the closest location that might have someone who could, however, is the Kargath outpost in the Badlands.  Perhaps that is a good place to start." },
            { ids = { 2338 }, name = "Translating the Journal", level = 42, zone = "Badlands", giver = "Jarkal Mossmeld", giverMap = 1418, giverX = 2.4, giverY = 46.1, ender = "Jarkal Mossmeld", enderMap = 1418, enderX = 2.4, enderY = 46.1, objective = "Let Jarkal borrow the necklace.  In exchange, he will translate the journal for you.", summary = "Droffers and Son Salvage aren't smart enough to restore the magic in the necklace, but I am.  All I want to do is study the necklace so I can learn to make them myself.  To do that, I will need your necklace.  Let me borrow it, and in exchange for the time I get to study it I will translate the journal for you.  While you are searching for the gems, I should have enough time to learn what I need to.$B$BIt's a simple deal, and no one else will be the wiser.  Whatcha wanna do?" },
            { ids = { 2339 }, name = "Find the Gems and Power Source", level = 44, zone = "Badlands", giver = "Jarkal Mossmeld", giverMap = 1418, giverX = 2.4, giverY = 46.1, ender = "Jarkal Mossmeld", enderMap = 1418, enderX = 2.4, enderY = 46.1, objective = "Recover all three gems and a power source for the necklace from Uldaman, and then bring them to Jarkal Mossmeld in Kargath.  Jarkal believes a power source might be found on the strongest construct present in Uldaman.$B$BFrom the journal, you know...$B* The ruby has been stashed in a barricaded Shadowforge area.$B* The topaz has been hidden in an urn in one of the Trogg areas, near some Alliance dwarves.$B* The sapphire has been claimed by Grimlok, the trogg leader.", summary = "Here is the journal, translated for you to read on your own.  The crux of it says dwarves hid the ruby, the troggs hid the topaz, and a trogg named Grimlok has the sapphire.$B$BLook - you're going to need a power source to make the necklace work again.  Dran Droffers doesn't know this.  To find one, here's what I'd do: go as deep as you can in Uldaman and kill whatever construct there is the strongest.  No doubt whatever that is would have it.$B$BWhen you have everything collected, come back here!" },
            { ids = { 2340 }, name = "Deliver the Gems", level = 44, zone = "Badlands", giver = "Jarkal Mossmeld", giverMap = 1418, giverX = 2.4, giverY = 46.1, ender = "Dran Droffers", enderMap = 1454, enderX = 59.5, enderY = 36.6, objective = "Deliver the Necklace and Gem Salvage to Dran Droffers in Orgrimmar.", summary = "Any necklace setting and gem will work, so long as they are the same material.  This power source, however, is what will bring the magic back to the necklace... I hope.$B$BI'll gladly supply the gems needed for your version of the necklace, so long as the power source actually works.$B$BHead to Orgrimmar and keep your end of the bargain with Droffers and Son Salvage.  Just keep your mouth shut about our deal, and when you get back I might have a wonderful surprise for you." },
            { ids = { 2341 }, name = "Necklace Recovery, Take 3", level = 44, zone = "Orgrimmar", giver = "Dran Droffers", giverMap = 1454, giverX = 59.5, giverY = 36.6, ender = "Jarkal Mossmeld", enderMap = 1418, enderX = 2.4, enderY = 46.1, objective = "Visit Jarkal Mossmeld in Kargath to see if he was successful.", summary = "As Dran and Malton Droffers begin to squabble over their new salvage, half of the deal is now complete.  A trip to the Badlands is now in order to finish things up, as Jarkal Mossmeld in Kargath might have a special reward waiting for you there." },
        },
    },
    {
        id = "q992",
        name = "Pawn Captures Queen",
        zone = "Tanaris",
        minLevel = 38,
        maxLevel = 54,
        importance = 2,
        kind = "world",
        quests = {
            { ids = { 992 }, name = "Gadgetzan Water Survey", level = 46, zone = "Tanaris", giver = "Senior Surveyor Fizzledowser", giverMap = 1446, giverX = 50.2, giverY = 27.5, ender = "Senior Surveyor Fizzledowser", enderMap = 1446, enderX = 50.2, enderY = 27.5, objective = "Use the untapped dowsing widget near the pool of water by Sandsorrow Watch.  Once you have collected the sample, return the tapped dowsing widget to Senior Surveyor Fizzledowser in Gadgetzan.", summary = "We've got a position open for a temporary junior-grade surveyor in the Gadgetzan Water Company, if you're interested!$B$BWith the nomads seizing all our wells, we need to exploit more free sources of water!  There is water to be had in the desert, but only to those smart enough to survey them first.$B$BTake this dowsing widget and tap a sample of the water by the pool near Sandsorrow Watch.  It's right in sight of the trolls around there.  Bring the tapped widget back to me when you're done!" },
            { ids = { 82 }, name = "Noxious Lair Investigation", level = 47, zone = "Tanaris", giver = "Senior Surveyor Fizzledowser", giverMap = 1446, giverX = 50.2, giverY = 27.5, ender = "Alchemist Pestlezugg", enderMap = 1446, enderX = 50.9, enderY = 27.0, objective = "Bring five Centipaar insect parts from the Noxious Lair to Alchemist Pestlezugg in Gadgetzan.", summary = "All right now, these reports about the bugs... what we know is that they are draining the water pools that used to be where the Noxious Lair is. What we DON'T know is, well, everything else.$B$BLet's figure out who our enemy is first! I want you to head into the Noxious Lair and get some parts off of those critters. Get five from the Centipaar there and bring them to Alchemist Pestlezugg for him to dink with. With him on the case, we'll figure out what they are!" },
            { ids = { 10 }, name = "The Scrimshank Redemption", level = 48, zone = "Tanaris", giver = "Senior Surveyor Fizzledowser", giverMap = 1446, giverX = 50.2, giverY = 27.5, ender = "Senior Surveyor Fizzledowser", enderMap = 1446, enderX = 50.2, enderY = 27.5, objective = "Discover the fate of Junior Surveyor Scrimshank, and bring either him or his surveying equipment to Senior Surveyor Fizzledowser in Gadgetzan.", summary = "Oh, this is just terrible!  I sent out my top assistant, Junior Surveyor Scrimshank, into the desert southeast of here.  That's an area we call the Gaping Chasm.  Well, he's gone missing, and his last report had more of those weird bugs where he was.  Could it be that they've infested two major regions of the desert now?$B$BI need you to head into the Gaping Chasm and look for Scrimshank, please!  That... or at least find his surveying equipment.  I fear that may be all that is left of the poor sod." },
            { ids = { 110 }, name = "Insect Part Analysis", level = 48, zone = "Tanaris", giver = "Senior Surveyor Fizzledowser", giverMap = 1446, giverX = 50.2, giverY = 27.5, ender = "Alchemist Pestlezugg", enderMap = 1446, enderX = 50.9, enderY = 27.0, objective = "Check in Gadgetzan for Alchemist Pestlezugg and his analysis of the insect parts.", summary = "I'm going to spend some time taking a look at Scrimshank's surveying gear... as well as putting his personal effects in order.  I get the sneaking feeling behind my ears that this isn't the last loss we'll be facing against these bugs.$B$BI'd like for you to check in with Alchemist Pestlezugg to see if he has had a chance to process the insect parts we sent him.  If they're ready, bring them to me." },
            { ids = { 113 }, name = "Insect Part Analysis", level = 48, zone = "Tanaris", giver = "Alchemist Pestlezugg", giverMap = 1446, giverX = 50.9, giverY = 27.0, ender = "Senior Surveyor Fizzledowser", enderMap = 1446, enderX = 50.2, enderY = 27.5, objective = "Deliver the report to Senior Surveyor Fizzledowser in Gadgetzan.  Be sure he gives you a copy of the report, as Alchemist Pestlezugg has requested.", summary = "Senior Surveyor Fizzledowser needs to see this report immediately.  Actually... everyone who can read needs to see this report.  We are facing a grave and serious threat to not only Tanaris and Gadgetzan, but if left unchecked, the entirety of southern Kalimdor.  Heck, even quite possible the whole of Azeroth; this thing has given no indication it will subside.$B$BHave Fizzledowser make a duplicate of the report for you to distribute freely to your allegiance. Everyone must know about this threat!" },
            { ids = { 32 }, name = "Rise of the Silithid", level = 48, zone = "Tanaris", giver = "Senior Surveyor Fizzledowser", giverMap = 1446, giverX = 50.2, giverY = 27.5, ender = "Zilzibin Drumlore", enderMap = 1454, enderX = 56.3, enderY = 46.7, objective = "Take the report to Zilzibin Drumlore in Orgrimmar.", summary = "Here's your report.  I urge you to take it to someone who might have working knowledge in this kind of thing.$B$BI know this troll scholar named Zilzibin Drumlore.  He's spent a lot of time studying life forms that are unique to the ecology of Azeroth; he's a historian to boot!  If you want someone to help figure out what exactly this threat is and how to stop it, give this report to him.  We're going to need all the help we can get.$B$BZil lives in a house on the second tier of the Drag in Orgrimmar." },
            { ids = { 4494 }, name = "March of the Silithid", level = 53, zone = "Orgrimmar", giver = "Zilzibin Drumlore", giverMap = 1454, giverX = 56.3, giverY = 46.7, ender = "Alchemist Pestlezugg", enderMap = 1446, enderX = 50.9, enderY = 27.0, objective = "Speak to Alchemist Pestlezugg in Gadgetzan.", summary = "It would seem that the silithid's intent, nay - reason for being, is to devour everything in their path that is not of their ecology.  Their focus is singular, and it is for this reason they are a grave threat to all life on Azeroth.$B$BWhat we've seen to date is but the first stages.  I suspect that their strength comes from deeper in Kalimdor: Un'Goro Crater.  Go to Gadgetzan in the Tanaris desert and speak to Alchemist Pestlezugg.  Tell him of my theory; he will surely aid us in fighting the silithid." },
            { ids = { 4496 }, name = "Bungle in the Jungle", level = 53, zone = "Tanaris", giver = "Alchemist Pestlezugg", giverMap = 1446, giverX = 50.9, giverY = 27.0, ender = "Alchemist Pestlezugg", enderMap = 1446, enderX = 50.9, enderY = 27.0, objective = "Bring a Gorishi Scent Gland and 5 Un'Goro Soil samples to Alchemist Pestlezugg in Gadgetzan.", summary = "My research revealed to me that the silithid are like bees; destroy the queen of the hive, and the rest of should be thrown into disarray.  I'll brew a lure that we'll use to bring out the queen; once summoned, you'll take her down.$B$BFirst though, we need some reagents; we don't want you bungling into the jungle unprepared.  Go west to find the silithid hive in Un'Goro Crater and obtain a scent gland from one of the bugs.  I'll also need some samples of the native Un'Goro soil." },
            { ids = { 4507 }, name = "Pawn Captures Queen", level = 54, zone = "Tanaris", giver = "Alchemist Pestlezugg", giverMap = 1446, giverX = 50.9, giverY = 27.0, ender = "Alchemist Pestlezugg", enderMap = 1446, enderX = 50.9, enderY = 27.0, objective = "Defeat the Gorishi Hive Queen once she is summoned.$B$BBring the Gorishi Queen's Brain to Alchemist Pestlezugg in Gadgetzan.", summary = "Here's the lure.  Inside the hive network should be a crystal of some sort.  We think the silithid use the crystal as some sort of hive-wide attunement device.  As for where this crystal might be, I'd say try the hatcheries inside the hive.$B$BUsing the lure on the crystal should roust out the queen, but be warned - she will probably be protected by several guards.  Take out the queen and remove her brain.  As icky as that sounds, we desperately need to study it.  Good luck, $N!" },
            { ids = { 4509 }, name = "Calm Before the Storm", level = 54, zone = "Tanaris", giver = "Alchemist Pestlezugg", giverMap = 1446, giverX = 50.9, giverY = 27.0, ender = "Zilzibin Drumlore", enderMap = 1454, enderX = 56.3, enderY = 46.7, objective = "Bring Pestlezugg's Un'Goro Report to Zilzibin Drumlore in Orgrimmar.", summary = "My recent findings and the knowledge we have gained here today needs to reach hands that can quite possibly do something with it.  As resourceful as we are here in Gadgetzan, we can't do this alone.$B$BTake my latest report back to Zilzibin Drumlore in Orgrimmar; he's still in his place on the upper part of the Drag, is he not?  He's got friends who are high within the Horde; if we can get them involved in this $N, then we just might make it out of this alive." },
            { ids = { 4511 }, name = "Calm Before the Storm", level = 54, zone = "Orgrimmar", giver = "Zilzibin Drumlore", giverMap = 1454, giverX = 56.3, giverY = 46.7, ender = "Karus", enderMap = 1454, enderX = 49.6, enderY = 69.1, objective = "Bring the Bank Voucher to Karus in the bank of Orgrimmar.", summary = "$N, we could not have gotten this far without you.  The time will come soon, no doubt, when I'll ask for your help against the silithid once more.  We must absorb what we have learned in Un'Goro; I fear that my assumptions that the silithid originated from Un'Goro are now wrong... that indeed there is a far stronger presence somewhere.$B$BTake this note to Karus at the bank.  He'll give you something from my vault that should be viewed as a token of my gratitude.  Thank you for your assistance, mighty $c." },
        },
    },
    {
        id = "q1429",
        name = "The Temple of Atal'Hakkar",
        zone = "Swamp of Sorrows",
        minLevel = 38,
        maxLevel = 50,
        importance = 2,
        kind = "dungeon",
        quests = {
            { ids = { 1424 }, name = "Pool of Tears", level = 43, zone = "Swamp of Sorrows", giver = "Fel'zerul", giverMap = 1435, giverX = 47.9, giverY = 54.8, ender = "Fel'zerul", enderMap = 1435, enderX = 47.9, enderY = 54.8, objective = "Fel'zerul in Stonard wants you to gather 10 Atal'ai Artifacts.", summary = "The Warchief sent us to investigate strange happenings at The Temple of Atal'Hakkar.$b$bThe Atal'ai trolls are a tribe of dark casters, known for practicing forbidden magic. You can imagine how astonished we were when we arrived here to discover the temple had been sunk.$b$bThe green dragons now guard the site, claiming to be protectors of Azeroth.$b$bWe need to discover what happened. Explore around the Pool of Tears and gather Atal'ai artifacts. From those I can begin to piece together this puzzle." },
            { ids = { 1429 }, name = "The Atal'ai Exile", level = 44, zone = "Swamp of Sorrows", giver = "Fel'zerul", giverMap = 1435, giverX = 47.9, giverY = 54.8, ender = "Atal'ai Exile", enderMap = 1425, enderX = 33.8, enderY = 75.2, objective = "Bring the Bundle of Atal'ai Artifacts to the Atal'ai Exile in the Hinterlands.", summary = "While you were braving the dangers of the Pool of Tears, one of my scouts returned with a scroll written in blood on dried flesh. It seems to be a judicial sentence against a priest of the Atal'ai tribe.$b$bThis priest was sentenced to a fate worse than death amongst the Atal'ai.$b$bHe was exiled to live far north in the Hinterlands, with the Witherbark trolls.$b$bI will bundle these artifacts. You are to seek out the exile and discover their true use. Return to me once your journey is complete." },
            { ids = { 1444 }, name = "Return to Fel'Zerul", level = 44, zone = "The Hinterlands", giver = "Atal'ai Exile", giverMap = 1425, giverX = 33.8, giverY = 75.2, ender = "Fel'zerul", enderMap = 1435, enderX = 47.9, enderY = 54.8, objective = "Return to Fel'Zerul in Stonard.", summary = "Jammal'an the Prophet sentenced me to exile from The Temple of Atal'Hakkar. I once felt the high priest was a worthy leader.$b$bHis unyielding faith in his prophecy will bring about the destruction of the Atal'ai. If it hasn't already.$b$bWhen I expressed my concerns, I was labeled an infidel and ousted from the temple.$b$bThose artifacts you brought to me are harmless. But if Jammal'an has found the proper fetish enchantment for the summoning ritual, the world lies in great peril...." },
            { ids = { 1445 }, name = "The Temple of Atal'Hakkar", level = 50, zone = "Swamp of Sorrows", giver = "Fel'zerul", giverMap = 1435, giverX = 47.9, giverY = 54.8, ender = "Fel'zerul", enderMap = 1435, enderX = 47.9, enderY = 54.8, objective = "Collect 20 Fetishes of Hakkar and bring them to Fel'Zerul in Stonard.", summary = "So he spoke of Jammal'an's prophecy?$b$bThe Atal'ai spiritual leader believes once Hakkar returns to Azeroth from the Nether, the god will grant the Atal'ai tribe immortality.$b$bFoolish trickery to bring about a premature doomsday if you ask me.$b$bBut you say the exile spoke of enchanted fetishes? This concerns me greatly. If these are in fact the key to the Atal'ai ritual which caused this mess, we must understand their intrinsic powers.$b$bVenture into the Temple, and seize the fetishes!" },
        },
    },
    {
        id = "q232",
        name = "Slake That Thirst",
        zone = "Undercity",
        minLevel = 38,
        maxLevel = 46,
        importance = 2,
        kind = "world",
        quests = {
            { ids = { 232 }, name = "Errand for Apothecary Zinge", level = 45, zone = "Undercity", giver = "Apothecary Zinge", giverMap = 1458, giverX = 50.1, giverY = 68.0, ender = "Alessandro Luca", enderMap = 1458, enderX = 58.6, enderY = 54.7, objective = "Take the purchase order to Alessandro Luca in the Undercity.", summary = "The Royal Apothecary Society needs your assistance.  Listen closely, and both of us may profit from my plan.$B$BApothecary Keever in the next room may be... touched... but his research does potentially bear fruit if it were pursued by a clever researcher.  Fortunately, I am such a researcher.  I want you to take this purchase order to Alessandro Luca, the proprietor of Blue Moon Odds and Ends; he'll give you a testing kit.  When you have it, bring it back to me and I'll outline your task in detail." },
            { ids = { 238 }, name = "Errand for Apothecary Zinge", level = 45, zone = "Undercity", giver = "Alessandro Luca", giverMap = 1458, giverX = 58.6, giverY = 54.7, ender = "Apothecary Zinge", enderMap = 1458, enderX = 50.1, enderY = 68.0, objective = "Bring the Field Sampling Kit to Apothecary Zinge in the Undercity.", summary = "The kit is ready, $n.  No doubt that Apothecary Zinge will want this as soon as possible.  Take it to her without delay, and let her know that I will add the cost of the kit to the Society's tab.  Also, please extend to her my warmest salutations.$B$BWell, don't just stand there.  Such is the life of a simple courier, yes?" },
            { ids = { 243 }, name = "Into the Field", level = 46, zone = "Undercity", giver = "Apothecary Zinge", giverMap = 1458, giverX = 50.1, giverY = 68.0, ender = "Chief Engineer Bilgewhizzle", enderMap = 1446, enderX = 52.5, enderY = 28.5, objective = "Speak to Chief Engineer Bilgewhizzle in Gadgetzan about getting a power source for the testing kit.", summary = "You will be headed to the Tanaris desert, testing the tissue consistency of the basilisks, scorpids, and hyena native there.  Obtain tissue samples and use them with the testing kit in tow; expect a chunk of the samples to fail.  I need eight acceptable samples of each creature type.$B$BIn addition, the goblins of Gadgetzan have a power source that must be used with this kind of modified kit.  Speak to Chief Engineer Bilgewhizzle and acquire one for the kit.$B$BReturn to me only when you are successful." },
            { ids = { 379 }, name = "Slake That Thirst", level = 46, zone = "Tanaris", giver = "Chief Engineer Bilgewhizzle", giverMap = 1446, giverX = 52.5, giverY = 28.5, ender = "Chief Engineer Bilgewhizzle", enderMap = 1446, enderX = 52.5, enderY = 28.5, objective = "Bring 5 Wastewander Water Pouches to Chief Engineer Bilgewhizzle in Gadgetzan.", summary = "You want a power source.  I can help you with that.  Know what I want?  I want something to drink!  Bring me five Wastewander Water Pouches, and I'll give you the 4711-FTZ.$B$BNow... guess where you can find Wastewander Water Pouches!  Why don't you walk up to one of the Wastewander nomads to the east of here and ask them for one.  Let me know how that works out for you." },
            { ids = { 654 }, name = "Tanaris Field Sampling", level = 46, zone = "Tanaris", ender = "Chief Engineer Bilgewhizzle", enderMap = 1446, enderX = 52.5, enderY = 28.5, objective = "Acquire acceptable samples for 8 basilisks, 8 hyenas, and 8 scorpions.  Bring the testing kit back to Chief Engineer Bilgewhizzle in Gadgetzan before the power source runs out.", summary = "Activating the power source makes the field testing kit start to glow and vibrate.  It would seem to be working as planned.$B$BAccording to Chief Engineer Bilgewhizzle, you now have two hours to collect the data you need in the Tanaris desert.  If you do not collect it within two hours, all the data will be lost and you will need to buy another power source from him.$B$BReturn to him when you have completed the task." },
            { ids = { 864 }, name = "Return to Apothecary Zinge", level = 46, zone = "Tanaris", giver = "Chief Engineer Bilgewhizzle", giverMap = 1446, giverX = 52.5, giverY = 28.5, ender = "Apothecary Zinge", enderMap = 1458, enderX = 50.1, enderY = 68.0, objective = "Bring the Sealed Field Testing Kit to Apothecary Zinge in the Undercity.", summary = "\"Here you go, the power source is safely removed and the data is preserved.  Well, safe journeys and all that.  Hope the nefarious science experiment worked out for you and all.\"$B$BThe goblin turns away from you to attend to the demands of the Gadgetzan Water Company.  You secure the sealed testing kit for the journey back to the Undercity.  Apothecary Zinge waits for you and the sealed field testing kit there." },
        },
    },
    {
        id = "q2902",
        name = "The Battle Plans",
        zone = "Feralas",
        minLevel = 39,
        maxLevel = 48,
        importance = 1,
        kind = "world",
        quests = {
            { ids = { 2862 }, name = "War on the Woodpaw", level = 42, zone = "Feralas", giver = "Hadoken Swiftstrider", giverMap = 1444, giverX = 74.9, giverY = 42.5, ender = "Hadoken Swiftstrider", enderMap = 1444, enderX = 74.9, enderY = 42.5, objective = "Bring 10 Woodpaw Gnoll Manes to Hadoken Swiftstrider in Camp Mojache.", summary = "The gnolls... they are more than a nuisance.  They are a constant threat to the existence of this very camp!  It is irrelevant whether they are indigenous to Feralas or not; if we do not strengthen our resolve against them, we will find ourselves driven out of the entire region.$B$BThe gnoll attacks against the camp have become more fevered as of late.  We need your aid in thinning their numbers; bring to me ten of their manes, and I will reward you handsomely for your effort.$B$BGo!" },
            { ids = { 2863 }, name = "Alpha Strike", level = 43, zone = "Feralas", giver = "Hadoken Swiftstrider", giverMap = 1444, giverX = 74.9, giverY = 42.5, ender = "Hadoken Swiftstrider", enderMap = 1444, enderX = 74.9, enderY = 42.5, objective = "Kill 5 Woodpaw Alphas and return to Hadoken Swiftstrider within one hour.", summary = "The plan is for various leaders of the gnolls - Alphas as they call themselves - to be taken down within rapid succession.  If we're able to execute this sort of swift and precise devastation against them, it would cause chaos in their ranks.  Perhaps it would also drive a message through their thick flea-bitten heads that we can and will destroy them!$B$BI want you to be the messenger of my will; eliminate five of their Alphas within one hour for this to work $N, or we'll remain at this impasse!" },
            { ids = { 2902 }, name = "Woodpaw Investigation", level = 43, zone = "Feralas", giver = "Hadoken Swiftstrider", giverMap = 1444, giverX = 74.9, giverY = 42.5, ender = "Woodpaw Battle Map", enderMap = 1444, enderX = 71.6, enderY = 55.9, objective = "Find the gnoll battle plans somewhere in the gnoll camps to the south of Camp Mojache.", summary = "Gnolls aren't the sharpest tools in the shed, but they will no doubt have some sort of documented strategy on their recent activity.  If we were to find those plans, then we'd have a clearer idea of what is making them so worked up.$B$BI want you to head back to the Woodpaw and find anything that might resemble their battle plans.  They have to have something; their attacks have been too coordinated to be done without them.  Find them, and return to me when you have them." },
            { ids = { 2903 }, name = "The Battle Plans", level = 43, zone = "Feralas", giver = "Woodpaw Battle Map", giverMap = 1444, giverX = 71.6, giverY = 55.9, ender = "Hadoken Swiftstrider", enderMap = 1444, enderX = 74.9, enderY = 42.5, objective = "Bring the Woodpaw Battle Plans to Hadoken Swiftstrider in Camp Mojache.", summary = "With the battle plans of the gnolls discovered, all that now remains is to bring the plans back to Hadoken Swiftstrider in Camp Mojache.  Perhaps he or someone there can make further sense of what the gnolls are up to." },
            { ids = { 7730 }, name = "Zukk'ash Infestation", level = 45, zone = "Feralas", giver = "Hadoken Swiftstrider", giverMap = 1444, giverX = 74.9, giverY = 42.5, ender = "Hadoken Swiftstrider", enderMap = 1444, enderX = 74.9, enderY = 42.5, objective = "Bring 20 Zukk'ash Carapaces to Hadoken Swiftstrider at Camp Mojache, Feralas.", summary = "From what scouting we have managed to muster, we believe that the foe south of the gnolls is an insect-like race.  Frankly, it is irrelevant whether or not if they're sentient.  If they are driving the gnolls to frenzy against us, then they are as big of a threat - if not more - than the gnolls.$B$BDrive deep into where these Zukk'ash insects dwell; it is known as the Writhing Deep.  Thin their numbers and report back to me what you find, bringing back their carapaces as evidence of your handiwork." },
            { ids = { 7731 }, name = "Stinglasher", level = 47, zone = "Feralas", giver = "Hadoken Swiftstrider", giverMap = 1444, giverX = 74.9, giverY = 42.5, ender = "Hadoken Swiftstrider", enderMap = 1444, enderX = 74.9, enderY = 42.5, objective = "Defeat Stinglasher in the Writhing Deep, bringing its glands back to Hadoken Swiftstrider at Camp Mojache, Feralas.", summary = "In surveying the Writhing Deep, one of our scouts reported seeing a giant insect - much larger than the other insects spotted - wandering about the twisted terrain.  Not only is it larger, it also seems to secrete some sort of aura that the other insects don't.  We've given it a name - Stinglasher.$B$BThe innards of this beast would be invaluable to study as we figure out the best way to deal with this new threat.  Cut out its secretion glands and bring it back to me immediately!" },
            { ids = { 7732 }, name = "Zukk'ash Report", level = 48, zone = "Feralas", giver = "Hadoken Swiftstrider", giverMap = 1444, giverX = 74.9, giverY = 42.5, ender = "Zilzibin Drumlore", enderMap = 1454, enderX = 56.3, enderY = 46.7, objective = "Deliver the Camp Mojache Zukk'ash Report to Zilzibin Drumlore.  He resides in the Drag of Orgrimmar.", summary = "You've done doubly well in addressing the threat that the Zukk'ash insects pose to Camp Mojache.  The threat these things pose is far from over, and I'd like to ask you for one last task on behalf of the Horde.$B$BThis is a document that details all the information we have learned about these Zukk'ash insects.  I want you to deliver it to Zilzibin Drumlore in the Drag of Orgrimmar.  He's an expert on alien creatures like these; I hope he can do something with the lore we've obtained." },
        },
    },
    {
        id = "q2278",
        name = "Portents of Uldum",
        zone = "Uldaman",
        minLevel = 40,
        maxLevel = 50,
        importance = 3,
        kind = "dungeon",
        quests = {
            { ids = { 2278 }, name = "The Platinum Discs", level = 47, zone = "Uldaman", giver = "The Discs of Norgannon", giverMap = 1418, giverX = 44.6, giverY = 12.1, giverInside = "Uldaman", ender = "The Discs of Norgannon", enderMap = 1418, enderX = 44.6, enderY = 12.1, enderInside = "Uldaman", objective = "Speak with stone watcher and learn what ancient lore it keeps.  Once you have learned what lore it has to offer, activate the Discs of Norgannon.", summary = "The centerpieces of this treasure chamber are four huge platinum discs, each adorned with numerous sigils of an unknown origin.  Touching them makes your hand tingle.  Just after touching the discs, the visage of a large stone watcher springs forth.$B$B\"Salutations.  I am a keeper of knowledge.  The Creators' synthesis of the Earthen has been chronicled and stored here for this world in the Discs of Norgannon.\"$B$BYou have uncovered a wealth of previously undiscovered worldly lore!" },
            { ids = { 2280 }, name = "The Platinum Discs", level = 47, zone = "Uldaman", giver = "The Discs of Norgannon", giverMap = 1418, giverX = 44.6, giverY = 12.1, giverInside = "Uldaman", ender = "Sage Truthseeker", enderMap = 1456, enderX = 34.4, enderY = 46.9, objective = "Take the miniature version of the Discs of Norgannon to the one of the sages in Thunder Bluff.", summary = "Touching the Discs of Norgannon once again makes your hand tingle.  This time, however, a strange grinding noise is heard from inside the discs.$B$BYour backpack suddenly becomes heavier than it was before.  Inside, you discover a miniature version of the discs!$B$BNo doubt, an item of this sort would be invaluable for someone interested in the ancient history of Azeroth.  The sages of Thunder Bluff are such historians, known throughout the Horde; perhaps they can make good use of it." },
            { ids = { 2440 }, name = "The Platinum Discs", level = 47, zone = "Thunder Bluff", giver = "Sage Truthseeker", giverMap = 1456, giverX = 34.4, giverY = 46.9, ender = "Bena Winterhoof", enderMap = 1456, enderX = 46.6, enderY = 33.2, objective = "Take the reward voucher to Bena Winterhoof in Thunder Bluff.", summary = "I shall focus my energies on these discs; they will reveal their true workings to me in due time.$B$BAs for you $N, I will now reward you for your diligence in bringing this to my attention.  Take this voucher to Bena Winterhoof, the alchemy trainer for Thunder Bluff.  She will give you a special item I believe you will find appealing, and she will supply you with a choice of potions from my personal stock.$B$BReturn to me soon, as I sense there is much more at hand for us to do regarding this find." },
            { ids = { 2965 }, name = "Portents of Uldum", level = 50, zone = "Thunder Bluff", giver = "Sage Truthseeker", giverMap = 1456, giverX = 34.4, giverY = 46.9, ender = "Nara Wildmane", enderMap = 1456, enderX = 75.7, enderY = 31.6, objective = "Speak with Nara Wildmane on the Elder Rise in Thunder Bluff.", summary = "Ah, $n, it is fortuitous that you have come to me again.  Your revelations at the Uldaman dig site have certainly given us sages much discuss.  I was doing just that with one of the druids, Nara Wildmane, when it dawned on me that her past adventuring experiences may have some great importance as to the next step we need to take.$B$BI would like for you to speak with her concerning her travels to the Valley of the Watchers in the Tanaris desert.  She waits for you on the Elder Rise." },
            { ids = { 2966 }, name = "Seeing What Happens", level = 50, zone = "Thunder Bluff", giver = "Nara Wildmane", giverMap = 1456, giverX = 75.7, giverY = 31.6, ender = "Uldum Pedestal", enderMap = 1446, enderX = 37.6, enderY = 81.4, objective = "Bring the miniature platinum discs to the gates of Uldum in Tanaris and look for clues as to the connection between the two.", summary = "Sage Truthseeker and I would like you to take the miniature discs you found to the sealed gates of Uldum.  We... we aren't sure what will happen when you do this.$B$BThis sounds risky, sure, we acknowledge that.  It might, however, do nothing.  You might need to use the discs on something.  Perhaps the doors unlock when you have the discs in your possession.  Be open to try anything, and be ready for anything to happen.$B$BLearn what you can, then return to me. We will have much to discuss." },
            { ids = { 2954 }, name = "The Stone Watcher", level = 50, zone = "Tanaris", giver = "Stone Watcher of Norgannon", giverMap = 1446, giverX = 37.6, giverY = 81.4, ender = "Uldum Pedestal", enderMap = 1446, enderX = 37.6, enderY = 81.4, objective = "Learn the purpose of the Stone Watcher of Norgannon, and then interact with the Uldum Pedestal in the Tanaris desert.", summary = "\"Salutations - I am a guardian of entry.  Unless you have the Plates of Uldum already integrated with your disc set, I will not allow for entry into the Uldum compound.\"$B$BThe appearance of the Stone Watcher of Norgannon must be the reaction that was hoped for in sending you out to the Tanaris desert with the platinum discs.  As instructed, you will need to find out what the story behind the Stone Watcher is before continuing on." },
            { ids = { 2967 }, name = "Return to Thunder Bluff", level = 50, zone = "Tanaris", giver = "Uldum Pedestal", giverMap = 1446, giverX = 37.6, giverY = 81.4, ender = "Nara Wildmane", enderMap = 1456, enderX = 75.7, enderY = 31.6, objective = "Speak with Nara Wildmane in Thunder Bluff.", summary = "You access the pedestal again; the platinum discs suddenly appear once more in your backpack.$B$BWith the knowledge of the stone watcher learned and the discs returned to your possession, the time has come to return to Thunder Bluff and inform the Nara Wildmane of your discovery." },
            { ids = { 2968 }, name = "A Future Task", level = 50, zone = "Thunder Bluff", giver = "Nara Wildmane", giverMap = 1456, giverX = 75.7, giverY = 31.6, ender = "Sage Truthseeker", enderMap = 1456, enderX = 34.4, enderY = 46.9, objective = "Speak with Sage Truthseeker in Thunder Bluff.", summary = "Well $n... we seem to be at an unfortunate impasse.  We know what we need - the Plates of Uldum - but we have no idea where they might be.  We will research this, and then devise a solid plan of attack.  I have a couple ideas where to start looking; I have high hopes that soon, we'll be asking you to rejoin our efforts to discover the truth.$B$BSage Truthseeker needs to be informed on this, $n; no doubt, he also wants to thank you personally for once again heeding the call." },
        },
    },
    {
        id = "q3520",
        name = "The Prophecy of Mosh'aru",
        zone = "Tanaris",
        minLevel = 40,
        maxLevel = 58,
        importance = 3,
        kind = "raid",
        quests = {
            { ids = { 3520 }, name = "Screecher Spirits", level = 44, zone = "Tanaris", giver = "Yeh'kinya", giverMap = 1446, giverX = 67.0, giverY = 22.4, ender = "Yeh'kinya", enderMap = 1446, enderX = 67.0, enderY = 22.4, objective = "Capture the spirits of 3 screechers in Feralas, then return to Yeh'kinya in Steamwheedle Port.", summary = "I seek the spirits of the vale screechers of Feralas.  They are the cousins of an old, old god, and their spirits are linked to him.$B$BTake this bramble wand and go to Feralas.  Find and defeat vale screechers in southern and central Feralas, then wave my bramble over their fallen bodies.  This will coax their spirit to reveal itself.  Touch the spirit and collect its essence.$B$BReturn to me with my bramble and with the collected essence, and I will tell you more of the old god of which I spoke." },
            { ids = { 3527 }, name = "The Prophecy of Mosh'aru", level = 47, zone = "Tanaris", giver = "Yeh'kinya", giverMap = 1446, giverX = 67.0, giverY = 22.4, ender = "Yeh'kinya", enderMap = 1446, enderX = 67.0, enderY = 22.4, objective = "Bring the First and Second Mosh'aru Tablets to Yeh'kinya in Tanaris.", summary = "The ancient prophecy of Mosh'aru speaks of a way to contain the god Hakkar's essence.  It was written on two tablets and taken to the troll city of Zul'Farrak, west of Gadgetzan.$B$BBring me the Mosh'aru tablets!$B$BThe first tablet is held by the long-dead troll Theka the Martyr.  It is said his persecutors were cursed into scarabs and now scuttle about his shrine.$B$BThe second tablet is held by the hydromancer Velratha, near the sacred pool of Gahz'rilla.$B$BWhen you have the tablets, bring them to me." },
            { ids = { 4787 }, name = "The Ancient Egg", level = 50, zone = "Tanaris", giver = "Yeh'kinya", giverMap = 1446, giverX = 67.0, giverY = 22.4, ender = "Yeh'kinya", enderMap = 1446, enderX = 67.0, enderY = 22.4, objective = "Bring the Ancient Egg to Yeh'kinya in Tanaris.", summary = "The Prophecy of Mosh'aru speaks of an ancient egg.  It is a relic of a time when trolls ruled vast empires, and it has the power to hold the essence of Hakkar.  It may be the only way to keep our world safe from his evil.$B$BBring me the ancient egg, $N.  It is said to lay hidden deep within Jintha'Alor in the Hinterlands, in a cave behind the amphitheater at the top of the city." },
            { ids = { 3528 }, name = "The God Hakkar", level = 53, zone = "Tanaris", giver = "Yeh'kinya", giverMap = 1446, giverX = 67.0, giverY = 22.4, ender = "Yeh'kinya", enderMap = 1446, enderX = 67.0, enderY = 22.4, objective = "Bring the Filled Egg of Hakkar to Yeh'kinya in Tanaris.", summary = "Now it is time to capture the essence of the avatar of Hakkar.$B$BTake the Egg of Hakkar to the Sanctum of the Fallen God in the Sunken Temple in Azeroth.  Invoke the egg's power to stir the dead god.$B$BHe will send his minions against you.  Defeat his bloodrinkers and take their Hakkari blood, then use the blood to dowse the eternal flames that hold Hakkar's spirit.  When all the flames go out, the avatar of Hakkar will enter our world.$B$BDefeat him, and place his essence within the egg of Hakkar." },
            { ids = { 5065 }, name = "The Lost Tablets of Mosh'aru", level = 58, zone = "Tanaris", giver = "Prospector Ironboot", giverMap = 1446, giverX = 66.9, giverY = 24.0, ender = "Prospector Ironboot", enderMap = 1446, enderX = 66.9, enderY = 24.0, objective = "Bring the Third and Fourth Mosh'aru Tablets to Prospector Ironboot in Tanaris.", summary = "The troll with whom you spoke did not tell the truth.  The two tablets you gained for him spoke of containing the essence of Hakkar, but there is more to that legend.  I have studied long, and found that there are six Tablets of Mosh'aru, not two!  Six!$B$BAnd I fear that we will not like what secrets the others hold..$B$BFind the third and fourth tablets of Mosh'aru.  They're in the Eastern Plaguelands, held by the mossflayer trolls. Find them, and bring them to me." },
            { ids = { 4788 }, name = "The Final Tablets", level = 58, zone = "Tanaris", giver = "Prospector Ironboot", giverMap = 1446, giverX = 66.9, giverY = 24.0, ender = "Prospector Ironboot", enderMap = 1446, enderX = 66.9, enderY = 24.0, objective = "Bring the Fifth and Sixth Mosh'aru Tablets to Prospector Ironboot in Tanaris.", summary = "While I look over the third and fourth tablets of Mosh'aru, you must find the fifth and sixth!  It will not be easy, for they are held by the Smolderthorn trolls within Blackrock Spire.  The spire is a dark mountain of fire between the Burning Steppes and the Searing Gorge.$B$BGood luck, $N.  Blackrock Spire is no place for decent folk..." },
            { ids = { 8181 }, name = "Confront Yeh'kinya", level = 58, zone = "Tanaris", giver = "Prospector Ironboot", giverMap = 1446, giverX = 66.9, giverY = 24.0, ender = "Yeh'kinya", enderMap = 1446, enderX = 67.0, enderY = 22.4, objective = "Speak with Yeh'kinya.", summary = "My delvings into the Mosh'aru Tablets bear grim news, $N.  Hakkar's true form, the god himself, can be born again through the very egg into which you captured him.  Yeh'kinya told you it was to contain his evil, but it is to recreate it!  The troll has led you astray!$B$BGo to Yeh'kinya and demand the egg from him.  Pray that it is not too late to stop Hakkar's return!" },
            { ids = { 8182 }, name = "The Hand of Rastakhan", level = 58, zone = "Tanaris", giver = "Prospector Ironboot", giverMap = 1446, giverX = 66.9, giverY = 24.0, ender = "Molthor", enderMap = 1434, enderX = 15.0, enderY = 15.1, objective = "Speak with Molthor in Stranglethorn.", summary = "$N, our worst fears have come.  Legend speaks of the Soulflayer ruling the ancient troll world through evil and terror, and his power was absolute.  If he cannot be stopped now, then his new reign may spread across all of Azeroth!$B$BThere is a contingent of Zandalarian trolls who may help us stem this tide of darkness.  They have camped on Yojamba Isle, off the coast of Stranglethorn, west of the ruins of Zul'Kunda.  Speak with their leader, Molthor, and pray he knows how to defeat Hakkar." },
        },
    },
    {
        id = "q3441",
        name = "A Taste of Flame",
        zone = "Searing Gorge",
        minLevel = 40,
        maxLevel = 58,
        importance = 3,
        kind = "dungeon",
        quests = {
            { ids = { 3441 }, name = "Divine Retribution", level = 48, zone = "Searing Gorge", giver = "Kalaran Windblade", giverMap = 1427, giverX = 39.1, giverY = 39.0, ender = "Kalaran Windblade", enderMap = 1427, enderX = 39.1, enderY = 39.0, objective = "Listen as Kalaran Windblade tells his story.", summary = "Hear my tale, adventurer." },
            { ids = { 3442 }, name = "The Flawless Flame", level = 48, zone = "Searing Gorge", giver = "Kalaran Windblade", giverMap = 1427, giverX = 39.1, giverY = 39.0, ender = "Kalaran Windblade", enderMap = 1427, enderX = 39.1, enderY = 39.0, objective = "Collect 4 Hearts of Flame and 4 globes of Golem Oil and return the items to Kalaran Windblade.", summary = "You have made the right decision, $N.$B$BWe must strike where we will do the most damage: the four sentry towers.$B$BWith the four towers in flames, we can initiate an offensive before they have time to react.$B$BYou will need the proper tool to set the towers ablaze. To make the tool requires some materials.$B$BBring me four hearts of flame and four golem oil and I shall craft the torch of flawless flame.$B$BThe golems and elementals in these lands should be your first target." },
            { ids = { 3443 }, name = "Forging the Shaft", level = 48, zone = "Searing Gorge", giver = "Kalaran Windblade", giverMap = 1427, giverX = 39.1, giverY = 39.0, ender = "Kalaran Windblade", enderMap = 1427, enderX = 39.1, enderY = 39.0, objective = "Bring 8 Thorium Plated Daggers to Kalaran Windblade.", summary = "To hold the flawless flame, we will need a shaft and a casing. You must first find a suitable shaft.$B$BThe Dark Iron taskmasters and slavers of the cauldron use weapons of enchanted thorium, an extremely sturdy alloy. If you bring me eight thorium plated daggers, I can break the alloy down and reforge a shaft." },
            { ids = { 3452 }, name = "The Flame's Casing", level = 50, zone = "Searing Gorge", giver = "Kalaran Windblade", giverMap = 1427, giverX = 39.1, giverY = 39.0, ender = "Kalaran Windblade", enderMap = 1427, enderX = 39.1, enderY = 39.0, objective = "Find and return a Symbol of Ragnaros to Kalaran Windblade.", summary = "We need one final piece to form the torch.$B$BIn the mountains to the northwest you will find a large encampment of Twilight's Hammer. It is rumored that they carry symbols and idols that pay homage to their god. These symbols and idols could carry sufficient enchantment to form a magical casing. Bring me a single symbol of Ragnaros and I will try to extract the magic from the item to create the casing." },
            { ids = { 3453 }, name = "The Torch of Retribution", level = 50, zone = "Searing Gorge", giver = "Kalaran Windblade", giverMap = 1427, giverX = 39.1, giverY = 39.0, ender = "Kalaran Windblade", enderMap = 1427, enderX = 39.1, enderY = 39.0, objective = "Wait for Kalaran Windblade to complete the Torch of Retribution.", summary = "Give me a moment to combine the pieces and apply the necessary enchantments." },
            { ids = { 3454 }, name = "The Torch of Retribution", level = 50, zone = "Searing Gorge", giver = "Kalaran Windblade", giverMap = 1427, giverX = 39.1, giverY = 39.0, ender = "Torch of Retribution", enderMap = 1427, enderX = 39.1, enderY = 39.1, objective = "Take the Torch of Retribution.", summary = "The torch must now be bound to its owner. Pick up the torch, $N. " },
            { ids = { 3462 }, name = "Squire Maltrake", level = 50, zone = "Searing Gorge", giver = "Kalaran Windblade", giverMap = 1427, giverX = 39.1, giverY = 39.0, ender = "Squire Maltrake", enderMap = 1427, enderX = 39.2, enderY = 39, objective = "Speak with Squire Maltrake.", summary = "Speak with my envoy, Squire Maltrake. He will further instruct you as to the use of the Torch of Retribution." },
            { ids = { 3463 }, name = "Set Them Ablaze!", level = 52, zone = "Searing Gorge", giver = "Squire Maltrake", giverMap = 1427, giverX = 39.2, giverY = 39, ender = "Squire Maltrake", enderMap = 1427, enderX = 39.2, enderY = 39, objective = "Set the North, South, East, and West Sentry Towers on fire by using the Torch of Retribution inside each of the buildings. ", summary = "Listen well, $N. While the four towers can never be destroyed, you can use the torch of retribution to set them ablaze for a very long period of time: A fire that no element or force can subdue.$B$BWhile they are ablaze, no guard or sentry unit can inhabit the watch posts and thus, their first line of defense is nullified.$B$BYou must enter each tower and use the Torch of Retribution within their fortifications. Beware the elite sentry units of the Dark Irons, $N." },
            { ids = { 3481 }, name = "Trinkets...", level = 50, zone = "Searing Gorge", giver = "Hoard of the Black Dragonflight", giverMap = 1427, giverX = 38.9, giverY = 39.0, ender = "Hoard of the Black Dragonflight", enderMap = 1427, enderX = 38.9, enderY = 39.0, objective = "Open the chest.", summary = "The chest appears locked." },
            { ids = { 4022 }, name = "A Taste of Flame", level = 54, zone = "Burning Steppes", giver = "Cyrus Therepentous", giverMap = 1428, giverX = 95.1, giverY = 31.6, ender = "Cyrus Therepentous", enderMap = 1428, enderX = 95.1, enderY = 31.6, objective = "Show Cyrus Therepentous the Black Dragonflight Molt you received from Kalaran Windblade.", summary = "The flight is aware of your work in the Searing Gorge.$B$BShow it to me, $r. The molt, imbecile." },
            { ids = { 4024 }, name = "A Taste of Flame", level = 58, zone = "Burning Steppes", giver = "Cyrus Therepentous", giverMap = 1428, giverX = 95.1, giverY = 31.6, ender = "Cyrus Therepentous", enderMap = 1428, enderX = 95.1, enderY = 31.6, objective = "Travel to Blackrock Depths and slay Bael'Gar.$B$BYou only know that the giant resides inside Blackrock Depths. Remember to use the Altered Black Dragonflight Molt on Bael'Gar's remains to capture the Fiery Essence.$B$BReturn the Encased Fiery Essence to Cyrus Therepentous.", summary = "I wish to taste the searing flames of the mountain of fire. To let the molten fires of Blackrock cascade across my being. That essence, that searing heat, it is what I crave.$B$BBael'Gar resides in the Depths of Blackrock: A being of pure flame, born of the fires of Ragnaros. Slay Bael'Gar and from his smoldering remains bring for me a piece of his inner fire.$B$BUse the molt on his remains to safely extract the inner flame.$B$BSucceed and be rewarded." },
        },
    },
    {
        id = "q2933",
        name = "The Spider God",
        zone = "The Hinterlands",
        minLevel = 40,
        maxLevel = 55,
        importance = 2,
        kind = "dungeon",
        quests = {
            { ids = { 2933 }, name = "Venom Bottles", level = 43, zone = "The Hinterlands", giver = "Venom Bottle", giverMap = 1425, giverX = 23.5, giverY = 58.8, ender = "Apothecary Lydon", enderMap = 1424, enderX = 61.4, enderY = 19.1, objective = "Bring a Venom Bottle to an apothecary in Tarren Mill.", summary = "These bottles hold a vile, green venom.$B$BConsidering the number of bottles in this village, the Witherbarks must deem it very important.  Perhaps an apothecary in nearby Tarren Mill would like a sample." },
            { ids = { 2934 }, name = "Undamaged Venom Sac", level = 45, zone = "Hillsbrad Foothills", giver = "Apothecary Lydon", giverMap = 1424, giverX = 61.4, giverY = 19.1, ender = "Apothecary Lydon", enderMap = 1424, enderX = 61.4, enderY = 19.1, objective = "Bring an Undamaged Venom Sac to Apothecary Lydon in Tarren Mill.", summary = "I must have a fresh sample of the venom you brought me.  The spiders from which it was gathered must dwell in the Hinterlands -- hunt them until you find an undamaged venom sac and bring it to me.  You will find many spiders near the troll city of Shadra'Alor.$B$BDo not tarry, $N, for the venom sac must be fresh when you deliver it." },
            { ids = { 2935 }, name = "Consult Master Gadrin", level = 45, zone = "Hillsbrad Foothills", giver = "Apothecary Lydon", giverMap = 1424, giverX = 61.4, giverY = 19.1, ender = "Master Gadrin", enderMap = 1411, enderX = 56.0, enderY = 74.7, objective = "Speak with Master Gadrin in Sen'jin Village.", summary = "The venom from the broodguards wasn't as potent as the venom you brought originally.  It must have come from a different spider.$B$BI want a fresh sample of that venom.  To find out where it came from, you must consult with a troll who knows the Witherbark well--Master Gadrin in Sen'jin Village.  Travel to Durotar and speak with Gadrin.  With luck, he'll know where the Witherbarks get their venom." },
            { ids = { 2936 }, name = "The Spider God", level = 45, zone = "Durotar", giver = "Master Gadrin", giverMap = 1411, giverX = 56.0, giverY = 74.7, ender = "Master Gadrin", enderMap = 1411, enderX = 56.0, enderY = 74.7, objective = "Read from the Tablet of Theka to learn the name of the Witherbark spider god, then return to Master Gadrin.", summary = "The Witherbarks worship a spider god, and from her they collect their most potent venom.  So if you want the venom, then you must summon their god!$B$BTo do that, you must know her true name, and that name is on a tablet buried in Tanaris, in the troll city of Zul'Farrak, in a tomb guarded by Theka the Martyr.$B$BDefeat Theka and find and read his tablet to discover the spider god's name.  When you know it, return to me." },
            { ids = { 2937 }, name = "Summoning Shadra", level = 55, zone = "Durotar", giver = "Master Gadrin", giverMap = 1411, giverX = 56.0, giverY = 74.7, ender = "Apothecary Lydon", enderMap = 1424, enderX = 61.4, enderY = 19.1, objective = "Defeat Shadra at the altar of Shadra'Alor, then bring her venom to Apothecary Lydon in Tarren Mill.", summary = "Take his parchment, and read it at the altar of Shadra'Alor, deep within the witherbark realm in the Hinterlands.  This will summon Shadra the spider god." },
            { ids = { 2938 }, name = "Venom to the Undercity", level = 55, zone = "Hillsbrad Foothills", giver = "Apothecary Lydon", giverMap = 1424, giverX = 61.4, giverY = 19.1, ender = "Master Apothecary Faranell", enderMap = 1458, enderX = 48.8, enderY = 69.3, objective = "Bring Faranell's Parcel to Master Apothecary Faranell in the Undercity.", summary = "The venom you gathered from the Witherbark's spider god is quite a find!  I've been able to kill nearly two dozen rabbits with just a drop of the stuff.  Granted, some of those rabbits were very young and small enough to fit in the palm of one's hand so I'm certain their resistance to toxins was low, but it can't be denied that this poison is powerful!$B$BI'd like a sample sent to my superior, Apothecary Faranell in the Apothecarium of the Undercity.  I am positive he would want to test this himself." },
        },
    },
    {
        id = "q3121",
        name = "A Strange Request",
        zone = "Feralas",
        minLevel = 40,
        maxLevel = 50,
        importance = 1,
        kind = "world",
        quests = {
            { ids = { 3121 }, name = "A Strange Request", level = 45, zone = "Feralas", giver = "Witch Doctor Uzer'i", giverMap = 1444, giverX = 74.4, giverY = 43.4, ender = "Neeru Fireblade", enderMap = 1454, enderX = 49.5, enderY = 50.6, objective = "Take the Shrunken Head to Neeru Fireblade in Orgrimmar.", summary = "Neeru Fireblade in Orgrimmar has what I need to get started here! He has mixed up a concoction that I need for my... well, you'll see.$B$BOff with you now -- to Orgrimmar. Here, take this with you. It's a shrunken head that I promised Neeru in exchange for the herbs. It's the head of some poor dwarf I ventured across in the forest. I'm sure Neeru will be pleased.$B$BYou'll find Neeru in the Cleft of Shadow." },
            { ids = { 3122 }, name = "Return to Witch Doctor Uzer'i", level = 45, zone = "Orgrimmar", giver = "Neeru Fireblade", giverMap = 1454, giverX = 49.5, giverY = 50.6, ender = "Witch Doctor Uzer'i", enderMap = 1444, enderX = 74.4, enderY = 43.4, objective = "Deliver Neeru's Herb Pouch to Witch Doctor Uzer'i in Feralas.", summary = "Here are the herbs, $N. Take them to Witch Doctor Uzer'i.$B$BPlease let him know that I am satisfied with the shrunken head." },
            { ids = { 3123 }, name = "Testing the Vessel", level = 47, zone = "Feralas", giver = "Witch Doctor Uzer'i", giverMap = 1444, giverX = 74.4, giverY = 43.4, ender = "Witch Doctor Uzer'i", enderMap = 1444, enderX = 74.4, enderY = 43.4, objective = "Travel to the Hinterlands, and locate the Wildkin. Kill 10, and use the Muisek Vessel to shrink and capture the fallen Wildkin.$B$BBring 10 Wildkin Muiseks and the Muisek Vessel to Witch Doctor Uzer'i in Feralas.", summary = "This will be a test; both of the ritual I performed, and of your abilities. Take this vessel, $N. With it, you will have the power to shrink and capture a creature inside of it.$B$BTravel to the Hinterlands and look for creatures known as Wildkin that were once pets of the night elf goddess Elune. The vicious, primitive, or savage owlbeasts are your targets, $N. Kill 10, and use the muisek vessel to shrink and capture them before their spirits can escape." },
            { ids = { 3128 }, name = "Natural Materials", level = 50, zone = "Feralas", giver = "Witch Doctor Uzer'i", giverMap = 1444, giverX = 74.4, giverY = 43.4, ender = "Witch Doctor Uzer'i", enderMap = 1444, enderX = 74.4, enderY = 43.4, objective = "Bring 2 Splintered Logs, 6 Encrusted Minerals, 20 pieces of Resilient Sinew, and 40 Metallic Fragments to Witch Doctor Uzer'i in Camp Mojache.", summary = "I will need certain materials to complete my endeavor... You may do this alongside the other tasks I will give you.$B$BI'll need a splintered log from a treant of Feralas. Encrusted minerals, these can be found on the mountain giants and faerie dragons to the west. Also, find me some resilient sinew from the owlbeasts of the Hinterlands or hippogryphs of Feralas. Finally, I'll need a large amount of metallic fragments from any of these creatures I mentioned." },
            { ids = { 3124 }, name = "Hippogryph Muisek", level = 47, zone = "Feralas", giver = "Witch Doctor Uzer'i", giverMap = 1444, giverX = 74.4, giverY = 43.4, ender = "Witch Doctor Uzer'i", enderMap = 1444, enderX = 74.4, enderY = 43.4, objective = "Kill 10 Frayfeather Hippogryphs of any type, then use the Muisek Vessel to shrink and capture them.", summary = "Since you have proven that you are both trustworthy and gifted with the ability to use the muisek vessel, I now wish you to capture another creature.$B$BHippogryphs have been loyal companions to the night elves for many years; their spirits are loyal and steadfast.$B$BYour task is to kill 10 frayfeather hippogryphs, and quickly, shrink and capture them with the vessel, so that their muisek may be preserved. You will find the hippogryphs in the High Wilderness, to the south of here. " },
            { ids = { 3125 }, name = "Faerie Dragon Muisek", level = 45, zone = "Feralas", giver = "Witch Doctor Uzer'i", giverMap = 1444, giverX = 74.4, giverY = 43.4, ender = "Witch Doctor Uzer'i", enderMap = 1444, enderX = 74.4, enderY = 43.4, objective = "Kill 8 Sprite Darters or Sprite Dragons. Use the Muisek Vessel to shrink and capture the fallen Faerie Dragons.", summary = "$N, next I must have you capture a creature that in appearance, may look quite fragile, yet its powerful spirit is what we are truly after. The faerie dragons that I speak of have served the night elves as their allies. We must capture one so that the horde may benefit from this strength of spirit as well.$B$BHere is the muisek, $N. Kill 8 sprite darters or sprite dragons, and capture their muisek. They may be found to the west of here." },
            { ids = { 3126 }, name = "Treant Muisek", level = 50, zone = "Feralas", giver = "Witch Doctor Uzer'i", giverMap = 1444, giverX = 74.4, giverY = 43.4, ender = "Witch Doctor Uzer'i", enderMap = 1444, enderX = 74.4, enderY = 43.4, objective = "Kill 3 Wandering Forest Walkers. Use the Muisek Vessel to shrink and capture the fallen Treants.", summary = "The wandering forest walkers that can be found meandering through the forest are our next target, $N. Night elves have enlisted treants as allies to fight against the horde. Their movement may be slow, but their role as protectors is undeniable.$B$BSoon we will be able to use this power for our own benefit.$B$BFind 3 wandering forest walkers; kill them, and use the muisek vessel to shrink and capture them." },
            { ids = { 3127 }, name = "Mountain Giant Muisek", level = 50, zone = "Feralas", giver = "Witch Doctor Uzer'i", giverMap = 1444, giverX = 74.4, giverY = 43.4, ender = "Witch Doctor Uzer'i", enderMap = 1444, enderX = 74.4, enderY = 43.4, objective = "Kill 7 Land Walkers or Cliff Giants. Use the Muisek Vessel to shrink and capture the fallen Mountain Giants.", summary = "The last task I will require of you is to travel to the northwest and find the final enemy.$B$BThe mountain giants left the mountains to aid the night elves when the burning legion appeared in the world. You will know them by their massive size and the way the ground begins to shake as you travel along their rocky terrain.$B$BI am eager to harness power of that size. Kill 7 mountain giants, then use the muisek vessel to capture their powerful muisek." },
            { ids = { 3129 }, name = "Weapons of Spirit", level = 50, zone = "Feralas", giver = "Witch Doctor Uzer'i", giverMap = 1444, giverX = 74.4, giverY = 43.4, ender = "Witch Doctor Uzer'i", enderMap = 1444, enderX = 74.4, enderY = 43.4, objective = "Witch Doctor Uzer'i wants you to wait for a moment while he prepares the weapons.", summary = "Imbuing the muisek into the weapons is a difficult process. Now that I have all of the required materials and the muisek of the creatures that you captured, I may begin. Please wait; I will return in a moment." },
        },
    },
    {
        id = "q7044",
        name = "Legends of Maraudon",
        zone = "Desolace",
        minLevel = 41,
        maxLevel = 49,
        importance = 1,
        kind = "dungeon",
        quests = {
            { ids = { 7044 }, name = "Legends of Maraudon", level = 49, zone = "Desolace", giver = "Cavindra", giverMap = 1443, giverX = 31.9, giverY = 63.8, ender = "Celebras the Redeemed", enderMap = 1443, enderX = 29.1, enderY = 62.5, enderInside = "Maraudon", objective = "Recover the two parts of the Scepter of Celebras: the Celebrian Rod and the Celebrian Diamond.$B$BFind a way to speak with Celebras.", summary = "A dark satyr called Lord Vyletongue spread his evil through these twisting caves, poisoning the minds of all inside. He still resides beyond the purple crystals.$B$BVyletongue also created a living symbol of his corruption called Noxxion that dwells beyond the orange crystals. Together, they have stolen the two parts of my brother's scepter. Celebras, my brother... he wanders blindly inside, cursed by corruption.$B$BYou must help him! Find the pieces, and speak to my brother... somehow." },
            { ids = { 7046 }, name = "The Scepter of Celebras", level = 49, zone = "Maraudon", giver = "Celebras the Redeemed", giverMap = 1443, giverX = 29.1, giverY = 62.5, giverInside = "Maraudon", ender = "Celebras the Redeemed", enderMap = 1443, enderX = 29.1, enderY = 62.5, enderInside = "Maraudon", objective = "Assist Celebras the Redeemed while he creates the Scepter of Celebras.$B$BSpeak with him when the ritual is complete.", summary = "My scepter was once a source of hope for me. Its power allowed me the freedom to travel quickly through these caverns. I had hoped to bring peace to the spirit of my uncle... It is a task that I now pass to you.$B$BFor the two parts to once again become one, I will need your assistance in performing the ritual. Please follow me, and listen to my instructions while I channel the energy required to reunite the rod with the diamond.$B$BTogether, we shall create the Scepter of Celebras once again!" },
        },
    },
    {
        id = "q2784",
        name = "The Demon Hunter",
        zone = "Swamp of Sorrows",
        minLevel = 45,
        maxLevel = 60,
        importance = 3,
        kind = "world",
        quests = {
            { ids = { 2784 }, name = "Fall From Grace", level = 50, zone = "Swamp of Sorrows", giver = "Fallen Hero of the Horde", giverMap = 1435, giverX = 34.3, giverY = 66.1, ender = "Fallen Hero of the Horde", enderMap = 1435, enderX = 34.3, enderY = 66.1, objective = "Listen to the Fallen Hero of the Horde tell his story.", summary = "Hear my story, $r." },
            { ids = { 2621 }, name = "The Disgraced One", level = 50, zone = "Swamp of Sorrows", giver = "Fallen Hero of the Horde", giverMap = 1435, giverX = 34.3, giverY = 66.1, ender = "Dispatch Commander Ruag", enderMap = 1435, enderX = 47.8, enderY = 54.9, objective = "Speak to Dispatch Commander Ruag in Stonard.", summary = "Regret. It is all I have now. One bad decision resulting in several horrible outcomes. If only I had waited for those orders. Maybe they would have detailed the horrors that awaited us in those cursed lands! Maybe they were to redirect us to another detail? Ultimately, it was my fault. All of it was my fault.$B$BSo here I stand, awaiting orders. I must know. I must have those orders.$B$BDispatch Commander Ruag resides in Stonard. Find him and find out what became of the orders." },
            { ids = { 2622 }, name = "The Missing Orders", level = 50, zone = "Swamp of Sorrows", giver = "Dispatch Commander Ruag", giverMap = 1435, giverX = 47.8, giverY = 54.9, ender = "Bengor", enderMap = 1435, enderX = 45.0, enderY = 57.4, objective = "Speak to Bengor.", summary = "The orders? What could you possibly want with the orders?$B$BWhat are you implying, $N? Of course I relayed those orders! The soldiers I sent the orders with were ambushed and brutally beaten by murlocs. Only one survived, if you can call that surviving. He can hardly speak, cannot walk, and must be fed through a tube. If you want to know what happened to those orders, speak with Bengor. I'm sure he is around here somewhere... and, $N, be mindful of what you stick your nose into - it may get bitten off." },
            { ids = { 2623 }, name = "The Swamp Talker", level = 55, zone = "Swamp of Sorrows", giver = "Bengor", giverMap = 1435, giverX = 45.0, giverY = 57.4, ender = "Fallen Hero of the Horde", enderMap = 1435, enderX = 34.3, enderY = 66.1, objective = "Retrieve the Warchief's Orders and return them to the Fallen Hero of the Horde.", summary = "Orders were given by the dispatch commander. We took... took orders. On way to Blasted Lands, ambushed.$B$BMurlocs... Many murlocs... One named Swamp Talker. Took orders from my hands as spear thrust into my skull. East... cave....$B$B<Bengor passes out.>" },
            { ids = { 2801 }, name = "A Tale of Sorrow", level = 57, zone = "Swamp of Sorrows", giver = "Fallen Hero of the Horde", giverMap = 1435, giverX = 34.3, giverY = 66.1, ender = "Fallen Hero of the Horde", enderMap = 1435, enderX = 34.3, enderY = 66.1, objective = "Listen to the Fallen Hero of the Horde tell his story.", summary = "Before we may continue, you must hear my story." },
            { ids = { 2681 }, name = "The Stones That Bind Us", level = 57, zone = "Swamp of Sorrows", giver = "Fallen Hero of the Horde", giverMap = 1435, giverX = 34.3, giverY = 66.1, ender = "Fallen Hero of the Horde", enderMap = 1435, enderX = 34.3, enderY = 66.1, objective = "Free nine Servants of Razelikh, three Servants of Sevine, three Servants of Allistarj, and three Servants of Grol. Return to the Fallen Hero when your task is complete. You must remain within close proximity of the stones or the process will fail.", summary = "It will take more than you alone to overcome the forces of Razelikh and his subordinates.$B$BGather a suitable group of adventurers and free my men of their eternal torture! Eighteen stones you must shatter.$B$BFight hard and die with honor, $N." },
            { ids = { 2702 }, name = "Heroes of Old", level = 57, zone = "Swamp of Sorrows", giver = "Fallen Hero of the Horde", giverMap = 1435, giverX = 34.3, giverY = 66.1, ender = "Corporal Thund Splithoof", enderMap = 1435, enderX = 33.5, enderY = 66.0, objective = "Speak to Corporal Thund Splithoof.", summary = "You have honored me with your nobility and heroism, $N.$B$BYou have also honored them..." },
            { ids = { 2701 }, name = "Heroes of Old", level = 57, zone = "Swamp of Sorrows", giver = "Corporal Thund Splithoof", giverMap = 1435, giverX = 33.5, giverY = 66.0, ender = "Spectral Lockbox", enderMap = 1435, enderX = 33.3, enderY = 66.2, objective = "Open the chest and claim your reward.", summary = "Please, take from this a relic of old. We no longer have a use for the item.$B$BMay it serve you well in your fight against the legion." },
            { ids = { 2721 }, name = "Kirith", level = 58, zone = "Swamp of Sorrows", giver = "Fallen Hero of the Horde", giverMap = 1435, giverX = 34.3, giverY = 66.1, ender = "Spirit of Kirith", enderMap = 1419, enderX = 68.8, enderY = 31.1, objective = "Find out what became of Lieutenant Kirith.", summary = "As one chapter of your adventure closes, another one begins, $N.$B$BOne of my men is still unaccounted for, lost somewhere in the Blasted Lands. I am talking about Lieutenant Kirith, of course.$B$BAs I had mentioned earlier, we were both imprisoned and tortured by Allistarj, but poor Kirith, his strength of will faltered. I could hear the experiments from my cage; the tortured screams rang through the halls of the cave. That was the last I saw or heard of Kirith." },
            { ids = { 2743 }, name = "The Cover of Darkness", level = 60, zone = "Blasted Lands", giver = "Spirit of Kirith", giverMap = 1419, giverX = 68.8, giverY = 31.1, ender = "Fallen Hero of the Horde", enderMap = 1435, enderX = 34.3, enderY = 66.1, objective = "Return to the Fallen Hero of the Horde with your findings.", summary = "Let us not mince words, $r; my time here is limited.$B$BYou must destroy the triad of power which protects the demon lord, Razelikh. Doing so will not be as simple a task as freeing a damned soul.$B$B<Kirith grins.>$B$BYou see, each of Razelikh's underlings wears a third of an amulet of Razelikh's creation around their neck. The very same amulet you will need in order to summon the arch demon.$B$BReturn to Trebor and tell him what is required to summon Razelikh. He will be able to instruct you further." },
            { ids = { 2744 }, name = "The Demon Hunter", level = 60, zone = "Swamp of Sorrows", giver = "Fallen Hero of the Horde", giverMap = 1435, giverX = 34.3, giverY = 66.1, ender = "Loramus Thalipedes", enderMap = 1447, enderX = 60.8, enderY = 66.3, objective = "Speak with Loramus Thalipedes in Azshara.", summary = "The triad is protected by Razelikh.$B$BIn exchange for their servitude, Razelikh granted each of them nearly unlimited power within the Blasted Lands. The amulet pieces are each attuned to the lifeforce of their owner, granting them immortality. As long as they remain within the Blasted Lands, they cannot be slain, their life spans extended until the end of days.$B$BThere is one who may be able to assist you further, $N. Travel to Azshara and find the demon hunter, Loramus Thalipedes. Search the islands." },
            { ids = { 3141 }, name = "Loramus", level = 57, zone = "Azshara", giver = "Loramus Thalipedes", giverMap = 1447, giverX = 60.8, giverY = 66.3, ender = "Loramus Thalipedes", enderMap = 1447, enderX = 60.8, enderY = 66.3, objective = "Listen to Loramus Thalipedes tell his story.", summary = "So you wish to battle demons? You would do well to listen to my tale. " },
            { ids = { 3508 }, name = "Breaking the Ward", level = 58, zone = "Azshara", giver = "Loramus Thalipedes", giverMap = 1447, giverX = 60.8, giverY = 66.3, ender = "Loramus Thalipedes", enderMap = 1447, enderX = 60.8, enderY = 66.3, objective = "Wait for Loramus to complete the enlightenment spell.", summary = "You are foolhardy, $N. It is an admirable quality of your kind - to blindly enter battle when you have little to no chance of success. I will assist you, if only to see just one of Razelikh's minions fall.$B$BTo break the ward placed over Razelikh's subordinates will take time and require the acquisition of rare artifacts.$B$BBe still, I must first perform the enlightenment ritual. The information I gather will assist me in forging weapons of great power." },
            { ids = { 3509 }, name = "The Name of the Beast", level = 58, zone = "Azshara", giver = "Loramus Thalipedes", giverMap = 1447, giverX = 60.8, giverY = 66.3, ender = "Lord Arkkoroc", enderMap = 1447, enderX = 77.1, enderY = 42.8, objective = "Speak with Lord Arkkoroc in Azshara. Begin your search at the waters edge to find the Temple of Arkkoran.", summary = "There is only one way to harm the demon lord and his minions. A weapon of power must be forged bearing his true name.$B$BWhen such a weapon is forged, the demon and all under his command are vulnerable.$B$BA lesser deity resides in Azshara: Lord Arkkoroc. You must seek him out but be warned, his minions will stop at nothing to destroy you if you are discovered.$B$BUndoubtedly, you will have to pay a price for such information. " },
            { ids = { 3510 }, name = "The Name of the Beast", level = 58, zone = "Azshara", giver = "Lord Arkkoroc", giverMap = 1447, giverX = 77.1, giverY = 42.8, ender = "Lord Arkkoroc", enderMap = 1447, enderX = 77.1, enderY = 42.8, objective = "Slay Hetaera and bring back Hetaera's Bloodied Head, Hetaera's Beaten Head, and Hetaera's Bruised Head to Lord Arkkoroc.", summary = "She kills my children, mortal. She that calls herself the ruler of these oceans. A false god, nothing more. Crush her and bring back all of her heads.$B$BFor that, you will be given the name that you seek and something else of equal importance.$B$BShe roams the clutch... Hetaera she is called.$B$B<Lord Arkkoroc points to the southwest.>$B$BGo!" },
            { ids = { 3511 }, name = "The Name of the Beast", level = 58, zone = "Azshara", giver = "Lord Arkkoroc", giverMap = 1447, giverX = 77.1, giverY = 42.8, ender = "Loramus Thalipedes", enderMap = 1447, enderX = 60.8, enderY = 66.3, objective = "Take the temper back to Loramus Thalipedes.", summary = "As promised, I will reveal the name of the demon lord, Razelikh the Defiler. First, however, I must prepare something of utmost importance for your journey.$B$BThe weapon you seek to create requires a temper. Give me a moment to drain the blood from these heads.$B$B<Lord Arkkoroc squeezes the heads in between his gigantic fists, draining them of their blood.>$B$BTake the temper back to Loramus along with the name of the beast: Rakh'likh." },
            { ids = { 3602 }, name = "Azsharite", level = 58, zone = "Azshara", giver = "Loramus Thalipedes", giverMap = 1447, giverX = 60.8, giverY = 66.3, ender = "Loramus Thalipedes", enderMap = 1447, enderX = 60.8, enderY = 66.3, objective = "Recover twenty Crystallized Azsharite from southern Azshara. You may use the Felhound to assist you in 'sniffing' out the location of cleverly hidden deposits.$B$BReturn to Loramus when the task is complete.", summary = "The ancient cliff giants of the southern region of Azshara consume the rock and buildings of the land for sustenance. The excrement from their consumption is a highly malleable and extremely strong crystal known as Azsharite.$B$BThe formations litter the southern arc, but few are ever recovered due to the extremely violent nature of the giants.$B$BYou are to venture south and recover enough of the Azsharite for the creation of the weapon's body. My felhounds will aid in the recovery of the crystal." },
            { ids = { 3621 }, name = "The Formation of Felbane", level = 58, zone = "Azshara", giver = "Loramus Thalipedes", giverMap = 1447, giverX = 60.8, giverY = 66.3, ender = "Galvan the Ancient", enderMap = 1434, enderX = 50.6, enderY = 20.5, objective = "Take the Shipment to Galvan the Ancient in Stranglethorn Vale.", summary = "The weapons are ready to be forged. You must take the tempered azsharite to one with the ability to harness fel energy.$B$BIn Stranglethorn Vale such a blacksmith exists. Galvan the Ancient, leader of the Mithril Order, will craft the weapons to your specifications. You will find his encampment between Zul'Gurub and the Mosh'Ogg ogre mound.$B$BMay your determination and faith carry you through this ordeal. Should you fail, know that your God smiles down upon you, mortal." },
            { ids = { 3625 }, name = "Enchanted Azsharite Fel Weaponry", level = 58, zone = "Stranglethorn Vale", giver = "Galvan the Ancient", giverMap = 1434, giverX = 50.6, giverY = 20.5, ender = "Galvan the Ancient", enderMap = 1434, enderX = 50.6, enderY = 20.5, objective = "Wait for Galvan to finish forging the weaponry.", summary = "$N, the creation of each weapon will take some time.$B$BAdditionally, you may only use the power of the Felcurse once per three minutes. Its weakening properties against Razelikh the Defiler and his minions may be variable in duration. This is why you must release the Felcurse only when the moment is right!$B$BNow give me a moment to craft your weapon, $N." },
            { ids = { 3626 }, name = "Return to the Blasted Lands", level = 58, zone = "Stranglethorn Vale", giver = "Galvan the Ancient", giverMap = 1434, giverX = 50.6, giverY = 20.5, ender = "Fallen Hero of the Horde", enderMap = 1435, enderX = 34.3, enderY = 66.1, objective = "Return to the Fallen Hero of the Horde.", summary = "The hour of redemption is near, $N. You must return to the Blasted Lands with your new-found weaponry and speak with the Fallen Hero of the Horde to receive your final objective." },
            { ids = { 3627 }, name = "Uniting the Shattered Amulet", level = 60, zone = "Swamp of Sorrows", giver = "Fallen Hero of the Horde", giverMap = 1435, giverX = 34.3, giverY = 66.1, ender = "Fallen Hero of the Horde", enderMap = 1435, enderX = 34.3, enderY = 66.1, objective = "Slay Grol the Destroyer, Lady Sevine, and Archmage Allistarj. From their corpses take the Amulet of Grol, the Amulet of Sevine, and the Amulet of Allistarj.$B$BRemember to USE your Enchanted Azsharite Fel Weaponry to weaken the triad. They cannot be killed otherwise - but use them wisely...", summary = "To reach the Defiler, you must first destroy the triad of power and recover the amulet pieces. When you recover all three pieces, return to me and I shall give you further instruction.$B$BGo $N! To the Blasted Lands! Sevine, Allistarj, and Grol must fall!" },
            { ids = { 3628 }, name = "You Are Rakh'likh, Demon", level = 60, zone = "Swamp of Sorrows", giver = "Fallen Hero of the Horde", giverMap = 1435, giverX = 34.3, giverY = 66.1, ender = "Fallen Hero of the Horde", enderMap = 1435, enderX = 34.3, enderY = 66.1, objective = "Destroy Razelikh the Defiler and return the Severed Horn of the Defiler to the Fallen Hero of the Horde. You will also need to return the Ward of the Defiler so that the Fallen Hero can destroy it, preventing it from ever falling into the wrong hands.", summary = "Razelikh's lair is atop the highest mountain in the Blasted Lands. The only way to the lair is through the use of the teleport runes near the mountain. As long as you hold the amulet, you can freely transport up to the lair. Once you reach the lair, you must conjure the beast. The amulet is your key, $N. Use it on the Altar of the Defiler.$B$BShould you defeat the Defiler, bring back his horn. It will become a symbol of hope for all that view it - proof that heroes do exist in this war torn world." },
        },
    },
    {
        id = "q3518",
        name = "Magatha's Payment to Jediga",
        zone = "Azshara",
        minLevel = 45,
        maxLevel = 52,
        importance = 1,
        kind = "world",
        quests = {
            { ids = { 3517 }, name = "Stealing Knowledge", level = 52, zone = "Azshara", giver = "Jediga", giverMap = 1447, giverX = 22.6, giverY = 51.4, ender = "Jediga", enderMap = 1447, enderX = 22.6, enderY = 51.4, objective = "Find the Tablet of Beth'Amara, the Tablet of Jin'yael, the Tablet of Markri, and the Tablet of Sael'hai before returning to Jediga in Azshara.", summary = "I admit, $N, I've made the most of my situation in Azshara. Belgrom's punishment has had its share of benefits.$B$BBefore I left, I did some research and you would be surprised how many valuable items are lying around.$B$BI'll tell you more about my deals, and even give you a cut of the profits, if you help me gather some of them.$B$BThere are tablets throughout the Ruins of Eldarath to the east that I need. All four are named after Highborne wizards. Get them for me and we'll talk some more." },
            { ids = { 3518 }, name = "Delivery to Magatha", level = 52, zone = "Azshara", giver = "Jediga", giverMap = 1447, giverX = 22.6, giverY = 51.4, ender = "Magatha Grimtotem", enderMap = 1456, enderX = 69.8, enderY = 30.9, objective = "Bring the Tablet of Beth'Amara to Magatha in Thunder Bluff.", summary = "The first tablet goes to a tauren female... one called Magatha. She is among the elders in Thunder Bluff, and is one of the proponents of the alliance between the tauren and the Forsaken. She, more than anyone among the elders, feels the tauren and their ways can help the Forsaken find a path back to being human.$B$BBring her the Tablet of Beth'Amara. The tablet may be the link she needs in finding a way to help the Forsaken... or so she claims." },
            { ids = { 3562 }, name = "Magatha's Payment to Jediga", level = 52, zone = "Thunder Bluff", giver = "Magatha Grimtotem", giverMap = 1456, giverX = 69.8, giverY = 30.9, ender = "Jediga", enderMap = 1447, enderX = 22.6, enderY = 51.4, objective = "Deliver Magatha's Note to Jediga in Azshara.", summary = "Take this note to Jediga. Tell her the payment will be here for her when she returns. And tell her I am pleased with her work.$B$BGo swiftly, $N. Tell your master I will be awaiting her here." },
        },
    },
    {
        id = "q3561",
        name = "Xylem's Payment to Jediga",
        zone = "Azshara",
        minLevel = 45,
        maxLevel = 52,
        importance = 1,
        kind = "world",
        quests = {
            { ids = { 3561 }, name = "Delivery to Archmage Xylem", level = 52, zone = "Azshara", giver = "Jediga", giverMap = 1447, giverX = 22.6, giverY = 51.4, ender = "Archmage Xylem", enderMap = 1447, enderX = 29.2, enderY = 40.2, after = { 3517 }, objective = "Bring the Tablet of Sael'hai to Archmage Xylem in Azshara.", summary = "This final tablet goes to someone very dangerous, $N. Heed me when I tell you that I trust this person far less than anyone else I've asked you to meet with.$B$BArchmage Xylem has a tower up in the hills overlooking Azshara. He's human, but he acts like no human I've met... or killed. He exudes power, and I dare not ask him what he plans on doing with the tablet.$B$BHe came to me, but told me that his bodyguard Sanath would help me get to the tower when I was ready to meet him. Look north for Sanath." },
            { ids = { 3565 }, name = "Xylem's Payment to Jediga", level = 52, zone = "Azshara", giver = "Archmage Xylem", giverMap = 1447, giverX = 29.2, giverY = 40.2, ender = "Jediga", enderMap = 1447, enderX = 22.6, enderY = 51.4, objective = "Deliver Xylem's Note to Jediga in Azshara.", summary = "What is it? Oh yes, your payment. Of course.$B$BTake this and be off with you. I'm sure Jediga is awaiting oh so patiently for your return." },
        },
    },
    {
        id = "q3380",
        name = "Into the Depths",
        zone = "Feralas",
        minLevel = 46,
        maxLevel = 51,
        importance = 1,
        kind = "dungeon",
        quests = {
            { ids = { 3380 }, name = "The Sunken Temple", level = 51, zone = "Feralas", giver = "Witch Doctor Uzer'i", giverMap = 1444, giverX = 74.4, giverY = 43.4, ender = "Marvon Rivetseeker", enderMap = 1446, enderX = 52.7, enderY = 45.9, objective = "Find Marvon Rivetseeker in Tanaris.", summary = "There are restless spirits in this world, $N. There are spirits that have been tainted by their isolation, bound to an ancient evil...$B$BI have heard of a place that lies deep below the surface of the earth -- banished there by powers greater than I have ever seen.$B$BIf you wish to learn more of this place; the Sunken Temple, seek out a goblin named Marvon Rivetseeker. He has studied many ancient areas of the world, and was last known to have left his home in Ratchet to study the troll ruins in Tanaris." },
            { ids = { 3444 }, name = "The Stone Circle", level = 51, zone = "Tanaris", giver = "Marvon Rivetseeker", giverMap = 1446, giverX = 52.7, giverY = 45.9, ender = "Marvon Rivetseeker", enderMap = 1446, enderX = 52.7, enderY = 45.9, objective = "Retrieve the Stone Circle from Marvon Rivetseeker's workshop in Ratchet.", summary = "I once entered the foreboding chambers of the Sunken Temple. The evil in that place penetrates all that enter; I barely managed to find my way out, wading through the ooze that now covers the floors. All I can remember is stumbling through a large circular room, filled with serpent statues...$B$BRecently, I discovered a round stone that appeared to have the same serpent symbol imprinted on it. I had it packed up and shipped to my workshop in Ratchet. Retrieve it, and I might be able to tell you more." },
            { ids = { 3446 }, name = "Into the Depths", level = 51, zone = "Tanaris", giver = "Marvon Rivetseeker", giverMap = 1446, giverX = 52.7, giverY = 45.9, ender = "Altar of Hakkar", enderMap = 1435, enderX = 69.9, enderY = 53.5, enderInside = "The Temple of Atal'Hakkar", objective = "Find the Altar of Hakkar in the Sunken Temple in Swamp of Sorrows.", summary = "Inside the temple, I found a circular room with six balconies, each one with a serpent statue on the edge. Curious, I pushed one of them to see what would happen, and it was a trap! I nearly fell to my death from the explosion. Laying there on the ledge, I looked down and noticed that there was another statue at the base of the room; an altar of sorts... Hakkar, I think it was called.$B$BI think that this altar is the secret -- you must bring this token to the altar in the Sunken Temple." },
        },
    },
    {
        id = "q3844",
        name = "It's Dangerous to Go Alone",
        zone = "Un'Goro Crater",
        minLevel = 47,
        maxLevel = 56,
        importance = 2,
        kind = "world",
        quests = {
            { ids = { 3844 }, name = "It's a Secret to Everybody", level = 52, zone = "Un'Goro Crater", giver = "A Wrecked Raft", giverMap = 1449, giverX = 63.0, giverY = 68.6, ender = "A Small Pack", enderMap = 1449, enderX = 63.1, enderY = 69.1, objective = "Look around in the pond for a clue about who this wrecked raft may belong to.", summary = "A destroyed raft rests along the shoreline. Considering this is only a small pond, it is not clear as to how it ended up here, although looking at the trees tells you that the water level may not be constant.$B$BPerhaps a little exploration in the area might uncover more clues..." },
            { ids = { 3845 }, name = "It's a Secret to Everybody", level = 52, zone = "Un'Goro Crater", giver = "A Small Pack", giverMap = 1449, giverX = 63.1, giverY = 69.1, ender = "Linken", enderMap = 1449, enderX = 44.7, enderY = 8.1, objective = "Examine the items inside the pack and bring them to their owner.", summary = " Grabbing onto it, you pull the pack back to the shore. Perhaps if you examine the items inside the pack, you might find out more about who it belongs to.$B$BThere are a few stray travelers at Marshal's Refuge. Perhaps you might find out more there." },
            { ids = { 3908 }, name = "It's a Secret to Everybody", level = 52, zone = "Un'Goro Crater", giver = "Linken", giverMap = 1449, giverX = 44.7, giverY = 8.1, ender = "Donova Snowden", enderMap = 1452, enderX = 31.3, enderY = 45.2, objective = "Take Linken's Sword to Donova Snowden in Winterspring.", summary = "You see, I have no idea how I ended up here. No one really knows -- it's a secret to everybody! I just can't seem to remember anything...$B$BThese items you brought to me, though... I am remembering something.$B$BMy sword. I am supposed to strengthen it somehow, but I'm really not sure why. Sorry I can't tell you more, but I just don't remember!$B$BAnyhoo, I do know where you can take it -- Donova Snowden in Winterspring. You'll find her by the hot springs. She can temper the sword by the pools there." },
            { ids = { 3909 }, name = "The Videre Elixir", level = 52, zone = "Winterspring", giver = "Donova Snowden", giverMap = 1452, giverX = 31.3, giverY = 45.2, ender = "Donova Snowden", enderMap = 1452, enderX = 31.3, enderY = 45.2, objective = "Seek out Gregan Brewspewer in northern Feralas. From him, learn how you may acquire the Videre Elixir, then return to Donova Snowden in Winterspring.", summary = "Now, what's this? Linken... FORGOT?$B$BOh, I see... Lost his memory...$B$BWell, here is his sword. It's not complete, though. I know of the one that can finish it, but... speaking with him may prove difficult.$B$BListen, I know of someone that will be able to help you. It's too much to explain right now, but you must somehow acquire a Videre Elixir. The only one I know that can help you with that is Gregan Brewspewer. He's hard to track down, but last I knew he was camping in the wilds of Feralas." },
            { ids = { 3912 }, name = "Meet at the Grave", level = 52, zone = "Winterspring", giver = "Donova Snowden", giverMap = 1452, giverX = 31.3, giverY = 45.2, ender = "Gaeriyan", enderMap = 1446, enderX = 53.9, enderY = 23.3, objective = "Go to the graveyard outside Gadgetzan, and use the Videre Elixir. Follow the rest of Donova's instructions to find Gaeriyan.", summary = "This elixir will allow you to speak with one that you would not normally even see...$B$BTake the Videre elixir, along with Linken's sword, to the graveyard just outside Gadgetzan in Tanaris. Once there, drink the potion. You may be quite surprised at the results, but do not be alarmed.$B$BIn your \"other\" form, head due north until you reach the mountains. You'll find the one you need to speak with in one of the rocky crevices. His name is Gaeriyan.$B$BRemember, he will only speak to you in that form..." },
            { ids = { 3913 }, name = "A Grave Situation", level = 52, zone = "Tanaris", giver = "Gaeriyan", giverMap = 1446, giverX = 53.9, giverY = 23.3, ender = "A Conspicuous Gravestone", enderMap = 1446, enderX = 53.8, enderY = 29.1, objective = "Resurrect, then look for the gravestone that Gaeriyan told you to find.", summary = "If you return to the graveyard, $N, you will find a gravestone there... Not just any gravestone; this one will stand out from the others. Secrets lie within it.$B$BPush on the stone, and you will learn of these secrets..." },
            { ids = { 3914 }, name = "Linken's Sword", level = 52, zone = "Tanaris", giver = "A Conspicuous Gravestone", giverMap = 1446, giverX = 53.8, giverY = 29.1, ender = "Linken", enderMap = 1449, enderX = 44.7, enderY = 8.1, objective = "Deliver Linken's Superior Sword to Linken in Un'Goro Crater.", summary = "After a strong flash of light, you are able to pick up the sword again. It has been transformed!" },
            { ids = { 3941 }, name = "A Gnome's Assistance", level = 52, zone = "Un'Goro Crater", giver = "Linken", giverMap = 1449, giverX = 44.7, giverY = 8.1, ender = "J.D. Collie", enderMap = 1449, enderX = 41.9, enderY = 2.7, objective = "Find J.D. Collie in the cave at Marshal's Refuge.", summary = "Thinking... Thinking... I know I came here for something important...$B$BI have an idea, $N. In the cave over there is a gnome named J.D. that was very kind to me when I first arrived here. Perhaps in my disoriented state, I might have mentioned something to her.$B$BWhy don't you go ask her if she knows anything? Oh, but be careful -- she's always messing with those crazy glowing crystals I've seen in the crater. I'm not quite sure what she's up to in there!" },
            { ids = { 3942 }, name = "Linken's Memory", level = 54, zone = "Un'Goro Crater", giver = "J.D. Collie", giverMap = 1449, giverX = 41.9, giverY = 2.7, ender = "Eridan Bluewind", enderMap = 1448, enderX = 51.4, enderY = 81.5, objective = "Find Eridan Bluewind in southern Felwood.", summary = "Oh... Linken? Yeah, he's a funny one. When he first got here, he was mumbling about all kinds of strange things. Probably got bumped on the head pretty hard, I imagine.$B$BSomething he said kinda stuck with me though -- that he was making some sort of totem; said he had to talk to someone named Eridan Bluewind... in a place called Felwood, I think?$B$BI doubt he could tell you much now, though. If you want to know more, maybe you should look for Eridan yourself?" },
            { ids = { 4084 }, name = "Silver Heart", level = 54, zone = "Felwood", giver = "Eridan Bluewind", giverMap = 1448, giverX = 51.4, giverY = 81.5, ender = "Eridan Bluewind", enderMap = 1448, enderX = 51.4, enderY = 81.5, objective = "Collect 11 Silvery Claws and 1 Irontree Heart for Eridan Bluewind in Felwood.", summary = "I do not know the one you speak of, $N.$B$BBut worry not; if your friend was on a journey to find me, I do know what it was he desired.$B$BIn the heart of Un'Goro Crater dwells evil of the purest form. This evil takes the shape of an elemental called Blazerunner... protected by an aura that none can dispel...$B$BNone... except those with enough power to do so. I can teach you of this power, $N.$B$BFirst, do as I ask. Collect 11 Silvery Claws and 1 Irontree Heart from the creatures in Felwood, then return." },
            { ids = { 4005 }, name = "Aquementas", level = 54, zone = "Felwood", giver = "Eridan Bluewind", giverMap = 1448, giverX = 51.4, giverY = 81.5, ender = "J.D. Collie", enderMap = 1449, enderX = 41.9, enderY = 2.7, objective = "Take the Book of Aquor, the Silvery Claws, and the Irontree Heart to Tanaris.$B$BUse the Book of Aquor to summon Aquementas.$B$BAfter you have the completed totem, take it to J.D. Collie in Marshal's Refuge.", summary = "Take this bag of supplies with you to Tanaris. Travel to Lost Rigger Cove, and look for a circle of stones.$B$BThe eastmost peninsula is the secret...$B$BFrom this circle only, read from the book of Aquor; summon the only creature that can transform the items you collected into a totem to fight Blazerunner.$B$BAquementas will not be pleased to be awakened, but remember, you must remain in the circle for him to transform the items." },
            { ids = { 3961 }, name = "Linken's Adventure", level = 54, zone = "Un'Goro Crater", giver = "J.D. Collie", giverMap = 1449, giverX = 41.9, giverY = 2.7, ender = "Linken", enderMap = 1449, enderX = 44.7, enderY = 8.1, objective = "Take the Silver Totem of Aquementas to Linken in Marshal's Refuge.", summary = "To think all this time that the reason Linken came here was to rid us of Blazerunner... He seems like such an ordinary guy, but I did notice that he's not at all interested in any of my experiments or gadgets like most gnomes would be. He must be a true warrior at heart.$B$BBring the totem to him. See if that helps him remember why he came here." },
            { ids = { 3962 }, name = "It's Dangerous to Go Alone", level = 56, zone = "Un'Goro Crater", giver = "Linken", giverMap = 1449, giverX = 44.7, giverY = 8.1, ender = "Linken", enderMap = 1449, enderX = 44.7, enderY = 8.1, objective = "Travel to Fire Plume Ridge, south of Marshal's Refuge.$B$BFind Blazerunner and use the totem to remove his protective aura. Once he has been defeated, acquire the Golden Flame from the cave.", summary = "$N, I finally remember now... I did come here to fight Blazerunner. I was on a journey, and this was to be the last step.$B$BBut I am no longer the hero... You are. All that you have done -- you must finish this now, not me.$B$BBlazerunner guards an artifact called the Golden Flame. It provides power more vast than anything else I have ever known, and it is dangerous in the hands of one with an evil heart.$B$BYou will want to bring others with you -- it's dangerous to go alone. Take this as my advice." },
        },
    },
    {
        id = "q4001",
        name = "The Royal Rescue",
        zone = "Badlands",
        minLevel = 48,
        maxLevel = 60,
        importance = 3,
        kind = "dungeon",
        quests = {
            { ids = { 3981 }, name = "Commander Gor'shak", level = 52, zone = "Badlands", giver = "Galamav the Marksman", giverMap = 1418, giverX = 6.0, giverY = 47.7, ender = "Commander Gor'shak", enderMap = 1427, enderX = 34.8, enderY = 85.3, enderInside = "Blackrock Depths", after = { 3906 }, objective = "Find Commander Gor'shak in Blackrock Depths.$B$BYou recall that the crudely drawn picture of the orc included bars drawn over the portrait. Perhaps you should search for a prison of some sort.", summary = "Poor Gargal... didn't even see it coming. WHAM! The arrow landed dead center on the top of his head. He was no genius before but now...$B$B<Galamav grimaces.>$B$BWhen we dislodged the arrow, we noticed a rolled up note attached to the shaft. On the note was a crudely drawn picture of an orc behind bars with the signature of Commander Gor'shak attached.$B$BIf he's still alive in the Depths, you'll have to find him.$B$BA trap you say? Well no kidding, numb hooves! That's why you're going!" },
            { ids = { 3982 }, name = "What Is Going On?", level = 54, zone = "Blackrock Depths", giver = "Commander Gor'shak", giverMap = 1427, giverX = 34.8, giverY = 85.3, giverInside = "Blackrock Depths", ender = "Commander Gor'shak", enderMap = 1427, enderX = 34.8, enderY = 85.3, enderInside = "Blackrock Depths", objective = "Defend Gor'shak.", summary = "I was sent here under the auspices of Thrall. Do you actually think these buffoons could capture me? I allowed myself to be captured so that I could gather intelligence.$B$B<Gor'shak whispers.>$B$BThe Princess of Ironforge has been kidnapped by Emperor Thaurissan. Princess Bronzebeard is in this very city! I bet old Magni's heart almost stopped when he heard that news.$B$B<Gor'shak laughs.>$B$BShhh! Do you hear that? Guards coming! DEFEND YOURSELF!" },
            { ids = { 4001 }, name = "What Is Going On?", level = 54, zone = "Blackrock Depths", giver = "Commander Gor'shak", giverMap = 1427, giverX = 34.8, giverY = 85.3, giverInside = "Blackrock Depths", ender = "Thrall", enderMap = 1454, enderX = 31.7, enderY = 37.8, objective = "Speak with Kharan Mighthammer and gather information about Princess Moira Bronzebeard's kidnapping. Take that information to Thrall in Orgrimmar.$B$BYou recall Gor'shak mentioning that Kharan is being held in a cell nearby.", summary = "So far, my communication with the dwarf, Kharan, in the cell across the hall, has been limited. I have, however, managed to convince him that I, rather -we- mean him no harm.$B$BGo speak with him and gather as much information about the Princess and her captors as possible. Take that information back to the Warchief.$B$BThrall does not want the Princess harmed, but instead, has some grand plan laid out, which includes her being safely returned to Ironforge. Kharan already knows all of this... Go!" },
            { ids = { 4002 }, name = "The Eastern Kingdom", level = 54, zone = "Orgrimmar", giver = "Thrall", giverMap = 1454, giverX = 31.7, giverY = 37.8, ender = "Thrall", enderMap = 1454, enderX = 31.7, enderY = 37.8, objective = "Speak with Thrall if you are prepared to take on the mission he has planned.", summary = "You bring excellent information, $N.$B$BAs Warchief, it is my duty to do what is best for the Horde. To ensure that the generations that come after us are not forced into a hopeless existence.$B$BThe opportunity to shape our future alliances has fallen into our collective laps. A move to help the dwarves could greatly strengthen our relationships in the Eastern Kingdoms. This, then, is why you must not fail!$B$BAre you prepared?" },
            { ids = { 4003 }, name = "The Royal Rescue", level = 59, zone = "Orgrimmar", giver = "Thrall", giverMap = 1454, giverX = 31.7, giverY = 37.8, ender = "Princess Moira Bronzebeard", enderMap = 1427, enderX = 34.8, enderY = 85.3, enderInside = "Blackrock Depths", objective = "Slay Emperor Dagran Thaurissan and free Princess Moira Bronzebeard from his evil spell. ", summary = "This strike against the Dark Iron dwarves, if successful, will send a shockwave throughout their entire kingdom.$B$BPrincess Bronzebeard is under the control of Emperor Thaurissan. To free her, you must kill the Emperor. Be warned, your task is doubly dangerous, as Bronzebeard will attack you without question while under the control of the Emperor.$B$BDO NOT HARM HER!" },
            { ids = { 4004 }, name = "The Princess Saved?", level = 60, zone = "Blackrock Depths", giver = "Princess Moira Bronzebeard", giverMap = 1427, giverX = 34.8, giverY = 85.3, giverInside = "Blackrock Depths", ender = "Thrall", enderMap = 1454, enderX = 31.7, enderY = 37.8, objective = "Return to Thrall!", summary = "You have slain my husband, $r! My child will be born into this world without a father.$B$B<Princess Moira points directly at you.>$B$BI assure you, this child will be the next ruler of the kingdom of Ironforge. You and your kind shall be hunted down until the end of days for this wrongful act.$B$B<You think that Princess Moira may be suffering from the residual effect of Thaurissan's spell.>$B$BLeave me be, $r. I am certain your warchief will be eager to hear the results of his meddling." },
        },
    },
    {
        id = "q4081",
        name = "Operation: Death to Angerforge",
        zone = "Badlands",
        minLevel = 48,
        maxLevel = 58,
        importance = 3,
        kind = "dungeon",
        quests = {
            { ids = { 4081 }, name = "KILL ON SIGHT: Dark Iron Dwarves", level = 52, zone = "Badlands", giver = "WANTED", giverMap = 1418, giverX = 3.7, giverY = 47.4, ender = "Warlord Goretooth", enderMap = 1418, enderX = 5.8, enderY = 47.5, objective = "Venture to Blackrock Depths and destroy the vile aggressors!$B$BWarlord Goretooth wants you to kill 15 Anvilrage Guardsmen, 10 Anvilrage Wardens and 5 Anvilrage Footmen. Return to him once your task is complete.", summary = "By order of Warlord Goretooth, commander of the Kargath Expeditionary Force:$B$BAny and all of General Angerforge's forces within Blackrock Depths must be annihilated.$B$BAngerforge's men are ruthless killers, responsible for the mass murder of the 109th division of the Kargath Expeditionary Force. Heroes are warned to exercise extreme caution when confronting these brutes.$B$BAny person who destroys the first line of General Angerforge's forces in Blackrock Depths shall receive a tribute." },
            { ids = { 4082 }, name = "KILL ON SIGHT: High Ranking Dark Iron Officials", level = 54, zone = "Badlands", giver = "KILL ON SIGHT", giverMap = 1418, giverX = 3.9, giverY = 46.7, ender = "Warlord Goretooth", enderMap = 1418, enderX = 5.8, enderY = 47.5, objective = "Venture to Blackrock Depths and destroy the vile aggressors!$B$BWarlord Goretooth wants you to kill 10 Anvilrage Medics, 10 Anvilrage Soldiers and 10 Anvilrage Officers. Return to him once your task is complete.", summary = "By order of Warlord Goretooth, commander of the Kargath Expeditionary Force:$B$BHead of the K.E.F. reconnaissance division, Grandmaster Lexlort, has returned with news of the whereabouts of high ranking Dark Iron officials. Through locked gate, near the heart of the city, they train their forces to snuff out our men. Travel to Blackrock Depths and destroy them!$B$BCompletion of this mission will result in a tribute." },
            { ids = { 4122 }, name = "Grark Lorkrub", level = 58, zone = "Badlands", giver = "Lexlort", giverMap = 1418, giverX = 5.9, giverY = 47.6, ender = "Grark Lorkrub", enderMap = 1428, enderX = 40.2, enderY = 34.2, objective = "Travel to the Burning Steppes and find Grark Lorkrub. You recall Lexlort mentioning that he was last seen in a massive Blackrock fortress.$B$BWhen you find Grark Lorkrub, use the Thorium Shackles to bind him and then lead him back through Blackrock Mountain to the Searing Gorge. Lexlort will have his men waiting on the other side to take Grark into custody.", summary = "I tracked him across the Searing Gorge, through the mountain, and into the Burning Steppes. That traitor was caught red-handed giving the Blackrock orcs vital information about our day to day operations. I'm speaking of Grark Lorkrub.$B$BHe now sits in the Burning Steppes, safely under their protection - or so he thinks.$B$BTake these shackles, $N. Find Grark, place the shackles on him and lead him through Blackrock Mountain. Do this and a tribute is yours." },
            { ids = { 4121 }, name = "Precarious Predicament", level = 58, zone = "Burning Steppes", giver = "Grark Lorkrub", giverMap = 1428, giverX = 40.2, giverY = 34.2, ender = "Lexlort", enderMap = 1418, enderX = 5.9, enderY = 47.6, objective = "Escort your prisoner, Grark Lorkrub, through Burning Steppes and through Blackrock Mountain to the Searing Gorge.$B$BYou recall Lexlort mentioning that he would have his men waiting on the other side to take Grark into custody.$B$BYou will also be required to hand over your Thorium Shackles to Lexlort.", summary = "Do you truly believe that you will make it to your rendezvous point with me in custody? You actually expected to break into a heavily fortified Blackrock fortress to capture a prized asset of theirs without alerting anyone or anything to your presence?$B$BYou will be destroyed!" },
            { ids = { 4132 }, name = "Operation: Death to Angerforge", level = 58, zone = "Badlands", giver = "Warlord Goretooth", giverMap = 1418, giverX = 5.8, giverY = 47.5, ender = "Warlord Goretooth", enderMap = 1418, enderX = 5.8, enderY = 47.5, objective = "Travel to Blackrock Depths and slay General Angerforge! Return to Warlord Goretooth when the task is complete.", summary = "You have done an exemplary job, $N. It is now time to send you on your last mission.$B$BGeneral Angerforge, the Dark Iron responsible for coordinating the attacks on the 109th division of the K.E.F. and the mass slaughter of our forces must be brought to justice.$B$BThis will undoubtedly be your most grueling mission, but should you succeed, you will be richly rewarded." },
        },
    },
    {
        id = "q5155",
        name = "A Final Blow",
        zone = "Felwood",
        minLevel = 48,
        maxLevel = 58,
        importance = 2,
        kind = "world",
        quests = {
            { ids = { 5155 }, name = "Forces of Jaedenar", level = 51, zone = "Felwood", giver = "Greta Mosshoof", giverMap = 1448, giverX = 51.2, giverY = 82.1, ender = "Greta Mosshoof", enderMap = 1448, enderX = 51.2, enderY = 82.1, objective = "Enter Jaedenar and slay 4 Jaedenar Hounds, 4 Jaedenar Guardsmen, 6 Jaedenar Adepts, and 6 Jaedenar Cultists before returning to Greta Mosshoof in Felwood.", summary = "If I am to trust you in this matter, you will first have to prove yourself.$B$BI must know that you are an enemy of the Shadow Council--the ones responsible for many evils here and abroad.$B$BTravel deeper into Felwood. To the west you will see a path leading to Jaedenar. It is there that the Council plots with the Burning Legion.$B$BEnter the depths of one of the corrupted Barrow Dens they inhabit and slay their kind. Return to me after you've done this. Then I will know you truly seek to help us." },
            { ids = { 5157 }, name = "Collection of the Corrupt Water", level = 52, zone = "Felwood", giver = "Greta Mosshoof", giverMap = 1448, giverX = 51.2, giverY = 82.1, ender = "Greta Mosshoof", enderMap = 1448, enderX = 51.2, enderY = 82.1, objective = "Take the Empty Canteen to the Moon Well in the center of Jaedenar and fill it before returning to Greta Mosshoof in Felwood.", summary = "Deep within Jaedenar lies Shadow Hold--the main fortress of their corruption and evil.$B$BThe Shadow Council has protective spells surrounding their lair in the form of braziers. If I am to find out any more information about our enemy through scrying, then those braziers must be extinguished. By doing so, I should be able to spy on the Council and find out who leads them.$B$BIf you can, take this canteen and fill it at the Moon Well in the center of Jaedenar. Return to me afterwards." },
            { ids = { 5158 }, name = "Seeking Spiritual Aid", level = 52, zone = "Felwood", giver = "Greta Mosshoof", giverMap = 1448, giverX = 51.2, giverY = 82.1, ender = "Islen Waterseer", enderMap = 1413, enderX = 65.8, enderY = 43.8, objective = "Take the Corrupt Moon Well Water to Islen Waterseer in the Barrens.", summary = "Take the corrupt water to the Barrens, $N. South of Ratchet, hidden along the shore, is an old friend of mine, a shaman named Islen Waterseer. She is a powerful shaman who will help us. Her relationship with the spirits of water has always been strong. Our task being a noble one should be enough to persuade her and the spirits of water to aid us in this task.$B$BYou should find her at a small camp right along the water's edge. And, $N, ignore the pirates... they are but a nuisance and no threat to you." },
            { ids = { 5159 }, name = "Cleansed Water Returns to Felwood", level = 54, zone = "The Barrens", giver = "Islen Waterseer", giverMap = 1413, giverX = 65.8, giverY = 43.8, ender = "Greta Mosshoof", enderMap = 1448, enderX = 51.2, enderY = 82.1, objective = "Take the Purified Moon Well Water to Greta Mosshoof in Felwood.", summary = "Thank the spirits, $N. They are the ones that have come to your aid, not me.$B$BI give this purified water to you now. Please give my regards to Greta and my best wishes. She is tackling something greater than many of us... as I'm sure she will soon find out.$B$BThe Shadow Council is not a force to be trifled with, $N. Remember that.$B$BGo now. Take the water and return to Greta." },
            { ids = { 5165 }, name = "Dousing the Flames of Protection", level = 55, zone = "Felwood", giver = "Greta Mosshoof", giverMap = 1448, giverX = 51.2, giverY = 82.1, ender = "Greta Mosshoof", enderMap = 1448, enderX = 51.2, enderY = 82.1, objective = "Using the Purified Moon Well Water, douse the flames of the four braziers of protection within Shadow Hold in Felwood, then return to Greta Mosshoof in the Emerald Sanctuary.", summary = "Now, you must return to Jaedenar. The braziers are more than likely spread throughout Shadow Hold. Douse each of their flames and the protections the Council has set up will fall for at least a short period of time. I will be waiting for that to happen. When it does, I will look deep within the Hold and try to find out who the head of this beast is. Then, and only then, will we see about attacking them directly." },
            { ids = { 5242 }, name = "A Final Blow", level = 58, zone = "Felwood", giver = "Greta Mosshoof", giverMap = 1448, giverX = 51.2, giverY = 82.1, ender = "Greta Mosshoof", enderMap = 1448, enderX = 51.2, enderY = 82.1, objective = "Kill Moora and Salia, and bring Shadow Lord Fel'dan's Head to Greta Mosshoof in Felwood.", summary = "Unfortunately, I see the only way to stop this threat to Felwood is a frontal attack. There are no other ways into Shadow Hold, and I have no means to teleport you inside. The straight path down to the bottom is the only way... and I also know who you should seek out. His name is Fel'dan... Shadow Lord Fel'dan. He is the mortal in power down below... he is the head of the serpent. Kill him and his two succubus servants and return to me. Fel'dan is the one making pacts with the Legion. He must be stopped." },
        },
    },
    {
        id = "q3906",
        name = "Disharmony of Fire",
        zone = "Badlands",
        minLevel = 48,
        maxLevel = 56,
        importance = 2,
        kind = "dungeon",
        quests = {
            { ids = { 3906 }, name = "Disharmony of Flame", level = 52, zone = "Badlands", giver = "Thunderheart", giverMap = 1418, giverX = 3.3, giverY = 48.3, ender = "Thunderheart", enderMap = 1418, enderX = 3.3, enderY = 48.3, objective = "Travel to the quarry in Blackrock Mountain and slay Overmaster Pyron. Return to Thunderheart when you have completed this assignment.", summary = "The elders have felt a disturbance amongst the elements. The Dark Iron dwarves have summoned a foul spirit into our world that threatens to plague our lands with an eternal draught. This disharmony of flame must be investigated.$B$BTravel to Blackrock Mountain, through the Chasm of Flame, into the quarry. It is there that you shall find this lord of fire: Overmaster Pyron.$B$BEnd the disruption and return to me." },
            { ids = { 3907 }, name = "Disharmony of Fire", level = 56, zone = "Badlands", giver = "Thunderheart", giverMap = 1418, giverX = 3.3, giverY = 48.3, ender = "Thunderheart", enderMap = 1418, enderX = 3.3, enderY = 48.3, objective = "Enter Blackrock Depths and track down Lord Incendius. Slay him and return any source of information you may find to Thunderheart.", summary = "I can taste the foulness in the air that surrounds you, $N. There is another, hidden in the depths of Blackrock, who does control this foulness.$B$BThe wind and earth cry his name: Lord Incendius... but someone... something... commands this being. He is merely an emissary.$B$BFind him and discover where his master hides. Return to me when you have collected this information." },
        },
    },
    {
        id = "q5093",
        name = "The Scourge Cauldrons",
        zone = "Orgrimmar",
        minLevel = 50,
        maxLevel = 58,
        importance = 3,
        kind = "world",
        quests = {
            { ids = { 5093 }, name = "A Call to Arms: The Plaguelands!", level = 50, zone = "Orgrimmar", giver = "Warcaller Gorlach", giverMap = 1454, giverX = 37.7, giverY = 75.2, ender = "High Executor Derrington", enderMap = 1420, enderX = 83.1, enderY = 68.9, objective = "Seek out High Executor Derrington.  His base camp is located at the Bulwark, east of Tirisfal Glade and the Undercity.", summary = "Heroes of the realm, hear me - the Horde calls upon you for swift action!$B$BA call to arms has been issued for all able bodied individuals to take up arms against the Scourge!  Rumors fly of new threats rising from the ruins of the Eastern Kingdoms.  They loom to the east of the Undercity, in the northern reaches of the lands now known as the Plaguelands!$B$BHeroes of the realm - seek out High Executor Derrington, who has set up his base camp at the Bulwark, east of Tirisfal Glade!" },
            { ids = { 5096 }, name = "Scarlet Diversions", level = 53, zone = "Tirisfal Glades", giver = "High Executor Derrington", giverMap = 1420, giverX = 83.1, giverY = 68.9, ender = "High Executor Derrington", enderMap = 1420, enderX = 83.1, enderY = 68.9, objective = "Proceed to the Scarlet Crusade's base camp between Felstone Field and Dalson's Tears and destroy their command tent.$B$BPlace the Scourge banner at the camp, and then return to High Executor Derrington at the Bulwark, Western Plaguelands.", summary = "Before Andorhal, we must tackle the advancing Scarlet Crusade menace from Hearthglen.  They've made camp between Felstone Field and Dalson's Tears, making us risk conflict against both the Scourge and the Crusade at once.$B$BMy plan is to play them off of each other by sending you to destroy the command tent they've set up; use some Flame in a Bottle from this box of incendiaries.  Once razed, plant this Scourge banner by the tent.  With some luck, they'll ignore us and focus on the Scourge for vengeance." },
            { ids = { 5228 }, name = "The Scourge Cauldrons", level = 53, zone = "Tirisfal Glades", giver = "High Executor Derrington", giverMap = 1420, giverX = 83.1, giverY = 68.9, ender = "Shadow Priestess Vandis", enderMap = 1420, enderX = 83.0, enderY = 71.9, objective = "Speak with Shadow Priestess Vandis at the Bulwark, Western Plaguelands.", summary = "Within the lands of former Lordaeron are eight cauldrons - four in the west, and four more entrenched in the east.  These cauldrons spew poisons into the air, propagating the plague throughout the land for the Scourge.$B$BThe necromantic might of Kel'Thuzad is too strong to outright shut down these cauldrons, but we think we might have a way to subvert them to our advantage.  My second, Shadow Priestess Vandis, will be your point on this assignment; she'll continue the briefing from here." },
            { ids = { 5229 }, name = "Target: Felstone Field", level = 53, zone = "Tirisfal Glades", giver = "Shadow Priestess Vandis", giverMap = 1420, giverX = 83.0, giverY = 71.9, ender = "Scourge Cauldron", enderMap = 1422, enderX = 37.2, enderY = 56.8, objective = "Go to Felstone Field in Western Plaguelands to locate and defeat the Cauldron Lord present there.  It may have a key that will allow access to the cauldron.  You must have the Empty Felstone Field Bottle with you to secure a sample of the poisons used inside the cauldron.", summary = "Of the four cauldrons in the Western Plaguelands, the one at Felstone Field may be the easiest one to gain access to.  The Scourge have greener troops positioned here, though they should not be underestimated.$B$BGo to Felstone Field, due east of here and northwest of Andorhal, and engage the cauldron lord there.  On it is a key that will unlock access to the cauldron.  When unlocked, use this bottle to get a sample of the cauldron's toxins; we'll need it for study in developing a counter agent." },
            { ids = { 5230, 5232, 5234, 5236 }, name = "Return to the Bulwark", level = 53, zone = "Western Plaguelands", giver = "Scourge Cauldron", giverMap = 1422, giverX = 37.2, giverY = 56.8, ender = "Shadow Priestess Vandis", enderMap = 1420, enderX = 83.0, enderY = 71.9, objective = "Bring the Filled Felstone Field Bottle to Shadow Priestess Vandis at the Bulwark, Western Plaguelands.", summary = "You fill the bottle with enough of the cauldron's poisonous concoction for a suitable sample to be studied.$B$BWith the poison in hand, it is time to return to Shadow Priestess Vandis at the Bulwark to complete the mission." },
            { ids = { 5231 }, name = "Target: Dalson's Tears", level = 55, zone = "Tirisfal Glades", giver = "Shadow Priestess Vandis", giverMap = 1420, giverX = 83.0, giverY = 71.9, ender = "Scourge Cauldron", enderMap = 1422, enderX = 46.2, enderY = 51.9, objective = "Go to Dalson's Tears in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron.  You must have the Empty Dalson's Tears Bottle with you to secure a sample of the poisons used inside the cauldron.", summary = "One of the plague cauldrons is located in the field of a former farmhouse now referred to as Dalson's Tears.  No tears will be shed this day, $c; we must strike at this cauldron and gain access to it!$B$BGo to Dalson's Tears, almost due north of Andorhal, and eliminate the cauldron lord there.  It should have a key like the last one did, allowing you inside the cauldron's innards.  Use this bottle to obtain a sample from inside the cauldron; each cauldron has its own distinct brew of toxins it uses." },
            { ids = { 5233 }, name = "Target: Writhing Haunt", level = 55, zone = "Tirisfal Glades", giver = "Shadow Priestess Vandis", giverMap = 1420, giverX = 83.0, giverY = 71.9, ender = "Scourge Cauldron", enderMap = 1422, enderX = 53.0, enderY = 65.6, objective = "Go to the Writhing Haunt in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron.  You must have the Empty Writhing Haunt Bottle with you to secure a sample of the poisons used inside the cauldron.", summary = "Two cauldrons have been successfully opened; while you'll be able to access them indefinitely, we still want to open up the other two that remain.  This will provide all of us with more options to introduce the counter agent!$B$BThis time, you'll be hitting the Writhing Haunt's cauldron.  It is almost due east of Andorhal, relatively close to the ruined city walls; again, eliminate the cauldron lord present there for its key.  Use this bottle to obtain the sample from the cauldron.$B$BGood hunting, $N!" },
            { ids = { 5235 }, name = "Target: Gahrron's Withering", level = 58, zone = "Tirisfal Glades", giver = "Shadow Priestess Vandis", giverMap = 1420, giverX = 83.0, giverY = 71.9, ender = "Scourge Cauldron", enderMap = 1422, enderX = 62.5, enderY = 58.5, objective = "Go to Gahrron's Withering in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron.  You must have the Empty Gahrron's Withering Bottle with you to secure a sample of the poisons used inside the cauldron.", summary = "The last cauldron that remains is located on a farm now called Gahrron's Withering.  It is guarded by some of the Scourge's tougher minions - specifically, wraiths and ghosts.  They are not to be trifled with, $N.$B$BGahrron's Withering is far to the east of the Bulwark, close to where the Eastern Plaguelands begin; again, eliminate the cauldron lord present there for its key.  Here is your empty sample bottle; bring it to me filled.  May the shadows cloak you in safety for this dangerous mission, $c." },
            { ids = { 5238 }, name = "Mission Accomplished!", level = 58, zone = "Tirisfal Glades", giver = "High Executor Derrington", giverMap = 1420, giverX = 83.1, giverY = 68.9, ender = "High Executor Derrington", enderMap = 1420, enderX = 83.1, enderY = 68.9 },
        },
    },
    {
        id = "q5601",
        name = "The Battle of Darrowshire",
        zone = "Winterspring",
        minLevel = 50,
        maxLevel = 60,
        importance = 2,
        kind = "world",
        quests = {
            { ids = { 5601 }, name = "Sister Pamela", level = 55, zone = "Winterspring", giver = "Jessica Redpath", giverMap = 1452, giverX = 61.3, giverY = 39.0, ender = "Pamela Redpath", enderMap = 1423, enderX = 31.1, enderY = 78.0, objective = "Find Pamela Redpath in Darrowshire.", summary = "I fled Lordaeron during the great war, and was lucky to escape before the Scourge swept through my homeland and turned it into a plagued nightmare!  I was lucky, but my family was not.  I fear they were all killed during the battle of Darrowshire.$B$BDarrowshire is a village in the Eastern Kingdoms, nestled in the southern hills of what is now the Eastern Plaguelands.  Will you go there and search for my family?  I miss them so much, especially my little sister Pamela.$B$BPlease, find her for me!" },
            { ids = { 5149 }, name = "Pamela's Doll", level = 55, zone = "Eastern Plaguelands", giver = "Pamela Redpath", giverMap = 1423, giverX = 31.1, giverY = 78.0, ender = "Pamela Redpath", enderMap = 1423, enderX = 31.1, enderY = 78.0, objective = "Find Pamela's doll.", summary = "My auntie Marlene told me to stay here in our house because my father had to go and fight.  My father's the bravest man in the whole world!$B$BBut I've been here for a long time, and he hasn't come for me.  Sometimes bad people come and whisper to me and I want my dad to make them go away, but he's not here!$B$BAnd sometimes when it gets dark I want to play with my doll but I can't because I left it in town.$B$BWill you find my doll for me?" },
            { ids = { 5152 }, name = "Auntie Marlene", level = 56, zone = "Eastern Plaguelands", giver = "Pamela Redpath", giverMap = 1423, giverX = 31.1, giverY = 78.0, ender = "Marlene Redpath", enderMap = 1422, enderX = 49.2, enderY = 78.6, objective = "Speak with Marlene, south of the Ruins of Andorhal.", summary = "Oh, I'm so lonely!  Where is my family?  Auntie Marlene told me to stay here, but then she left and never came back!  And my dad... have you seen him?$B$BMaybe Auntie Marlene knows where he is.  She lives near Andorhal, in a house to the south.  I think it was on a hill... she said it was on a hill.$B$BPlease, $N.  You're my new friend!  Will you talk to my Auntie for me?" },
            { ids = { 5153 }, name = "A Strange Historian", level = 56, zone = "Western Plaguelands", giver = "Marlene Redpath", giverMap = 1422, giverX = 49.2, giverY = 78.6, ender = "Chromie", enderMap = 1422, enderX = 39.5, enderY = 66.8, objective = "Bring Joseph's Wedding Ring to Chromie.", summary = "I wish Joseph could again be with his daughter, but it cannot be so.  His soul was twisted by the Scourge, and he became a monster.  Oh, he is doomed!$B$BBut perhaps we can change his fate.$B$BSearch the graves outside for Joseph's monument.  His body's not there, for it was trampled and destroyed years ago, but under the monument is his wedding ring.  Take that ring to Chromie... a strange gnome with very strange powers.$B$BChromie is staying in the ruined inn at the northwest corner of Andorhal." },
            { ids = { 5154 }, name = "The Annals of Darrowshire", level = 56, zone = "Western Plaguelands", giver = "Chromie", giverMap = 1422, giverX = 39.5, giverY = 66.8, ender = "Chromie", enderMap = 1422, enderX = 39.5, enderY = 66.8, objective = "Bring the Annals of Darrowshire to Chromie in Andorhal.", summary = "To save Joseph Redpath, we must first discover his past.  We can learn this in the Annals of Darrowshire, a book held in the city hall of Andorhal.$B$BBring me that book.  We can then learn Joseph's fate, and with luck... change it!" },
            { ids = { 5210 }, name = "Brother Carlin", level = 56, zone = "Western Plaguelands", giver = "Chromie", giverMap = 1422, giverX = 39.5, giverY = 66.8, ender = "Carlin Redpath", enderMap = 1423, enderX = 71.7, enderY = 50.0, objective = "Bring the Extended Annals of Darrowshire to Carlin Redpath in Eastern Plaguelands.", summary = "The Annals of Darrowshire, through my magic, has gained pages at its end, and now it extends its history beyond the battle.  One of the extra passages tells of another Redpath, Carlin, who survived Joseph's betrayal.  Carlin's now in the Plaguelands to the east, at the Light's Hope Chapel.$B$BTake the book and speak with him." },
            { ids = { 5168 }, name = "Heroes of Darrowshire", level = 56, zone = "Eastern Plaguelands", giver = "Carlin Redpath", giverMap = 1423, giverX = 71.7, giverY = 50.0, ender = "Carlin Redpath", enderMap = 1423, enderX = 71.7, enderY = 50.0, objective = "Bring Davil's Libram and Redpath's Shield to Carlin Redpath.", summary = "The heroes of Darrowshire hold a place in my heart, and the book you brought me, the Annals of Darrowshire, tells their tales.$B$BIt tells of the paladin Davil Lightfire and how the Crusade took his libram to the town hall of Hearthglen.$B$BIts passages also speak of my brother, Captain Redpath.  After his betrayal, his shield was cracked and discarded and now lies in the most unlikely of places -- near the barn of Gahrron's Withering.$B$BGather these relics, $N.  For fate and tragedy surrounds them." },
            { ids = { 5181 }, name = "Villains of Darrowshire", level = 57, zone = "Eastern Plaguelands", giver = "Carlin Redpath", giverMap = 1423, giverX = 71.7, giverY = 50.0, ender = "Carlin Redpath", enderMap = 1423, enderX = 71.7, enderY = 50.0, objective = "Bring the Skull of Horgus and the Shattered Sword of Marduk to Carlin Redpath at Light's Hope Chapel.", summary = "The Annals of Darrowshire tells of the villains of that battle.  It tells how the ghoul lord Horgus the Ravager was destroyed by Alliance forces during the battle.  His body was cast into a lake, northwest of Corin's Crossing, and his skull remains there.$B$BMarduk the Black was never defeated, but his fabled sword was shattered and lost.  It lies at the bottom of the gorge west of Corin's Crossing.$B$BRetrieve these items, $N.  I know not why, but I am certain their fate lies with you." },
            { ids = { 5206 }, name = "Marauders of Darrowshire", level = 60, zone = "Eastern Plaguelands", giver = "Carlin Redpath", giverMap = 1423, giverX = 71.7, giverY = 50.0, ender = "Carlin Redpath", enderMap = 1423, enderX = 71.7, enderY = 50.0, objective = "Bring 5 Resonating Skulls and the Mystic Crystal to Carlin Redpath in Eastern Plaguelands.", summary = "Chromie said the relics you gathered are reagents to a powerful spell, and one more is required: skulls from the scourge who took part in the battle of Darrowshire.$B$BTake this crystal and hunt scourge champions for their skulls.  The crystal is enchanted; if a champion took part in the battle, then when you pass the crystal over its skull it will resonate.  Bring me those resonating skulls.$B$BGo, $N.  You'll find scourge champions in the Noxious Glade to the north and the Fungal Vale to the west." },
            { ids = { 5941 }, name = "Return to Chromie", level = 60, zone = "Eastern Plaguelands", giver = "Carlin Redpath", giverMap = 1423, giverX = 71.7, giverY = 50.0, ender = "Chromie", enderMap = 1422, enderX = 39.5, enderY = 66.8, objective = "Take the Bundle of Relics to Chromie in Andorhal.", summary = "You have gathered many relics of the battle of Darrowshire.  Each time you returned with more, my heart yearned for my village... yearned to protect it from its fate.$B$BI know that cannot be, but Chromie, that strange gnome in Andorhal, tells me it is possible.  She says you can save Darrowshire!$B$BShe asked me to gather together the relics, and to have you bring them to her.  She said that she awaits you in the ruined inn of Andorhal." },
            { ids = { 5721 }, name = "The Battle of Darrowshire", level = 60, zone = "Western Plaguelands", giver = "Chromie", giverMap = 1422, giverX = 39.5, giverY = 66.8, ender = "Pamela Redpath", enderMap = 1423, enderX = 31.1, enderY = 78.0, objective = "Place the Relic Bundle at the Darrowshire town square.$B$BPrevent Davil Lightfire's death until the death of Horgus.$B$BPrevent Captain Redpath's death until Redpath the Corrupted appears.$B$BDefeat Redpath the Corrupted.$B$BSpeak with the spirit of Joseph Redpath when he appears at the town square, then speak with Pamela at her home.", summary = "Now, $N, you will take part in battle of Darrowshire, and you will save Joseph Redpath.$B$BPlace this relic bundle in the Darrowshire town square, and the spirits of Darrowshire will rise.  Join their battle and assure that these two things come to pass: Davil must survive beyond the death of Horgus, and Redpath must survive to be corrupted, then defeated.$B$BAfter defeating the corrupted Redpath, his spirit will be saved.  Speak with him, then return to his daughter Pamela." },
            { ids = { 5942 }, name = "Hidden Treasures", level = 60, zone = "Eastern Plaguelands", giver = "Pamela Redpath", giverMap = 1423, giverX = 31.1, giverY = 78.0, ender = "Joseph's Chest", enderMap = 1423, enderX = 30.9, enderY = 77.8, objective = "Bring Joseph's Key to Joseph's Chest.", summary = "Daddy told me to give you this key.  He said it opens a chest out back behind the house.$B$BHe also wanted me to thank you.  Did you do a favor for him?  Did you tell him you found my doll?$B$BWell here's the key.  And thank you $N.  Thank you!  You're a very nice $gman:lady;!" },
        },
    },
    {
        id = "q4808",
        name = "Dawn's Gambit",
        zone = "Burning Steppes",
        minLevel = 50,
        maxLevel = 60,
        importance = 2,
        kind = "dungeon",
        quests = {
            { ids = { 4726 }, name = "Broodling Essence", level = 52, zone = "Burning Steppes", giver = "Tinkee Steamboil", giverMap = 1428, giverX = 65.2, giverY = 24, ender = "Tinkee Steamboil", enderMap = 1428, enderX = 65.2, enderY = 24, objective = "Bring 8 Broodling Essence and the Draco-Incarcinatrix 900 to Tinkee Steamboil at the Flame Crest in the Burning Steppes.", summary = "I have been studying the dragonkin of the Burning Steppes for weeks, and I think I've finally had a breakthrough!  I created a device--I call it the Draco Incarcinatrix 900.  It can capture the essence of dragon whelp broodlings!$B$BOr, at least I think it can.$B$BHere, take the device and zap a broodling in the Burning Steppes with it.  While it's under the device's effects, defeat the broodling and its essence should be released.$B$BIf it is, then splendid!  Bring me back samples so I can study them!" },
            { ids = { 4808 }, name = "Felnok Steelspring", level = 54, zone = "Burning Steppes", giver = "Tinkee Steamboil", giverMap = 1428, giverX = 65.2, giverY = 24, ender = "Felnok Steelspring", enderMap = 1452, enderX = 61.6, enderY = 38.6, objective = "Give Tinkee's Letter to Felnok Steelspring.", summary = "I have another favor to ask of you.$B$BMy initial study of the essence you collected shows that it might be possible to freeze dragon whelp eggs and preserve them!  I want to test this theory, but first I need specially made engineering components.  My colleague, Felnok Steelspring, can make them.$B$BHere, take this letter to Felnok.  It tells him what I need.  You'll find Felnok in Winterspring, in the town of Everlook." },
            { ids = { 4809 }, name = "Chillwind Horns", level = 54, zone = "Winterspring", giver = "Felnok Steelspring", giverMap = 1452, giverX = 61.6, giverY = 38.6, ender = "Felnok Steelspring", enderMap = 1452, enderX = 61.6, enderY = 38.6, objective = "Bring 8 Uncracked Chillwind Horns to Felnok Steelspring.", summary = "I have most of what Tinkee needs, but I'm missing one important component, and that's chillwind horns.  The horns of the chillwind chimaera in Winterspring are a concentrated source of cold, but only pristine, uncracked horns will do!  I'll need a supply of those to complete Tinkee's order.$B$BBring me the uncracked chillwind horns, and I'll prepare a package for Tinkee." },
            { ids = { 4810 }, name = "Return to Tinkee", level = 54, zone = "Winterspring", giver = "Felnok Steelspring", giverMap = 1452, giverX = 61.6, giverY = 38.6, ender = "Tinkee Steamboil", enderMap = 1428, enderX = 65.2, enderY = 24, objective = "Bring Felnok's Package to Tinkee Steamboil in the Burning Steppes.", summary = "Ok, everything is prepared and packed and ready for transport!  Good luck in your journey, and make sure you tell Tinkee that she owes me!" },
            { ids = { 4907 }, name = "Tinkee Steamboil", level = 60, zone = "Winterspring", giver = "Felnok Steelspring", giverMap = 1452, giverX = 61.6, giverY = 38.6, ender = "Tinkee Steamboil", enderMap = 1428, enderX = 65.2, enderY = 24, objective = "Speak with Tinkee Steamboil.", summary = "Hi, $N.  Remember Tinkee Steamboil?  Well, she remembers you!  She sent me a message to keep an eye out for you, because... she needs your help again.  I think it has something to do with her studies on dragons.$B$BYou should speak to her in the Burning Steppes, at the Flame Crest." },
            { ids = { 4734 }, name = "Egg Freezing", level = 60, zone = "Burning Steppes", giver = "Tinkee Steamboil", giverMap = 1428, giverX = 65.2, giverY = 24, ender = "Tinkee Steamboil", enderMap = 1428, enderX = 65.2, enderY = 24, objective = "Use the Eggscilloscope Prototype on an egg in the Rookery.", summary = "$N, I've been working hard on a new device, the eggscilloscope!  It's designed to project a burst of cold energy at the egg of a black dragon... and freeze it solid!  Can you test it for me?$B$BI heard that high up in Blackrock Spire, the dragons have a rookery where they hatch their eggs.  That's where you'll have to go to test the eggscilloscope, and then let me know how it worked!$B$BAnd don't worry.  Frozen dragon eggs should be harmless.  It's the unfrozen ones you have to worry about!" },
            { ids = { 4735 }, name = "Egg Collection", level = 60, zone = "Burning Steppes", giver = "Tinkee Steamboil", giverMap = 1428, giverX = 65.2, giverY = 24, ender = "Tinkee Steamboil", enderMap = 1428, enderX = 65.2, enderY = 24, objective = "Bring 8 Collected Dragon Eggs and the Collectronic Module to Tinkee Steamboil at Flame Crest in the Burning Steppes.", summary = "$N, I'm finally ready for real samples of dragon eggs!  Here, take this collectronic module.  It's designed to extract a dragon egg and prepare it for transport.  Go back to the Rookery and use the module to collect eggs.$B$BAnd don't forget to freeze them first, or they might hatch before you can collect them!$B$BWhen you have enough eggs, bring them to me! " },
            { ids = { 5522 }, name = "Leonid Barthalomew", level = 60, zone = "Burning Steppes", giver = "Tinkee Steamboil", giverMap = 1428, giverX = 65.2, giverY = 24, ender = "Leonid Barthalomew the Revered", enderMap = 1423, enderX = 71.9, enderY = 48.3, objective = "Bring the Frozen Eggs to Leonid Barthalomew in the Eastern Plaguelands.", summary = "I received a message from my master, Vectus.  Well, the message wasn't really from Vectus...it was from someone named Leonid Barthalomew.  I don't know Leonid, but he knew my master, and no one knows my master unless he allows it.$B$BLeonid says Vectus wants the dragon eggs.  He wants you to deliver them to him at the Light's Hope Chapel in the Eastern Plaguelands.$B$BThat hurts!  Why you?  Doesn't Vectus trust me?  Oh, never mind... just take the eggs and tell Leonid that I did what our master commanded." },
            { ids = { 5531 }, name = "Betina Bigglezink", level = 60, zone = "Eastern Plaguelands", giver = "Leonid Barthalomew the Revered", giverMap = 1423, giverX = 71.9, giverY = 48.3, ender = "Betina Bigglezink", enderMap = 1423, enderX = 71.7, enderY = 49.9, objective = "Bring the Frozen Eggs to Betina Bigglezink.", summary = "The eggs you brought were to be used in Scourge experiments to create a plagued dragonflight.  These frozen black dragon eggs would have been invaluable in their studies, and would have assuredly quickened their timetable.$B$BNow, it is time we ended their research.$B$BTake the frozen eggs to Betina Bigglezink outside.  She is well-learned in science and alchemy, and has produced a weapon we can use against the Scourge.  With your help, we will deal them a heavy blow." },
            { ids = { 4771 }, name = "Dawn's Gambit", level = 60, zone = "Eastern Plaguelands", giver = "Betina Bigglezink", giverMap = 1423, giverX = 71.7, giverY = 49.9, ender = "Betina Bigglezink", enderMap = 1423, enderX = 71.7, enderY = 49.9, objective = "Place Dawn's Gambit in the Viewing Room of the Scholomance.  Defeat Vectus, then return to Betina Bigglezink.", summary = "I've placed Dawn's Gambit in the container you brought to us, the one that held the dragon eggs.  Your job is to bring it deep within the Scholomance.$B$BThe undead mage Vectus leads a team of scourge scholars... place Dawn's Gambit in their chamber, called the \"viewing room.\"  It will then react with the undead found there and, with a little luck, destroy them!$B$BAfter that, defeating Vectus shouldn't be a problem.  Right?" },
        },
    },
    {
        id = "q8233",
        name = "The Azure Key",
        zone = "Stormwind City",
        minLevel = 50,
        maxLevel = 52,
        importance = 2,
        kind = "class",
        classes = { 4 },
        quests = {
            { ids = { 8233 }, name = "A Simple Request", level = 52, zone = "Stormwind City", giver = "Osborne the Night Man", giverMap = 1453, giverX = 77.4, giverY = 65.3, ender = "Lord Jorach Ravenholdt", enderMap = 1416, enderX = 86.0, enderY = 78.9, objective = "Speak with Lord Jorach Ravenholdt in Ravenholdt Manor.", summary = "Lord Jorach Ravenholdt has requested your presence.  The matter is secret, and I cannot say any more.$b$bRavenholdt Manor is located in the Hillsbrad Foothills -- look for a path in the mountains northwest of Durnhold Keep." },
            { ids = { 8234 }, name = "Sealed Azure Bag", level = 52, zone = "Alterac Mountains", giver = "Lord Jorach Ravenholdt", giverMap = 1416, giverX = 86.0, giverY = 78.9, ender = "Archmage Xylem", enderMap = 1447, enderX = 29.2, enderY = 40.2, objective = "Retrieve the Sealed Azure Bag from the Timbermaw Shaman in Azshara.  Then take the bag to Archmage Xylem, also found in Azshara.", summary = "First things first.  What I've lost is a small blue bag, the contents of which are a private matter.$b$bDon't bother going after the thieves, because they are already dead.  What we do know is the fools couldn't get the bag open. so they sold it to some timbermaw shaman in Azshara as a holy relic.  Clever.$b$bI need you to travel to Azshara and retrieve it from the shaman through subtlety... or force.  Better luck with the first method, I'd wager.  Once acquired, take it to Archmage Xylem." },
            { ids = { 8235 }, name = "Encoded Fragments", level = 52, zone = "Azshara", giver = "Archmage Xylem", giverMap = 1447, giverX = 29.2, giverY = 40.2, ender = "Archmage Xylem", enderMap = 1447, enderX = 29.2, enderY = 40.2, objective = "Bring 10 Encoded Fragments to Archmage Xylem in Azshara.", summary = "Lord Ravenholdt has asked a favor of us both.  He wishes to remove the enchantment from this bag.$b$bUnfortunately, some of my books on the subject of dispelling were taken recently, only to be destroyed by savages.  The remains of my books are still valuable to me.$b$bIf you can bring me enough of the encoded fragments, I can piece them back together.  Your best chance is to kill forest oozes, since they have a tendency to pick up just about anything.  You'll find them in northeast Azshara." },
            { ids = { 8236 }, name = "The Azure Key", level = 52, zone = "Azshara", giver = "Archmage Xylem", giverMap = 1447, giverX = 29.2, giverY = 40.2, ender = "Lord Jorach Ravenholdt", enderMap = 1416, enderX = 86.0, enderY = 78.9, objective = "Return the Azure Key to Lord Jorach Ravenholdt.", summary = "It will take some time to decipher the fragments and remove the enchantment.  When I am complete, I'll deliver the bag to Lord Ravenholdt personally.$b$bThere is still the matter of the key, said to be held by a green drake known as Morphaz.  The drake has made its home deep in the Temple of Atal'Hakkar, the entrance to which lies in the Swamp of Sorrows.$b$bGather your friends and venture to his lair.  Lord Ravenholdt will await your return with the key." },
        },
    },
    {
        id = "q5098",
        name = "The Key to Scholomance",
        zone = "Tirisfal Glades",
        minLevel = 50,
        maxLevel = 60,
        importance = 2,
        kind = "world",
        quests = {
            { ids = { 5098 }, name = "All Along the Watchtowers", level = 56, zone = "Tirisfal Glades", giver = "High Executor Derrington", giverMap = 1420, giverX = 83.1, giverY = 68.9, ender = "High Executor Derrington", enderMap = 1420, enderX = 83.1, enderY = 68.9, after = { 5096 }, objective = "Using the Beacon Torch, mark each tower in Andorhal; you will need to stand in the doorway of the tower to successfully mark it.$B$BOnce all four towers are marked, return the Beacon Torch to High Executor Derrington at the Bulwark, Western Plaguelands.", summary = "Through the use of a magical device known as a beacon torch, we can mark targets of our choosing for future actions by our troops.  To that end, we think the Scourge are using Andorhal's watchtowers as a means to control their troop movements.$B$BYour mission: breach Andorhal's defenses to plant beacons at all four watchtowers.  You'll need to be in the doorway of each tower to plant the beacon; it will then proceed to mark the tower.  There are only five charges on the beacon torch, so use them wisely!" },
            { ids = { 838 }, name = "Scholomance", level = 55, zone = "Tirisfal Glades", giver = "High Executor Derrington", giverMap = 1420, giverX = 83.1, giverY = 68.9, ender = "Apothecary Dithers", enderMap = 1420, enderX = 83.3, enderY = 69.2, objective = "Speak with Apothecary Dithers at the Bulwark, Western Plaguelands.", summary = "On the island of Caer Darrow lies Scholomance - a school that serves as a stronghold for the Scourge.  Our enemy dwells within, safely allowed to pursue research that strengthens their power.  A door bars the way, and try as we might no entry is to be had without a proper key.$B$BApothecary Dithers is well versed on Scholomance, and has an idea how to obtain a key.  You have proved your value to me as someone who can get things done; I now entrust this task to you.  Speak with him on this matter." },
            { ids = { 964 }, name = "Skeletal Fragments", level = 57, zone = "Tirisfal Glades", giver = "Apothecary Dithers", giverMap = 1420, giverX = 83.3, giverY = 69.2, ender = "Apothecary Dithers", enderMap = 1420, enderX = 83.3, enderY = 69.2, objective = "Bring 15 Skeletal Fragments to Apothecary Dithers at the Bulwark, Western Plaguelands.", summary = "The key to Scholomance is called a Skeleton Key.  It must be forged from the remains of a skeleton - several actually - and hardened by only the strongest of metals within a suitable mold.  A signet of power from a being who naturally can open the portal to Scholomance will make the key ultimately function.$B$BFirst thing's first though, $N.  We'll need skeletal fragments for the key's forging.  Skeletons inside Andorhal should yield what we need, but the ones outside the walls might work too." },
            { ids = { 5514 }, name = "Mold Rhymes With...", level = 57, zone = "Tirisfal Glades", giver = "Apothecary Dithers", giverMap = 1420, giverX = 83.3, giverY = 69.2, ender = "Krinkle Goodsteel", enderMap = 1446, enderX = 51.5, enderY = 28.8, objective = "Bring the Imbued Skeletal Fragments and 15 gold coins to Krinkle Goodsteel in Gadgetzan.", summary = "The goblin you will need to speak with is Krinkle Goodsteel.  He peddles his skills to the highest bidder in Gadgetzan, within the Tanaris desert.  He'll likely be the only one who can produce the mold we need, and his services won't come cheap.  We now ask for you to dig deep by footing whatever fee he will charge.$B$BI'm an apothecary, not a banker.  If I had gold lying around, I certainly wouldn't be here.$B$BI guess I said the quiet part out loud again.  Oops.$B$BGadgetzan awaits you!  Good luck!" },
            { ids = { 5802 }, name = "Fire Plume Forged", level = 57, zone = "Tanaris", giver = "Krinkle Goodsteel", giverMap = 1446, giverX = 51.5, giverY = 28.8, ender = "Apothecary Dithers", enderMap = 1420, enderX = 83.3, enderY = 69.2, objective = "Take the Skeleton Key Mold and 2 Thorium Bars to the top of Fire Plume Ridge in Un'Goro Crater.  Use the Skeleton Key Mold by the lava lake to forge the Unfinished Skeleton Key.$B$BBring the Unfinished Skeleton Key to Apothecary Dithers at the Bulwark, Western Plaguelands.", summary = "You need two bars of thorium and a powerfully hot heat source to forge the key stem.  You're on your own for the thorium, but I can help with the heat.$B$BTo our west in Un'Goro Crater is Fire Plume Ridge - a simmering volcano.  The lava lake up top is hot enough to fuse thorium and bone together.  Your gold has bought you a mold that simply requires you to dip it in the lake up top; the lava will take care of the rest.$B$BThat's it on my end.  To finish your key, you'll need to talk to Dithers again." },
            { ids = { 5804 }, name = "Araj's Scarab", level = 60, zone = "Tirisfal Glades", giver = "Apothecary Dithers", giverMap = 1420, giverX = 83.3, giverY = 69.2, ender = "Apothecary Dithers", enderMap = 1420, enderX = 83.3, enderY = 69.2, objective = "Destroy the four Scourge Summoning Crystals inside Andorhal to call forth Araj the Summoner.  Destroy Araj the Summoner and bring Araj's Scarab to Apothecary Dithers at the Bulwark, Western Plaguelands.", summary = "Araj the Summoner lords over Andorhal from an obfuscated vantage.  We know that he was the former leader of Scholomance before claiming the city as his own.  To finish the key, we will need his signet - called a scarab - mounted as the head of the key.$B$BIn the city are four summoning crystals, one in each tower you marked for us previously.  Destroy all four crystals and break his hold on the city, drawing him into the open.  Once destroyed, seize his scarab from his fallen phylactery!" },
            { ids = { 5511 }, name = "The Key to Scholomance", level = 60, zone = "Tirisfal Glades", giver = "High Executor Derrington", giverMap = 1420, giverX = 83.1, giverY = 68.9, ender = "High Executor Derrington", enderMap = 1420, enderX = 83.1, enderY = 68.9 },
        },
    },
    {
        id = "q8251",
        name = "Destroy Morphaz",
        zone = "Azshara",
        minLevel = 50,
        maxLevel = 52,
        importance = 2,
        kind = "class",
        classes = { 8 },
        quests = {
            { ids = { 8251 }, name = "Magic Dust", level = 52, zone = "Azshara", giver = "Archmage Xylem", giverMap = 1447, giverX = 29.2, giverY = 40.2, ender = "Archmage Xylem", enderMap = 1447, enderX = 29.2, enderY = 40.2, objective = "Bring 10 Glittering Dust to Archmage Xylem.", summary = "The blood elves in Azshara have developed a method for pulverizing the magical items they acquire.  This glittering dust they produce differs from the components normally acquired by a disenchantment spell.$b$bWhen I sent my apprentice to trade for the dust, he was killed without hesitation.  For that, they must pay.$b$bThe time for talk is over, $N.  Find the blood elves along the cliffs of Azshara and use more \"persuasive\" methods to acquire their glittering dust." },
            { ids = { 8252 }, name = "The Siren's Coral", level = 52, zone = "Azshara", giver = "Archmage Xylem", giverMap = 1447, giverX = 29.2, giverY = 40.2, ender = "Archmage Xylem", enderMap = 1447, enderX = 29.2, enderY = 40.2, objective = "Collect 6 Enchanted Coral and return them to Archmage Xylem.", summary = "Take a look around you.  The ruins and beaches are overrun with spitelash.  Recently, the wretched creatures have learned to recognize the rare components indigenous to Azshara.$b$bSpecifically, I speak of enchanted coral -- they are drawn to it by reasons unknown to me.  Now there is little coral left in the bay, and it is vital to my research.  I need you to separate some enchanted coral from the spitelash sirens and bring it to me." },
            { ids = { 8253 }, name = "Destroy Morphaz", level = 52, zone = "Azshara", giver = "Archmage Xylem", giverMap = 1447, giverX = 29.2, giverY = 40.2, ender = "Archmage Xylem", enderMap = 1447, enderX = 29.2, enderY = 40.2, objective = "Retrieve the Arcane Shard from Morphaz and return to Archmage Xylem.", summary = "There is a green drake deep in the sunken temple of Atal'Hakkar by the name of Morphaz.$b$bYears ago, he overwhelmed me in a bold ambush and consumed my apprentice whole.  While the loss of an apprentice is not unknown to me, this particular one carried an arcane shard of unsurpassed size and quality.$b$bYou must gather powerful allies and delve into the temple.  Destroy Morphaz and recover the arcane shard from his ageless stomach." },
        },
    },
    {
        id = "q8254",
        name = "Blood of Morphaz",
        zone = "Thunder Bluff",
        minLevel = 50,
        maxLevel = 52,
        importance = 2,
        kind = "class",
        classes = { 5 },
        quests = {
            { ids = { 8254 }, name = "Cenarion Aid", level = 52, zone = "Thunder Bluff", giver = "Malakai Cross", giverMap = 1456, giverX = 24.6, giverY = 22.6, ender = "Ogtinc", enderMap = 1447, enderX = 42.4, enderY = 42.6, objective = "Seek out Ogtinc in Azshara.", summary = "It is the way of the divine to help those in need.  The how is insignificant -- only the why matters.$b$bThe Cenarion Circle has such a need.  Speak with Ogtinc to lend aid to their plight.  He resides atop the cliffs to the northeast of the Ruins of Eldarath in Azshara." },
            { ids = { 8255 }, name = "Of Coursers We Know", level = 52, zone = "Azshara", giver = "Ogtinc", giverMap = 1447, giverX = 42.4, giverY = 42.6, ender = "Ogtinc", enderMap = 1447, enderX = 42.4, enderY = 42.6, objective = "Acquire 4 Healthy Courser Glands and bring them to Ogtinc in Azshara.  Ogtinc resides atop the cliffs northeast the Ruins of Eldarath.", summary = "The mosshoof coursers of Azshara are magnificent animals who once lived in Felwood.  They naturally resist disease and poison, and were unaffected by the corruption there.  In their ancestral wisdom, they simply chose to leave that sickened place.$b$bIt saddens my heart, but I must ask you to hunt these mighty beasts for me.  Gather four courser glands as the first ingredient for a restorative salve -- a salve we will use to heal Felwood." },
            { ids = { 8256 }, name = "The Ichor of Undeath", level = 52, zone = "Azshara", giver = "Ogtinc", giverMap = 1447, giverX = 42.4, giverY = 42.6, ender = "Ogtinc", enderMap = 1447, enderX = 42.4, enderY = 42.6, objective = "Acquire an Ichor of Undeath for Ogtinc in Azshara.  Ogtinc resides atop the cliffs northeast the Ruins of Eldarath.", summary = "For this restorative salve, you must use a simple formula: one part poison, two parts cure.  You have acquired one cure, now you must gather the poison.$b$bPowerful undead, such as the lingering highborne who wander the Ruins of Eldarath, are sometimes so infused with evil that it coalesces into a sickly greenish goo.  To the living, this substance is known as ichor of undeath.$b$bDue to the potency of this vile element, I require only a single ichor." },
            { ids = { 8257 }, name = "Blood of Morphaz", level = 52, zone = "Azshara", giver = "Ogtinc", giverMap = 1447, giverX = 42.4, giverY = 42.6, ender = "Greta Mosshoof", enderMap = 1448, enderX = 51.2, enderY = 82.1, objective = "Kill Morphaz in the sunken temple of Atal'Hakkar, and return his blood to Greta Mosshoof in Felwood.  The entrance to the sunken temple can be found in the Swamp of Sorrows.", summary = "Now the last part, the second cure.$b$bThe green drake Morphaz is known to be immune to all forms of poison and disease -- many druids died to bring us this information.  There is no doubt his blood is potent for our needs.$b$bA courier from the Cenarion Circle will take the parts you have already collected while you gather the last.  Summon your allies and seek out the drake's lair in the sunken temple of Atal'Hakkar.  Bring his blood to Greta Mosshoof in Felwood." },
        },
    },
    {
        id = "q8410",
        name = "Da Voodoo",
        zone = "Thunder Bluff",
        minLevel = 50,
        maxLevel = 52,
        importance = 2,
        kind = "class",
        classes = { 7 },
        quests = {
            { ids = { 8410 }, name = "Elemental Mastery", level = 50, zone = "Thunder Bluff", giver = "Beram Skychaser", giverMap = 1456, giverX = 22.0, giverY = 18.8, ender = "Bath'rah the Windwatcher", enderMap = 1416, enderX = 80.5, enderY = 66.9, objective = "Collect a sample of air, fire, earth and water for Bath'rah the Windwatcher.", summary = "Bath'rah the Windwatcher has sent out a summons for a shaman of your wisdom.  He requests you bring a sample of each of the elements to show you are ready.$b$bTo find Bath'rah, go to the river east of Tarren Mill.  Follow the river north until you come across the ruins where Bath'rah resides." },
            { ids = { 8412 }, name = "Spirit Totem", level = 52, zone = "Alterac Mountains", giver = "Bath'rah the Windwatcher", giverMap = 1416, giverX = 80.5, giverY = 66.9, ender = "Bath'rah the Windwatcher", enderMap = 1416, enderX = 80.5, enderY = 66.9, objective = "Bring the pieces for the spirit totem to Bath'rah the Windwatcher.", summary = "The elemental spirits of this place don't be likin' me any more.$b$bYou know about the totems more than any, and I be needin' a spirit totem to protect me.  We already got the elements, now we need somethin' more with more nature.  More primal.$b$bIn the Western Plaguelands you can kill bears for claws and spiders for their eyes.  The carrion birds eat everything, so they might have either one." },
            { ids = { 8413 }, name = "Da Voodoo", level = 52, zone = "Alterac Mountains", giver = "Bath'rah the Windwatcher", giverMap = 1416, giverX = 80.5, giverY = 66.9, ender = "Bath'rah the Windwatcher", enderMap = 1416, enderX = 80.5, enderY = 66.9, objective = "Bring the voodoo feathers to Bath'rah the Windwatcher.", summary = "The spirit totem just isn't enough.  We be needin' some voodoo magic to make it work jus' right.$b$bThe trolls in the sunken temple have feathers strong with voodoo magics.  Go there and kill Gasher, Mijan, Zolo, Hukku, Zul'lor, and Loro.  Then we have magic enough for a real spirit totem." },
        },
    },
    {
        id = "q5021",
        name = "Good Luck Charm",
        zone = "Western Plaguelands",
        minLevel = 50,
        maxLevel = 54,
        importance = 1,
        kind = "world",
        quests = {
            { ids = { 5021 }, name = "Better Late Than Never", level = 52, zone = "Western Plaguelands", giver = "Janice Felstone", giverMap = 1422, giverX = 38.4, giverY = 54.0, ender = "Janice's Parcel", enderMap = 1422, enderX = 38.7, enderY = 55.2, objective = "The ramblings of the ghostly woman indicated that she needed a package delivered.  She claimed that it was where her horse was.  As to where the horse is or where the package was to be delivered - the ghost remains incomprehensible.", summary = "\"The package must be delivered... delivered before I'm trapped here!\"$B$BThe cries of a panicked woman feel almost like a whisper floating through the house.  Cowered in the upstairs corner is the apparition of a woman.  She does not seem to be fully cognizant of her surroundings, and she is only vaguely aware of you.$B$B\"Are you here to deliver my package?  Please, before it gets much worse!  I was going to ride out of here.  It should still be by my horse... or am I too late?\"" },
            { ids = { 5023 }, name = "Better Late Than Never", level = 52, zone = "Western Plaguelands", giver = "Janice's Parcel", giverMap = 1422, giverX = 38.7, giverY = 55.2, ender = "Royal Overseer Bauhaus", enderMap = 1458, enderX = 69.8, enderY = 43.2, objective = "Check with the Royal Overseers of the Undercity to learn the whereabouts of a Jeremiah Felstone.  There is usually a census officer located near guild and tabard registration.", summary = "You pick up the package, wiping off a small layer of dust and grime that had settled on it.  It is addressed in a hurried hand to a Jeremiah Felstone of Lordaeron; the delivery of the package is dated for well over four years ago.$B$BThough it is unclear if Jeremiah Felstone is even alive, it is widely known that the Undercity, formerly known as Lordaeron, keeps records on the populace of the city.  This is handled through the Royal Overseers of the Undercity Census." },
            { ids = { 5049 }, name = "The Jeremiah Blues", level = 52, zone = "Undercity", giver = "Royal Overseer Bauhaus", giverMap = 1458, giverX = 69.8, giverY = 43.2, ender = "Jeremiah Payson", enderMap = 1458, enderX = 67.6, enderY = 44.2, objective = "Find Jeremiah Payson in the Undercity and see if he is in fact Jeremiah Felstone.  If he is, then perhaps he'd like the package Janice Felstone made for him.", summary = "From the evidence I am able to muster, the person you seek - and the intended recipient of the parcel - is Jeremiah Payson, the Undercity cockroach vendor.$B$BI've always been of the opinion that it takes a special gift to sell... cockroaches.  No doubt you are on quite the epic sojourn now, mighty $c.  I will leave you to your world-shaping endeavors.  Allow me, however, to be a part of your magnum opus and reveal that he is located near the bank, suitably groveling under one of the walkways." },
            { ids = { 5050 }, name = "Good Luck Charm", level = 52, zone = "Stormwind City", giver = "Ol' Emma", giverMap = 1453, giverX = 60.2, giverY = 57.0, ender = "Janice Felstone", enderMap = 1422, enderX = 38.4, enderY = 54.0, objective = "Return to Janice Felstone in Western Plaguelands her Good Luck Half-Charm.", summary = "It would seem that I was wrong about you $N, and for that I owe you an apology.  My sister sent me a number of personal effects, including humorously enough the deed to the Felstone farm.  I think I'll pass on reclaiming it right now.$B$BIf my sister's spirit remains tethered to the farm and cannot rest, please... could you return this to her?  It is half of a good luck charm she had, with her husband having the other half.$B$BMaybe her knowing I have these things will now put her soul to rest." },
            { ids = { 5051 }, name = "Two Halves Become One", level = 54, zone = "Western Plaguelands", giver = "Janice Felstone", giverMap = 1422, giverX = 38.4, giverY = 54.0, ender = "Janice Felstone", enderMap = 1422, enderX = 38.4, enderY = 54.0, objective = "Locate the other half of the Good Luck Charm somewhere on the Felstone Farm in Western Plaguelands and reassemble it.$B$BGive the Good Luck Charm to Janice Felstone on the Felstone Farm, Western Plaguelands.", summary = "The ramblings of the poor ghost continue:$B$B\"I'm so cold, John.  Bring me your charm, and we'll be together!  Quickly John, before the plague comes to change us into hideous beasts!  I can't see you John... but I know you're near.  I feel you near me.\"$B$BPerhaps if the second half of the charm was found and reassembled, this would constitute what the spirit of Janice Felstone is seeking." },
        },
    },
    {
        id = "q4133",
        name = "Lost Thunderbrew Recipe",
        zone = "Undercity",
        minLevel = 50,
        maxLevel = 55,
        importance = 1,
        kind = "dungeon",
        quests = {
            { ids = { 4133 }, name = "Vivian Lagrave", level = 55, zone = "Undercity", giver = "Apothecary Zinge", giverMap = 1458, giverX = 50.1, giverY = 68.0, ender = "Shadowmage Vivian Lagrave", enderMap = 1418, enderX = 2.9, enderY = 47.8, objective = "Speak with Shadowmaster Vivian Lagrave in Kargath.", summary = "Shadowmaster Vivian Lagrave is in need of your services.  She is in the Badlands, in the orcish outpost of Kargath, pursuing rumors of a certain brew made by the Dark Iron dwarves of Blackrock Depths.$B$BSpeak with Vivian.  She awaits you." },
            { ids = { 4134 }, name = "Lost Thunderbrew Recipe", level = 55, zone = "Badlands", giver = "Shadowmage Vivian Lagrave", giverMap = 1418, giverX = 2.9, giverY = 47.8, ender = "Shadowmage Vivian Lagrave", enderMap = 1418, enderX = 2.9, enderY = 47.8, objective = "Bring the Lost Thunderbrew Recipe to Vivian Lagrave in Kargath.", summary = "It is rumored that the Dark Iron Hurley Blackbreath has stolen a recipe for ale.  This ale, Thunderbrew Lager, is said to infuse its imbiber with great strength and courage.  We wish to study the drink.  Perhaps, we will find other applications for its virtues... applications more in line with Forsaken objectives.$B$BDelve into Blackrock Depths, find Hurley, take from him the recipe for Thunderbrew lager and bring it to me.$B$BAnd to find him, you may have to entice him by threatening his precious ale." },
        },
    },
    {
        id = "q5543",
        name = "In Dreams",
        zone = "Eastern Plaguelands",
        minLevel = 52,
        maxLevel = 60,
        importance = 3,
        kind = "dungeon",
        quests = {
            { ids = { 5542 }, name = "Demon Dogs", level = 56, zone = "Eastern Plaguelands", giver = "Tirion Fordring", giverMap = 1423, giverX = 5.2, giverY = 35.6, ender = "Tirion Fordring", enderMap = 1423, enderX = 5.2, enderY = 35.6, objective = "Slay 20 Plaguehound Runts, 5 Plaguehounds and 5 Frenzied Plaguehounds. Return to Tirion Fordring when the task is complete.", summary = "If you are going to remain here, I ask only that you earn your keep. We have many nuisances that could use some 'discipline.'$B$BYou can start with the Plaguehounds and their runts.$B$BI cannot offer much in return, but you are guaranteed a warm meal and some conversation should you succeed." },
            { ids = { 5543 }, name = "Blood Tinged Skies", level = 56, zone = "Eastern Plaguelands", giver = "Tirion Fordring", giverMap = 1423, giverX = 5.2, giverY = 35.6, ender = "Tirion Fordring", enderMap = 1423, enderX = 5.2, enderY = 35.6, objective = "Slay 30 Plaguebats and return to Tirion Fordring.", summary = "Woe to those that foolishly wander into the Plaguelands. All manner of foulness inhabit these woods - from the fanatical Scarlet Crusade, who will kill any that do not bear the mark of the Crusade, to the murderous Scourge, who only look to bolster their numbers by adding more undead to their ranks.$B$BEven the wildlife have been transformed into rapacious, man eating beasts. I ask that you destroy those that would strike from the skies: The Plaguebats." },
            { ids = { 5544 }, name = "Carrion Grubbage", level = 56, zone = "Eastern Plaguelands", giver = "Tirion Fordring", giverMap = 1423, giverX = 5.2, giverY = 35.6, ender = "Tirion Fordring", enderMap = 1423, enderX = 5.2, enderY = 35.6, objective = "Seek out the Carrion Grubs and Devourers of the region. Slay them and harvest their meat. Return to Tirion Fordring when you have gathered 15 Slabs of Carrion Worm Meat.", summary = "My food supplies are running low, $r. I am ashamed to admit that I might not have enough food to share with you.$B$BCould you assist an old man with a simple task? Around here, the only manner of beast unaffected by the ravages of the Plague are the Carrion worms. While rather bland in taste, the meat of the worms can easily be preserved to last for months. I will need several hundred pounds to restock for the coming winter!" },
            { ids = { 5742 }, name = "Redemption", level = 56, zone = "Eastern Plaguelands", giver = "Tirion Fordring", giverMap = 1423, giverX = 5.2, giverY = 35.6, ender = "Tirion Fordring", enderMap = 1423, enderX = 5.2, enderY = 35.6, objective = "Listen to what Tirion Fordring has to say.", summary = "You have worked hard, friend. Rest your weary bones and allow me to properly introduce myself." },
            { ids = { 5781 }, name = "Of Forgotten Memories", level = 57, zone = "Eastern Plaguelands", giver = "Tirion Fordring", giverMap = 1423, giverX = 5.2, giverY = 35.6, ender = "Tirion Fordring", enderMap = 1423, enderX = 5.2, enderY = 35.6, objective = "Travel to the Undercroft - at the southernmost section of the Eastern Plaguelands - and recover Taelan's Hammer. Return to Tirion Fordring upon completion of your objective.", summary = "To help Taelan regain what he has lost, you must gather items from his past.$B$BThe first such item is a toy that I gave to him on his 7th birthday. It was his most cherished possession: A miniature war hammer; an exact replica of my very own.$B$BAfter I was banished for treason, his mother told him that I had died. He was taken to my false grave at the Undercroft, where he buried the hammer along with my memory - forever.$B$BYou must venture to the Undercroft and recover Taelan's hammer." },
            { ids = { 5845 }, name = "Of Lost Honor", level = 58, zone = "Eastern Plaguelands", giver = "Tirion Fordring", giverMap = 1423, giverX = 5.2, giverY = 35.6, ender = "Tirion Fordring", enderMap = 1423, enderX = 5.2, enderY = 35.6, objective = "Travel to Northdale, in the northeastern region of the Eastern Plaguelands, and recover the Symbol of Lost Honor. Return to Tirion Fordring upon completion of your objective.", summary = "The Order of the Silver Hand was utterly decimated when Uther was slain.$B$BThe boy held out for as long as he could. Pushed to the war torn hamlet of Northdale, he made his final stand.$B$BWere any of the Order left alive, he thought - and did it matter?$B$BIt was with that thought that Taelan threw down the standard of the Order and renounced all that he had known. His honor left upon the blood soaked ground of Northdale.$B$BYou must travel to Northdale and recover that symbol of lost honor." },
            { ids = { 5846 }, name = "Of Love and Family", level = 58, zone = "Eastern Plaguelands", giver = "Tirion Fordring", giverMap = 1423, giverX = 5.2, giverY = 35.6, ender = "Artist Renfray", enderMap = 1422, enderX = 65.8, enderY = 75.4, objective = "Travel to island of Caer Darrow, in the south-central region of the Plaguelands, and look for any clues as to the whereabouts of the painting.", summary = "When Taelan was a child, we would oft visit Caer Darrow on family excursions. On our last visit, an artist by the name of Renfray painted a portrait of us poised along the beachside. It is my fondest memory of both Taelan and Karandra. For it was at that moment, with my wife and son in my arms, that I felt a bond of love and family that I would never know again.$B$BIf this painting still exists, you must find it.$B$BTravel to the ruined island of Caer Darrow and see if the painting or the artist remain." },
            { ids = { 5848 }, name = "Of Love and Family", level = 60, zone = "Western Plaguelands", giver = "Artist Renfray", giverMap = 1422, giverX = 65.8, giverY = 75.4, ender = "Tirion Fordring", enderMap = 1423, enderX = 5.2, enderY = 35.6, objective = "Travel to Stratholme, in the northern part of the Plaguelands. It is in the Scarlet Bastion that you will find the painting 'Of Love and Family,' hidden behind another painting depicting the twin moons of our world.$B$BReturn the painting to Tirion Fordring.", summary = "The painting... It hung on the wall of my workshop - inside the Order's barracks - for years.$B$BAfter Tirion's trial was over, I knew that I could no longer keep the painting visible. I hid it in a place that they would never think to look.$B$BTravel to Stratholme and make your way deep inside what is now the Scarlet Bastion, search for a painting of our twin moons. Chip away at the paint until you uncover my master work, 'Of Love and Family.'$B$BMay the Light guide your actions." },
            { ids = { 5861 }, name = "Find Myranda", level = 60, zone = "Eastern Plaguelands", giver = "Tirion Fordring", giverMap = 1423, giverX = 5.2, giverY = 35.6, ender = "Myranda the Hag", enderMap = 1422, enderX = 50.8, enderY = 77.8, objective = "Travel to Uther's Tomb, located in the southern Plaguelands. Show Myranda the Hag Tirion's Gift.", summary = "$N, you have done all that I have asked thus far. Only one step remains in your quest of redemption.$B$BYou must deliver the items you have collected to Taelan. Unfortunately, Taelan and his Scarlet Crusaders will attack you on sight.$B$BThere is only one way in which to deliver my message and that is through a guise of deception.$B$BTo the south you will find Uther's tomb. An old and trusted confidant of mine, Myranda, now resides there - seek her out. Show her the items and she will assist you." },
            { ids = { 5862 }, name = "Scarlet Subterfuge", level = 60, zone = "Western Plaguelands", giver = "Myranda the Hag", giverMap = 1422, giverX = 50.8, giverY = 77.8, ender = "Highlord Taelan Fordring", enderMap = 1422, enderX = 42.0, enderY = 14.8, objective = "Speak to Myranda to gain the Scarlet Illusion. Travel to Hearthglen while under the Scarlet Illusion and deliver Tirion's Gift to Highlord Taelan Fordring.$B$BHearthglen is to the north, Taelan should be inside of Mardenholde Keep.", summary = "I am what you would call, an illusionist. Though I may be able to create an illusion to allow you entry into Hearthglen, be warned; my powers have their limitations.$B$BShould you travel too far from these lands, the effects of the illusion will cease. The spell itself takes a great amount of concentration and power from me, and thus, I can only sustain the effect for a short time.$B$BSpeak to me again when you are ready." },
            { ids = { 5944 }, name = "In Dreams", level = 60, zone = "Western Plaguelands", giver = "Highlord Taelan Fordring", giverMap = 1422, giverX = 42.0, giverY = 14.8, ender = "Tirion Fordring", enderMap = 1423, enderX = 5.2, enderY = 35.6, objective = "Escort Taelan Fordring out of Hearthglen.", summary = "For so long, I have been a puppet of the Grand Crusader. What reason was there to fight against what the Scarlet Crusade had become? It has been decades, yet the memories of my father; those precious memories, they are what have kept me alive.$B$BI have dreams, stranger. In these dreams my father is with me. He stands proudly at my side as I am inducted into the Order. We battle legion of Scourge, side by side. We bring honor to the Alliance, to Lordaeron.$B$BI want not to dream anymore.$B$BTake me to him." },
        },
    },
    {
        id = "q5083",
        name = "Words of the High Chief",
        zone = "Winterspring",
        minLevel = 52,
        maxLevel = 59,
        importance = 1,
        kind = "world",
        quests = {
            { ids = { 5083 }, name = "Winterfall Firewater", level = 56, zone = "Winterspring", ender = "Donova Snowden", enderMap = 1452, enderX = 31.3, enderY = 45.2, objective = "Bring the Empty Firewater Flask to Donova Snowden in Winterspring.", summary = "This vial that you picked up from the Winterfall furbolg is empty, but you can detect a few drops of a strange green liquid inside; it almost glows.$B$BIs it something important?$B$BDonova Snowden would probably be able to tell you more, since she has been camped by the hot springs in Winterspring for some time now." },
            { ids = { 5084 }, name = "Falling to Corruption", level = 56, zone = "Winterspring", giver = "Donova Snowden", giverMap = 1452, giverX = 31.3, giverY = 45.2, ender = "Deadwood Cauldron", enderMap = 1448, enderX = 60.2, enderY = 5.8, objective = "Search the Deadwood furbolg camp in northern Felwood for a clue.", summary = "This greenish liquid... it reminds me a bit of the sludge I saw when traveling through Felwood. And I have seen some Winterfall Runners passing into Timbermaw... Perhaps these things have something to do with the flask you found, $N.$B$BThere is a large group of furbolg just past Timbermaw Hold, in Felwood. Called the Deadwood tribe, they have been corrupted and driven mad by the fel. Why don't you look around there and see if you can find any evidence of dealings between the Winterfall and the Deadwood?" },
            { ids = { 5085 }, name = "Mystery Goo", level = 56, zone = "Felwood", giver = "Deadwood Cauldron", giverMap = 1448, giverX = 60.2, giverY = 5.8, ender = "Donova Snowden", enderMap = 1452, enderX = 31.3, enderY = 45.2, objective = "Report back to Donova Snowden with your findings.", summary = "The greenish substance inside the cauldron appears to be similar to what you found in the flask. This strange gooey stuff could be as corrupted as the furbolg that created it...$B$BIf the Winterfall furbolg are using it, does this mean that they will soon be as corrupted as the Deadwood tribe?$B$BIt would be best to report back to Donova with your findings, along with a sample of the liquid in the cauldron." },
            { ids = { 5086 }, name = "Toxic Horrors", level = 56, zone = "Winterspring", giver = "Donova Snowden", giverMap = 1452, giverX = 31.3, giverY = 45.2, ender = "Donova Snowden", enderMap = 1452, enderX = 31.3, enderY = 45.2, objective = "Collect 3 Toxic Horror Droplets for Donova Snowden in Winterspring.", summary = "I've studied the sample you returned with, and while I can't say for sure, I believe it contains traces of toxic elements. However, the only way to know for sure is to gather some as a comparison.$B$BI believe that the Deadwood furbolg may be gathering these elements from other corrupted creatures in Felwood; in particular, the elementals living in the Irontree Woods, called toxic horrors.$B$BCollect a few samples for me to compare, but be careful -- it's very dangerous there!" },
            { ids = { 5087 }, name = "Winterfall Runners", level = 57, zone = "Winterspring", giver = "Donova Snowden", giverMap = 1452, giverX = 31.3, giverY = 45.2, ender = "Donova Snowden", enderMap = 1452, enderX = 31.3, enderY = 45.2, objective = "Find the Winterfall Runners and stop them from delivering their shipment to Winterfall Village.", summary = "Very interesting, $N...$B$BWhen this toxic substance is mixed with the water from the hot springs, it loses its toxicity, only retaining the ability to temporarily affect those that ingest it. This must be why the Winterfall protect the hot springs so fervently -- they need them to purify their firewater.$B$BWe need to stop this -- cut off contact between the Winterfall and the Deadwood. A group of runners walks the distance between their village and Felwood. Find and defeat them, and steal their shipment." },
            { ids = { 5123 }, name = "The Final Piece", level = 59, zone = "Winterspring", ender = "Donova Snowden", enderMap = 1452, enderX = 31.3, enderY = 45.2, objective = "Bring the Crudely-written Log to Donova Snowden in Winterspring.", summary = "The log you found on the high chief looks extensive, but after looking through a couple of the pages, you find that you cannot read the text. The markings are so crude and poorly-formed that you are not sure if anyone would be able to read them.$B$BBut perhaps Donova will be able to tell you what it says... " },
            { ids = { 5128 }, name = "Words of the High Chief", level = 59, zone = "Winterspring", giver = "Donova Snowden", giverMap = 1452, giverX = 31.3, giverY = 45.2, ender = "Kelek Skykeeper", enderMap = 1448, enderX = 51.1, enderY = 81.8, objective = "Take the Crudely-written Log to Kelek Skykeeper in southern Felwood.", summary = "The Winterfall are no longer a threat to me, but if you still want to find out what was driving the furbolg to create and consume this strange firewater, I think you should seek out Kelek Skykeeper.$B$BHe is part of a group known as the Emerald Circle, druids that are committed to their work in Felwood, healing the land from the corruption.$B$BKelek has much experience with the furbolgs in Felwood, and may be able to tell you more about the log.$B$BThank you, again, $N." },
        },
    },
    {
        id = "q5054",
        name = "Brumeran of the Chillwind",
        zone = "Winterspring",
        minLevel = 53,
        maxLevel = 60,
        importance = 1,
        kind = "world",
        quests = {
            { ids = { 5054 }, name = "Ursius of the Shardtooth", level = 56, zone = "Winterspring", giver = "Storm Shadowhoof", giverMap = 1452, giverX = 61.9, giverY = 38.4, ender = "Storm Shadowhoof", enderMap = 1452, enderX = 61.9, enderY = 38.4, objective = "Storm Shadowhoof at Bloodvenom Post in Felwood wants you to kill Ursius.", summary = "In the snowy mountains of Winterspring, a skilled hunter stalks his prey... I speak of Ursius of the shardtooth bears, an agile and clever beast.$B$BI send you now against him. He roams the sloping hills to the west of Everlook. Find and hunt him, before he discovers your intent.$B$BAll that have gone up against Ursius have quickly found themselves to be the prey, and he, the hunter. Stay on your guard." },
            { ids = { 5055 }, name = "Brumeran of the Chillwind", level = 58, zone = "Winterspring", giver = "Storm Shadowhoof", giverMap = 1452, giverX = 61.9, giverY = 38.4, ender = "Storm Shadowhoof", enderMap = 1452, enderX = 61.9, enderY = 38.4, objective = "Storm Shadowhoof at Bloodvenom Post in Felwood wants you to kill Brumeran.", summary = "Swift, and clever, Brumeran glides silently across the snowy landscape of southern Winterspring. But do not let her graceful appearance convince you that she is harmless. All that cross her pay considerably, and often with their own lives.$B$BSeek out Brumeran of the chillwind among the chimera. Defeat her, then return again to me." },
            { ids = { 5056 }, name = "Shy-Rotam", level = 60, zone = "Winterspring", giver = "Storm Shadowhoof", giverMap = 1452, giverX = 61.9, giverY = 38.4, ender = "Storm Shadowhoof", enderMap = 1452, enderX = 61.9, enderY = 38.4, objective = "Storm Shadowhoof at Bloodvenom Post in Felwood wants you to defeat Shy-Rotam.", summary = "In northern Winterspring, great cats assemble around a large landmark called Frostsaber Rock. The leader of these cats is known by the name Shy-Rotam. Defeating the matriarch of the frostsabers would grant you much respect in the eyes of your fellow $R.$B$BGo again to Winterspring, and once there, gather sacred meat from the frostsabers. Find the stone of Shy-Rotam, and place it there. Placing the meat of her kin before her will summon Shy-Rotam, in anger.$B$BBe ready for her fury, and defeat her." },
            { ids = { 5057 }, name = "Past Endeavors", level = 60, zone = "Winterspring", giver = "Storm Shadowhoof", giverMap = 1452, giverX = 61.9, giverY = 38.4, ender = "Storm Shadowhoof", enderMap = 1452, enderX = 61.9, enderY = 38.4, objective = "Bring Storm Shadowhoof's Marker to Melor Stonehoof in Thunder Bluff.", summary = "Before you spoke to me, $N, I had heard of your endeavors... that you had an unyielding desire to prove yourself, that you had an exceptional ability as a $c, and I now know these things to be the truth.$B$BThose that excel as you do are worthy of recognition. Take this marker to a friend of mine in Thunder Bluff named Melor Stonehoof. I'm sure he will remember you, and what you accomplished so long ago. Speak to him of you recent victories, and do not ever forget what you have accomplished today." },
        },
    },
    {
        id = "q6022",
        name = "The Crimson Courier",
        zone = "Eastern Plaguelands",
        minLevel = 54,
        maxLevel = 60,
        importance = 2,
        kind = "world",
        quests = {
            { ids = { 6022 }, name = "To Kill With Purpose", level = 58, zone = "Eastern Plaguelands", giver = "Nathanos Blightcaller", giverMap = 1423, giverX = 22.2, giverY = 63.5, ender = "Nathanos Blightcaller", enderMap = 1423, enderX = 22.2, enderY = 63.5, objective = "Travel to Corin's Crossing to the east and slaughter the Scourge that inhabit the town. Collect 7 pieces of Living Rot in under 10 minutes. Use the Mortar and Pestle to grind the Living Rot into Coagulated Rot.", summary = "You kill with purpose while you remain on my stead.$B$BYour first task is to feed my hounds.$B$BTake this mortar and pestle and travel to Corin's Crossing. Once there, you will find a robust selection of Scourge to slaughter. From their fresh carcasses I need living rot. Take that living rot and grind it up in the mortar, then let it sit to coagulate. Bring the coagulated rot back here.$B$BAnd imbecile, realize that living rot from the undead doesn't remain 'living' for very long. You must kill quickly!" },
            { ids = { 6042 }, name = "Un-Life's Little Annoyances", level = 58, zone = "Eastern Plaguelands", giver = "Nathanos Blightcaller", giverMap = 1423, giverX = 22.2, giverY = 63.5, ender = "Nathanos Blightcaller", enderMap = 1423, enderX = 22.2, enderY = 63.5, objective = "Slay 20 Noxious Plaguebats and 10 Monstrous Plaguebats. Return to Nathanos Blightcaller when you are finished.", summary = "You cannot take two steps off of this farm without running into one of those obnoxious bats. I want to be able to take the hounds out and slaughter Scourge without being accosted by any damned, dirty bats. Obviously, I have better things to do with my time than mindlessly kill bats day in and day out. You, however, do not.$B$BWhat? Your training? This is your training! Now get out of my sight and don't come back until you've killed a fair number of those winged demons. Don't disappoint me." },
            { ids = { 6133 }, name = "The Ranger Lord's Behest", level = 60, zone = "Eastern Plaguelands", giver = "Nathanos Blightcaller", giverMap = 1423, giverX = 22.2, giverY = 63.5, ender = "Nathanos Blightcaller", enderMap = 1423, enderX = 22.2, enderY = 63.5, objective = "Travel to the northern borders of the Eastern Plaguelands and recover the Quel'Thalas Registry. The item is somewhere in the Quel'Lithien lodge.$B$BYou must also slay 8 Rangers, 8 Pathstriders, and 8 Woodsmen.", summary = "The high elves of the Quel'Lithien lodge possesses something that belongs to me, $c: A document detailing my life as a mortal.$B$BBefore you ask; no, you most certainly are not privy to such information. Just do as I tell you, worm: Recover the registry.$B$BAnd imbecile, be sure to leave as much strife and grief as possible in your wake. Leave them suffering..." },
            { ids = { 6135 }, name = "Duskwing, Oh How I Hate Thee...", level = 60, zone = "Eastern Plaguelands", giver = "Nathanos Blightcaller", giverMap = 1423, giverX = 22.2, giverY = 63.5, ender = "Nathanos Blightcaller", enderMap = 1423, enderX = 22.2, enderY = 63.5, objective = "Find Duskwing and slay him. From the corpse, recover a Patch of Duskwing's Fur and return it to Nathanos Blightcaller.$B$BIt is said that Duskwing roams the countryside to the north of Marris Stead.", summary = "Up until now, you have completed the missions I have assigned; even if not in the most timely manner.$B$BI suppose you think that you are ready for a challenge. Yes... Yes, imbecile, perhaps you are ready for a more involved set of missions.$B$BThe albino demon bat, Duskwing, roams the countryside just north of here. Track him down and destroy him. Return to me with a patch of his white fur and you shall be rewarded." },
            { ids = { 6136 }, name = "The Corpulent One", level = 60, zone = "Eastern Plaguelands", giver = "Nathanos Blightcaller", giverMap = 1423, giverX = 22.2, giverY = 63.5, ender = "Nathanos Blightcaller", enderMap = 1423, enderX = 22.2, enderY = 63.5, objective = "Find Borelgore in the northern wastes of Eastern Plaguelands and destroy him. Return to Nathanos Blightcaller when the mission is complete.", summary = "Past the Argent Dawn encampment of Light's Hope and west of Northdale, you will find the corpulent maggot beast, Borelgore.$B$BI've lost entire regiments to that monster. His size knows no bounds! The more he eats the greater his girth becomes...$B$BWhile I would not suffer any emotional harm should the beast devour you, I would prefer that you were the victor. I recommend you enlist the help of others for this mission. Borelgore has been known to devour small battalions foolish enough to attack him." },
            { ids = { 6144 }, name = "The Call to Command", level = 60, zone = "Eastern Plaguelands", giver = "Nathanos Blightcaller", giverMap = 1423, giverX = 22.2, giverY = 63.5, ender = "Varimathras", enderMap = 1458, enderX = 56.2, enderY = 92.2, objective = "Travel to the Undercity and speak with Varimathras.", summary = "The order has come down, $c. Varimathras himself has requested that I send my most 'capable' agents back to the Undercity for a highly sensitive tactical operation.$B$BUnfortunately, my most capable agents were killed over three years ago. In their stead I have a collection of brain dead riff-raff.$B$B<Nathanos stares coldly at you.>$B$BTravel to the Undercity at once and report to Varimathras. Do not embarrass me, $c!" },
            { ids = { 6145 }, name = "The Crimson Courier", level = 60, zone = "Undercity", giver = "Varimathras", giverMap = 1458, giverX = 56.2, giverY = 92.2, ender = "Nathanos Blightcaller", enderMap = 1423, enderX = 22.2, enderY = 63.5, objective = "Return to Eastern Plaguelands and track down the Crimson Courier. Kill the Courier and recover the Grand Crusader's Command.$B$BTake the command to Nathanos Blightcaller for further instruction.", summary = "Just as the body cannot survive without the head, the head cannot survive without the body. The defenses of the Scarlet Crusade's command inside Stratholme are almost impenetrable. We must, instead, cut the body out from under the head.$B$BMy Deathstalkers have been collecting data on the activity of the Crusade outside of Stratholme. Each day, a report is sent from their central command to Tyr's Hand. This report is the key, $r! Find the Crimson Courier and recover that report. Return it to Nathanos." },
            { ids = { 6146 }, name = "Nathanos' Ruse", level = 60, zone = "Eastern Plaguelands", giver = "Nathanos Blightcaller", giverMap = 1423, giverX = 22.2, giverY = 63.5, ender = "Crusader Lord Valdelmar", enderMap = 1423, enderX = 75.2, enderY = 71.2, objective = "Travel to Tyr's Hand, southeast of the Marris Stead. Once there, take a bite of the Rotten Apple. While under the guise of the Scarlet Crusade, deliver the Grand Crusader's Command to Crusader Lord Valdelmar.", summary = "I have made some adjustments to this command. Should our little ruse work, they will expose the Scarlet Oracle and we shall strike!$B$BNow pay attention, $c. You are to deliver this command to the Crusader Lord, Valdelmar.$B$BHow? You are going to hand it to him, imbecile.$B$BTake the command and this rotten apple to Tyr's Hand. When you cross into the city, eat the apple. You will transform into something more... palatable to the humans. Take the command and hand it to the Crusader Lord, Valdelmar." },
            { ids = { 6147 }, name = "Return to Nathanos", level = 60, zone = "Eastern Plaguelands", giver = "Crusader Lord Valdelmar", giverMap = 1423, giverX = 75.2, giverY = 71.2, ender = "Nathanos Blightcaller", enderMap = 1423, enderX = 22.2, enderY = 63.5, objective = "Return to Nathanos Blightcaller with the new information.", summary = "The Grand Crusader makes an unusual request. Hrm, regardless... what he asks will be done. Return to the Scarlet Bastion and notify him that the Oracle will be en route shortly.$B$BWe will take every precaution to ensure that she makes it to Stratholme unharmed." },
            { ids = { 6148 }, name = "The Scarlet Oracle, Demetria", level = 60, zone = "Eastern Plaguelands", giver = "Nathanos Blightcaller", giverMap = 1423, giverX = 22.2, giverY = 63.5, ender = "Nathanos Blightcaller", enderMap = 1423, enderX = 22.2, enderY = 63.5, objective = "The Scarlet Crusade is on the move. Somewhere along the road from Tyr's Hand to Stratholme you will find the Oracle, Demetria, and her entourage. Hunt her down and slay her. Return to Nathanos Blightcaller should you succeed.", summary = "Demetria is chief advisor to the Grand Crusader. She is called the Oracle due to her 'otherworldly' senses. She has successfully assisted the Crusade in several of their victories against the Scourge.$B$BWhile this ruse was successful in exposing her, if she truly does possess psychic powers, she will undoubtedly be expecting some sort of trouble. You are going to provide that 'trouble.'$B$BTrack down the Oracle and terminate her. They should be moving out of Tyr's Hand as we speak. Make me proud, worm." },
        },
    },
    {
        id = "q1000",
        name = "Uncovering Past Secrets",
        zone = "Thunder Bluff",
        minLevel = 54,
        maxLevel = 57,
        importance = 1,
        kind = "world",
        quests = {
            { ids = { 1000 }, name = "The New Frontier", level = 55, zone = "Thunder Bluff", giver = "Bluff Runner Windstrider", giverMap = 1456, giverX = 44.3, giverY = 58.8, ender = "Arch Druid Hamuul Runetotem", enderMap = 1456, enderX = 78.6, enderY = 28.6, objective = "Speak with Arch Druid Hamuul Runetotem on the Elder Rise of Thunder Bluff about the Cenarion Circle's call to explore the frontiers of Kalimdor.", summary = "Attention, heroes!$B$BThe Cenarion Circle seeks able bodied individuals to assist them in exploring the vast new frontiers of Kalimdor!  A forbidden wasteland of unimaginable dangers lies far to the west of Tanaris and Gadgetzan, and the Circle needs willing and honorable proxies to act in their stead.$B$BAll interested individuals should seek audience with the Cenarion Circle.  Speak with the Arch Druid Hamuul Runetotem on the Elder's Rise of Thunder Bluff for more information!" },
            { ids = { 1123 }, name = "Rabine Saturna", level = 55, zone = "Thunder Bluff", giver = "Arch Druid Hamuul Runetotem", giverMap = 1456, giverX = 78.6, giverY = 28.6, ender = "Rabine Saturna", enderMap = 1450, enderX = 51.7, enderY = 45.1, objective = "Speak with Rabine Saturna in the village of Nighthaven, Moonglade.  Moonglade lies between Felwood and Winterspring, accessible through a path out of Timbermaw Hold.", summary = "For this task, Keeper Remulos' majordomo in Moonglade - Rabine Saturna - seeks aid in exploring the vast wastelands far to the west of Tanaris and Un'Goro.  He is located in Nighthaven, the main village of Moonglade.$B$BI want to impart on you the importance of your presence.  There are growing tensions between the night elves of Darnassus and the Cenarion Circle in Moonglade.  Look beyond racial boundaries and tap into the wisdom of your ancestors in dealings with the Circle there, $N.  Good luck." },
            { ids = { 1124 }, name = "Wasteland", level = 55, zone = "Moonglade", giver = "Rabine Saturna", giverMap = 1450, giverX = 51.7, giverY = 45.1, ender = "Layo Starstrike", enderMap = 1451, enderX = 81.9, enderY = 18.9, objective = "Speak with Layo Starstrike near the Valor's Rest graveyard of Silithus, showing him Rabine's Letter.", summary = "West of Un'Goro Crater, via the northwestern ridge, is a harsh wasteland - Silithus.  Few know that an ancient war was waged there between the night elves and a malign, alien power.  The evil was sealed, but now we suspect that forces work to stir this... unspeakable horror.$B$BSeek out Layo Starstrike, one of our agents in Silithus; look for him at Valor's Rest, the final resting spot for the fallen of the wastes.  Give him this letter, and he will give you his trust accordingly." },
            { ids = { 1125 }, name = "The Spirits of Southwind", level = 55, zone = "Silithus", giver = "Layo Starstrike", giverMap = 1451, giverX = 81.9, giverY = 18.9, ender = "Layo Starstrike", enderMap = 1451, enderX = 81.9, enderY = 18.9, objective = "Free the spirits of 8 Tortured Druids and 8 Tortured Sentinels in Southwind Village, and then return to Layo Starstrike at the Valor's Rest graveyard of Silithus.", summary = "To our southwest lies a tragic site - the ruins of Southwind Village.  This is where our work should begin, $N.$B$BFrom what we've learned, this village was once a night elf base of operations for Silithus.  It's long since overrun by the silithid hives that infest the wastes.  I can only imagine the horror of the village's initial sundering...$B$BThe tortured spirits of fallen druids and sentinels wander the ruins aimlessly.  Explore this locale, freeing the souls of these wretched beings as needed." },
            { ids = { 1126 }, name = "Hive in the Tower", level = 57, zone = "Silithus", giver = "Layo Starstrike", giverMap = 1451, giverX = 81.9, giverY = 18.9, ender = "Layo Starstrike", enderMap = 1451, enderX = 81.9, enderY = 18.9, objective = "Scale the tower of Southwind Village and locate a means to stir the silithid hive into activity.  Bring back anything unusual you may uncover when doing so to Layo Starstrike at the Valor's Rest graveyard of Silithus.", summary = "The hive needs to be addressed in Southwind Village, and I think I know a way to get at them.  It's been my experience that the silithid hives are very sensitive to their environment; this explains their attacks when hearing the death wails of the spirits.$B$BThe silithid are strongest in the tower - the one with the mass of wasps circling it.  Scale the tower and jostle the hive into activity.  Report back what you learn, but be careful!  If you uncover anything that might help, bring it to me." },
            { ids = { 6844 }, name = "Umber, Archivist", level = 57, zone = "Silithus", giver = "Layo Starstrike", giverMap = 1451, giverX = 81.9, giverY = 18.9, ender = "Umber", enderMap = 1450, enderX = 44.9, enderY = 35.6, objective = "Take the Encrusted Silithid Object to Umber - the Cenarion Circle's archivist - in the village of Nighthaven, Moonglade.", summary = "There's plenty to do here still, but I think taking this back to the Circle for analysis is key.  Trust me - the work will still be here once this is all said and done.  If it's a journal inside this sticky chitin, then the Circle would finally have a window into the past!$B$BTake this to the Circle's archivist in Nighthaven.  His name is Umber, and the man's brilliant.  Touched, sure, but brilliant nonetheless!  Umber's salvaged tomes in far worse shape than this.  If it can be saved, he can do it." },
            { ids = { 6845 }, name = "Uncovering Past Secrets", level = 57, zone = "Moonglade", giver = "Umber", giverMap = 1450, giverX = 44.9, giverY = 35.6, ender = "Rabine Saturna", enderMap = 1450, enderX = 51.7, enderY = 45.1, objective = "Speak with Rabine Saturna in the village of Nighthaven, Moonglade.", summary = "Anyway, you should check back with me relatively soon... that is if you want to know what was in here.  As soon as I find out what it is, and if it's indeed a book, I'd be happy to share that information with you.$B$BIn the meantime, I'd check in with the den mother of this little bear camp, Rabine.  No doubt he'll want to know what crazy antics you've been up to.  Never leave the den mother waiting, $N... that is, unless you want to be doused in honey.$B$BIt's happened, trust me." },
            { ids = { 1185 }, name = "Under the Chitin Was...", level = 57, zone = "Moonglade", giver = "Umber", giverMap = 1450, giverX = 44.9, giverY = 35.6, ender = "Umber", enderMap = 1450, enderX = 44.9, enderY = 35.6 },
        },
    },
    {
        id = "q4903",
        name = "For The Horde!",
        zone = "Badlands",
        minLevel = 55,
        maxLevel = 60,
        importance = 3,
        kind = "dungeon",
        quests = {
            { ids = { 4903 }, name = "Warlord's Command", level = 60, zone = "Badlands", giver = "Warlord Goretooth", giverMap = 1418, giverX = 5.8, giverY = 47.5, ender = "Warlord Goretooth", enderMap = 1418, enderX = 5.8, enderY = 47.5, objective = "Slay Highlord Omokk, War Master Voone, and Overlord Wyrmthalak. Recover Important Blackrock Documents. Return to Warlord Goretooth in Kargath when the mission has been accomplished.", summary = "By order of Warlord Goretooth, the following inhabitants of Blackrock Spire must be destroyed:$B$BThe rotund menace, Highlord Omokk.$B$BThe cruel and ruthless troll, War Master Voone.$B$BOverlord Wyrmthalak, taskmaster of the lesser city.$B$BYou will also be required to return any important documents that you may find.$B$BSucceed and be honored.$B$BFail and be forgotten." },
            { ids = { 4941 }, name = "Eitrigg's Wisdom", level = 60, zone = "Badlands", giver = "Warlord Goretooth", giverMap = 1418, giverX = 5.8, giverY = 47.5, ender = "Thrall", enderMap = 1454, enderX = 31.7, enderY = 37.8, objective = "Speak with Eitrigg in Orgrimmar. When you have discussed matters with Eitrigg, seek council from Thrall.$B$BYou recall having seen Eitrigg in Thrall's chamber.", summary = "Rend lives?$B$BImpossible!$B$BIt had been thought that Rend  was slain decades ago.$B$BSeek out the wisdom of Eitrigg, $N. None know the workings of the Blackrock better than he and if what is written here bares truth, Eitrigg should be informed. No person should be denied the right of vengeance.$B$BYou will find him in Orgrimmar.$B$BOnce you have spoken with Eitrigg, confer with the Warchief to find out what he wishes to do about this problem." },
            { ids = { 4974 }, name = "For The Horde!", level = 60, zone = "Orgrimmar", giver = "Thrall", giverMap = 1454, giverX = 31.7, giverY = 37.8, ender = "Thrall", enderMap = 1454, enderX = 31.7, enderY = 37.8, objective = "Travel to Blackrock Spire and slay Warchief Rend Blackhand. Take his head and return to Orgrimmar.", summary = "Rend dares make such grand claims because of the protection he is afforded by the black flight.$B$BYou, $N, will find a way to pass through the Halls of Ascension. You will then find 'Warchief' Rend Blackhand and you will destroy him - FOR THE HORDE!$B$B<Thrall slams a fist down upon his throne.>$B$BThe next time you return to my chambers, you will hold his head high in triumph and then you shall present it to your Warchief. Do this and be honored as a hero of the Horde." },
            { ids = { 6566 }, name = "What the Wind Carries", level = 60, zone = "Orgrimmar", giver = "Thrall", giverMap = 1454, giverX = 31.7, giverY = 37.8, ender = "Thrall", enderMap = 1454, enderX = 31.7, enderY = 37.8, objective = "Listen to Thrall.", summary = "It is good to see you again, $N. The wind carries with it news from the Eastern Kingdom.$B$BSit, listen. " },
            { ids = { 6567 }, name = "The Champion of the Horde", level = 60, zone = "Orgrimmar", giver = "Thrall", giverMap = 1454, giverX = 31.7, giverY = 37.8, ender = "Rexxar", enderMap = 1443, enderX = 54, enderY = 2, objective = "Seek out Rexxar. The Warchief has instructed you as to his whereabouts. Search the paths of Desolace, between the Stonetalon Mountains and Feralas.", summary = "I have received word from one of my champions that a way into the lair of the dragon may exist. You are to seek him out.$B$BRexxar wanders the desert wasteland of Desolace, traveling between Stonetalon and Feralas. He awaits your arrival." },
            { ids = { 6568 }, name = "The Testament of Rexxar", level = 60, zone = "Desolace", giver = "Rexxar", giverMap = 1443, giverX = 54, giverY = 2, ender = "Myranda the Hag", enderMap = 1422, enderX = 50.8, enderY = 77.8, objective = "Deliver Rexxar's Testament to Myranda the Hag in the Western Plaguelands.", summary = "What do you know of illusions, $N? For you see, it is an illusion that you must create in order to circumvent the Black Flight's defenses.$B$BI know of one that may be willing to assist you in your quest of deception. She has assisted our kind in the past when she has deemed the cause worthy.$B$BIn the Western Plaguelands you will find Myranda the Hag, master illusionist - an exile of the Lordaeron alliance. Travel there and take with you this message." },
            { ids = { 6569 }, name = "Oculus Illusions", level = 60, zone = "Western Plaguelands", giver = "Myranda the Hag", giverMap = 1422, giverX = 50.8, giverY = 77.8, ender = "Myranda the Hag", enderMap = 1422, enderX = 50.8, enderY = 77.8, objective = "Travel to Blackrock Spire and collect 20 Black Dragonspawn Eyes. Return to Myranda the Hag when the task is complete.", summary = "So the $r wishes to become one of the Black Flight, eh?$B$BThe creation of the illusion you require is trivial, but the components required for the divination are quite difficult to obtain. Rexxar and the Warchief have entrusted you with this mission, so Myranda must assume you as capable.$B$BTravel to the upper citadel of Blackrock Spire and slay enough of the black dragonspawn to fill up one of your packs with their eyes.$B$BReturn to Myranda when you have gathered enough of the reagent." },
            { ids = { 6570 }, name = "Emberstrife", level = 60, zone = "Western Plaguelands", giver = "Myranda the Hag", giverMap = 1422, giverX = 50.8, giverY = 77.8, ender = "Emberstrife", enderMap = 1445, enderX = 56.7, enderY = 87.7, objective = "Travel to the Wyrmbog in Dustwallow Marsh and seek out Emberstrife's Den. Once inside, wear the Amulet of Draconic Subversion and speak with Emberstrife.", summary = "I have attuned this medallion with the magic necessary to create and maintain an illusion within the bounds of the den of Emberstrife.$B$BEmberstrife is an ancient drake; an old gatekeeper of Nefarian, burdened with the duty to test those dragonspawn that would ascend to the rank of elite guard to Onyxia.$B$BTravel to the Wyrmbog of Dustwallow Marsh and enter the lair of Emberstrife. Once there, put on the amulet and follow where your destiny may lead!" },
            { ids = { 6582 }, name = "The Test of Skulls, Scryer", level = 60, zone = "Dustwallow Marsh", giver = "Emberstrife", giverMap = 1445, giverX = 56.7, giverY = 87.7, ender = "Emberstrife", enderMap = 1445, enderX = 56.7, enderY = 87.7, objective = "You must find the blue dragonflight drake champion, Scryer, and slay him. Pry his skull from his corpse and return it to Emberstrife.$B$BYou know that Scryer can be found in Winterspring.", summary = "We are Deathwing's children, whelp. Our dominance over the lesser Aspects must be enforced.$B$BIf you are truly worthy of ascension, the lesser dragonflight will wilt in your presence.$B$BFind their champions and lay waste to them in the name of our Father!$B$BTravel to Winterspring and track down the mighty blue drake, Scryer. Crush him and any of the Blue Flight that stand in your path. Tear out his skull and return it to me." },
            { ids = { 6583 }, name = "The Test of Skulls, Somnus", level = 60, zone = "Dustwallow Marsh", giver = "Emberstrife", giverMap = 1445, giverX = 56.7, giverY = 87.7, ender = "Emberstrife", enderMap = 1445, enderX = 56.7, enderY = 87.7, objective = "Destroy the drake champion of the Green Flight, Somnus. Take his skull and return it to Emberstrife.", summary = "Just as our Father crushes the Aspects themselves, so too must we strive to bring chaos and destruction to their children.$B$BYou must test your battle prowess against the sleepless dreamers: The children of the Green Flight.$B$BTravel to the Swamp of Sorrows and track down Somnus, drake champion of the Green Flight. Let flow your hatred; dominate the insect... Return to me with his skull..." },
            { ids = { 6584 }, name = "The Test of Skulls, Chronalis", level = 60, zone = "Dustwallow Marsh", giver = "Emberstrife", giverMap = 1445, giverX = 56.7, giverY = 87.7, ender = "Emberstrife", enderMap = 1445, enderX = 56.7, enderY = 87.7, objective = "Guarding the Caverns of Time in the Tanaris Desert is Chronalis, child of Nozdormu. Destroy him and return his skull to Emberstrife.", summary = "The time watchers, children of Nozdormu - Lord of the Centuriesss...$B$BIt is three that guard the Caverns of Time, but only one that holds the interests of the Black Flight: The Time Shifter, Chronalis, favored drakeling of Nozdormu.$B$BSsstrike at this champion, a blow to make even the stoic sands of time weep. Return to me with his skull." },
            { ids = { 6585 }, name = "The Test of Skulls, Axtroz", level = 60, zone = "Dustwallow Marsh", giver = "Emberstrife", giverMap = 1445, giverX = 56.7, giverY = 87.7, ender = "Emberstrife", enderMap = 1445, enderX = 56.7, enderY = 87.7, objective = "Travel to Grim Batol and track down Axtroz, drake champion of the Red Flight. Destroy him and take his skull. Return the skull to Emberstrife.", summary = "It was over the mountains of Grim Batol that our Father raged against the combined might of the Aspects. The cowardly act of the betrayer, Alexstrasza, bought the other Aspects enough time to escape from Father's wrath.$B$BSssuch a shameful act...$B$BThe Red Flight now guards Grim Batol, their lieutenant, Axtroz, must be destroyed. Return the skull of Axtroz to me. For Father, whelp!" },
            { ids = { 6601 }, name = "Ascension...", level = 60, zone = "Dustwallow Marsh", giver = "Emberstrife", giverMap = 1445, giverX = 56.7, giverY = 87.7, ender = "Rexxar", enderMap = 1443, enderX = 54, enderY = 2, objective = "It would appear as if the charade is over. You know that the Amulet of Draconic Subversion that Myranda the Hag created for you will not function inside Blackrock Spire. Perhaps you should find Rexxar and explain your predicament. Show him the Dull Drakefire Amulet. Hopefully he will know what to do next.", summary = "From the skulls of our enemies is shaped a medallion. You know this medallion, yesss? You have no doubt seen it worn by your elders.$B$BTake it, whelp. Return to the Spire and present it to General Drakkisath. The General will place the final enchantment upon the medallion, attuning the trinket to your spirit.$B$BYou will wear the finished medallion as a badge of honor, symbolizing your ascension to one of our most guarded ranks: Guardian to the brood mother.$B$BGo!" },
            { ids = { 6602 }, name = "Blood of the Black Dragon Champion", level = 60, zone = "Desolace", giver = "Rexxar", giverMap = 1443, giverX = 54, giverY = 2, ender = "Rexxar", enderMap = 1443, enderX = 54, enderY = 2, objective = "Travel to Blackrock Spire and slay General Drakkisath. Gather his blood and return it to Rexxar.", summary = "You will pay the General a visit, yes, but not as one of the Black Dragonflight.$B$BYou see, a ceremony is merely another term for blood letting to the Black Flight.$B$BThe latent amulet merely needs the blood of the General in order to become active. One of their crude failsafe mechanisms.$B$BReturn to Blackrock Spire and destroy Drakkisath. Bring his blood back here and I shall activate the key to Onyxia's lair." },
            { ids = { 7490 }, name = "Victory for the Horde", level = 60, zone = "Orgrimmar", ender = "Thrall", enderMap = 1454, enderX = 31.7, enderY = 37.8, objective = "Take the Head of Onyxia to Thrall in Orgrimmar.", summary = "You have accomplished the impossible. The brood mother of the Black Dragonflight lies dead at your feet. Take her head and present it to your Warchief." },
            { ids = { 7491 }, name = "For All To See", level = 60, zone = "Orgrimmar", giver = "Thrall", giverMap = 1454, giverX = 31.7, giverY = 37.8, ender = "Overlord Runthak", enderMap = 1454, enderX = 51.7, enderY = 75.5, objective = "Seek out Overlord Runthak in the Valley of Strength.", summary = "Overlord Runthak awaits your arrival in the Valley of Strength.$B$B<Thrall salutes you.>$B$BDo not keep your public waiting, hero." },
        },
    },
    {
        id = "q6804",
        name = "The Molten Core",
        zone = "Azshara",
        minLevel = 55,
        maxLevel = 60,
        importance = 3,
        kind = "raid",
        quests = {
            { ids = { 6804 }, name = "Poisoned Water", level = 56, zone = "Azshara", giver = "Duke Hydraxis", giverMap = 1447, giverX = 79.3, giverY = 73.7, ender = "Duke Hydraxis", enderMap = 1447, enderX = 79.3, enderY = 73.7, objective = "Use the Aspect of Neptulon on poisoned elementals of Eastern Plaguelands.  Bring 12 Discordant Bracers and the Aspect of Neptulon to Duke Hydraxis in Azshara.", summary = "A force of elemental scouts was sent to the eastern plaguelands of Lordaeron, and the disease of that place twisted and infected them.  The Waterlords cannot allow this affront to our purity!$B$BTake this vial.  In it is a quantity of one aspect of Neptulon.  If used on the plagued elementals it will fight the poison within their bodies and cure them!  But their inner conflict will drive them into a surging madness.$B$BDefeat the discordant surges and bring me their bracers of binding." },
            { ids = { 6805 }, name = "Stormers and Rumblers", level = 57, zone = "Azshara", giver = "Duke Hydraxis", giverMap = 1447, giverX = 79.3, giverY = 73.7, ender = "Duke Hydraxis", enderMap = 1447, enderX = 79.3, enderY = 73.7, objective = "Kill 15 Dust Stormers and 15 Desert Rumbers and then return to Duke Hydraxis in Azshara.", summary = "We, the elementals of water, wage war with those beings of the lesser elements.  If you are truly our ally in this conflict, then show me your conviction!$B$BFar to the south, in the desert land of Silithus, the servants of air and earth scurry in a corner of rock named the Crystal Vale.  They protect items of power from smaller beings, mortals, and although I do not know why they do this, I wish to foil their efforts.$B$BGo to the Crystal Vale in Silithus and defeat our enemies, then return to me." },
            { ids = { 6821 }, name = "Eye of the Emberseer", level = 60, zone = "Azshara", giver = "Duke Hydraxis", giverMap = 1447, giverX = 79.3, giverY = 73.7, ender = "Duke Hydraxis", enderMap = 1447, enderX = 79.3, enderY = 73.7, objective = "Bring the Eye of the Emberseer to Duke Hydraxis in Azshara.", summary = "You have shown me that you can defeat our enemies and perform missions to further the cause of the Waterlords.  But until now you have only faced lesser foes... if pitted against a powerful enemy, can you prevail?$B$BThat is your new task.$B$BHigh up in Blackrock Spire the orcs have captured a servant of fire, the Pyroguard Emberseer.  Find his place of imprisonment, slay his captors, and then slay the emberseer.  Bring me his eye and it will show me your worth." },
            { ids = { 6822 }, name = "The Molten Core", level = 60, zone = "Azshara", giver = "Duke Hydraxis", giverMap = 1447, giverX = 79.3, giverY = 73.7, ender = "Duke Hydraxis", enderMap = 1447, enderX = 79.3, enderY = 73.7, objective = "Kill 1 Fire Lord, 1 Molten Giant, 1 Ancient Core Hound and 1 Lava Surger, then return to Duke Hydraxis in Azshara.", summary = "$n, perhaps it is time to give you a real test.  Are you ready?$B$BAt the bottom of Blackrock Depths is a passage to the Molten Core.  This is a stronghold of our enemy, held by the most powerful servants of fire on this world.$B$BGo to the Molten Core, $N.  Show me you have the strength and the will to defeat what you find there.$B$BAnd if you have allies among your people, then rally them.  Nothing short of an army can hope to enter the Molten Core and live." },
            { ids = { 6823 }, name = "Agent of Hydraxis", level = 60, zone = "Azshara", giver = "Duke Hydraxis", giverMap = 1447, giverX = 79.3, giverY = 73.7, ender = "Duke Hydraxis", enderMap = 1447, enderX = 79.3, enderY = 73.7, objective = "Earn an Honored faction with the Hydraxian Waterlords, then talk to Duke Hydraxis in Azshara.", summary = "If you truly wish an allegiance with us, then I invite you to wage war on our foes, the servants of air and earth and fire.  Each defeat you heap upon them will weaken their foothold here, and further prove your adherence to our cause.$B$BThe campaign will be long, but if you persevere then your glory and honor will be great." },
            { ids = { 6824 }, name = "Hands of the Enemy", level = 60, zone = "Azshara", giver = "Duke Hydraxis", giverMap = 1447, giverX = 79.3, giverY = 73.7, ender = "Duke Hydraxis", enderMap = 1447, enderX = 79.3, enderY = 73.7, objective = "Bring the Hands of Lucifron, Sulfuron, Gehennas and Shazzrah to Duke Hydraxis in Azshara.", summary = "$N, your service is of great value to us, so we are reluctant to send you on this last mission for we do not want to lose such a useful agent.$B$BBut its success would further our war efforts tremendously and... it was deemed worth risking you.$B$BWe want these captains in the Molten Core destroyed: Lucifron, Sulfuron, Gehennas and Shazzrah.  Kill them and bring me their hands!$B$BThis task will take every resource you possess, $N, but if can do it then the Firelords will be dealt a terrible blow." },
            { ids = { 7486 }, name = "A Hero's Reward", level = 60, zone = "Azshara", giver = "Duke Hydraxis", giverMap = 1447, giverX = 79.3, giverY = 73.7, ender = "Hydraxis' Coffer", enderMap = 1447, enderX = 79.2, enderY = 74.9, objective = "Claim your reward from Hydraxis' Coffer.", summary = "$N, your services to the Warlords surpassed all we could expect from the denizens of this world.$B$BWe do not understand your people's notions of gratitude, or rewarding good works, but in this case... perhaps a reward is warranted.$B$BUnder the surf at the southern base of this island, you will find a coffer.  In it you will find your... reward.$B$BGo, $N.  Claim your reward." },
        },
    },
    {
        id = "q5382",
        name = "The Lich, Ras Frostwhisper",
        zone = "Western Plaguelands",
        minLevel = 55,
        maxLevel = 60,
        importance = 2,
        kind = "dungeon",
        quests = {
            { ids = { 5382 }, name = "Doctor Theolen Krastinov, the Butcher", level = 60, zone = "Western Plaguelands", giver = "Eva Sarkhoff", giverMap = 1422, giverX = 70.2, giverY = 73.7, ender = "Eva Sarkhoff", enderMap = 1422, enderX = 70.2, enderY = 73.7, objective = "Find Doctor Theolen Krastinov inside the Scholomance. Destroy him, then burn the Remains of Eva Sarkhoff and the Remains of Lucien Sarkhoff. Return to Eva Sarkhoff when the task is complete.", summary = "Krastinov is responsible for the deaths of thousands. He must be punished, justice must be meted out.$B$BFind him and exact upon him the agony he has inflicted upon countless innocents. Once he is destroyed, burn our remains. Turn them to ashes, $N." },
            { ids = { 5515 }, name = "Krastinov's Bag of Horrors", level = 60, zone = "Western Plaguelands", giver = "Eva Sarkhoff", giverMap = 1422, giverX = 70.2, giverY = 73.7, ender = "Eva Sarkhoff", enderMap = 1422, enderX = 70.2, enderY = 73.7, objective = "Locate Jandice Barov in the Scholomance and destroy her. From her corpse recover Krastinov's Bag of Horrors. Return the bag to Eva Sarkhoff.", summary = "A great weight has been lifted from our hearts, $N, but your task is not yet complete. Krastinov's master, Kirtonos, still lives.$B$BBefore you may face Kirtonos, however, you must first secure a method in which to summon him.$B$BIt is said that Jandice Barov stewards the blood of innocents from Krastinov to Kirtonos.$B$BFind her in the sunken catacombs of Scholomance and strike her down. Bring back any clues that you may find." },
            { ids = { 5384 }, name = "Kirtonos the Herald", level = 60, zone = "Western Plaguelands", giver = "Eva Sarkhoff", giverMap = 1422, giverX = 70.2, giverY = 73.7, ender = "Eva Sarkhoff", enderMap = 1422, enderX = 70.2, enderY = 73.7, objective = "Return to the Scholomance with the Blood of Innocents. Find the porch and place the Blood of Innocents in the brazier. Kirtonos will come to feast upon your soul.$B$BFight valiantly, do not give an inch! Destroy Kirtonos and return to Eva Sarkhoff.", summary = "This is it, $N.$B$B<Eva points to the vial inside the bag.>$B$BThe blood of innocents. The purest blood, used to appease Krastinov's master.$B$BIt is with this blood that Kirtonos may be summoned. It is with this blood, then, that Kirtonos must be destroyed.$B$BTake the blood to the porch. Place it upon the brazier. Kirtonos will come - he cannot resist. When he appears, unleash the fury and wrath of a thousand innocent deaths upon him.$B$BShould you succeed, you will earn more than just our gratitude." },
            { ids = { 5461 }, name = "The Human, Ras Frostwhisper", level = 60, zone = "Western Plaguelands", giver = "Magistrate Marduke", giverMap = 1422, giverX = 70.6, giverY = 74.1, ender = "Magistrate Marduke", enderMap = 1422, enderX = 70.6, enderY = 74.1, objective = "Travel to the Arathi Highlands, to the ruins of Stromgarde. Search Stromgarde for a Keepsake of Remembrance. If you find such an item, return with it to Magistrate Marduke.", summary = "The undead fear life just as the living fear death. It is not unusual for a sentient undead being to completely destroy all remnants of his or her previous life after having turned.$B$BUnfortunately, in order to create an artifact capable of reverting Ras Frostwhisper to a mortal, we must have a keepsake from his years among the living.$B$BYou must venture to the ruined city of Stromgarde, Frostwhisper's home, and search for such an item. May luck be with you, $N." },
            { ids = { 5462 }, name = "The Dying, Ras Frostwhisper", level = 60, zone = "Western Plaguelands", giver = "Magistrate Marduke", giverMap = 1422, giverX = 70.6, giverY = 74.1, ender = "Leonid Barthalomew the Revered", enderMap = 1423, enderX = 71.9, enderY = 48.3, objective = "Travel to Light's Hope in Eastern Plaguelands and seek out Leonid Barthalomew the Revered. Show him the Keepsake of Remembrance and tell him all that you have discovered.", summary = "Upon tainted soil, the keepsake must be attuned.$B$BIt is rumored that Stratholme is where Frostwhisper succumbed to the Lich King. Upon those bloodied grounds he gave his life - freely and with motive - to become one of the undying.$B$BIt is those grounds that must be found.$B$BThere is one, an undead dissenter of the Scourge, freed by the Banshee Queen but loyal to the cause of the Argent Dawn. Find him: Leonid Barthalomew the Revered. He may know more. Seek out Light's Hope, $N. " },
            { ids = { 5463 }, name = "Menethil's Gift", level = 60, zone = "Eastern Plaguelands", giver = "Leonid Barthalomew the Revered", giverMap = 1423, giverX = 71.9, giverY = 48.3, ender = "Menethil's Gift", enderMap = 1423, enderX = 26.5, enderY = 10.4, enderInside = "Stratholme", objective = "Travel to Stratholme and find Menethil's Gift. Place the Keepsake of Remembrance upon the unholy ground. ", summary = "I watched as the human, Ras Frostwhisper, pledged his undying soul to the Lich King. He drew the dagger to his own throat and with a smile, cut from ear to ear. His body collapsed inside the borders of the pentagram. The Lich King stood over the fallen mage and with a single motion, Ras Frostwhisper the lich, was born.$B$B<Leonid gazes at the ground and then looks up at you.>$B$BYes, $r, I remember. What you seek has a name - Menethil's Gift: The ground blessed by the Lich King - holy ground to Scourge." },
            { ids = { 5464 }, name = "Menethil's Gift", level = 60, zone = "Stratholme", giver = "Menethil's Gift", giverMap = 1423, giverX = 26.5, giverY = 10.4, giverInside = "Stratholme", ender = "Leonid Barthalomew the Revered", enderMap = 1423, enderX = 71.9, enderY = 48.3, objective = "Take the Soulbound Keepsake to Leonid Barthalomew in Eastern Plaguelands.", summary = "The soul of the fallen clings to that which represents its former life and transforms the item into a soulbound keepsake. You pick the item up and place it in your pack." },
            { ids = { 5465 }, name = "Soulbound Keepsake", level = 60, zone = "Eastern Plaguelands", giver = "Leonid Barthalomew the Revered", giverMap = 1423, giverX = 71.9, giverY = 48.3, ender = "Magistrate Marduke", enderMap = 1422, enderX = 70.6, enderY = 74.1, objective = "Return to Magistrate Marduke in Caer Darrow. Show him the Soulbound Keepsake.", summary = "Return to Marduke with the keepsake, $N. He will instruct you in its use." },
            { ids = { 5466 }, name = "The Lich, Ras Frostwhisper", level = 60, zone = "Western Plaguelands", giver = "Magistrate Marduke", giverMap = 1422, giverX = 70.6, giverY = 74.1, ender = "Magistrate Marduke", enderMap = 1422, enderX = 70.6, enderY = 74.1, objective = "Find Ras Frostwhisper in the Scholomance. When you have found him, use the Soulbound Keepsake on his undead visage. Should you succeed in reverting him to a mortal, strike him down and recover the Human Head of Ras Frostwhisper. Take the head back to Magistrate Marduke.", summary = "There is but one task remaining, $N. Confront the lich, Ras Frostwhisper, in his lair.$B$BUse the power of the keepsake against the beast -  be unrelenting in your actions!  Weather the blows that the flailing beast will surely bring down upon you. Do not give in to the pain!$B$BWhen the ritual is complete, Ras will be mortal once more. It is at that point that he must be slain. Strike him down and take his human head." },
        },
    },
    {
        id = "q5251",
        name = "The Archivist",
        zone = "Eastern Plaguelands",
        minLevel = 55,
        maxLevel = 60,
        importance = 1,
        kind = "dungeon",
        quests = {
            { ids = { 5251 }, name = "The Archivist", level = 60, zone = "Eastern Plaguelands", giver = "Duke Nicholas Zverenhoff", giverMap = 1423, giverX = 71.6, giverY = 50.1, ender = "Duke Nicholas Zverenhoff", enderMap = 1423, enderX = 71.6, enderY = 50.1, objective = "Travel to Stratholme and find Archivist Galford of the Scarlet Crusade. Destroy him and burn down the Scarlet Archive.", summary = "Anything taken to an extreme is hazardous to our world, $N. Take for example, the Scarlet Crusade. Do you believe that their blind zealotry serves a greater good? How many innocents have they destroyed in the name of the Light?$B$BBlasphemers, one and all!$B$BOne in particular interests me, though; the Archivist Galford of Stratholme: A man that watches over the Crusade's most valued documents. Destroy him and burn down his archives! Should you succeed, return to me and be rewarded." },
            { ids = { 5262 }, name = "The Truth Comes Crashing Down", level = 60, zone = "Stratholme", ender = "Duke Nicholas Zverenhoff", enderMap = 1423, enderX = 71.6, enderY = 50.1, objective = "Take the Head of Balnazzar to Duke Nicholas Zverenhoff in the Eastern Plaguelands.", summary = "You try and gather your thoughts as the dust settles across the chamber. You go over the events that just transpired and still cannot comprehend the gravity of the situation.$B$BThe Grand Crusader of the Scarlet Crusade a demon? And not just any demon but brother to Varimathras, arch lord of the Undercity?$B$BYou carefully stow the severed head of the dreadlord into your pack. Surely, none would believe the tale you would tell without proof.$B$BDuke Nicholas Zverenhoff must be told at once!" },
            { ids = { 5263 }, name = "Above and Beyond", level = 60, zone = "Eastern Plaguelands", giver = "Duke Nicholas Zverenhoff", giverMap = 1423, giverX = 71.6, giverY = 50.1, ender = "Duke Nicholas Zverenhoff", enderMap = 1423, enderX = 71.6, enderY = 50.1, objective = "Venture to Stratholme and destroy Baron Rivendare. Take his head and return to Duke Nicholas Zverenhoff.", summary = "You display a natural aptitude for destruction and you follow orders. It is rare to see the two coexist. I am beginning to think that you may make an excellent vehicle of divine justice.$B$B<Zverenhoff clasps his hands together in front of his face.>$B$BKel'Thuzad's errand boy rules over Stratholme. Prove to me that you are a champion - my champion. Destroy Baron Rivendare and return to me with his head. " },
            { ids = { 5264 }, name = "Lord Maxwell Tyrosus", level = 60, zone = "Eastern Plaguelands", giver = "Duke Nicholas Zverenhoff", giverMap = 1423, giverX = 71.6, giverY = 50.1, ender = "Lord Maxwell Tyrosus", enderMap = 1423, enderX = 71.9, enderY = 48.4, objective = "Speak with Lord Maxwell Tyrosus. He is inside the church.", summary = "I am about to bestow a great honor upon you, $N.$B$BLord Maxwell wishes to reward you for your service to the Argent Dawn!$B$BIt has been years since Maxwell has granted audience to outsiders." },
            { ids = { 5265 }, name = "The Argent Hold", level = 60, zone = "Eastern Plaguelands", giver = "Lord Maxwell Tyrosus", giverMap = 1423, giverX = 71.9, giverY = 48.4, ender = "The Argent Hold", enderMap = 1423, enderX = 72.0, enderY = 48.4, objective = "Open the Argent Hold and claim your reward.", summary = "Through the years the Argent Hold has remained locked. None have been worthy to reach inside and take from it the power of the Argent Dawn - until today.$B$BThe Argent Hold is now open to you, $N." },
        },
    },
    {
        id = "q5160",
        name = "The Matron Protectorate",
        zone = "Blackrock Spire",
        minLevel = 57,
        maxLevel = 60,
        importance = 2,
        kind = "dungeon",
        quests = {
            { ids = { 5160 }, name = "The Matron Protectorate", level = 60, zone = "Blackrock Spire", giver = "Awbee", giverMap = 1427, giverX = 34.8, giverY = 85.3, giverInside = "Blackrock Spire", ender = "Haleh", enderMap = 1452, enderX = 54.5, enderY = 51.2, objective = "Travel to Winterspring and find Haleh. Give her Awbee's scale.", summary = "Travel to Kalimdor, $r. Our flight makes its home in the frigid landscape of Winterspring. Once you reach Winterspring, find the caves of Mazthoril.$B$BUpon the icy floors of Mazthoril you will find cobalt runes. Hold one of my scales and stand upon a rune and you shall be transported to Haleh, our matron protectorate.$B$BGive her the scale so that she may scry what it is I have seen and felt, here in this doomed place." },
            { ids = { 5161 }, name = "Wrath of the Blue Flight", level = 60, zone = "Winterspring", giver = "Haleh", giverMap = 1452, giverX = 54.5, giverY = 51.2, ender = "Haleh", enderMap = 1452, enderX = 54.5, enderY = 51.2, objective = "Speak with Haleh if you wish to continue.", summary = "We understand what the cursed brood of Deathwing attempts to do and we know that it cannot be allowed.$B$BBecause of the protection Blackrock mountain affords Nefarian, it has become increasingly difficult for us to intercede.$B$BWe can, however, empower you, mortal - should you so choose.$B$BThe path before you is one full of peril. You must decide whether to accept our help. Ponder this and speak with me again when a decision has been made." },
            { ids = { 5162 }, name = "Wrath of the Blue Flight", level = 60, zone = "Winterspring", giver = "Haleh", giverMap = 1452, giverX = 54.5, giverY = 51.2, ender = "Jeziba", enderMap = 1422, enderX = 39.4, enderY = 66.8, objective = "Speak with Jeziba in the Plaguelands. He resides in Andorhal.", summary = "It is the arcane that I control and the arcane which will send you to your next destination.$B$BWhen you are ready, the journey will begin. To the Plaguelands you will go and to Jeziba you will speak.$B$BHe is a mortal as wise as the ancients and as patient as the immovable earth. Find him in Andorhal." },
            { ids = { 5164 }, name = "Catalogue of the Wayward", level = 60, zone = "Western Plaguelands", giver = "Jeziba", giverMap = 1422, giverX = 39.4, giverY = 66.8, ender = "Catalogue of the Wayward", enderMap = 1422, enderX = 39.4, enderY = 66.6, objective = "Read from the Catalogue of the Wayward.", summary = "A finer instrument of justice, Haleh could not have chosen. Read from the catalogue of the wayward and be enlightened.$B$BShould you persist... should you do what is asked of you... should you survive... a hero you will make." },
            { ids = { 5166 }, name = "Breastplate of the Chromatic Flight", level = 60, zone = "Western Plaguelands", giver = "Catalogue of the Wayward", giverMap = 1422, giverX = 39.4, giverY = 66.6, ender = "Jeziba", enderMap = 1422, enderX = 39.4, enderY = 66.8, objective = "To forge the Breastplate of the Chromatic Flight, you will be required to bring the following items to Jeziba the 'Sculptor':$B$B1 Chromatic Carapace.$B$B10 Brilliant Chromatic Scales.$B$B10 Blood of Heroes.$B$B10 Frayed Abomination Stitchings.", summary = "The forging of a powerful breastplate to protect against the unrelenting attacks of the chromatic flight is one built upon irony.$B$BThe scales of the very beasts we battle must be sewn to the pristine carapace of an elder chromatic drake or dragon. None are known to exist at this time and we should hope that none will ever exist.$B$BLastly, perhaps the most difficult of all components: the blood of heroes.$B$BThe Sculptor must ultimately forge this creation." },
        },
    },
    {
        id = "q9032",
        name = "Lord Valthalak's Amulet",
        zone = "Eastern Plaguelands",
        minLevel = 58,
        maxLevel = 60,
        importance = 2,
        kind = "dungeon",
        quests = {
            { ids = { 8957, 9016, 9017, 9018, 9019, 9020, 9021, 9022 }, name = "Anthion's Parting Words", level = 60, zone = "Eastern Plaguelands", giver = "Anthion Harmon", giverMap = 1423, giverX = 26.1, giverY = 11.3, ender = "Mokvar", enderMap = 1454, enderX = 35.0, enderY = 38.3, after = { 9015 }, objective = "Return to Mokvar in Orgimmar with a set of Boots of Elements, Kilt of Elements and Pauldrons of Elements.", summary = "Valthalak's soul was stored in this amulet.  In our greed we foolishly split it into three parts, not knowing the curse that would await us.$B$BThe only way to stop Valthalak's spell is to put the amulet back together.  Return to Mokvar and tell him that Bodley is his only hope for finding the remaining pieces.  Speak to him about any rewards you've arranged for.$B$BI, for once, shall rest in peace.  I wish you the best of luck; you shall need every bit of it!" },
            { ids = { 9032 }, name = "Bodley's Unfortunate Fate", level = 60, zone = "Orgrimmar", giver = "Mokvar", giverMap = 1454, giverX = 35.0, giverY = 38.3, ender = "Bodley", enderMap = 1415, enderX = 48.9, enderY = 63.9, objective = "Travel to Blackrock Mountain and use the Extra-Dimensional Ghost Revealer to find Bodley near Blackrock Spire.", summary = "The medallion contained Valthalak's soul?  It's no surprise it was guarded by such a powerful curse.$B$BLocating Bodley presents a bit of a problem.  Last time I heard of him, he was preparing to venture back into Blackrock Spire.  He was never heard of again.$B$BSeek him out in Blackrock Mountain, though I'm afraid to say he's probably dead by now.  I suggest taking the goblin's device with you, friend." },
            { ids = { 8961 }, name = "Three Kings of Flame", level = 60, zone = "Eastern Kingdoms", giver = "Bodley", giverMap = 1415, giverX = 48.9, giverY = 63.9, ender = "Bodley", enderMap = 1415, enderX = 48.9, enderY = 63.9, objective = "Gather the Incendicite of Incendius, the Ember of Emberseer and the Cinder of Cynders, along with a Hallowed Brazier, and return them to Bodley inside Blackrock Mountain.", summary = "In order to summon Lord Valthalak we're first going to need to gather the other two-thirds of the amulet. To do that we need to get a brazier and some special coals to burn in it.$B$BThere are three nobles of fire, Lord Incedius in Blackrock Depths, Pyroguard Emberseer in Blackrock Spire and The Duke of Cynders in Silithus, with what we need. Collect from each a piece of their remains, and then return to me with a Hallowed Brazier, which can be purchased from the Argent Dawn if you are honored by them." },
            { ids = { 8962 }, name = "Components of Importance", level = 60, zone = "Eastern Kingdoms", giver = "Bodley", giverMap = 1415, giverX = 48.9, giverY = 63.9, ender = "Bodley", enderMap = 1415, enderX = 48.9, enderY = 63.9, objective = "Acquire Druidical Remains and return them to Bodley inside Blackrock Mountain.", summary = "$C, listen closely. Now that we have the brazier, and the means to light it, we still need another component to suffuse it with; something that will provide a focus strong enough to entice the spirit of my deceased, former comrade.$B$BMor Grayhoof, our most prominent druid, had many close friends amongst the Cenarion Circle, some of which have fallen to the silithid. I need you to retrieve some Druidical Remains from the silithid that inhabit the environs of Hive'Regal in southeastern Silithus." },
            { ids = { 8967 }, name = "The Left Piece of Lord Valthalak's Amulet", level = 60, zone = "Eastern Kingdoms", giver = "Bodley", giverMap = 1415, giverX = 48.9, giverY = 63.9, ender = "Bodley", enderMap = 1415, enderX = 48.9, enderY = 63.9, objective = "Use the Brazier of Beckoning to summon forth the spirit of Isalien and slay her. Return to Bodley inside Blackrock Mountain with the Left Piece of Lord Valthalak's Amulet and the Brazier of Beckoning.", summary = "It became known to us in later days, as we were doing what we could ourselves to survive, that Isalien, a night elf priestess of our company, had gone to the night elvic ancestral city, now known as Dire Maul. From what we gathered, she went there both for personal reasons and also to unlock the secrets of the piece of the amulet that she had in her possession.$B$BShe didn't quite make it, though. Word got back to us that she was ambushed at the Shrine of Eldretharr by Alzzin the Wildshaper and his forces." },
            { ids = { 8970 }, name = "I See Alcaz Island In Your Future...", level = 60, zone = "Eastern Kingdoms", giver = "Bodley", giverMap = 1415, giverX = 48.9, giverY = 63.9, ender = "Bodley", enderMap = 1415, enderX = 48.9, enderY = 63.9, objective = "Gather 20 Bloodkelp from the Strashaz naga and then return to Bodley inside Blackrock Mountain.", summary = "As I was saying, $c, in my living years I flirted with becoming a diviner. But, there really wasn't as much profit in it as you might imagine, mostly because it's dangerous and the reagents are rare and expensive. However, I do know enough to be able to pinpoint the final piece of the amulet, and the spirit of my former comrade along with it.$B$BThis is where you come in, $N. I need you to go to Alcaz Island off the coast of Dustwallow Marsh and collect Bloodkelp from the Strashaz naga that live there." },
            { ids = { 8986 }, name = "More Components of Importance", level = 60, zone = "Eastern Kingdoms", giver = "Bodley", giverMap = 1415, giverX = 48.9, giverY = 63.9, ender = "Bodley", enderMap = 1415, enderX = 48.9, enderY = 63.9, objective = "Acquire Druidical Remains and return them to Bodley inside Blackrock Mountain.", summary = "$C, listen closely. Now that we have the location of the last amulet piece, we still need another component to suffuse the brazier with; something that will provide a focus strong enough to entice the spirit of my deceased, former comrade.$B$BMor Grayhoof, our most prominent druid, had many close friends amongst the Cenarion Circle, some of which have fallen to the silithid. I need you to retrieve some Druidical Remains from the silithid that inhabit the environs of Hive'Regal in southeastern Silithus." },
            { ids = { 8990 }, name = "The Right Piece of Lord Valthalak's Amulet", level = 60, zone = "Eastern Kingdoms", giver = "Bodley", giverMap = 1415, giverX = 48.9, giverY = 63.9, ender = "Bodley", enderMap = 1415, enderX = 48.9, enderY = 63.9, objective = "Use the Brazier of Beckoning to summon forth the spirit of Isalien and slay her. Return to Bodley inside Blackrock Mountain with the recombined Lord Valthalak's Amulet and the Brazier of Beckoning.", summary = "It became known to us in later days, as we were doing what we could ourselves to survive, that Isalien, a night elf priestess of our company, had gone to the night elvic ancestral city, now known as Dire Maul. From what we gathered, she went there both for personal reasons and also to unlock the secrets of the piece of the amulet that she had in her possession.$B$BShe didn't quite make it, though. Word got back to us that she was ambushed at the Shrine of Eldretharr by Alzzin the Wildshaper and his forces." },
            { ids = { 8994 }, name = "Final Preparations", level = 60, zone = "Eastern Kingdoms", giver = "Bodley", giverMap = 1415, giverX = 48.9, giverY = 63.9, ender = "Bodley", enderMap = 1415, enderX = 48.9, enderY = 63.9, objective = "Gather 40 Blackrock Bracers and acquire a Flask of Supreme Power. Return them to Bodley inside Blackrock Mountain.", summary = "We're nearly there, $c. All that is left is to retrieve a few more components so that I can attune the brazier and enable it to beckon forth Lord Valthalak.$B$BTo begin I must ask you to journey forth into Blackrock Spire and slay the orcs therein. They wear bracers that contain trace metals that I will need, so I'll need more than a few to extract the right amount out of them. Then, to complete the imbuing process, you'll need to bring me a Flask of Supreme Power.$B$BGood luck, $N!" },
            { ids = { 8995 }, name = "Mea Culpa, Lord Valthalak", level = 60, zone = "Eastern Kingdoms", giver = "Bodley", giverMap = 1415, giverX = 48.9, giverY = 63.9, ender = "Spirit of Lord Valthalak", enderMap = 1427, enderX = 34.8, enderY = 85.3, enderInside = "Blackrock Spire", objective = "Use the Brazier of Beckoning to summon Lord Valthalak. Dispatch him, and use Lord Valthalak's Amulet on the corpse. Then, return Lord Valthalak's Amulet to the Spirit of Lord Valthalak.", summary = "All is now ready, $N.$B$BWhen alive, Lord Valthalak used to inhabit what is now The Beast's chamber. Go there and use the Brazier of Beckoning to summon forth Lord Valthalak. It will reincorporate him, so he'll have to be killed again. I'd take care of The Beast first, and be sure take enough friends along to survive the upper portion of Blackrock Spire.$B$BOnce you've dispatched Valthalak, use the amulet on his corpse. With his spirit reunified, he'll likely want his amulet back, as well.$B$BGood luck!" },
            { ids = { 8996 }, name = "Return to Bodley", level = 60, zone = "Blackrock Spire", giver = "Spirit of Lord Valthalak", giverMap = 1427, giverX = 34.8, giverY = 85.3, giverInside = "Blackrock Spire", ender = "Bodley", enderMap = 1415, enderX = 48.9, enderY = 63.9, objective = "Return to Bodley inside Blackrock Mountain and give him the Brazier of Beckoning.", summary = "I will ignore your impertinence this time, $c, because you have done a noble thing today; returning the rest of my stolen spirit to me. Despite your obviously weak nature, $r, you have shown courage where those that stole from me did not, and probably never could!$B$BReturn to them, before I change my mind and slay you where you stand. Go back and tell them that they are safe... for now." },
            { ids = { 8998 }, name = "Back to the Beginning", level = 60, zone = "Eastern Kingdoms", giver = "Bodley", giverMap = 1415, giverX = 48.9, giverY = 63.9, ender = "Mokvar", enderMap = 1454, enderX = 35.0, enderY = 38.3, objective = "Speak with Mokvar at Grommash Hold in Orgrimmar's Valley of Wisdom.", summary = "I suppose that this is goodbye then, my friend. But, I'll always be here if you want to come back and talk with me from time to time. Probably while you're loitering around waiting for your buddies to join you for a raid on Blackrock Spire.$B$BGo, before I start to cry. Go back to Mokvar in Orgrimmar and tell him what's happened." },
        },
    },
    {
        id = "q8930",
        name = "The Challenge",
        zone = "Orgrimmar",
        minLevel = 58,
        maxLevel = 60,
        importance = 2,
        kind = "dungeon",
        quests = {
            { ids = { 8913, 8914, 8915, 8916, 8917, 8918, 8919, 8920 }, name = "An Earnest Proposition", level = 60, zone = "Orgrimmar", giver = "Mokvar", giverMap = 1454, giverX = 35.0, giverY = 38.3, ender = "Mokvar", enderMap = 1454, enderX = 35.0, enderY = 38.3, objective = "Acquire 15 Silithus Venom Samples and 20 gold and bring them along with a set of Wildheart Bracers to Mokvar in Orgrimmar.", summary = "Hail, $c!  I can tell by your demeanor that you've seen and done much in this world.  Yet I'm willing to wager you haven't seen a piece of armor like this.$B$BPerform a small favor for me and I'll be willing to trade it to you for an ordinary set of bracers.$B$BI'm in need of a sizeable sample of venom drawn from the spiders and scorpions that inhabit Silithus.  Bring this to me along with a few gold coins and I'll perform the exchange." },
            { ids = { 8923 }, name = "A Supernatural Device", level = 60, zone = "Orgrimmar", giver = "Mokvar", giverMap = 1454, giverX = 35.0, giverY = 38.3, ender = "Mux Manascrambler", enderMap = 1446, enderX = 52.5, enderY = 27.2, objective = "Take the Sealed Venom Container to Mux Manascrambler in Gadgetzan.", summary = "You must be quite brave to have stuck around after that.  That or I've piqued your interest with the piece of armor I gave you.  There is more from where that came from, if you're still interested in aiding me.$B$BThe venom samples you collected are for an acquaintance of mine, Mux Manascrambler, an engineer with an interest in the supernatural.  His latest project consists of a device that allows you to communicate with the dead!  My last hope is to contact Anthion and find out more about my situation." },
            { ids = { 8927, 8938, 8939, 8940, 8941, 8942, 8943, 8944 }, name = "Just Compensation", level = 60, zone = "Orgrimmar", giver = "Mokvar", giverMap = 1454, giverX = 35.0, giverY = 38.3, ender = "Mokvar", enderMap = 1454, enderX = 35.0, enderY = 38.3, objective = "Bring a Wildheart Belt and a set of Wildheart Gloves to Mokvar in Orgrimmar.", summary = "You've proven to be a very reliable individual, $N.  As much as I trust that you'll help me through this predicament, it would be wise of me to reward you according to your performance.$B$BFor now I will exchange your belt and gloves.  If we both see this through I shall make the rest of the pieces available to you." },
            { ids = { 8930 }, name = "In Search of Anthion", level = 60, zone = "Orgrimmar", giver = "Mokvar", giverMap = 1454, giverX = 35.0, giverY = 38.3, ender = "Anthion Harmon", enderMap = 1423, enderX = 26.1, enderY = 11.3, objective = "Use the Extra-Dimensional Ghost Revealer at the entrance to Stratholme and speak with the ghost of Anthion Harmon.", summary = "Very well, $N.  All that remains is to put the goblin's invention to the test.  Word has it that Anthion was slain by the undead legions of Stratholme as he tried to enter its gates.$B$BTry using the device there and see if, indeed, you can speak with the dead!" },
            { ids = { 8921 }, name = "The Ectoplasmic Distiller", level = 60, zone = "Tanaris", giver = "Mux Manascrambler", giverMap = 1446, giverX = 52.5, giverY = 27.2, ender = "Mux Manascrambler", enderMap = 1446, enderX = 52.5, enderY = 27.2, objective = "Return to Mux Manascrambler in Gadgetzan with 1 Delicate Arcanite Converter, 4 Greater Eternal Essence, 10 Stonescale Oil, 25 Volcanic Ash and 40 gold.", summary = "Ah, you're in need of my latest project... the extra-dimensional ghost revealer!  Unfortunately I've run out of funds and manpower.$B$BYou're willing to help?  Excellent!  Our first task is to build a device to harvest the very fabric of death!  Building an ectoplasmic distiller won't be an easy task, $N.$B$BI'll need you to bring me an arcanite converter, some greater eternal essences and stonescale oil. I'll also need some volcanic ash from the lava pools in the Burning Steppes to build a filter." },
            { ids = { 8945 }, name = "Dead Man's Plea", level = 60, zone = "Eastern Plaguelands", giver = "Anthion Harmon", giverMap = 1423, giverX = 26.1, giverY = 11.3, ender = "Ysida Harmon", enderMap = 1423, enderX = 26.5, enderY = 10.4, enderInside = "Stratholme", objective = "Go into Stratholme and rescue Ysida Harmon from Baron Rivendare.", summary = "I'll provide you the information you ask for, $N.  But more pressing matters are at hand.$B$BMy beloved wife has been taken prisoner by Rivendare's undead scum.$B$BI strongly objected to her joining the Argent Dawn's foolish crusade, yet that's not of importance anymore.  You must finish what I attempted to do, you must rescue Ysida from the clutches of the Baron!" },
            { ids = { 8924 }, name = "Hunting for Ectoplasm", level = 60, zone = "Tanaris", giver = "Mux Manascrambler", giverMap = 1446, giverX = 52.5, giverY = 27.2, ender = "Mux Manascrambler", enderMap = 1446, enderX = 52.5, enderY = 27.2, objective = "Use the Ectoplasmic Distiller near incorporeal undead to collect 12 Scorched Ectoplasms in Silithus, 12 Frozen Ectoplasms in Winterspring and 12 Stable Ectoplasms in the Eastern Plaguelands.  Bring them along with the Ectoplasmic Distiller back to Mux Manascrambler in Gadgetzan.", summary = "A fine piece of engineering, if I do say so myself!  You will need to travel a bit, I'm afraid, in order to find the incorporeal undead we require.$B$BYou see, different climates lend different consistencies to the spectral fabric of the dead.  The tortured night elves of Silithus, the spirits of the highborne from Winterspring and the ghosts and banshees of the Eastern Plaguelands should give us the different types of ectoplasm we need.  Be sure to place the distiller nearby before you harvest them!" },
            { ids = { 8946 }, name = "Proof of Life", level = 60, zone = "Stratholme", giver = "Ysida Harmon", giverMap = 1423, giverX = 26.5, giverY = 10.4, giverInside = "Stratholme", ender = "Anthion Harmon", enderMap = 1423, enderX = 26.1, enderY = 11.3, objective = "Bring Ysida's Locket to Anthion Harmon in Eastern Plaguelands.", summary = "It is the cruelest of fates that my beloved has perished while trying to rescue me.  Yet, you claim to possess the ability to converse with him.$B$BBring him this locket as proof that I am well.  He must not linger in this world; my heart would not be able to bear it.$B$BFarewell, $N.  I shall be in your debt always." },
            { ids = { 8925 }, name = "A Portable Power Source", level = 60, zone = "Tanaris", giver = "Mux Manascrambler", giverMap = 1446, giverX = 52.5, giverY = 27.2, ender = "Mux Manascrambler", enderMap = 1446, enderX = 52.5, enderY = 27.2, objective = "Find Magma Lord Bokk in the Burning Steppes, obtain his Magma Core and bring it to Mux Manascrambler in Gadgetzan.", summary = "Next we shall need to find a stable and portable source of energy to keep the ectoplasm active.  I've heard rumors of a mighty elemental called Magma Lord Bokk, whose heart is a powerful magma core - an endless supply of heat!$B$BIt's said he can be found in the Burning Steppes, south of Blackrock Mountain.  Bring the magma core to me and we shall have enough juice to power the extra-dimensional ghost revealer!" },
            { ids = { 8947 }, name = "Anthion's Strange Request", level = 60, zone = "Eastern Plaguelands", giver = "Anthion Harmon", giverMap = 1423, giverX = 26.1, giverY = 11.3, ender = "Anthion Harmon", enderMap = 1423, enderX = 26.1, enderY = 11.3, objective = "Bring 3 Dark Iron Bars, 20 Enchanted Leather, 3 Mooncloth and 4 Cured Rugged Hides to Anthion Harmon in the Eastern Plaguelands.", summary = "We didn't realize the importance of Valthalak's medallion, so it was divided along with the rest of the spoils.  The first piece was taken by a dwarf named Theldren.  I tried to retrieve it from him and he beat me within an inch of my life.  You shall have to take the fragment by force.$B$BLast I heard of him, he'd become a gladiator for the Dark Iron dwarves.  Getting him to fight you is going to present a bit of a challenge, though.$B$BGather the following materials for me.  You're going to need them." },
            { ids = { 8928 }, name = "A Shifty Merchant", level = 60, zone = "Tanaris", giver = "Mux Manascrambler", giverMap = 1446, giverX = 52.5, giverY = 27.2, ender = "Mux Manascrambler", enderMap = 1446, enderX = 52.5, enderY = 27.2, objective = "Search for an imp inside a cave at the entrance of Darkwhisper Gorge in southern Winterspring, purchase a Fel Elemental Rod and return to Mux Manascrambler in Gadgetzan.", summary = "The core will provide us with enough juice to power our device; now we just have to build a rod that can channel that energy without melting.$B$BI met an imp in Winterspring that sold all manner of exotic goods.  He had an elemental rod that would do perfectly.  I'm kicking myself in the head right now for not having bought it.$B$BHe lives inside a cave in the entrance to Darkwhisper Gorge.  Sneak in there and try to find him.$B$BMake sure he only charges you forty gold; that's the price he quoted me!" },
            { ids = { 8948 }, name = "Anthion's Old Friend", level = 60, zone = "Eastern Plaguelands", giver = "Anthion Harmon", giverMap = 1423, giverX = 26.1, giverY = 11.3, ender = "Falrin Treeshaper", enderMap = 1444, enderX = 62.5, enderY = 24.9, enderInside = "Dire Maul", objective = "Take the incomplete Banner of Provocation to Falrin Treeshaper at the library in Dire Maul.", summary = "Theldren is not one to willingly participate in a fair fight.  I've shaped this banner to display his family colors.$B$BWith some additional sorcery, this banner shall provoke him in a way he won't be able to resist.$B$BAn old acquaintance of mine named Falrin knows the exact procedure required.  He has a particular way of... aggravating people.  You shall find him at the library in Dire Maul." },
            { ids = { 8978 }, name = "Return to Mokvar", level = 60, zone = "Tanaris", giver = "Mux Manascrambler", giverMap = 1446, giverX = 52.5, giverY = 27.2, ender = "Mokvar", enderMap = 1454, enderX = 35.0, enderY = 38.3, objective = "Return to Mokvar in Orgrimmar with the Extra-Dimensional Ghost Revealer.", summary = "It's been great working with you, $N.  Here is the finished product.$B$BI hope it helps you in your current endeavors.  And hey, if you don't mind, help spread the word.  I wouldn't mind having more customers!" },
            { ids = { 8949 }, name = "Falrin's Vendetta", level = 60, zone = "Dire Maul", giver = "Falrin Treeshaper", giverMap = 1444, giverX = 62.5, giverY = 24.9, giverInside = "Dire Maul", ender = "Falrin Treeshaper", enderMap = 1444, enderX = 62.5, enderY = 24.9, enderInside = "Dire Maul", objective = "Collect 25 Ogre Warbeads from Ogres inside Dire Maul or Blackrock Spire and return to Falrin Treeshaper inside the Athenaeum in Dire Maul.", summary = "Yes, it is true that I am familiar with this enchantment you require, $c.  Yet I'm not one to give out favors freely, even if you were sent here by an old friend.$B$BI hold nothing but hatred and contempt for our brutish ogre neighbors.  And not only them, I hate the followers of Omokk just as much as I hate those that follow King Gordok.$B$BI want you to kill them.  Kill lots of them!  Bring me the beads they carry around their neck as proof of your work.  Do this and we shall talk about your request." },
            { ids = { 8950 }, name = "The Instigator's Enchantment", level = 60, zone = "Dire Maul", giver = "Falrin Treeshaper", giverMap = 1444, giverX = 62.5, giverY = 24.9, giverInside = "Dire Maul", ender = "Falrin Treeshaper", enderMap = 1444, enderX = 62.5, enderY = 24.9, enderInside = "Dire Maul", objective = "Bring the following to Falrin Treeshaper inside Dire Maul: 1 Jeering Spectre's Essence, 4 Dark Runes and 8 Large Brilliant Shards.", summary = "I can place the enchantment you require on the banner quite easily, $N.  Unfortunately I don't have the materials I need as it is very rarely that someone asks for this sort of charm.$B$BI will require the essence of one of the Eldreth ghosts that haunt these halls, a handful of Scholomance dark runes and some large brilliant shards.  Bring me these reagents and I shall perform this task for you." },
            { ids = { 9015 }, name = "The Challenge", level = 60, zone = "Dire Maul", giver = "Falrin Treeshaper", giverMap = 1444, giverX = 62.5, giverY = 24.9, giverInside = "Dire Maul", ender = "Anthion Harmon", enderMap = 1423, enderX = 26.1, enderY = 11.3, objective = "Travel to the Ring of the Law in Blackrock Depths and place the Banner of Provocation in its center as you are sentenced by High Justice Grimstone.  Slay Theldren and his gladiators and return to Anthion Harmon in the Eastern Plaguelands with the first piece of Lord Valthalak's amulet.", summary = "Heed me well, $N.  For the banner to work in the desired way, you will need to step into the Ring of the Law in Blackrock Depths.  Allow yourself to be sentenced by High Justice Grimstone and place the banner firmly on the ground in a sign of defiance.$B$BYour victim will not be able to restrain himself and shall enter the fray filled with a desire to fight you.  Once you obtain that which you seek, go back to Anthion." },
        },
    },
    {
        id = "q8286",
        name = "Only One May Rise",
        zone = "Silithus",
        minLevel = 60,
        maxLevel = 60,
        importance = 3,
        kind = "raid",
        quests = {
            { ids = { 8286 }, name = "What Tomorrow Brings", level = 60, zone = "Silithus", giver = "Baristolth of the Shifting Sands", giverMap = 1451, giverX = 49.5, giverY = 36.5, ender = "Baristolth of the Shifting Sands", enderMap = 1451, enderX = 49.5, enderY = 36.5, objective = "Venture to the Caverns of Time in Tanaris and find Anachronos, Brood of Nozdormu.", summary = "The embrace of death had all but overcome my being when he intervened. He breathed only once upon my maimed body and then waited patiently for the sands of time to cleanse my wounds.$B$B\"Forever you will remain if you must,\" he said, and with those words I was bound as a Watcher.$B$BLook now to the desert. The second war is upon us. You must seek out the resting place of the Bronze. Venture to the Caverns of Time and see if the master has returned. I must be sure before I am able to proceed." },
            { ids = { 8288 }, name = "Only One May Rise", level = 60, zone = "Silithus", giver = "Baristolth of the Shifting Sands", giverMap = 1451, giverX = 49.5, giverY = 36.5, ender = "Baristolth of the Shifting Sands", enderMap = 1451, enderX = 49.5, enderY = 36.5, objective = "Return the Head of the Broodlord Lashlayer to Baristolth of the Shifting Sands at Cenarion Hold in Silithus.", summary = "There is no time to waste! A hero must be found! The task I give will require an army to complete but only one may rise from the throng of would be champions to take on the burden and responsibility of an ally of the Brood.$B$BWithin the lair of the Lord of Blackrock is a most cruel beast. The Broodlord Lashlayer guards the Halls of Strife, blocking the way into Nefarian's inner sanctum. Slay the foul aberration and return his head to me. Do this and you may begin the next step of your journey." },
            { ids = { 8301 }, name = "The Path of the Righteous", level = 60, zone = "Silithus", giver = "Baristolth of the Shifting Sands", giverMap = 1451, giverX = 49.5, giverY = 36.5, ender = "Baristolth of the Shifting Sands", enderMap = 1451, enderX = 49.5, enderY = 36.5, objective = "Collect 200 Silithid Carapace Fragments and return to Baristolth.", summary = "The Brood of Nozdormu are naturally distrusting of the lesser races. While it is true that you have proven to me that you have the potential makings of a hero, the time has come to prove this to my master.$B$BHive'Ashi, Hive'Zora, Hive'Regal: All swarming with activity and all a threat to our existence. Slay silithid at these hives and take from them a fragment of their carapace. When you can carry no more, return to me and I shall strengthen your resolve." },
            { ids = { 8303 }, name = "Anachronos", level = 60, zone = "Silithus", giver = "Baristolth of the Shifting Sands", giverMap = 1451, giverX = 49.5, giverY = 36.5, ender = "Anachronos", enderMap = 1446, enderX = 65.3, enderY = 50.0, objective = "Seek out Anachronos at the Caverns of Time in Tanaris.", summary = "It is time, $N.$B$BI must apologize for keeping so much in secret. Enemies abound, even under our very noses. Please, read from this tome and learn. Take the knowledge I give to you and seek out our master." },
            { ids = { 8305 }, name = "Long Forgotten Memories", level = 60, zone = "Tanaris", giver = "Anachronos", giverMap = 1446, giverX = 65.3, giverY = 50.0, ender = "Crystalline Tear", enderMap = 1451, enderX = 28.7, enderY = 89.1, objective = "Locate the Crystalline Tear in Silithus and gaze into its depths.", summary = "In the southern desert of Silithus, near the sacred barrier, exists a single crystalline tear. This tear serves as a symbol of the great losses beset upon us during the War of the Shifting Sands. Locate this tear and gaze into its depths to gain enlightenment." },
            { ids = { 8519 }, name = "A Pawn on the Eternal Board", level = 60, zone = "Silithus", giver = "Crystalline Tear", giverMap = 1451, giverX = 28.7, giverY = 89.1, ender = "Anachronos", enderMap = 1446, enderX = 65.3, enderY = 50.0, objective = "Learn all that you can of the past, then speak with Anachronos at the Caverns of Time in Tanaris.", summary = "As you regain your composure and focus your gaze, you notice that something stirs within the crystal. Upon closer inspection, you realize that you are looking into the past... a memory... long forgotten." },
            { ids = { 8555 }, name = "The Charge of the Dragonflights", level = 60, zone = "Tanaris", giver = "Anachronos", giverMap = 1446, giverX = 65.3, giverY = 50.0, ender = "Anachronos", enderMap = 1446, enderX = 65.3, enderY = 50.0 },
            { ids = { 8730 }, name = "Nefarius's Corruption", level = 60, zone = "Blackwing Lair", giver = "Vaelastrasz the Corrupt", giverMap = 1427, giverX = 34.8, giverY = 85.3, giverInside = "Blackwing Lair", ender = "Anachronos", enderMap = 1446, enderX = 65.3, enderY = 50.0, objective = "Slay Nefarian and recover the Red Scepter Shard. Return the Red Scepter Shard to Anachronos at the Caverns of Time in Tanaris. You have 5 hours to complete this task.", summary = "Champion, is it you? A thousand years it has been since I was entrusted the shard and it is at my darkest hour that one should rise to relieve me of it... But what would tragedy be without cruelty?$B$B<Vaelastrasz coughs weakly.>$B$BNe... Nefarius now holds the scepter shard.$B$BTime is of the essence. Nefarius plans to destroy the shard. You must hurry!" },
            { ids = { 8733 }, name = "Eranikus, Tyrant of the Dream", level = 60, zone = "The Temple of Atal'Hakkar", giver = "Malfurion Stormrage", giverMap = 1435, giverX = 69.9, giverY = 53.5, giverInside = "The Temple of Atal'Hakkar", ender = "Forest Wisp", enderMap = 1438, enderX = 37.5, enderY = 47.9, objective = "Travel to the continent of Teldrassil and find Malfurion's agent somewhere outside the walls of Darnassus.", summary = "This is a journey of redemption, hero. Would it be that I was slain today, I would have died for a just and righteous cause. You must recover the green scepter shard. You must cleanse Eranikus of the taint placed upon him by the Old Gods.$B$BTravel to Darnassus. Just outside the city walls you will find one of my agents. This agent will set things in motion for us and inform Tyrande of our plans without alerting Staghelm.$B$B<Malfurion sighs.>$B$BA fall from grace a thousand years in the making..." },
            { ids = { 8734 }, name = "Tyrande and Remulos", level = 60, zone = "Teldrassil", giver = "Forest Wisp", giverMap = 1438, giverX = 37.5, giverY = 47.9, ender = "Keeper Remulos", enderMap = 1450, enderX = 36.2, enderY = 41.8, objective = "Travel to the Moonglade and speak to Keeper Remulos. ", summary = "Tyrande will be notifed, mortal. Shan'do Stormrage has prepared me for this contingency.$B$BNow you must venture to the Moonglade and speak with Remulos. He will have further instruction as to the summoning of Eranikus.$B$BWe all wish you great luck." },
            { ids = { 8735 }, name = "The Nightmare's Corruption", level = 60, zone = "Moonglade", giver = "Keeper Remulos", giverMap = 1450, giverX = 36.2, giverY = 41.8, ender = "Keeper Remulos", enderMap = 1450, enderX = 36.2, enderY = 41.8, objective = "Travel to the four Emerald Dream portals in Azeroth and collect a Fragment of the Nightmare's Corruption from each. Return to Keeper Remulos in the Moonglade when you have completed this task.", summary = "You must travel to the four dream portals of Azeroth. From each you must draw a fragment of the Nightmare's corruption. The dragonkin that inhabit these areas will hold such fragments. Return to me when you have gathered these fragments." },
            { ids = { 8736 }, name = "The Nightmare Manifests", level = 60, zone = "Moonglade", giver = "Keeper Remulos", giverMap = 1450, giverX = 36.2, giverY = 41.8, ender = "Keeper Remulos", enderMap = 1450, enderX = 36.2, enderY = 41.8, objective = "Defend Nighthaven from Eranikus. Do not let Keeper Remulos perish. Do not slay Eranikus. Defend yourself. Await Tyrande.", summary = "We must use restraint against Eranikus. We are to redeem him not destroy him.$B$BTyrande is already en route to assist us in this task. We must weather the dragon's blows and save Nighthaven from certain destruction.$B$BBe on guard! You and your allies are our only hope." },
            { ids = { 8741 }, name = "The Champion Returns", level = 60, zone = "Moonglade", giver = "Keeper Remulos", giverMap = 1450, giverX = 36.2, giverY = 41.8, ender = "Anachronos", enderMap = 1446, enderX = 65.3, enderY = 50.0, objective = "Take the Green Scepter Shard to Anachronos at the Caverns of Time in Tanaris.", summary = "The keeper awaits your return, $N. Take the green scepter shard to Anachronos at the Caverns of Time." },
            { ids = { 8742 }, name = "The Might of Kalimdor", level = 60, zone = "Tanaris", giver = "Anachronos", giverMap = 1446, giverX = 65.3, giverY = 50.0, ender = "Anachronos", enderMap = 1446, enderX = 65.3, enderY = 50.0, after = { 8729 } },
            { ids = { 8745 }, name = "Treasure of the Timeless One", level = 60, zone = "Silithus", giver = "Jonathan the Revelator", giverMap = 1451, giverX = 25.9, giverY = 91.0, ender = "Jonathan the Revelator", enderMap = 1451, enderX = 25.9, enderY = 91.0 },
        },
    },
    {
        id = "q8575",
        name = "The Wrath of Neptulon",
        zone = "Azshara",
        minLevel = 60,
        maxLevel = 60,
        importance = 2,
        kind = "raid",
        quests = {
            { ids = { 8575 }, name = "Azuregos's Magical Ledger", level = 60, zone = "Azshara", giver = "Spirit of Azuregos", giverMap = 1447, giverX = 53.0, giverY = 81.7, ender = "Narain Soothfancy", enderMap = 1446, enderX = 65.2, enderY = 18.6, after = { 8555 }, objective = "Deliver Azuregos's Magical Ledger to Narain Soothfancy in Tanaris.", summary = "You cannot understand a single word on this ledger. You don't even know what language it is written in!" },
            { ids = { 8576 }, name = "Translating the Ledger", level = 60, zone = "Tanaris", giver = "Narain Soothfancy", giverMap = 1446, giverX = 65.2, giverY = 18.6, ender = "Narain Soothfancy", enderMap = 1446, enderX = 65.2, enderY = 18.6 },
            { ids = { 8577 }, name = "Stewvul, Ex-B.F.F.", level = 60, zone = "Tanaris", giver = "Narain Soothfancy", giverMap = 1446, giverX = 65.2, giverY = 18.6, ender = "Inconspicuous Crate", enderMap = 1421, enderX = 46.2, enderY = 86.7, objective = "Narain Soothfancy wants you to find his ex-best friend forever (BFF), Stewvul, and take back the scrying goggles that Stewvul stole from him.", summary = "If I am to translate anything, I will need my scrying goggles. Unfortunately, those were stolen quite some time ago by my ex-best friend forever, Stewvul. He broke my heart in five places and then left me here to rot.$B$BWith the help of my trusty crystal ball, I've isolated his whereabouts to either the Greymane Wall in Silverpine or what appears to be a portal world in the Outland that is currently being overrun by the Burning Legion. You're going to have to track him down and get my goggles back, $N!" },
            { ids = { 8584 }, name = "Never Ask Me About My Business", level = 60, zone = "Tanaris", giver = "Narain Soothfancy", giverMap = 1446, giverX = 65.2, giverY = 18.6, ender = "Dirge Quikcleave", enderMap = 1446, enderX = 52.6, enderY = 28.1, objective = "Narain Soothfancy in Tanaris wants you to speak with Dirge Quikcleave in Gadgetzan.", summary = "If there is one thing that you should know about me, it is this: NEVER ask me about my business! I work with things you simply cannot understand. Like for example: Do you know what a psychotronic muzzledorf is? Of course you don't! And that's why we leave the planning to me and the fetching to you.$B$BAs I said earlier, if this is going to work, we're going to need a 500 pound chicken.$B$BHead to Gadgetzan and speak with Dirge Quikcleave - he'll get you started on finding a suitable specimen." },
            { ids = { 8597 }, name = "Draconic for Dummies", level = 60, zone = "Tanaris", giver = "Narain Soothfancy", giverMap = 1446, giverX = 65.2, giverY = 18.6, ender = "Freshly Dug Dirt", enderMap = 947, enderX = 30.0, enderY = 89.2, objective = "Find Narain Soothfancy's book, buried on an island in the South Seas.", summary = "I knew that book would come in handy some day! Thankfully, I had the wit and foresight to stow it somewhere safe.$B$BDon't worry, it's in a place that nobody could ever hope to find it! I needed a gyrocopter just to get there the first time. Unfortunately I crashed it on the beach on my way back. It was through that accident that I gained these super-gnomish psychic powers!$B$BLook for my crashed gyrocopter somewhere on Land's End Beach and swim south from there! You'll know the spot when you see it!" },
            { ids = { 8578 }, name = "Scrying Goggles? No Problem!", level = 60, zone = "Silverpine Forest", giver = "Inconspicuous Crate", giverMap = 1421, giverX = 46.2, giverY = 86.7, ender = "Narain Soothfancy", enderMap = 1446, enderX = 65.2, enderY = 18.6, objective = "Find Narain's Scrying Goggles and return them to Narain Soothfancy in Tanaris.", summary = "<You hear a sigh of relief escape the crate.>$B$BYou just want his scrying goggles? Great! That will be no problem... Just give me a minute to... Hey! Where the... Dagnabbit!$B$BWell, there's some bad news and some worse news. The bad news is that I lost the goggles. The worse news is that I lost them when I was nosing around in the Molten Core last month. Yep, the Molten Core... I guess that concludes our business! Bye!" },
            { ids = { 8585 }, name = "The Isle of Dread!", level = 60, zone = "Tanaris", giver = "Dirge Quikcleave", giverMap = 1446, giverX = 52.6, giverY = 28.1, ender = "Dirge Quikcleave", enderMap = 1446, enderX = 52.6, enderY = 28.1, objective = "Recover Lakmaeran's Carcass and 20 Chimaerok Tenderloins for Dirge Quickcleave in Tanaris.", summary = "Legend has it that the chimaerok of the Isle of Dread in Feralas have the most succulent and tender vittles in existence! Now these chimaerok also have a daddy who, with proper preparation, may or may not look like a 500 pound chicken.$B$BHead to the Isle of Dread and kill Lord Lakmaeran and bring me his fresh carcass. That should satisfy the gnome. To satisfy me, you'll need to get your hands on some chimaerok tenderloin.$B$BDo this and you'll have your 500 pound chicken and a little something extra." },
            { ids = { 8598 }, name = "rAnS0m", level = 60, zone = "Azeroth", giver = "Freshly Dug Dirt", giverMap = 947, giverX = 30.0, giverY = 89.2, ender = "Narain Soothfancy", enderMap = 1446, enderX = 65.2, enderY = 18.6, objective = "Return the Ransom Letter to Narain Soothfancy in Tanaris.", summary = "<The text on this note is made up of various typefaces glued onto the parchment's surface.>$B$BWe've got your precious book, gnome. If you ever want to see it again, you'll do exactly as we ask.$B$B<A detailed set of instructions is listed, spanning 3 pages.>$B$BBring the money and come alone!" },
            { ids = { 8586 }, name = "Dirge's Kickin' Chimaerok Chops", level = 60, zone = "Tanaris", giver = "Dirge Quikcleave", giverMap = 1446, giverX = 52.6, giverY = 28.1, ender = "Dirge Quikcleave", enderMap = 1446, enderX = 52.6, enderY = 28.1, objective = "Dirge Quikcleave in Gadgetzan wants you to bring him 20 Goblin Rocket Fuel and 20 Deeprock Salt.", summary = "My recipe is complete! What I need from you now is some rocket fuel and deeprock salt. I'll handle the spices and the meat you brought me will cover the rest.$B$BAfter you bring me what I asked for, the chicken will be ready to take back to Narain." },
            { ids = { 8606 }, name = "Decoy!", level = 60, zone = "Tanaris", giver = "Narain Soothfancy", giverMap = 1446, giverX = 65.2, giverY = 18.6, ender = "Narain Soothfancy", enderMap = 1446, enderX = 65.2, enderY = 18.6, objective = "Narain Soothfancy in Tanaris wants you to travel to Winterspring and place the Bag of Gold at the drop off point documented by the booknappers.", summary = "I've got it! Here's what we're going to do. I'm going to fill a sack up with rocks and you're going to make the drop. I know it said that I should make the delivery and I'm going to - sort of.$B$B<Narain looks you up and down.>$B$BYes, you will do just fine. Take this turban, robe, and sack of rocks and head to the drop off point in Winterspring.$B$BI've included everything you need in this special kit. When they show up to pick up the goods, snuff them out! That will teach them to mess with Narain!" },
            { ids = { 8587 }, name = "Return to Narain", level = 60, zone = "Tanaris", giver = "Dirge Quikcleave", giverMap = 1446, giverX = 52.6, giverY = 28.1, ender = "Narain Soothfancy", enderMap = 1446, enderX = 65.2, enderY = 18.6, objective = "Deliver the 500 Pound Chicken to Narain Soothfancy in Tanaris.", summary = "I'm a goblin of my word, kid. Here's your 500 pound chicken.$B$BWhat a gnome wants with a 500 pound chicken, I'll never know...$B$B<Dirge grumbles something unintelligible.>$B$BProbably to sleep in it... Dirty gnomes..." },
            { ids = { 8620 }, name = "The Only Prescription", level = 60, zone = "Tanaris", giver = "Narain Soothfancy", giverMap = 1446, giverX = 65.2, giverY = 18.6, ender = "Narain Soothfancy", enderMap = 1446, enderX = 65.2, enderY = 18.6, objective = "Recover the 8 lost chapters of Draconic for Dummies and combine them with the Magical Book Binding and return the completed book of Draconic for Dummies: Volume II to Narain Soothfancy in Tanaris.", summary = "I should have known. My arch-enemy, Doctor Weavil, up to his old tricks! And now, thanks to your failure in Winterspring, Doctor Weavil has destroyed my book! How are you going to save the world now, hero?$B$BThe note I received stated that the only known copy of \"Draconic for Dummies: Volume II\" was ripped into 8 parts and scattered to the wind! If you somehow manage to find those missing chapters, use this magical binding to put them back together and return to me." },
            { ids = { 8728 }, name = "The Good News and The Bad News", level = 60, zone = "Tanaris", giver = "Narain Soothfancy", giverMap = 1446, giverX = 65.2, giverY = 18.6, ender = "Narain Soothfancy", enderMap = 1446, enderX = 65.2, enderY = 18.6, objective = "Narain Soothfancy in Tanaris wants you to bring him 20 Arcanite Bars, 10 Elementium Ore, 10 Azerothian Diamonds, and 10 Blue Sapphires.", summary = "Well that took a little longer than expected. Now let me see what this ledger says.$B$B<Narain silently reads the ledger, periodically mumbling under his breath.>$B$B The good news is that I am 99% certain that I am capable of creating an arcanite buoy that will function to your specifications. This is, of course, wholly dependant on the bad news.$B$BThe bad news is that I'm going to need a lot of arcanite, elementium ore, and rare gemstones.$B$BBring me what I need and I will craft the buoy." },
            { ids = { 8729 }, name = "The Wrath of Neptulon", level = 60, zone = "Tanaris", giver = "Narain Soothfancy", giverMap = 1446, giverX = 65.2, giverY = 18.6, ender = "Anachronos", enderMap = 1446, enderX = 65.3, enderY = 50.0, objective = "Use the Arcanite Buoy at the Swirling Maelstrom at the Bay of Storms in Azshara.", summary = "Did I mention the bad news yet? Its name is Maws: 100 feet of death and destruction. I guess I may have forgotten that little tidbit.$B$BAccording to my superior psycho-psionic clairvoyance, you'll find that the best spot to cast this buoy is off the coast of Azshara, in the Bay of Storms.$B$BLook for a swirling maelstrom, most likely cluttered with wreckage.$B$BBy the by, I hope you have friends.$B$BNow if you somehow miraculously succeed, take the scepter shard to Anachronos." },
        },
    },
    {
        id = "q7507",
        name = "The Forging of Quel'Serrar",
        zone = "Dire Maul",
        minLevel = 60,
        maxLevel = 60,
        importance = 2,
        kind = "class",
        classes = { 1 },
        quests = {
            { ids = { 7507 }, name = "Nostro's Compendium", level = 60, zone = "Dire Maul", ender = "Lorekeeper Lydros", enderMap = 1444, enderX = 62.5, enderY = 24.9, enderInside = "Dire Maul", objective = "Return Foror's Compendium of Dragon Slaying to the Athenaeum.", summary = "You have uncovered something of great importance. This book is unlike any that you have seen.$B$BIt would appear as if someone or something has managed to shatter the seal of Athenaeum. The text within is garbled and barely legible." },
            { ids = { 7508 }, name = "The Forging of Quel'Serrar", level = 60, zone = "Dire Maul", ender = "Lorekeeper Lydros", enderMap = 1444, enderX = 62.5, enderY = 24.9, enderInside = "Dire Maul", objective = "Give the Dull and Flat Elven Blade to Lorekeeper Lydros.", summary = "If you wish to take on this task, present Lydros with the dull blade." },
            { ids = { 7509 }, name = "The Forging of Quel'Serrar", level = 60, zone = "Dire Maul", giver = "Lorekeeper Lydros", giverMap = 1444, giverX = 62.5, giverY = 24.9, giverInside = "Dire Maul", ender = "Lorekeeper Lydros", enderMap = 1444, enderX = 62.5, enderY = 24.9, enderInside = "Dire Maul", objective = "You must get Onyxia to breathe fire on the Unfired Ancient Blade. Once this is done, pick up the now Heated Ancient Blade. Be warned, a Heated Ancient Blade will not remain heated forever - time is of the essence.$B$BThe last step before returning to me is to slay the beast and drive the Heated Ancient Blade into her corpse.$B$BDo this and Quel'Serrar will be yours.", summary = "Take the unfired ancient blade to the lair of Onyxia and engage her in battle.$B$BSome trickery must be utilized for the heating of the blade. While in combat, she will surely try to incinerate you with her fiery breath. You must plant the unfired ancient blade nearby and hope that the fiery breath heats the blade. If you live beyond this, pick up the now heated ancient blade and finish off the dragon.$B$BPlunge the heated ancient blade into her smoldering corpse to fashion the treated ancient blade." },
        },
    },
    {
        id = "q7623",
        name = "Dreadsteed of Xoroth",
        zone = "Burning Steppes",
        minLevel = 60,
        maxLevel = 60,
        importance = 2,
        kind = "class",
        classes = { 9 },
        quests = {
            { ids = { 7563 }, name = "Rage of Blood", level = 58, zone = "Burning Steppes", giver = "Mor'zul Bloodbringer", giverMap = 1428, giverX = 12.7, giverY = 31.6, ender = "Mor'zul Bloodbringer", enderMap = 1428, enderX = 12.7, enderY = 31.6, objective = "Bring 30 bottles of Raging Beast's Blood to Mor'zul Bloodbringer in the Burning Steppes.", summary = "The dreadsteeds dwell on another world, on the fiery Plains of Xoroth, and to bind one of those famed beasts you must invoke powerful glyphs.  I can scribe the glyphs on a parchment for you, but first I will need a special ink.$B$BIn distant Winterspring there dwells a race of owl beasts.  Once pure creatures, they were turned mad by the demonic emanations of the Darkwhisper Gorge and now roam the snows in a frenzy.$B$BTheir blood is what I need to ink your parchment.  Bring it to me." },
            { ids = { 7623 }, name = "Lord Banehollow", level = 58, zone = "Burning Steppes", giver = "Gorzeeki Wildeyes", giverMap = 1428, giverX = 12.4, giverY = 31.6, ender = "Lord Banehollow", enderMap = 1448, enderX = 35.9, enderY = 44.4, objective = "Purchase Shadowy Potions from Gorzeeki in the Burning Steppes.$B$BUse the potions to travel through Jaedenar, and speak with Lord Banehollow.", summary = "Mor'zul says that you want to open a portal to Xoroth.  To do that, you'll need Xorothian stardust.  That's not easy to find on Azeroth!$B$BThere is one being who might have some: Lord Banehollow in Jaedenar, the seat of the Shadow Council!  Speak with him and he might part with the stardust.$B$BBut if you're going to Jaedenar, then you'll need to cloak yourself in the Shadow Council's own flavor of evil.  That will require some of my shadowy potions, and that will cost you..." },
            { ids = { 7564 }, name = "Wildeyes", level = 58, zone = "Burning Steppes", giver = "Mor'zul Bloodbringer", giverMap = 1428, giverX = 12.7, giverY = 31.6, ender = "Gorzeeki Wildeyes", enderMap = 1428, enderX = 12.4, enderY = 31.6, objective = "Bring the Case of Blood to Gorzeeki Wildeyes in the Burning Steppes.", summary = "My servant, Gorzeeki, is an alchemist of some skill.  He can prepare the ink I will need for your parchment.  I gathered together the blood you acquired; take it to Gorzeeki so that he can begin his work." },
            { ids = { 7624 }, name = "Ulathek the Traitor", level = 58, zone = "Felwood", giver = "Lord Banehollow", giverMap = 1448, giverX = 35.9, giverY = 44.4, ender = "Lord Banehollow", enderMap = 1448, enderX = 35.9, enderY = 44.4, objective = "Confront Ulathek, then bring The Traitor's Heart to Lord Banehollow in Jaedenar.", summary = "You wish to enter my good graces?  Then kill for me.$B$BMy servant, Ulathek, is pathetic how he grovels before me, all the while plotting with Lord Hel'nurath on Xoroth.  Hel'nurath plans to usurp my power here, and Ulathek is his spy...$B$BProve that you serve me and not my rivals.  Confront Ulathek in his quarters, in the Shadow Hold to the west.  Tell him that I know his secret and watch as fear grips him.  Then, bring me the traitor's heart!" },
            { ids = { 7626 }, name = "Bell of Dethmoora", level = 60, zone = "Burning Steppes", giver = "Mor'zul Bloodbringer", giverMap = 1428, giverX = 12.7, giverY = 31.6, ender = "Gorzeeki Wildeyes", enderMap = 1428, enderX = 12.4, enderY = 31.6, objective = "Bring 10 Elixirs of Shadow Power to Gorzeeki Wildeyes in the Burning Steppes.", summary = "A Bell of Dethmoora, named after the late warlock Dethmoora Darkeyes, is one of the three tools needed to create a Circle of Greater Summoning.  When properly atuned with the Wheel and the Candle, these items conduct vast stores of arcane power.$B$BMy servant Gorzeeki can construct such a bell, but to do so he will need a large supply of elixirs of shadow power.  Procure the elixirs from an alchemist and bring them to Gorzeeki." },
            { ids = { 7627 }, name = "Wheel of the Black March", level = 60, zone = "Burning Steppes", giver = "Mor'zul Bloodbringer", giverMap = 1428, giverX = 12.7, giverY = 31.6, ender = "Gorzeeki Wildeyes", enderMap = 1428, enderX = 12.4, enderY = 31.6, objective = "Bring 6 Large Brilliant Shards and 25 Dark Iron Ore to Gorzeeki in the Burning Steppes.", summary = "A Wheel of the Black March contains and directs the violent energies required for the Circle of Greater Summoning.  For Gozeeki to construct a wheel, he will need both large brilliant shards from an enchanter, and dark iron ore from a master miner.$B$BAcquire these and bring them to my servant." },
            { ids = { 7628 }, name = "Doomsday Candle", level = 60, zone = "Burning Steppes", giver = "Mor'zul Bloodbringer", giverMap = 1428, giverX = 12.7, giverY = 31.6, ender = "Gorzeeki Wildeyes", enderMap = 1428, enderX = 12.4, enderY = 31.6, objective = "Bring 35 Black Dragonscales to Gorzeeki Wildeyes in the Burning Steppes.", summary = "A Doomsday Candle stores fire and directs it at those who would disrupt your ritual.  When creating your Circle of Greater Summoning, if your candle is lit then any wayward demons will be burned by its flames!$B$BContaining that fire is not easy, and requires the essence within the scales of a black dragon.  Acquire those scales from a skinner and bring them to Gorzeeki Wildeyes." },
            { ids = { 7625 }, name = "Xorothian Stardust", level = 60, zone = "Felwood", giver = "Lord Banehollow", giverMap = 1448, giverX = 35.9, giverY = 44.4, ender = "Gorzeeki Wildeyes", enderMap = 1428, enderX = 12.4, enderY = 31.6, objective = "Purchase Xorothian Stardust from Ur'dan.  Bring it to Gorzeeki Wildeyes in the Burning Steppes.", summary = "So you come to me seeking Xorothian stardust?  You wish to open a portal to Xoroth, the domain of Hel'nurath my rival?  Perhaps you plan to steal from him one of his precious dreadsteeds?$B$BVery well.  My servant Ur'dan has a supply of Xorothian stardust.  You may obtain it from him... if you can pay the price." },
            { ids = { 7630 }, name = "Arcanite", level = 60, zone = "Burning Steppes", giver = "Gorzeeki Wildeyes", giverMap = 1428, giverX = 12.4, giverY = 31.6, ender = "Gorzeeki Wildeyes", enderMap = 1428, enderX = 12.4, enderY = 31.6, objective = "Bring 3 Arcanite Bars to Gorzeeki in the Burning Steppes.", summary = "Now that the Bell, Wheel and Candle are made, I should make a black lodestone.  During your ritual, you'll need that lodestone to maintain the other ritual objects if they should fail.$B$BTo make the lodestone, I require arcanite.  Do you have any?  If not, then... you'll have to get the arcanite from an alchemist.$B$BReturn to me when you have the arcanite, and then I'll make the black lodestone." },
            { ids = { 7629 }, name = "Imp Delivery", level = 60, zone = "Burning Steppes", giver = "Gorzeeki Wildeyes", giverMap = 1428, giverX = 12.4, giverY = 31.6, ender = "Gorzeeki Wildeyes", enderMap = 1428, enderX = 12.4, enderY = 31.6, objective = "Bring the Imp in a Jar to the alchemy lab in the Scholomance.  After the parchment is created, return the jar to Gorzeeki Wildeyes.", summary = "There is one more process required for Mor'zul's parchment; I need paper infused with Xorothian stardust.  And... I'm afraid I can't do that here.  I don't have the equipment!$B$BThere is an alchemy lab, however, with everything needed.  It's in the Scholomance, on the isle of Caer Darrow in the Plaguelands.$B$BI can't make the trip, but here - take this jar.  There's an imp inside who is quite clever.  Let him out at the alchemy lab and he'll infuse the parchment." },
            { ids = { 7631 }, name = "Dreadsteed of Xoroth", level = 60, zone = "Burning Steppes", giver = "Mor'zul Bloodbringer", giverMap = 1428, giverX = 12.7, giverY = 31.6, ender = "Dreadsteed Spirit", enderMap = 1444, enderX = 60.3, enderY = 30.2, enderInside = "Dire Maul", objective = "Read Mor'zul's Instructions.  Summon a Xorothian Dreadsteed, defeat it, then bind its spirit to you.", summary = "All the preparations are made.  Now, you must perform the ritual to create a Circle of Greater Summoning, then use the parchment infused with Xorothian stardust... to open a portal to Xoroth.$B$BI have written the instructions for the ritual onto a scroll.  Study it closely, for you must perform each step exactly if you wish to succeed.$B$BFortune to you, $N.  And may the souls of your enemies swiftly find their way into your shard pouch." },
        },
    },
    {
        id = "q9250",
        name = "Atiesh, the Befouled Greatstaff",
        zone = "",
        minLevel = 60,
        maxLevel = 60,
        importance = 2,
        kind = "class",
        classes = { 5, 8, 9, 11 },
        quests = {
            { ids = { 9250 }, name = "Frame of Atiesh", level = 60, ender = "Anachronos", enderMap = 1446, enderX = 65.3, enderY = 50.0, objective = "Find someone that will help you in recovering the last two pieces of the staff and ridding it of evil.", summary = "With the frame formed, Atiesh is nearly whole. Only the head and base of the staff are now missing. There is also a minor issue regarding the staff being a conduit for Sargeras's evil.$B$BFind someone that can assist you in locating the remaining pieces and exorcising the evil from the staff." },
            { ids = { 9251 }, name = "Atiesh, the Befouled Greatstaff", level = 60, zone = "Tanaris", giver = "Anachronos", giverMap = 1446, giverX = 65.3, giverY = 50.0, ender = "Anachronos", enderMap = 1446, enderX = 65.3, enderY = 50.0, objective = "Anachronos at the Caverns of Time in Tanaris wants the Staff Head of Atiesh and the Base of Atiesh.", summary = "You question why you are still alive. After all, you have in your possession an item of great evil. The answer is not clear, $N. I only do as I must.$B$BKel'Thuzad sits atop his throne in Naxxramas, plotting... He seeks that which you hold and holds that which you seek.$B$BAs for the base of the staff; the dwarf, Brann Bronzebeard, held it when he entered Ahn'Qiraj. He has left Ahn'Qiraj but the base of Atiesh remains.$B$BShould you succeed in recovering the pieces, return them to me." },
        },
    },
    {
        id = "q9123",
        name = "Echoes of War",
        zone = "Eastern Plaguelands",
        minLevel = 60,
        maxLevel = 60,
        importance = 1,
        kind = "raid",
        quests = {
            { ids = { 9123 }, name = "The Dread Citadel - Naxxramas", level = 60, zone = "Eastern Plaguelands", giver = "Archmage Angela Dosantos", giverMap = 1423, giverX = 71.7, giverY = 48.7, ender = "Archmage Angela Dosantos", enderMap = 1423, enderX = 71.7, enderY = 48.7, objective = "Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands will grant you Arcane Cloaking at no cost. You must be Exalted with the Argent Dawn.", summary = "In the thick of Plaguewood lies the entrance to the dread citadel of Naxxramas. Previously, all attempts to enter had been stymied by the magical wards placed upon the rune portal. That is, until now.$B$BWe have devised a way to gain entry via a permanent arcane cloaking of sorts - an old cantrip of the Kirin Tor with a few modifications of my own. With that said, the cloaking is costly; however, your dedication to the cause of the Dawn is unwavering! We will waive all cost associations." },
            { ids = { 9033 }, name = "Echoes of War", level = 60, zone = "Eastern Plaguelands", giver = "Commander Eligor Dawnbringer", giverMap = 1423, giverX = 71.7, giverY = 48.6, ender = "Commander Eligor Dawnbringer", enderMap = 1423, enderX = 71.7, enderY = 48.6, objective = "Commander Eligor Dawnbringer at Light's Hope Chapel in the Eastern Plaguelands wants you to slay 5 Living Monstrosities, 5 Stoneskin Gargoyles, 8 Deathknight Captains and 3 Venom Stalkers.", summary = "Five years since the last war...$B$BTens of thousands of lives were lost and for what? The threat was never fully extinguished.$B$BAnd so the Lich King stirs once more... His yes-man, Kel'Thuzad, amassing for another attack upon our lands.$B$BWe will not allow it! Prove your dedication. Prove that you are willing to risk life and limb to stop this madness and the combined might of the Dawn and the Crusade will be at your beck and call.$B$BEnter Naxxramas and destroy the Scourge within..." },
            { ids = { 9229 }, name = "The Fate of Ramaladni", level = 60, zone = "Eastern Plaguelands", giver = "Korfax, Champion of the Light", giverMap = 1423, giverX = 72.0, giverY = 48.5, ender = "Korfax, Champion of the Light", enderMap = 1423, enderX = 72.0, enderY = 48.5, objective = "Enter Naxxramas and uncover the Fate of Ramaladni.", summary = "Ramaladni was a warrior of the Brotherhood - a pupil of Highlord Mograine before the Dawn even existed! When news of Mograine's death reached him, hatred and anger took over.$B$BUnderstand this, $N, when rage and retribution take the reins, a man ceases to be a man. The man personifies the emotions that control him instead. And so it would be that Ramaladni, the spirit of retribution, would enter Naxxramas to exact vengeance... and never return.$B$BEnter Naxxramas and find what became of Ramaladni." },
            { ids = { 9230 }, name = "Ramaladni's Icy Grasp", level = 60, zone = "Eastern Plaguelands", giver = "Korfax, Champion of the Light", giverMap = 1423, giverX = 72.0, giverY = 48.5, ender = "Korfax, Champion of the Light", enderMap = 1423, enderX = 72.0, enderY = 48.5, objective = "Korfax at Light's Hope Chapel in the Eastern Plaguelands wants you to bring him 1 Frozen Rune, 1 Blue Sapphire and 1 Arcanite Bar.", summary = "Fixing this band may prove to be quite challenging, $N. You see, it was made from the very runes that form inside Scourge structures - like Naxxramas. Additional materials are also required but your main concern should be getting those frozen runes. Bring me what I need and I will restore the ring to its former glory." },
        },
    },
    {
        id = "q8801",
        name = "The Savior of Kalimdor",
        zone = "Ahn'Qiraj",
        minLevel = 60,
        maxLevel = 60,
        importance = 1,
        kind = "raid",
        quests = {
            { ids = { 8801 }, name = "C'Thun's Legacy", level = 60, zone = "Ahn'Qiraj", ender = "Caelestrasz", enderMap = 1451, enderX = 28.6, enderY = 92.3, enderInside = "Temple of Ahn'Qiraj", objective = "Take the Eye of C'Thun to Caelastrasz in the Temple of Ahn'Qiraj.", summary = "The walls of Ahn'Qiraj tremble. A force of evil, older than the world itself, has been destroyed.$B$BAs you look at the remnants of the colossal abomination your heart nearly freezes. Even in death you can feel the legacy of C'Thun's evil around you.$B$BYou have done what was thought to be impossible.$B$BYou grab at an eye stalk of the fiend, stowing it safely in your pack.$B$BTake the Eye of C'Thun to the dragons in the next chamber. " },
            { ids = { 8802 }, name = "The Savior of Kalimdor", level = 60, zone = "Temple of Ahn'Qiraj", giver = "Caelestrasz", giverMap = 1451, giverX = 28.6, giverY = 92.3, giverInside = "Temple of Ahn'Qiraj", ender = "Anachronos", enderMap = 1446, enderX = 65.3, enderY = 50.0, objective = "Take the Eye of C'Thun to Anachronos at the Caverns of Time.", summary = "To the Caverns of Time you go, $G Lord:Lady; $N. Anachronos awaits your return. Give him the eye of C'Thun as he will undoubtedly wish to place it in his master's collection." },
        },
    },
}
